INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p1-1', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 1, 'NIST Special Publication 800-150 Guide to Cyber Threat Information Sharing Chris Johnson Lee Badger David Waltermire Julie Snyder Clem Skorupka This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 C  O  M  P  U  T  E  R      S  E  C  U  R  I  T  Y', 'vec_doc-03-nist-sp-800-150-p1-1', 0, 72, 'v2.1.0', '32e016a08f2b803cc53e6365b5a44576b60880b9ee33887c8cef16787553cece', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":1,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":1,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p2-2', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 2, 'NIST Special Publication 800-150 Guide to Cyber Threat Information Sharing Chris Johnson Lee Badger David Waltermire Computer Security Division Information Technology Laboratory Julie Snyder Clem Skorupka The MITRE Corporation This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 October 2016 U.S. Department of Commerce Penny Pritzker, Secretary National Institute of Standards and Technology Willie May, Under Secretary of Commerce for Standards and Technology and Director', 'vec_doc-03-nist-sp-800-150-p2-2', 0, 129, 'v2.1.0', '187e1cf8c4b60e21eddf7a102db2c1af81e7f1f8cc40d3c46118032e4cb66128', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":2,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":2,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p3-3', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 3, 'i Authority This publication has been developed by NIST in accordance with its statutory responsibilities under the Federal Information Security Modernization Act (FISMA) of 2014, 44 U.S.C. § 3551 et seq., Public Law (P.L.) 113-283. NIST is responsible for developing information security standards and guidelines, including minimum requirements for federal information systems, but such standards and guidelines shall not apply to national security systems without the express approval of appropriate federal officials exercising policy authority over such systems. This guideline is consistent with the requirements of the Office of Management and Budget (OMB) Circular A-130. Nothing in this publication should be taken to contradict the standards and guidelines made mandatory and binding on federal agencies by the Secretary of Commerce under statutory  authority.', 'vec_doc-03-nist-sp-800-150-p3-3', 0, 218, 'v2.1.0', 'b3064171c9d48df1d21ea5d725d63f591a4f1de991d5c25d295ced659198ad45', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p3-4', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 3, 'Nor should these guidelines be interpreted as altering or superseding the existing authorities of the Secretary of Commerce, Director of the OMB, or any other f ederal official. This publication may be used by nongovernmental organizations on a voluntary basis and is not subject to copyright in the United States. Attribution would, however, be appreciated by NIST. National Institute of Standards and Technology Special Publication 800-150 Natl. Inst. Stand. Technol. Spec. Publ. 800-150, 35 pages (October 2016) CODEN: NSPUE2 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Certain commercial entities, equipment, or materials may be identified in this document in order to describe an experimental procedure or concept adequately. Such identification is not intended to imply recommendation or endorsement by NIST, nor is it inte nded to imply that the entities, materials, or equipment are necessarily the best available for the purpose.', 'vec_doc-03-nist-sp-800-150-p3-4', 0, 247, 'v2.1.0', '9d6391f87429a82ce022388f7f470fc8225c2a274f03e9bc898b0fa27f52a2d8', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":4,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p3-5', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 3, 'There may be references in this publication to other publications currently under development by NIST in accordance with its assigned statutory responsibilities. The information in this publication, including concepts and methodologies, may be used by federal agencies even before the completion of such companion publications. Thus, until each publication is completed, current requirements, guideline s, and procedures, where they exist, remain operative. For planning and transition purposes, federal agencies may wish to closely follow the development of t hese new publications by NIST. Organizations are encouraged to review all draft publications during public comment periods and provide feedback to NIST. Many NIST cybersecurity  publications, ot her than the ones noted above, are available at http://csrc.nist.gov/publications.', 'vec_doc-03-nist-sp-800-150-p3-5', 0, 210, 'v2.1.0', 'aa82bd3b9ecd771426bd27dcb3fbffee6451f555f54b9489013f65c9e9c5a35a', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":5,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p3-6', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 3, 'Comments on this publication may be submitted to: National Institute of Standards and Technology Attn: Computer Security Division, Information Technology Laboratory 100 Bureau Drive (Mail Stop 8930) Gaithersburg, MD 20899-8930 Email: sp800-150comments@nist.gov All comments are subject to release under the Freedom of Information Act (FOIA).', 'vec_doc-03-nist-sp-800-150-p3-6', 0, 86, 'v2.1.0', 'e16e940e74872ec6d4fa390f274ad8f2d47127f6fa543ae1e05bc957a20a95b9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":3,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":6,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p4-7', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 4, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING ii This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Reports on Computer Systems Technology The Information Technology Laboratory (ITL) at the National Institute of Standards and Technology (NIST) promotes the U.S. economy and public welfare by providing technical leadership for the Nation’s measurement and standards infrastructure. ITL develops tests, test methods, reference data, proof of concept implementations, and technical analyses to advance the development and productive use of information technology. ITL’s responsibilities include the development of management, administrative, technical, and physical standards and guidelines for the cost-effective security and privacy of other than national security- related information in f ederal information systems.', 'vec_doc-03-nist-sp-800-150-p4-7', 0, 218, 'v2.1.0', '6cbc61f982bbd011c7f0746e401abb53ae9b72272706f010ecbd70a96ccee4bb', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":7,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p4-8', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 4, 'The Special Publication 800 -series reports on ITL’s research, guidelines, and outreach efforts in information system security, and its collaborative activities with industry, government, and academic organizations. Abstract Cyber threat information is any information that can help an organization identify, assess, monitor, and respond to cyber threats. Cyber threat information includes indicators of compromise; tactics, techniques, and procedures used by threat actors; suggested actions to detect, contain, or prevent attacks; and the findings from the analyses of incidents. Organizations that share cyber threat information can improve their own security postures as well as those of other organizations. This publication provides guidelines for establishing and participating in cyber threat information sharing relationships.', 'vec_doc-03-nist-sp-800-150-p4-8', 0, 209, 'v2.1.0', 'b0a26ddd65ee999209a6504b43a1edd6c7da219c27b0da5d1240a650ea608cea', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":8,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p4-9', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 4, 'This guidance helps organizations establish information sharing goals, identify cyber threat information sources, scope information sharing activities, develop rules that control the publication and distribution of threat information, engage with existing sharing communities, and make effective use of threat information in support of the organization’s overall cybersecurity practices.', 'vec_doc-03-nist-sp-800-150-p4-9', 0, 97, 'v2.1.0', 'b7e26d37afebd4c66393f37d436fabb9f16ce206b16e4393a1230d2eb5c17e68', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":9,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p4-10', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 4, 'Keywords cyber threat; cyber threat information sharing; indicators; information security; information sharing Acknowledgments The authors, Chris Johnson, Lee Badger, and David Waltermire of the National Institute of Standards and Technology (NIST), and Julie Snyder and Clem Skorupka of The MITRE Corporation, wish to thank their colleagues who contributed to this publication, including Tom Millar and Rich Struse of the Department of Homeland Security (DHS); Karen Quigg, Richard Murad, Carlos Blazquez, and Jon Baker of The MITRE Corporation; Murugiah Souppaya and Melanie Cook of NIST; Ryan Meeuf, of the Software Engineering Institute, Carnegie Mellon University; George Saylor, Greg Witte, and Matt Smith of G2 Inc.; Karen Scarfone of Scarfone Cybersecurity; Chris Bean of the National Security Agency (NSA); Eric Burger of the Georgetown Center for Secure Communications, Georgetown University; Joe Drissel of Cyber Engineering Services Inc.; Tony Sager of the Center for Internet Security; Kent Landfield of Intel Security; Bruce Potter of KEYW Inc.; Jeff Carpenter of Dell SecureWorks; Ben Miller of the North American Electric Reliability Corporation (NERC); Anton Chuvakin of Gartner, Inc.; Johannes Ullrich of the SANS Technology Institute; Patrick Dempsey, Defense Industrial Base Collaborative Information Sharing Environment (DCISE); Matthew Schuster, Mass Insight; Garrett Schubert of EMC; James Caulfield of the Federal Reserve; Bob Guay of Biogen; and Chris Sullivan of Courion.', 'vec_doc-03-nist-sp-800-150-p4-10', 0, 375, 'v2.1.0', '045af8468704dfa92a35e83853055dc3789075920c8886f337bb82845485e3df', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":10,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p4-11', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 4, 'Trademark Information All registered trademarks or trademarks belong to their respective organizations.', 'vec_doc-03-nist-sp-800-150-p4-11', 0, 26, 'v2.1.0', '7d6f375d3ac20e73c94bba14bdc53acd4a614ce3cf941a032e6007f7087407d0', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":11,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p5-12', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 5, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING iii This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Executive Summary Cyber attacks have increased in frequency and sophistication, presenting significant challenges for organizations that must defend their data and systems from capable threat actors. These actors range from individual, autonomous attackers to well-resourced groups operating in a coordinated manner as part of a criminal enterprise or on behalf of a nation-state. Threat actors can be persistent, motivated, and agile, and they use a variety of tactics, techniques, and procedures (TTPs) to compromise systems, disrupt services, commit financial fraud, and expose or steal intellectual property and other sensitive information. Given the risks these threats present, it is increasingly important that organizations share cyber threat information and use it to improve their security posture.', 'vec_doc-03-nist-sp-800-150-p5-12', 0, 241, 'v2.1.0', '7cc6f406ef4f282709cb6bb359164dcaa9e9acdf3a00dcdffe1919574175f134', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":5,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":12,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p5-13', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 5, 'Cyber threat information is any information that can help an organization identify, assess, monitor, and respond to cyber threats. Examples of cyber threat information include indicators (system artifacts or observables associated with an attack), TTPs, security alerts, threat intelligence reports, and recommended security tool configurations. Most organizations already produce multiple types of cyber threat information that are available to share internally as part of their information technology and security operations efforts. By exchanging cyber threat information within a sharing community, organizations can leverage the collective knowledge, experience, and capabilities of that sharing community to gain a more complete understanding of the threats the organization may face. Using this knowledge, an organization can make threat-informed decisions regarding defensive capabilities, threat detection techniques, and mitigation strategies.', 'vec_doc-03-nist-sp-800-150-p5-13', 0, 239, 'v2.1.0', 'af49098fd3f6efbb1a933b6893dc5316d46555fc3e7f61829b98c12de6a75f19', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":5,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":13,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p5-14', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 5, 'By correlating and analyzing cyber threat information from multiple sources, an organization can also enrich existing information and make it more actionable. This enrichment may be achieved by independently confirming the observations of other community members, and by improving the overall quality of the threat information through the reduction of ambiguity and errors. Organizations that receive threat information and subsequently use this information to remediate a threat confer a degree of protection to other organizations by impeding the threat’s ability to spread. Additionally, sharing of cyber threat information allows organizations to better detect campaigns that target particular industry sectors, business entities, or institutions. This publication assists organizations in establishing and participating in cyber threat information sharing relationships.', 'vec_doc-03-nist-sp-800-150-p5-14', 0, 219, 'v2.1.0', '0e27dd0cc8e8c1ae24c057ee2ac6beddf52f3f576b724c102244ddfcfe8d77d2', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":5,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":14,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p5-15', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 5, 'The publication describes the benefits and challenges of sharing, clarifies the importance of trust, and introduces specific data handling considerations. The goal of the publication is to provide guidelines that improve cybersecurity operations and risk management activities through safe and effective information sharing practices, and that help organizations plan, implement, and maintain information sharing. NIST encourages greater sharing of cyber threat information among organizations, both in acquiring threat information from other organizations and in providing internally-generated threat information to other organizations. Implementing the following recommendations enables organizations to make more efficient and effective use of information sharing capabilities. Establish information sharing goals and objectives that support business processes and security policies.', 'vec_doc-03-nist-sp-800-150-p5-15', 0, 222, 'v2.1.0', '2a62fac28f3d3a4e56c6ee4fd9073db68a5b3e0dff5022e67aeeb279887d4be5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":5,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":15,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p5-16', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 5, 'An organization’s information sharing goals and objectives should advance its overall cybersecurity strategy and help an organization more effectively manage cyber-related risk. An organization should use the combined knowledge and experience of its own personnel and others, such as members of cyber threat information sharing organizations, to share threat information while operating per its security, privacy, regulatory, and legal compliance requirements.', 'vec_doc-03-nist-sp-800-150-p5-16', 0, 115, 'v2.1.0', 'f563edfefcc704bebce09643ae842ed4645e0a00d66b1c0e5d637ea64b141481', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":5,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":16,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p6-17', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 6, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING iv This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Identify existing internal sources of cyber threat information. Organizations should identify tools, sensors, and repositories that collect, produce, or store cyber threat information, threat analytics platforms, and delivery mechanisms that support the exchange of cyber threat information. As internal cyber threat information sources and capabilities are identified, organizations should determine how information from these sources currently support cybersecurity and risk management activities. Organizations should also document observed knowledge gaps and consider acquiring additional threat information from other (possibly external) sources or through the deployment of other tools or sensors. Finally, organizations should identify threat information that is available and suitable for sharing with outside parties.', 'vec_doc-03-nist-sp-800-150-p6-17', 0, 245, 'v2.1.0', 'd55d87ec6cf749a127add7ff609519c06ebe814ed1bf50146b329197569c9f7c', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":6,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":17,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p6-18', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 6, 'Specify the scope of information sharing activities. The breadth of an organization’s information sharing activities should be consistent with its resources, abilities, and objectives. Information sharing efforts should focus on activities that provide the greatest value to an organization and its sharing partners. The scoping activity should identify types of information that an organization’s key stakeholders authorize for sharing, the circumstances under which sharing of this information is permitted, and those with whom the information can and should be shared. Establish information sharing rules. Sharing rules are intended to control the publication and distribution of threat information, and consequently help to prevent the dissemination of information that, if improperly disclosed, may have adverse consequences for an organization, its customers, or its business partners.', 'vec_doc-03-nist-sp-800-150-p6-18', 0, 223, 'v2.1.0', '13e826e37b1dab07f6973849067ebbc3d87b4a6195629cbb30c5143889ecdb59', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":6,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":18,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p6-19', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 6, 'Information sharing rules should take into consideration the trustworthiness of the recipient, the sensitivity of the shared information, and the potential impact of sharing (or not sharing) specific types of information. Join and participate in information sharing efforts. An organization should identify and participate in sharing activities that complement its existing threat information capabilities. An organization may need to participate in multiple information sharing forums to meet its operational needs. Organizations should consider public and private sharing communities, government repositories, commercial cyber threat information feeds, and open sources such as public websites, blogs, and data feeds. Actively seek to enrich indicators by providing additional context, corrections, or suggested improvements. When possible, organizations should increase the usefulness and effectiveness of threat information by producing metadata for each indicator that is generated.', 'vec_doc-03-nist-sp-800-150-p6-19', 0, 247, 'v2.1.0', '2a6e4db8a62fdb803e538d92571a0345ef3d1ed8e618900ee23729b00be814bb', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":6,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":19,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p6-20', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 6, 'Such metadata can provide context regarding the indicator by describing the intended use of the indicator, how it is to be interpreted, and how it relates to other indicators. Additionally, sharing processes should include mechanisms for publishing indicators, updating indicators and associated metadata, and retracting submissions that are incorrect or perhaps inadvertently shared. Such feedback plays an important role in the enrichment, maturation, and quality of the indicators shared within a community. Use secure, automated workflows to publish, consume, analyze, and act upon cyber threat information. The use of standardized data formats and transport protocols to share cyber threat information makes it easier to automate threat information processing. The use of automation enables cyber threat information', 'vec_doc-03-nist-sp-800-150-p6-20', 0, 205, 'v2.1.0', '2daedc19810ec423137637799ec442b3005b0a63d6b3a5bc537b114f00a541bd', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":6,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":20,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p7-21', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 7, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING v This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 to be rapidly shared, transformed, enriched, analyzed, and acted upon with less need for manual intervention. Proactively establish cyber threat sharing agreements. Rather than attempting to establish sharing agreements during an active cyber incident, organizations should plan ahead and have agreements in place before incidents occur. Such advanced planning helps ensure that participating organizations establish trusted relationships and understand their roles, responsibilities, and information handling requirements. Protect the security and privacy of sensitive information. Sensitive information such as controlled unclassified information (CUI) [16] and personally identifiable information (PII) may be encountered when handling cyber threat information.', 'vec_doc-03-nist-sp-800-150-p7-21', 0, 230, 'v2.1.0', 'e4eafc7fbfbcef898a72f592c538da85dacc27b699ea6ec26e418d6ba8c8756b', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":7,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":21,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p7-22', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', 'UNKNOWN', 7, 'The improper disclosure of such information could cause financial loss; violate laws, regulations, and contracts; be cause for legal action; or damage an organization’s or individual’s reputation. Accordingly, organizations should implement the necessary security and privacy controls and handling procedures to protect this information from unauthorized disclosure or modification. Provide ongoing support for information sharing activities. Each organization should establish an information sharing plan that provides for ongoing infrastructure maintenance and user support. The plan should address the collection and analysis of threat information from both internal and external sources and the use of this information in the development and deployment of protective measures. A sustainable approach is necessary to ensure that resources are available for the ongoing collection, storage, analysis, and dissemination of cyber threat information.', 'vec_doc-03-nist-sp-800-150-p7-22', 0, 238, 'v2.1.0', '54d99245947056c94419183996545db8c21818473d19c0ff0ae4e95115845160', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":7,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":22,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"General Document Content"}');
