INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p9-29', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.6 Plan to Provide Ongoing Support for Information Sharing Activities ......................... 18', 9, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 1 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'vec_doc-03-nist-sp-800-150-p9-29', 0, 38, 'v2.1.0', '8865076f2eacaf6031c0390d52c66e2706a60bba06542dafe19be947dfe960ec', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.6 Plan to Provide Ongoing Support for Information Sharing Activities ......................... 18","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":29,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.6 Plan to Provide Ongoing Support for Information Sharing Activities ......................... 18"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p9-30', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '1.1 Purpose and Scope', 9, 'This publication provides guidance to help organizations exchange cyber threat information. The guidance addresses sharing of cyber threat information within an organization, consuming and using cyber threat information received from external sources, and producing cyber threat information that can be shared with other organizations. The document also presents specific considerations for participation in information sharing communities. This publication expands upon the information sharing concepts introduced in Section 4, Coordination and Information Sharing, of NIST Special Publication (SP) 800-61[1].', 'vec_doc-03-nist-sp-800-150-p9-30', 0, 153, 'v2.1.0', '8747be3728e343356ab5e2c79181b51dfdff5b49d11d13d306cc08bbfaab1194', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"1.1 Purpose and Scope","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":30,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"1.1 Purpose and Scope"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p9-31', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '1.2 Audience', 9, 'This publication is intended for computer security incident response teams (CSIRTs), system and network administrators, cybersecurity specialists, privacy officers, technical support staff, chief information security officers (CISOs), chief information officers (CIOs), computer security program managers, and others who are key stakeholders in cyber threat information sharing activities. Although this guidance is written primarily for federal agencies, it is intended to be applicable to a wide variety of governmental and non-governmental organizations.', 'vec_doc-03-nist-sp-800-150-p9-31', 0, 140, 'v2.1.0', 'f6794fd1371e7ff3f74f27d9fb7a724f6cb0dafdf32659e35ee36e86d25cbb00', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"1.2 Audience","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":31,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"1.2 Audience"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p9-32', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '1.3 Document Structure', 9, 'The remainder of this document is organized into the following sections and appendices: • Section 2 introduces basic cyber threat information sharing concepts, describes the benefits of sharing information, and discusses the challenges faced by organizations as they implement sharin g cap abilities. • Section 3 provides guidelines on establishing sharing relationships with other organizations. • Section 4 discusses considerations for effectively participating in sharing relationships. • A ppendix A contains scenarios that show how organizations can enhance their network defenses by sharing cyber threat information and by leveraging the cyber experience and capabilities of their partners. • Appendix B contains a list of terms used in the document and their associated definitions. • Appendix C provides a list of acronyms used in the document. • Appendix D identifies resources referenced in the document.', 'vec_doc-03-nist-sp-800-150-p9-32', 0, 229, 'v2.1.0', 'ea1d1762f4435d59acc4749d511b4289ce30a8949a8f72e46f1fa1d4248f9ab9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"1.3 Document Structure","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":32,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"1.3 Document Structure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p10-33', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '1.3 Document Structure', 10, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 2 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'vec_doc-03-nist-sp-800-150-p10-33', 0, 38, 'v2.1.0', '6fa9fd4d6207b3b65b49a70de80926b2e5358aeb740fa2f31ec5f741605b6bc3', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"1.3 Document Structure","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":33,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"1.3 Document Structure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p10-34', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2. Basics of Cyber Threat Information Sharing', 10, 'This section introduces basic cyber threat information sharing concepts including types of cyber threat information and common terminology. The section also examines potential uses for shared cyber threat information and explores the benefits and challenges of threat information sharing.', 'vec_doc-03-nist-sp-800-150-p10-34', 0, 72, 'v2.1.0', 'db52eab30cbd12e87ab3d7ab1ac636f6506bb14e5e78606cc5e6cc07d740a653', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2. Basics of Cyber Threat Information Sharing","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":34,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2. Basics of Cyber Threat Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p10-35', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.1 Threat Information Types', 10, 'A cyber threat is “any circumstance or event with the potential to adversely impact organizational operations (including mission, functions, image, or reputation), organizational assets, individuals, other organizations, or the Nation through an information system via unauthorized access, destruction, disclosure, or modification of information, and/or denial of service.” [2] For brevity, this publication uses the term threat instead of “cyber threat”. The individuals and groups posing threats are known as “threat actors” or simply actors. Threat information is any information related to a threat that might help an organization protect itself against a threat or detect the activities of an actor. Major types of threat information include the following: • Indicators are technical artifacts or observables1 that suggest an attack is imminent or is currently underway or that a compromise may have already occurred. Indicators can be used to detect and defend against potential threats.', 'vec_doc-03-nist-sp-800-150-p10-35', 0, 249, 'v2.1.0', 'a95982b98d8bc119847a7eb71f63ea4dcf821524c0f406813206728323fddd29', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.1 Threat Information Types","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":35,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.1 Threat Information Types"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p10-36', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.1 Threat Information Types', 10, 'Examples of indicators include the Internet Protocol (IP) address of a suspected command and control server, a suspicious Domain Name System (DNS) domain name, a Uniform Resource Locator (URL) that references malicious content, a file hash for a malicious executable, or the subject line text of a malicious email message. • Tactics, techniques, and procedures (TTPs) describe the behavior of an actor. Tactics are high-level descriptions of behavior, techniques are detailed descriptions of behavior in the context of a tactic, and procedures are even lower-level, highly detailed descriptions in the context of a technique. TTPs could describe an actor’s tendency to use a specific malware variant, order of operations, attack tool, delivery mechanism (e.g., phishing or watering hole attack), or exploit.', 'vec_doc-03-nist-sp-800-150-p10-36', 0, 202, 'v2.1.0', '710492b44bf0c51c963fc464fcbfd32d9dde47bec2a30190f2a4a0c2c90de267', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.1 Threat Information Types","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":36,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.1 Threat Information Types"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p10-37', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.1 Threat Information Types', 10, '• Security alerts, also known as advisories, bulletins, and vulnerability notes, are brief, usually human- readable, technical notifications regarding current vulnerabilities, exploits, and other security issues. Security alerts originate from sources such as the United States Computer Emergency Readiness Team (US-CERT), Information Sharing and Analysis Centers (ISACs), the National Vulnerability Database (NVD), Product Security Incident Response Teams (PSIRTs), commercial security service providers, and security researchers. • Threat intelligence reports are generally prose documents that describe TTPs, actors, types of systems and information being targeted, and other threat-related information that provides greater situational awareness to an organization. Threat intelligence is threat information that has been aggregated, transformed, analyzed, interpreted, or enriched to provide the necessary context for decision-making processes.', 'vec_doc-03-nist-sp-800-150-p10-37', 0, 238, 'v2.1.0', 'ef3b9c1c88a3a06ce0468c98ab2ca84c15ff06a76587f998e309f41ae452dd0f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.1 Threat Information Types","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":37,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.1 Threat Information Types"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p10-38', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.1 Threat Information Types', 10, '• Tool configurations are recommendations for setting up and using tools (mechanisms) that support the automated collection, exchange, processing, analysis, and use of threat information. For example, tool configuration information could consist of instructions on how to install and use a rootkit 1 An observable is an event (benign or malicious) on a network or system.', 'vec_doc-03-nist-sp-800-150-p10-38', 0, 93, 'v2.1.0', '2b7a66d4c9295b6c08896574dfe13be071e1aa076d09e9b8d878a7b2fe6d088a', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.1 Threat Information Types","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":38,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.1 Threat Information Types"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p11-39', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.1 Threat Information Types', 11, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 3 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 detection and removal utility, or how to create and customize intrusion detection signatures, router access control lists (ACLs), firewall rules, or web filter configuration files. Many organizations already produce and share threat information internally. For example, an organization’s security team may identify malicious files on a compromised system when responding to an incident and produce an associated set of indicators (e.g., file names, sizes, hash values). These indicators might then be shared with system administrators who configure security tools, such as host- based intrusion detection systems, to detect the presence of these indicators on other systems. Likewise, the security team may launch an email security awareness initiative in response to an observed rise in phishing attacks within the organization. These practices demonstrate information sharing within an organization. The primary goal of this publication is to foster similar threat information sharing practices across organizational boundaries – both acquiring threat information from other organizations, and providing internally-generated threat information to other organizations.', 'vec_doc-03-nist-sp-800-150-p11-39', 0, 331, 'v2.1.0', '1b64144a9a0996d87e1eed4be43b185661c0a0786733e1ca8ee6fd542352b0be', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.1 Threat Information Types","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":39,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.1 Threat Information Types"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p11-40', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.2 Benefits of Information Sharing', 11, 'Threat information sharing provides access to threat information that might otherwise be unavailable to an organization. Using shared resources, organizations can enhance their security posture by leveraging the knowledge, experience, and capabilities of their partners in a proactive way. Allowing “one organization’s detection to become another’s prevention”2 is a powerful paradigm that can advance the overall security of organizations that actively share threat information. An organization can use shared threat information in many ways. Some uses are operationally oriented, such as updating enterprise security controls for continuous monitoring with new indicators and configurations to detect the latest attacks and compromises. Threat information may also be used strategically, such as using shared threat information as inputs when planning major changes to an organization’s security architecture.', 'vec_doc-03-nist-sp-800-150-p11-40', 0, 228, 'v2.1.0', '9c5694d4b612e910d679492b1ce6f6fd2546dc2dd886474d454a0d7ccf4f6bc4', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.2 Benefits of Information Sharing","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":40,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.2 Benefits of Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p11-41', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.2 Benefits of Information Sharing', 11, 'Threat information exchanged within communities organized around specific industries or sectors (or some other shared characteristic) can be particularly beneficial because the member organizations often face actors that use common TTPs that target the same types of systems and information. Cyber defense is most effective when organizations work together to deter and defend against well-organized, capable actors. Such collaboration helps to reduce risk and improve the organization’s security posture. Benefits of information sharing include: • Shared Situational Awareness. Information sharing enables organizations to leverage the collective knowledge, experience, and analytic capabilities of their sharing partners within a community of interest, thereby enhancing the defensive capabilities of multiple organizations. Even a single contribution—a new indicator or observation about an actor—can increase the awareness and security of an entire community. • Improved Security Posture.', 'vec_doc-03-nist-sp-800-150-p11-41', 0, 248, 'v2.1.0', 'af62803daf69f259963ada6db8c54b7b50ff48165f692b058d4091e2f0695294', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.2 Benefits of Information Sharing","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":41,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.2 Benefits of Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p11-42', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.2 Benefits of Information Sharing', 11, 'By developing and sharing threat information, organizations gain a better understanding of the threat environment and can use threat information to inform their cybersecurity and risk management practices. Using shared information, organizations can identify affected platforms or systems, implement protective measures, enhance detection capabilities, and more effectively respond and recover from incidents based on observed changes in the threat environment. As organizations share information and subsequently mitigate threats, those 2 This phrase, which has been used in numerous presentations and discussions, was formulated by Tony Sager, Senior VP and Chief Evangelist, Center for Internet Security.', 'vec_doc-03-nist-sp-800-150-p11-42', 0, 177, 'v2.1.0', '50e4bba4f045eb63914df71413d3d3628a2fd4c0bbf97d4c6e121cbd33d4db7c', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.2 Benefits of Information Sharing","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":42,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.2 Benefits of Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p12-43', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.2 Benefits of Information Sharing', 12, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 4 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 organizations can improve their overall cybersecurity posture, even providing a degree of protection to other organizations, including those who may not have responded to the threat information, by reducing the number of viable attack vectors for actors. • Knowledge Maturation. When seemingly unrelated observations are shared and analyzed by organizations, those observations can be correlated with data collected by others. This enrichment process increases the value of information by enhancing existing indicators and by developing knowledge of actor TTPs that are associated with a specific incident, threat, or threat campaign. Correlation can also impart valuable insights into the relationships that exist between indicators. • Greater Defensive Agility. Actors continually adapt their TTPs to try to evade detection, circumvent security controls, and exploit new vulnerabilities. Organizations that share information are often better informed about changing TTPs and the need to rapidly detect and respond to threats. This awareness helps increase their operational tempo and reduce the probability of successful attack. Such agility also creates economies of scale for network defenders while increasing actors’ costs by forcing them to develop new TTPs.', 'vec_doc-03-nist-sp-800-150-p12-43', 0, 355, 'v2.1.0', '4417ffcb9fbf43fcebae41801f902c12ba4e37fb764b57ac6d25c24e06fce3fc', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.2 Benefits of Information Sharing","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":43,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.2 Benefits of Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p12-44', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 12, 'While sharing threat information clearly has benefits, certain challenges still remain. Some challenges that apply both to consuming and to producing threat information are: • Establishing Trust. Trust relationships form the basis for information sharing, but require effort to establish and maintain. Ongoing communication through regular in-person meetings, phone calls, or social media can help accelerate the process of building trust. • Achieving Interoperability and Automation. Standardized data formats and transport protocols are important building blocks for interoperability. The use of common formats and protocols enables automation and allows organizations, repositories, and tools to exchange threat information at machine speed. Adopting specific formats and protocols, however, can require significant time and resources, and the value of these investments can be substantially reduced if sharing partners require different formats or protocols.', 'vec_doc-03-nist-sp-800-150-p12-44', 0, 241, 'v2.1.0', 'b138b0beb7f706af34666add731d1336cda9d21da24cb5de7f29bd6a0b3293f6', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":44,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p12-45', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 12, 'During the standards development process, early adopters need to accept the risk that it may be necessary to purchase new tools if significant changes to formats and protocols take place. • Safeguarding Sensitive Information. Disclosure of sensitive information, such as controlled unclassified information (CUI) and personally identifiable information (PII) can result in financial loss, violation of sharing agreements, legal action, and loss of reputation. Sharing security and event information, such as security logs or scan results, could expose the protective or detective capabilities of the organization and result in threat shifting by the actor.3 The unauthorized disclosure of information may impede or disrupt an ongoing investigation, jeopardize information needed for future legal proceedings, or disrupt response actions such as botnet takedown operations.', 'vec_doc-03-nist-sp-800-150-p12-45', 0, 218, 'v2.1.0', 'f56abc07ae6a98ae49945afef89138de8b0ee4c2d6158b4243d53058be6300c9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":45,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p12-46', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 12, 'Organizations should apply handling designations to shared information and implement policies, procedures, and technical controls to actively manage the risks of disclosure of sensitive information. 3 NIST SP 800-30 Revision 1, Guide for Conducting Risk Assessments, defines threat shifting as “the response of adversaries to perceived safeguards and/or countermeasures (i.e., security controls), in which adversaries change some characteristic of their intent/targeting in order to avoid and/or overcome those safeguards/countermeasures.', 'vec_doc-03-nist-sp-800-150-p12-46', 0, 135, 'v2.1.0', '014f75f7a27c5faa611a0e735a5ee9e0ff98dbce3cdf2cf04ca72dd633ea298b', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":46,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p12-47', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 12, 'Threat shifting can occur in one or more domains including: (i) the time domain (e.g., a delay in an attack or illegal entry to conduct additional surveillance); (ii) the target domain (e.g., selecting a different target that is not as well protected); (iii) the resource domain (e.g., adding resources to the attack in order to reduce uncertainty or overcome safeguards and/or countermeasures); or (iv) the attack planning/attack method domain (e.g., changing the attack weapon or attack path).” [2, p.9]', 'vec_doc-03-nist-sp-800-150-p12-47', 0, 127, 'v2.1.0', 'd803b671e274fc07475f472b4c034cde6000c7f758c41beea7a607d9456d5ad8', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":47,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p13-48', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 13, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 5 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Protecting Classified Information. Information received from government sources may be marked as classified, making it difficult for an organization to use. Acquiring and maintaining the clearances ne eded for ongoing access to classified information sources is expensive and time-consuming for or ganizations. In addition, many organizations employ non-U.S. citizens who are not eligible to hold secu rity clearances and are not permitted access to classified information. [3] • E nabling Information Consumption and Publication. Organizations that want to consume and publ ish threat information need to have the necessary infrastructure, tools, personnel, and training to do so.', 'vec_doc-03-nist-sp-800-150-p13-48', 0, 209, 'v2.1.0', '6c86877ef0ab2a233d691e9c0502c38a559fa317b036b8f88758a124aec898f0', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":48,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p13-49', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 13, 'Information sharing initiatives should be carefully scoped, because high-frequency, high- volume information exchanges have the potential to overwhelm an organization’s processing capabilities. Organizations that are currently unable to support automated indicator exchange can explore other options such as the manual exchange of best practices or summary indicator information. As additional resources become available, an organization may decide to use automated tools and workflows to process and use threat information. Some information sharing challenges apply only to the consumption of threat information: • Accessing External Information. Organizations need the infrastructure to access external sources a nd incorporate the information retrieved from external sources into local decision-making processes. Information received from external sources has value only to the extent that an organization is e quipped to act on the information. • Evaluating the Quality of Received Information.', 'vec_doc-03-nist-sp-800-150-p13-49', 0, 250, 'v2.1.0', '03f1f69c7a09b58d9b544f719869d8a0bb85126b7470fc07c543dd7299f8f7e0', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":49,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p13-50', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 13, 'Before acting on threat information, an or ganization needs to confirm that the information is correct, that the threat is relevant, and that the risks of using or not using the information (i.e., potential impacts of action vs. inaction) are well understood. Several challenges are only applicable if an organization wants to provide its own information to other organizations: • Complying with Legal and Organizational Requirements. An organization’s executive and legal teams may restrict the types of information that the organization can provide to others. Such restrictions may include limits on the types of information and the level of technical detail provided. These safeguards are appropriate when they address legitimate business, legal, or privacy concerns, but the imposition of unwarranted or arbitrary restrictions may diminish the utility, availability, quality, and timeliness of shared information. • Limiting Attribution.', 'vec_doc-03-nist-sp-800-150-p13-50', 0, 236, 'v2.1.0', '18e853ab613f233695f61b2a103ee4a9eb77a453bb3e609781ddbe2f83918c15', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":50,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p13-51', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 13, 'Organizations may openly participate in information sharing communities, but still require that their contributions remain anonymous. Unattributed information sharing may allow a n organization to share more information because there is less perceived risk to the organization’s reputation. The lack of attribution may, however, limit the usefulness of the information because users may have less confidence in information that originates from an unknown source. If the original s ources of information cannot be identified, organizations may be unable to confirm that information has been received from multiple independent sources, and thus reduce an organization’s ability to bui ld confidence in received information.', 'vec_doc-03-nist-sp-800-150-p13-51', 0, 181, 'v2.1.0', 'fc9e320173fc8c745890169eb617b20584078f5fc9f25e748c3f9b795d637736', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":51,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p14-52', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '2.3 Challenges to Information Sharing', 14, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 6 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'vec_doc-03-nist-sp-800-150-p14-52', 0, 38, 'v2.1.0', '1859021419d2972ea4242b8a9c6678c7de817c4568f0e5dceb2907066da52e64', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"2.3 Challenges to Information Sharing","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":52,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"2.3 Challenges to Information Sharing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p14-53', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3. Establishing Sharing Relationships', 14, 'When launching a threat information sharing capability, the following planning and preparation activities are recommended:4 • Define the goals and objectives of information sharing (section 3.1). • Identify internal sources of threat information (section 3.2). • Define the scope of information sharing activities (section 3.3). • Establish information sharing rules (section 3.4). • Join a sharing community (section 3.5). • Plan to provide ongoing support for information sharing activities (section 3.6). Throughout this process, organizations are encouraged to consult with subject matter experts both inside and outside their organization. Such sources include: • Experienced cybersecurity personnel, • Members and operators of established threat information sharing organizations, • Trusted business associates, supply chain partners, and industry peers, and • Personnel knowledgeable about legal issues, internal business processes, procedures, and systems. An organization should use the knowledge and experience from these experts to help shape a threat information sharing capability that supports its mission and operates under its security, privacy, regulatory, and legal compliance requirements. Due to constantly changing risks, requirements, priorities, technology, and/or regulations, this process will often be iterative. Organizations should reassess and adjust their information sharing capabilities as needed based on changing circumstances. Such a change may involve repeating some or all of the planning and preparation activities listed above.', 'vec_doc-03-nist-sp-800-150-p14-53', 0, 392, 'v2.1.0', '9ce8ad251c3e631569f785cfff0563e9ca239beb72b3c6fc5d45021e1f68d156', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3. Establishing Sharing Relationships","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":53,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3. Establishing Sharing Relationships"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p14-54', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.1 Define Information Sharing Goals and Objectives', 14, 'At the outset, an organization should establish goals and objectives that describe the desired outcomes of threat information sharing in terms of the organization’s business processes and security policies. These goals and objectives will help guide the organization through the process of scoping its information sharing efforts, selecting and joining sharing communities, and providing ongoing support for information sharing activities. Due to technological and/or resource constraints, it may be necessary to prioritize goals and objectives to ensure that the most important information sharing activities are performed.', 'vec_doc-03-nist-sp-800-150-p14-54', 0, 156, 'v2.1.0', '6feed656c63a442bcd8e3930f227ede473ac495d2c7296bcf0b01a3db0a3ae4b', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.1 Define Information Sharing Goals and Objectives","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":54,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.1 Define Information Sharing Goals and Objectives"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p14-55', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 14, 'A key step in any information sharing effort is to identify potential sources of threat information within an organization. By conducting an inventory of internal threat information sources, an organization is better able to identify knowledge gaps. These gaps can be addressed by deploying additional tools and sensors or by acquiring threat information from external threat information feeds or repositories. In large 4 Although an order for these activities is described, in practice the sequence of these activities can vary, and activities can even be performed concurrently. For example, when joining an established sharing organization, it may make sense to address information sharing rules as part of joining the community.', 'vec_doc-03-nist-sp-800-150-p14-55', 0, 183, 'v2.1.0', '1b01b6d092251a25cee6a53a79dc537554793877906908468e125f4c35cfccd1', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":55,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p15-56', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 15, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 7 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 organizations, this inventory process is also a means of discovering information that is being collected and analyzed in business units across the organization that may not be currently shared within the organization. The process of identifying threat information sources includes the following steps: • Identify sensors, tools, data feeds, and repositories that produce threat information, and confirm that the information is produced at a frequency, precision, and accuracy to support cybersecurity decision- making. • Identify threat information that is collected and analyzed as part of an organization’s continuous monitoring strategy. • Locate threat information that is collected and stored, but not necessarily analyzed or reviewed on an ongoing basis.', 'vec_doc-03-nist-sp-800-150-p15-56', 0, 229, 'v2.1.0', '05d9f5edff88a797e7437fdb220122897d4a931c685477e4fa74df2599f8757b', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":56,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p15-57', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 15, 'If an organization finds useful threat information that is being underutilized, methods of integrating this information into its cybersecurity and risk management practices should be explored. • Identify threat information that is suitable for sharing with outside parties and that could help them more effectively respond to threats. The owners and operators of threat information sources play an important role in the inventory process and should be consulted. These personnel understand what information is available and how it is natively stored; the data export formats that are supported; and the query languages, protocols, and services available for data retrieval. Some sources may store and publish structured, machine-readable data, while others may provide unstructured data with no fixed format (e.g., free text or images).', 'vec_doc-03-nist-sp-800-150-p15-57', 0, 209, 'v2.1.0', '2e9075203638c1af01c2ab7989c47cfd260b6403f43f5384d384f14b011c78c3', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":57,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p15-58', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 15, 'Structured data that is expressed using open, machine-readable, standard formats can generally be more readily accessed, searched, and analyzed by a wider range of tools. Thus, the format of the information plays a significant role in determining the ease and efficiency of information use, analysis, and exchange. As part of the inventory process, organizations should take note of information gaps that may prevent realization of the organization’s goals and objectives. By identifying these gaps, an organization is better able to prioritize investments into new capabilities, and identify opportunities to fill gaps by acquiring threat information from other, possibly external, sources or through the deployment of additional tools or sensors. Table 3-1 describes common sources of cybersecurity-related information and provides examples of data elements from these sources that may be of interest to security operations personnel.', 'vec_doc-03-nist-sp-800-150-p15-58', 0, 234, 'v2.1.0', 'f982b09bd583724e9813738211788153315372d549fc6c9192b2191d19a89163', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":58,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p15-59', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 15, 'Table 3-1:  Selected Internal Information Sources Source Examples Network Data Sources Router, firewall, Wi-Fi, remote services (such as remote login or remote command execution), and Dynamic Host Configuration Protocol (DHCP) server logs Timestamp Source and destination IP address Domain name TCP/UDP port number Media Access Control (MAC) address Hostname Action (deny/allow) Status code Other protocol information', 'vec_doc-03-nist-sp-800-150-p15-59', 0, 105, 'v2.1.0', '9e25b58bf95d521c0edd82102b02f5615b14040f7ca19f26ca1befa4f7e0e1c0', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":59,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p16-60', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 16, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 8 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Source Examples Diagnostic and monitoring tools (network intrusion detection and prevention system, packet capture & protocol analysis) Timestamp IP address, port, and other protocol information Network flow data Packet payload Application-specific information Type of attack (e.g., SQL injection, buffer overflow) Targeted vulnerability Attack status (success/fail/blocked) Host Data Sources Operating system and application configuration settings, states, and logs Bound and established network connection and port Process and thread Registry setting Configuration file entry Software version and patch level information Hardware information User and group File attribute (e.g., name, hash value, permissions, timestamp, size) File access System event (e.g., startup, shutdown, failures) Command history Antivirus products Hostname IP address MAC address Malware name Malware type (e.g., virus, hacking tool, spyware, remote access) File name File location (i.e., path) File hash Action taken (e.g., quarantine, clean, rename, delete) Web browsers Browser history and cache including: • Site visited • Object downloaded • Object uploaded • Browser extension installed or enabled • Cookies Other Data Sources Security Information and Event Management (SIEM) Summary reports synthesized from a variety of data sources (e.g., operating system, application, and network logs) Email systems Email messages: Email header content • Sender/recipient email address • Subject line • Routing information Attachments URLs Embedded graphic', 'vec_doc-03-nist-sp-800-150-p16-60', 0, 421, 'v2.1.0', 'f1b6ab810f9ccc0faff1f25a7bf4d190b4f9f9a98654e385a042462e029f4bd1', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":60,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p17-61', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.2 Identify Internal Sources of Cyber Threat Information', 17, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 9 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Source Examples Help desk ticketing systems, incident management/tracking system, and people from within the organization Analysis reports and observations regarding: • TTPs • Campaigns • Affiliations • Motives • Exploit code and tools • Response and mitigation strategies • Recommended courses of action User screen captures (e.g., error messages or dialog boxes) Forensic toolkits and dynamic and/or virtual execution environments Malware samples System artifacts (network, file system, memory) Organizations should update the inventory when new sensors, repositories, or capabilities are deployed or when significant changes to a device’s configuration, ownership, or administrative point of contact occur.', 'vec_doc-03-nist-sp-800-150-p17-61', 0, 216, 'v2.1.0', 'db85019ebf6f9a32979294cc29ecda577e7f6a966d02bf6dd1ae1c1290c15f35', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.2 Identify Internal Sources of Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":61,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.2 Identify Internal Sources of Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p17-62', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.3 Define the Scope of Information Sharing Activities', 17, 'Organizations should specify the scope of their information sharing activities by identifying the types of information available to share, the circumstances under which sharing this information is permitted, and those with whom the information can and should be shared. Organizations should review their information sharing goals and objectives while scoping information sharing activities to ensure that priorities are addressed. When defining these activities, organizations should ensure that the information sources and capabilities needed to support each activity are available. Organizations should also consider pursuing sharing activities that will address known information gaps. For example, an organization might not have an internal malware analysis capability, but it may gain access to malware indicators by participating in a sharing community. The breadth of information sharing activities will vary based on an organization’s resources and abilities.', 'vec_doc-03-nist-sp-800-150-p17-62', 0, 242, 'v2.1.0', '6c65be4a772d502774b9f8ad28d820e51e1ac888232de5385372c72dfabb5888', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.3 Define the Scope of Information Sharing Activities","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":62,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.3 Define the Scope of Information Sharing Activities"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p17-63', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.3 Define the Scope of Information Sharing Activities', 17, 'By choosing a relatively narrow scope, an organization with limited resources can focus on a smaller set of activities that provides the greatest value to the organization and its sharing partners. An organization may be able to expand the scope as additional capabilities and resources become available. Such an incremental approach may help to ensure that information sharing activities support an organization’s information sharing goals and objectives, while at the same time fit within available resources. Organizations with greater resources and advanced capabilities may choose a larger initial scope that allows for a broader set of activities in support of their goals and objectives. The degree of automation available to support the sharing and receipt of threat information is a factor to consider when establishing the scope of sharing activities.', 'vec_doc-03-nist-sp-800-150-p17-63', 0, 216, 'v2.1.0', '9f2d2b739b94e050d3c91b3a883a4a3e810f7542614c0e69bfdd521668a7c88e', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.3 Define the Scope of Information Sharing Activities","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":63,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.3 Define the Scope of Information Sharing Activities"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p17-64', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.3 Define the Scope of Information Sharing Activities', 17, 'Less automated approaches or manual approaches, which require direct human intervention, may increase human resource costs and limit the breadth and volume of information that can be processed. The use of automated exchange mechanisms can help reduce human resource costs, and allow an organization to exchange threat information on a larger scale. Automated threat information sharing concepts are further discussed in section 4.', 'vec_doc-03-nist-sp-800-150-p17-64', 0, 108, 'v2.1.0', 'b852df505985f7d8cf5d037d0f8f9444f271110d41982643a0f0ff6cde8d9fec', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.3 Define the Scope of Information Sharing Activities","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":64,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.3 Define the Scope of Information Sharing Activities"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p17-65', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 17, 'Before sharing threat information, organizations should: • List the types of threat information that may be shared.', 'vec_doc-03-nist-sp-800-150-p17-65', 0, 29, 'v2.1.0', 'd16bfd63d7d8472e662462e387c64e35f309897727858b057441c18fb6f5abf5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":65,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p18-66', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 18, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 10 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Describe the conditions and circumstances when sharing is permitted. • Identify approved recipients of threat information. • Describe any requirements for redacting or sanitizing information to be shared. • Specify if source attribution is permitted. • Apply information handling designations that describe recipient obligations for protecting information. Sharing rules help control the publication and distribution of threat information, and consequently help to prevent the dissemination of information that, if improperly disclosed, may have adverse consequences for the organization or its customers or business partners. Information sharing rules should take into consideration the trustworthiness of the recipient, the sensitivity of the shared information, and the potential impacts of sharing (or not sharing).', 'vec_doc-03-nist-sp-800-150-p18-66', 0, 244, 'v2.1.0', '8840e583ac13c38de633dff465ed658af41e3c44498ebb141b0b43227a1f441f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":66,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p18-67', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 18, 'For example, an organization may establish rules that limit the exchange of highly sensitive information to internal individuals or groups, that allow the sharing of moderately sensitive information with specific trusted partners, that permit information having a low sensitivity to be published within a closed sharing community, and that allow for the free exchange of non-sensitive information within public information sharing forums. Large organizations that want to share internal threat information across business units may also need to establish rules governing the exchange of threat information between organizational elements. Business units within an organization that either collect or process threat information should participate in scoping what types of threat information will be shared and how that will be done. The steps for establishing information sharing rules apply to internal sharing of threat information within large organizations.', 'vec_doc-03-nist-sp-800-150-p18-67', 0, 240, 'v2.1.0', 'd457c7a2bd9e77b063f0e92f9f4268baabefd834c3f126ff712a43d969cf9f44', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":67,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p18-68', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 18, 'Multinational corporations need to consider the differences in various nation’s privacy laws and how to address handling of classified information, which typically cannot be shared with foreign nationals. When establishing and reviewing information sharing rules, organizations should request input from their legal and privacy officials, information owners, the management team, and other key stakeholders to ensure that the sharing rules align with the organization’s documented policies and procedures. Sharing rules can specified in a variety of ways including, Memoranda of Understanding (MOUs), Non- Disclosure Agreements (NDAs), Framework Agreements5, or other agreements. Organizations are encouraged to proactively establish threat information sharing agreements as part of their ongoing cybersecurity operations rather than attempting to put such agreements into place while under duress in the midst of an active cyber incident.', 'vec_doc-03-nist-sp-800-150-p18-68', 0, 235, 'v2.1.0', 'ef26c06f7512c4ec9c9dacc3f6ee86cb1157407fce17c3ca0fea370ac9cdc008', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":68,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p18-69', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 18, 'An organization’s information sharing rules should be reevaluated on a regular basis. Some of the events that can trigger reevaluation are: • Changes to regulatory or legal requirements, • Updates to organizational policy, • Introduction of new information sources, • Risk tolerance changes, 5 An example of such an agreement is the Defense Industrial Base (DIB) Cyber Security/Information Assurance (CS/IA) Program standardized Framework Agreement [4] which implements the requirements set forth in Title 32 Code of Federal Regulations, Part 236, Sections 236.4 through 236.6.', 'vec_doc-03-nist-sp-800-150-p18-69', 0, 145, 'v2.1.0', '16e674b3968ef3708664376b9c5570de95806be8dd5c2667269694fa479e48b2', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":69,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p19-70', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 19, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 11 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Information ownership changes, • Changes in the operating/threat environment, and • Organizational mergers and acquisitions. 3.4.1  Information Sensitivity and Privacy Many organizations handle information that, by regulation, law, or contractual obligation, requires protection. This includes PII, CUI, and other sensitive information afforded protection under the Sarbanes-Oxley Act (SOX), the Payment Card Industry Data Security Standard (PCI DSS), the Health Information Portability and Accountability Act (HIPAA), the Federal Information Security Modernization Act of 2014 (FISMA), and the Gramm-Leach-Bliley Act (GLBA) and other legislation, regulations, and guidelines. Organizations should identify and properly protect such information.', 'vec_doc-03-nist-sp-800-150-p19-70', 0, 226, 'v2.1.0', '5d0475908f6aec66d2e8320b2a6a4af61e38a264ac9a871da05dd09720f00d96', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":70,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p19-71', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 19, 'An organization’s legal team, privacy officers, auditors, and experts familiar with the various regulatory frameworks should be consulted when developing procedures for identifying and protecting sensitive information. From a privacy perspective, one of the key challenges with threat information sharing is the potential for disclosure of PII6. Education and awareness activities are critical to ensure that individuals responsible for handling threat information understand how to recognize and safeguard PII.7 Internal sharing of information may result in disclosure of PII to people who, by virtue of their job functions, would not typically have routine access to such information. For example, a forensic analyst or incident responder may encounter PII while searching a hard drive for malware indicators, reviewing emails related to suspected phishing attacks, or inspecting packet captures.', 'vec_doc-03-nist-sp-800-150-p19-71', 0, 225, 'v2.1.0', '9903a1297935c8f46e1f3527aa4680dbbcee9fe0fc3d5e0bb4a5825a6fc56bde', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":71,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p19-72', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 19, 'The analyst has a legitimate need to review this information to investigate an exploit, develop detection strategies, or develop defensive measures. If the result of such an analysis is shared with others, steps should be taken to protect the confidentiality of PII. An organization should have information sharing policies and procedures in place that provide guidance for the handling of PII. These policies and procedures should include steps for identifying incident data types that are likely to contain PII. Policies should describe proper safeguards for managing the privacy risks associated with sharing such data. A common practice is to focus on the exchange of indicators to the maximum extent possible. Some indicators, such as file hashes, network port numbers, registry key values, and other data elements, are largely free of PII.', 'vec_doc-03-nist-sp-800-150-p19-72', 0, 212, 'v2.1.0', '4b695237f0fbbee95dbd3ec0909c14fc42a8294f3dacc748640921c05c831b8d', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":72,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p19-73', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 19, 'Where PII is identified, however, organizations should redact fields containing PII that are not relevant to investigating or addressing threats before sharing.8 The type and degree of protection applied should be based on the intended use of the information, the sensitivity of the information, and the intended recipient. 6 OMB Memorandum 07-16 [5] defines PII as “information which can be used to distinguish or trace an individual’s identity, such as their name, social security number, biometric records, etc. alone, or when combined with other personal or identifying information which is linked or linkable to a specific individual, such as date and place of birth, mother’s maiden name, etc.” OMB Memorandum 10-22 [6] further states that “the definition of PII is not anchored to any single category of information or technology. Rather, it demands a case-by-case assessment of the specific risk that an individual can be identified.', 'vec_doc-03-nist-sp-800-150-p19-73', 0, 236, 'v2.1.0', '5ce51cad5e93d659c1cb91ddbc5617509c28a4d6ba5aaef0105c5e9e7865d4ce', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":73,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p19-74', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 19, 'In performing this assessment, it is important for an agency to recognize that non-PII can become PII whenever additional information is made publicly available — in any medium and from any source — that, when combined with other available information, could be used to identify an individual.” NIST SP 800-122 [7] includes a slightly different definition of PII that is focused on the security objective of confidentiality and not privacy in the broad sense. Definitions of PII established by organizations outside of the federal government may vary based on the consideration of additional regulatory requirements. The guidance in this document applies regardless of how organizations define PII. 7 For additional guidance and examples of privacy controls, see NIST SP 800-53 Rev. 4, Appendix J, “Privacy Control Catalog, Privacy Controls, Enhancements, and Supplemental Guidance” [8].', 'vec_doc-03-nist-sp-800-150-p19-74', 0, 222, 'v2.1.0', '8347252d81194b61d1b2bbb840eb0b583b0d58b833533094bb0771c97fdaa3ab', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":74,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p19-75', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 19, '8 NIST SP 800-122 [7] describes a process called “de-identification” which entails the removal or obfuscation of PII, such that the remaining information cannot be used to identify an individual.', 'vec_doc-03-nist-sp-800-150-p19-75', 0, 49, 'v2.1.0', '73df83758290a9888bf0ff7579cf6f551db28b8e593614b6678b64f8b167ad74', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":75,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p20-76', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 20, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 12 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Where practical, organizations are encouraged to use automated methods rather than human-oriented methods to identify and protect PII. Manual identification, extraction, and obfuscation of PII can be a slow, error-prone, and resource-intensive process. Automated methods may include field-level data validation using permitted values lists, searching for PII using pattern matching techniques such as regular expressions, and performing operations that de-identify, mask, and anonymize data containing PII. The degree of automation that can be achieved will vary based on factors such as the structure, complexity, and sensitivity of the information. Organizations should also implement safeguards to protect intellectual property, trade secrets, and other proprietary information from unauthorized disclosure.', 'vec_doc-03-nist-sp-800-150-p20-76', 0, 241, 'v2.1.0', '59cf2a446f547ca65f7f60484da46a9015c1ef310ebafd06ebfea59f2c71dd33', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":76,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p20-77', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 20, 'The disclosure of such information could result in financial loss, violate NDAs or other sharing agreements, be cause for legal action, or damage an organization’s reputation. Organizations should have a plan in place to address the unauthorized or inadvertent disclosure of CUI. The plan should cover containment, control, and recovery procedures; breach notification requirements, and post-incident activities such as capturing lessons learned. Table 3-2 introduces selected types of threat information, provides examples of sensitive data that may be present in these types of threat information, and offers general recommendations for handling such data.', 'vec_doc-03-nist-sp-800-150-p20-77', 0, 165, 'v2.1.0', '57d9f5f5e80afd290d20bbe2713492d29bf2ecf10c7917167e70a347e59da75f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":77,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p20-78', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 20, 'Table 3-2:  Handling Recommendations for Selected Types of Sensitive Data Type of Threat Information Examples of Sensitive Data Elements9 Recommendations Network Indicators Any single network indicator can be sensitive, but network indicators in the aggregate are often more sensitive because they can reveal relationships between network entities. By studying these relationships it may be possible to infer the identity of users, gather information about the posture of devices, perform network reconnaissance, and characterize the security safeguards and tools that an organization uses. Focus on the exchange of network indicators such as destination IP addresses associated with an actor’s command and control infrastructure, malicious URLs/domains, and staging servers. Before sharing, anonymize or sanitize network indicators that contain IP or MAC addresses of target systems or addresses registered to your organization.', 'vec_doc-03-nist-sp-800-150-p20-78', 0, 233, 'v2.1.0', 'bfed346c468c69bb13ce36fa92fece4e84b860bd31c7f23097afc5c128fc36c3', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":78,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p20-79', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 20, 'Also anonymize or sanitize indicators that may reveal the structure of internal networks, or ports or protocols that identify particular products. 9 The PII confidentiality impact level as discussed in NIST SP 800-122 [7] is a useful tool for gauging sensitivity of PII.', 'vec_doc-03-nist-sp-800-150-p20-79', 0, 68, 'v2.1.0', '1fe7d50c0c6f4eea1f11cc2486a32221022819d7c832c4ec0b67f7116be69122', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":79,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p21-80', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 21, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 13 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Type of Threat Information Examples of Sensitive Data Elements9 Recommendations Packet Capture (PCAP) In addition to the network indicators previously discussed, unencrypted or decrypted packets may contain authentication credentials and sensitive organization information, such as PII, CUI or other types of sensitive information. PCAP files can be challenging because network indicators may be present within both the packet header and the payload. For example, PCAP files may show protocols (e.g., DHCP, Address Resolution Protocol (ARP), File Transfer Protocol (FTP), DNS) and applications operating at multiple layers within the network stack. These protocols and applications generate network information that may be captured within PCAP files and may require sanitization or anonymization to prevent sensitive information leakage.', 'vec_doc-03-nist-sp-800-150-p21-80', 0, 248, 'v2.1.0', 'e218462ab47dcdb93e55fb60473bd8857d0dee11a1aba5cd72c9e132f7b2ca99', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":80,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p21-81', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 21, 'Filter PCAP files before sharing by extracting only those packets that are related to the investigation of a specific incident or pattern of events: • Related to a particular network conversation (i.e., exchange of information between specific IP addresses of interest); • Occurring during a chosen time period; • Destined for, or originating from, a specific port; or • Use of a particular network protocol. Redact payload content that contains PII, CUI or other types of sensitive information that is not relevant for characterizing the incident or event of interest. When anonymizing or redacting network information, use a strategy that preserves enough information to support meaningful analysis of the resulting PCAP file contents. Network Flow Data Network flow data contains information such as: • Source IP address (i.e., the sender), • Destination IP address (i.e., the recipient), • Port and protocol information, • Byte counts, and • Timestamps.', 'vec_doc-03-nist-sp-800-150-p21-81', 0, 240, 'v2.1.0', 'c93b9746541a5f0c9f19177b1234a6a3d1a91f91623a9ed3acac27f853f0d8eb', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":81,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p21-82', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 21, 'If not effectively anonymized, network flow data may make identification of specific users possible, provide insights into user behavior (e.g., web sites visited), expose application and service usage patterns, or reveal network routing information and data volumes. Before sharing network flow data, organizations should consider redacting portions of session histories using cryptography-based, prefix- preserving, IP address anonymization techniques to prevent network identification or to conceal specific fields within the session trace (e.g., time stamps, ports, protocols, or byte counts). To gain the greatest value from the information, use a tool that transforms network flow data without breaking referential integrity. Network flow analysis and correlation operations often require that IP address replacement and transformation operations are performed consistently within and sometimes across multiple files.', 'vec_doc-03-nist-sp-800-150-p21-82', 0, 231, 'v2.1.0', 'ac7abfa466e35e09690b9518366e42a42459b1bfd00a4c09f291c66e6c333273', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":82,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p21-83', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 21, 'Anonymization techniques that do not use a consistent replacement strategy may reduce or eliminate the value of sharing this type of information.', 'vec_doc-03-nist-sp-800-150-p21-83', 0, 37, 'v2.1.0', '5abc5373255eefc1b6c797891c79b9f493e28338c0839da56e937da2fe7d2291', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":83,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p22-84', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 22, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 14 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Type of Threat Information Examples of Sensitive Data Elements9 Recommendations Phishing Email Samples Email headers may contain information such as: • Mail agent IP addresses, • Host or domain names, and • Email addresses. An email message body may also contain PII, CUI, or other types of sensitive information. Organizations should anonymize email samples and remove any sensitive information that is not necessary for describing an incident or event of interest. System, Network, and Application Logs Log files may contain PII, CUI or other types of sensitive information. Log data may reveal IP addresses, ports, protocols, services, and URLs, as well as connection strings, logon credentials, portions of financial transactions, or other activities captured in URL parameters.', 'vec_doc-03-nist-sp-800-150-p22-84', 0, 234, 'v2.1.0', 'f470a5b0962afc3d5598b7acd83489de2974a792466de0ace03b4ed67ad072e5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":84,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p22-85', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 22, 'Organizations should perform IP address, timestamp, port, and protocol anonymization and remove any sensitive information that is not necessary for describing an incident or event of interest. Before sharing log data, it may also be necessary to sanitize URLs that contain identifying information such as session or user identifiers. Application logs may require redaction and anonymizing operations that are specific to particular application log formats. Malware Indicators and Samples Although organizations are unlikely to encounter sensitive information in malware indicators or samples, sensitive information may be present depending on how targeted the malware is and what collection methods were used to gather a sample. Organizations should remove PII, CUI, and other types of sensitive information that is not necessary for describing an incident or event of interest. 3.4.2 Sharing Designations A variety of methods exist to designate handling requirements for shared threat information.', 'vec_doc-03-nist-sp-800-150-p22-85', 0, 250, 'v2.1.0', '09c6b4fefc648da033d44917c56aa705e678068f68c503dec910ec43b570cd07', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":85,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p22-86', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 22, 'These designations identify unclassified information that may not be suitable for public release and that may require special handling. A designation applied to threat information can communicate specific handling requirements and identify data elements that are considered sensitive and should be redacted prior to sharing. Organizations are encouraged to provide clear handling guidance for any shared threat information. Likewise, recipients of threat information should observe the handling, attribution, dissemination, and storage requirements expressed in the source organization’s handling guidance. The Traffic Light Protocol (TLP), depicted in Table 3-3, provides a framework for expressing sharing designations [9].', 'vec_doc-03-nist-sp-800-150-p22-86', 0, 182, 'v2.1.0', '27c1dfee9123112bb00f60c2f6c0da01ff61a7c6dcae5f09960cdab42b56c479', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":86,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p23-87', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 23, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 15 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Table 3-3:  Traffic Light Protocol, Version 1.0 Color When should it be used? How may it be shared? TLP:RED Not for disclosure, restricted to participants only. Sources may use TLP:RED when information cannot be effectively acted upon by additional parties, and could lead to impacts on a party''s privacy, reputation, or operations if misused. Recipients may not share TLP:RED information with any parties outside of the specific exchange, meeting, or conversation in which it was originally disclosed. In the context of a meeting, for example, TLP:RED information is limited to those present at the meeting. In most circumstances, TLP:RED should be exchanged verbally or in person. TLP:AMBER Limited disclosure, restricted to participants’ organizations.', 'vec_doc-03-nist-sp-800-150-p23-87', 0, 228, 'v2.1.0', '7cfb45a2a2168df8f270bd0f78f470983fdab7fac3298926afce0b814fc19f28', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":87,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p23-88', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 23, 'Sources may use TLP:AMBER when information requires support to be effectively acted upon, yet carries risks to privacy, reputation, or operations if shared outside of the organizations involved. Recipients may only share TLP:AMBER information with members of their own organization, and with clients or customers who need to know the information to protect themselves or prevent further harm. Sources are at liberty to specify additional intended limits of the sharing: these must be adhered to. TLP:GREEN Limited disclosure, restricted to the community. Sources may use TLP:GREEN when information is useful for the awareness of all participating organizations as well as with peers within the broader community or sector. Recipients may share TLP:GREEN information with peers and partner organizations within their sector or community, but not via publicly accessible channels. Information in this category can be circulated widely within a particular community.', 'vec_doc-03-nist-sp-800-150-p23-88', 0, 241, 'v2.1.0', 'a0e6979da5dea50be337f3b8288e2b8c142dbe63718819492b422bf70f15788c', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":88,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p23-89', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 23, 'TLP:GREEN information may not be released outside of the community. TLP:WHITE Disclosure is not limited. Sources may use TLP:WHITE when information carries minimal or no foreseeable risk of misuse, in accordance with applicable rules and procedures for public release. Subject to standard copyright rules. TLP:WHITE information may be distributed without restriction. The TLP specifies a color-coded set of restrictions that indicate which restrictions apply to a particular record. In the TLP, red specifies the most restrictive rule, with information sharable only in a particular exchange or meeting, not even within a participant’s own organization. The amber, green, and white color codes specify successively relaxed restrictions. The Anti-Phishing Working Group (APWG) has also proposed a schema for expressing sharing designations [10]. The APWG schema describes an extensible, hierarchical tagging system that can be used to express distribution restrictions on shared information.', 'vec_doc-03-nist-sp-800-150-p23-89', 0, 248, 'v2.1.0', '22640922e323831a8cc5b584881ac134f9cb6c2f66a96200d697e8302bd8e1a5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":89,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p23-90', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 23, 'The tags can be used to indicate with whom the information may or may not be shared (e.g., recipient only, with affected parties only, no restrictions) and to express other caveats (e.g., that no attribution is permitted). For some threat information, collection methods may be considered confidential or proprietary, but the actual indicators observed may be shareable. In such cases, an organization may want to use tear line reporting, an approach where reports are organized such that information of differing sensitivity is not intermingled (e.g., the indicator information is presented in a separate part of the document than the', 'vec_doc-03-nist-sp-800-150-p23-90', 0, 159, 'v2.1.0', 'b86d5bfc4420bb12df1a8579a83b83d750186586caeb23c02730beaf0ce0c6f7', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":90,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p24-91', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 24, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 16 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 collection methods). Organizing a report in this manner allows an organization to readily produce a report containing only information that designated recipients are authorized to receive. An organization should carefully choose, or formulate, an approach for expressing sharing designations. Regardless of how an organization expresses sharing designations, the procedures for applying designations to threat information should be documented and approved, and the personnel responsible for assigning such designations properly trained. 3.4.3 Cyber Threat Information Sharing and Tracking Procedures Over time, an organization’s cybersecurity activities can result in the accumulation of large quantities of threat information from various sources, both internal and external.', 'vec_doc-03-nist-sp-800-150-p24-91', 0, 233, 'v2.1.0', '8f9b955e187840c666ffd345242b648c443282512120583a10594f5089a732b2', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":91,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p24-92', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 24, 'Though challenging, tracking of data sources is important both for protecting information owners and for ensuring that consuming organizations can meet their legal or regulatory commitments for data protection. Organizations should also preserve the provenance of data by tracking who provided the information and how the information was collected, transformed, or processed, information that is important for drawing conclusions from shared information. An organization should formulate procedures that allow prompt sharing of threat information while at the same time satisfying its obligations for protecting potentially sensitive data. The procedures should, to the extent possible, balance the risks of possibly ineffective sharing against the risks of possibly flawed protection. An organization’s information sharing and tracking procedures should: • Identify threat information that can be readily shared with trusted parties.', 'vec_doc-03-nist-sp-800-150-p24-92', 0, 234, 'v2.1.0', 'f6d87e6f6553436503b446565d581e4bf6c8703b9a9e076255c393f89d78d72e', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":92,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p24-93', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.4 Establish Information Sharing Rules', 24, '• Establish processes for reviewing, sanitizing, and protecting threat information that is likely to contain sensitive information. • Develop plan for addressing leakage of sensitive data. • Automate the processing and exchange of threat information where possible. • Describe how information handling designations are applied, monitored, and enforced. • Accommodate non-attributed information exchange, when needed. • Track internal and external sources of threat information. The procedures should describe the roles, responsibilities, and authorities (both scope and duration) of all stakeholders. The procedures should allow for the effective transfer of authority and flow of shared information to key decision makers and should enable collaboration with approved external communities when needed.', 'vec_doc-03-nist-sp-800-150-p24-93', 0, 201, 'v2.1.0', '3c92b8c94bd4badd800b221c04486e9c276c5a324abe88c9665919f2bfe90ed6', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.4 Establish Information Sharing Rules","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":93,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.4 Establish Information Sharing Rules"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p24-94', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 24, 'When evaluating potential sharing partners, an organization should look to sources that complement its existing threat information resources or that offer actionable information that addresses known gaps in an organization’s situational awareness. Since sharing communities may focus on the exchange of a specific type of threat information, an organization may need to participate in multiple information sharing forums to meet its information sharing objectives. Threat information can be acquired from public and private sharing communities, government repositories, across the organization, commercial threat information feeds, and open sources. Sharing communities often organize around a shared characteristic or interest. The composition of a community', 'vec_doc-03-nist-sp-800-150-p24-94', 0, 190, 'v2.1.0', 'a83a2d422863e13b2771aa314b15b16d152a938594e58ab0aa7a15273c65415d', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":94,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p25-95', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 25, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 17 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 may be based on geographic region, political boundary, industrial sector, business interest, or threat space (e.g., focused on phishing attacks). Many of these communities have multinational constituencies and global reach. Examples of potential sharing partners are ISACs, domestic and foreign Computer Emergency Readiness Teams (CERTs) or CSIRTs, Information Sharing and Analysis Organizations (ISAOs), DHS Automated Indicator Sharing (AIS) initiative, threat and vulnerability repositories, law enforcement agencies, product vendors, managed security service providers, internet service providers, supply chain partners, industry sector peers, business partners, and customers. Some communities are informal, open, self-organizing groups that largely operate through voluntary cooperation.', 'vec_doc-03-nist-sp-800-150-p25-95', 0, 237, 'v2.1.0', 'c748ce23ed704fd94c28405adf8c399a05c975630c27898ef9ada0bf397f9ffe', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":95,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p25-96', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 25, 'The membership of these communities is often mutable (i.e., no formal fixed membership), sometimes anonymous, and the members may maintain full autonomy with minimal central coordination. These communities generally operate under basic rules of conduct rather than formal agreements. In such communities, members publish threat information to the community on a voluntary, ad hoc basis and are individually responsible for ensuring that the content provided to the community is suitable for sharing. Organizations wishing to consume information can subscribe to or access various delivery mechanisms offered by a community such as web services, email or text alerts, and RSS feeds. Such sharing communities generally make no assertions regarding the quality and accuracy of data provided by their members, and the degree to which the information should be trusted depends on the reputation of submitters (if known).', 'vec_doc-03-nist-sp-800-150-p25-96', 0, 229, 'v2.1.0', '1fb79c65ecee3758bd4b65ce9f27145c2e2b3ecf12905f07d26298dbf1120b59', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":96,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p25-97', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 25, 'In contrast, formal sharing communities may define specific membership rules such as: • Membership fee structures; • Eligibility requirements for institutions (e.g., must operate within a specific industry sector); • Eligibility requirements for individuals (e.g., must have enterprise-wide security responsibilities); • Nomination or sponsorship requirements (i.e., brokered trust); • Probationary membership period requirements; • Types of threat information the community provides/accepts; • Standard delivery mechanisms, formats, and protocols supported by the community; and • Required organizational cybersecurity capabilities. Formal communities may recruit members by invitation or through sponsorship, and, as such, members are vetted. Membership rosters in formal communities are generally more stable than those of informal communities.', 'vec_doc-03-nist-sp-800-150-p25-97', 0, 212, 'v2.1.0', 'b33bcee93c12b89a4ea370c889f1fbdc408932fab32300c83992410e20020658', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":97,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p25-98', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 25, 'The exchange of information in a formal community is often governed through service level agreements (SLAs), NDAs, and other agreements that describe the responsibilities of its members and participating organizations. Some communities collect an annual membership fee to cover the services and administrative costs of the community. These fees vary by community and the fee structure is sometimes tiered, providing for different levels of membership and service. Before entering into information sharing agreements, an organization should obtain approval from the: • Leadership team that has oversight for information sharing activities and for controlling the resources necessary to support the organization’s information sharing goals;', 'vec_doc-03-nist-sp-800-150-p25-98', 0, 185, 'v2.1.0', '6066c707f3db6a4aeb77c3235158e71d7e7ec99f8a354a19b3ed821d33f8cd79', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":98,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p26-99', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 26, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 18 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Legal team or those with the authority to enter into commitments; and • Privacy officers and other key stakeholders that have a role in the collection, ingest, storage, analysis, publication, or protection of threat information. When choosing a sharing community, consideration should be given to the types of information that are shared within the community, the structure and dynamics of the community, and the cost of entry and sustainment of membership. When evaluating how information is shared within a community, an organization should consider the following questions: • Is the threat information shared within the community relevant and does it complement existing threat information by providing meaningful insights in the context of an organization’s threat environment?', 'vec_doc-03-nist-sp-800-150-p26-99', 0, 235, 'v2.1.0', '4ddb7dad256caa17ce194df4d5fb7c78079c9b50691d506f81f8eafd9fd20164', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":99,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p26-100', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 26, '• Is the threat information exchanged within the community actionable? • Does the community have mechanisms in place to accept non-attributed threat information submissions and the ability to protect a submitter’s identity? • Is the threat information timely, reliable, and of known good quality? • Are the information exchange formats used by the community compatible with the infrastructure and tools used in an organization? • Given the frequency and volume of data sent by a community, does an organization have the capacity to ingest/analyze/store the information? In addition to the information shared within a community, consideration should also be given to the dynamics of the community and its participants, including: • What is the size and composition of the community? (e.g., number of participants, information producers, and information consumers) • How active is the community? (e.g., number of submissions or requests per day) • Are community members recruited and vetted? If so, how?', 'vec_doc-03-nist-sp-800-150-p26-100', 0, 251, 'v2.1.0', '52808a4b834ca7b7bd98f0e938b9c4dfb455f642ceb956281cf7574d2a461324', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":100,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p26-101', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.5 Join a Sharing Community', 26, '• What are the technical skills and proficiencies of the community members? • What is the community’s governance model? • What are the initial and sustained costs of membership? • What type of sharing agreement does the community use? • Is the sharing agreement well-aligned with an organization’s goals, objectives, and business rules? • What are the community’s data retention and disposal policies? When researching sharing communities, organizations are encouraged to have conversations with current or former members regarding their experiences as a participant in a community. Such conversation can provide additional insight and help an organization assess the trustworthiness of a prospective community.', 'vec_doc-03-nist-sp-800-150-p26-101', 0, 178, 'v2.1.0', 'ac186e2b806857cfdf5310a2bcb94ca2e8d9d20b70b4eba74fdb46fed486c683', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.5 Join a Sharing Community","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":101,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.5 Join a Sharing Community"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p26-102', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.6  Plan to Provide Ongoing Support for Information Sharing Activities', 26, 'Organizations should develop a support plan that addresses information sharing infrastructure maintenance and user support. The plan should identify the personnel, funding, infrastructure, and processes needed to:', 'vec_doc-03-nist-sp-800-150-p26-102', 0, 54, 'v2.1.0', '6f0685d4ffba96fe4419109060115f0b2420046b622082d90ffb595d0bc2f738', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.6  Plan to Provide Ongoing Support for Information Sharing Activities","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":102,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.6  Plan to Provide Ongoing Support for Information Sharing Activities"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p27-103', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.6  Plan to Provide Ongoing Support for Information Sharing Activities', 27, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 19 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Collect and analyze the information from both internal and external sources, • Acquire and deploy protective measures, and • Acquire and deploy a monitoring and threat detection infrastructure. Organizations should provide funding for the personnel, infrastructure, and training required for ongoing operational support for data collection, storage, analysis, and dissemination; for technology refreshment; and for membership or service fees required for community participation. Although participation in information sharing activities will require ongoing funding, effective use of threat information may avoid the potentially much larger costs of successful attacks.', 'vec_doc-03-nist-sp-800-150-p27-103', 0, 207, 'v2.1.0', '82f50df339e43958fa77e599c52f7de05cbacbb6a1fd38a3d54183a1bd9e8d56', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.6  Plan to Provide Ongoing Support for Information Sharing Activities","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":103,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.6  Plan to Provide Ongoing Support for Information Sharing Activities"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p28-104', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '3.6  Plan to Provide Ongoing Support for Information Sharing Activities', 28, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 20 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'vec_doc-03-nist-sp-800-150-p28-104', 0, 39, 'v2.1.0', 'be7e8df8c7aff82cbb99963ceb9edfaf93774562f2777f9fa74e0787254c7740', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"3.6  Plan to Provide Ongoing Support for Information Sharing Activities","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":104,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"3.6  Plan to Provide Ongoing Support for Information Sharing Activities"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p28-105', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4. Participating in Sharing Relationships', 28, 'An organization’s participation in an information sharing community will typically include some or all of the following activities: • Engage in ongoing communication (section 4.1), • Consume and respond to security alerts (section 4.2), • Consume and use indicators (section 4.3), • Organize and store indicators (section 4.4), and • Produce and publish indicators (section 4.5). The following sections describe these activities in greater detail. Organizations just starting their threat information sharing efforts should initially choose one or two activities to focus on and should consider adding activities as their information sharing capability matures. Organizations should understand that threat information sharing augments—not replaces—an organization’s fundamental cybersecurity capabilities, regardless of the maturity of their information sharing practices.', 'vec_doc-03-nist-sp-800-150-p28-105', 0, 218, 'v2.1.0', '9ca9909d1aa0685392666b69b2b864eb19d1fa7c097e6f5c2523d782e2133409', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4. Participating in Sharing Relationships","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":105,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4. Participating in Sharing Relationships"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p28-106', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.1 Engage in Ongoing Communication', 28, 'Information sharing communities use a variety of communications methods to share threat information with their members. Most organizations can receive threat information via email lists, text alerts, and web portals without infrastructure investments specific to information sharing, although the content received through these delivery channels may need to be manually processed (e.g., “cut and paste” into tools). Organizations with security tools that support standard data formats can use standards-based data feeds that enable semi-automated ingest, processing, and use of threat information. Other information sharing methods, such as conferences and workshops, require dedicated staff and travel. Organizations that actively produce and share threat information are likely to incur higher communication costs. Communications may be event-driven (i.e., in response to the actions or behavior of an actor) or periodic, such as bi-weekly reviews, teleconferences, and annual conferences.', 'vec_doc-03-nist-sp-800-150-p28-106', 0, 248, 'v2.1.0', '987b5186fc77131e601c534bf209fdabed4f7322bc19d489a2cee8e2f94af1b5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.1 Engage in Ongoing Communication","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":106,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.1 Engage in Ongoing Communication"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p28-107', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.1 Engage in Ongoing Communication', 28, 'The level of detail, volume, and frequency of messages delivered in human-readable formats varies widely across information sharing communities. Some communities seek to deliver the most current threat information with minimal latency. In contrast, some recipients using threat information for trending and analysis may prefer summary data and may have no need for near real-time delivery of detailed information. To reduce the number of messages generated, sharing communities sometimes provide the option of subscribing to digests (i.e., compilations of messages over time intervals) rather than receiving individual messages. An organization that has recently joined an information sharing community may require time to integrate new threat information sources into its existing cybersecurity practices, configure security tools, and train decision makers on how to interpret and act upon the threat information.', 'vec_doc-03-nist-sp-800-150-p28-107', 0, 229, 'v2.1.0', 'd1b6ebc4226534d5375cd1901070f60cde93dbb7d68bd0d23b06a26202f2d8ef', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.1 Engage in Ongoing Communication","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":107,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.1 Engage in Ongoing Communication"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p28-108', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.1 Engage in Ongoing Communication', 28, 'During this ramp-up period, an organization should consult any best practices guidance offered by a community, observe and learn from the interactions of more experienced members, and query community support resources (e.g., community knowledgebase, FAQs, blogs). Community-sponsored training events also provide opportunities for less mature organizations and inexperienced employees to gain practical insights from skilled practitioners. Organizations should also establish recruitment and retention processes that reduce personnel turnover and foster the formation of trusted professional relationships between sharing communities and organizations. Retention of skilled staff mitigates the loss of institutional knowledge, and preserves investments in training.', 'vec_doc-03-nist-sp-800-150-p28-108', 0, 192, 'v2.1.0', 'abc95f3ce7571fd987967f1e9ed6560e3512edb69b3e051f3c2d5a6b85aa62b7', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.1 Engage in Ongoing Communication","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":108,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.1 Engage in Ongoing Communication"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p29-109', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.1 Engage in Ongoing Communication', 29, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 21 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Ongoing participation in a sharing community is essential for fostering trust, establishing stronger ties to other members, and continuously improving practices. Organizations that actively participate in community-sponsored conference calls and face-to-face meetings are better able to establish trust with other members and consequently to effectively collaborate over time.', 'vec_doc-03-nist-sp-800-150-p29-109', 0, 133, 'v2.1.0', '71d656aa4ed78358e6807b458c32a2579d20e3a37207f3ccbdaf292718d1cbab', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.1 Engage in Ongoing Communication","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":109,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.1 Engage in Ongoing Communication"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p29-110', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.2 Consume and Respond to Security Alerts', 29, 'An information sharing community may publish security alerts notifying community members of emerging vulnerabilities, exploits, and other security issues. Fields that commonly appear in security alerts such as US-CERT alerts, NVD vulnerability advisories, and vendor security bulletins include10: • Brief overview/executive summary and detailed description, which would include indicators; • Platforms affected (e.g., operating system, application, hardware); • Estimated impact (e.g., system crash, data exfiltration, application hijacking)11; • Severity rating (e.g., Common Vulnerability Scoring System (CVSS) [11]); • Mitigation options, including permanent fixes and/or temporary workarounds; • References for more information; and • Alert metadata (e.g., alert creation and modification dates, acknowledgments). Upon receipt of a security alert, an organization should determine if the alert came from a trusted, reliable source.', 'vec_doc-03-nist-sp-800-150-p29-110', 0, 234, 'v2.1.0', 'd4ccd7216c480c797c5f5a9caeff6809988a08ff45651a1b0ee85a32064db6dc', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.2 Consume and Respond to Security Alerts","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":110,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.2 Consume and Respond to Security Alerts"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p29-111', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.2 Consume and Respond to Security Alerts', 29, 'When alerts originate from unknown or untrusted sources, organizations may need to apply greater scrutiny and/or seek independent confirmation before taking action. If an alert is deemed credible and it applies to systems, applications, or hardware that the organization owns or operates; the organization should determine a suitable course of action. When determining a proper response, an organization should characterize the overall impact of an alert by assessing factors such as the severity of the alert, the number of affected systems within the organization, the effects an attack might have on the organization’s mission-critical functions, and any operational impacts related to the deployment of mitigating security controls. This assessment should inform the prioritization and approach for response actions.', 'vec_doc-03-nist-sp-800-150-p29-111', 0, 205, 'v2.1.0', 'f9f3102afd74ce34774c4ab84653494948eaa8fa5bcc9918a02e7d945870f3e5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.2 Consume and Respond to Security Alerts","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":111,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.2 Consume and Respond to Security Alerts"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p29-112', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.2 Consume and Respond to Security Alerts', 29, 'Response actions include activities such as identifying and extracting indicators from an alert, using indicators to develop and deploy detection signatures, making configuration changes, applying patches, notifying personnel of threats, and implementing or enhancing security controls. Extracting indicators is largely a manual process today but there are clear incentives for automating indicator handling workflows. Manual processing of indicators can be time- consuming, tedious, error-prone, and slow; automation of the activities allows analysts to focus on the interpretation of information, rather than routine data manipulations.', 'vec_doc-03-nist-sp-800-150-p29-112', 0, 160, 'v2.1.0', '6ca399e53e72c7170c7105d0ff5debf16bfe1d56e9bc666d002ba153b8b0eefa', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.2 Consume and Respond to Security Alerts","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":112,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.2 Consume and Respond to Security Alerts"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p29-113', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 29, 'The consumption and use of indicators from external feeds is often a multi-step process that includes some, if not all, of the following activities: 10 Source: US-CERT (https://www.us-cert.gov/). 11 A more extensive list of potential effects is given in the MITRE Common Weakness Enumeration (http://cwe.mitre.org/) and Common Vulnerabilities and Exposures (http://cve.mitre.org/) listings.', 'vec_doc-03-nist-sp-800-150-p29-113', 0, 98, 'v2.1.0', 'da3d89cf3803b0d9ce7a3be449239d1ad20282f2867279801e659a56cdef6aee', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":113,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p30-114', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 30, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 22 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 • Validation: verifying the integrity of indicator content and provenance through digital signatures, c ryptographic hashes, or other means. • Decryption: transforming encrypted indicator files or data streams back to their original format. • Decompression: unpacking compressed indicator files, archive files (e.g., zip, tar), or data streams. • Content extraction: parsing indicator files and extracting indicators of interest to an organization.12 • P rioritization: processing indicators based on relative importance, the perceived value of a data source, the overall confidence in the data, any operational requirements that specify that data sources be processed in a particular order, the amount of effort required to transform the data into actionable information, or other factors.', 'vec_doc-03-nist-sp-800-150-p30-114', 0, 236, 'v2.1.0', 'c82e8703cc13b081cea148250a8a28f8165a9732e993a2470aca44d84a42c9f8', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":114,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p30-115', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 30, '• Categorization: reviewing indicator metadata to determine its security designation and handling requirements. Sensitive information may require encrypted storage, more stringent access control, or limitations on distribution. These activities are typically performed in the order described above, but the order may vary based on specific operational or security requirements. Where feasible, organizations are encouraged to use automated techniques to make the indicators available more quickly and reduce manual effort. In cases where indicators are being informally shared, such as through email, indicator prioritization and categorization are still important and should be performed by the recipient. Ideally, indicators are: • Timely. Indicators should be delivered with minimal latency thereby allowing additional time for r ecipients to prepare suitable responses.', 'vec_doc-03-nist-sp-800-150-p30-115', 0, 219, 'v2.1.0', '7ef9a9495f6f15de82b2621068a8da053e0fd05c85d0dcb8dd1e60d01d62ffa5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":115,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p30-116', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 30, 'The time criticality of indicators depends on the characteristics of the threats, including their severity, speed, and ease of propagation, the i nfrastructure being targeted, the TTPs being used, and the capabilities of the actor(s). • Relevant. Indicators should be applicable to a recipient’s operating environment and address threats t he organization is likely to face. The unnecessary processing of extraneous indicators creates a dditional work for analysts and slows down prioritization and categorization actions. • Accurate. Indicators should be correct, complete, and unambiguous. Inaccurate or incomplete information introduces uncertainty and may prevent critical action, stimulate unnecessary action, result in ineffective responses, or instill a false sense of security. Recipients should be made aware of any uncertainty or caveats regarding the accuracy of an indicator. • Specific.', 'vec_doc-03-nist-sp-800-150-p30-116', 0, 225, 'v2.1.0', 'd8cae34fd38a740106dbb1d4f3e85a0bc6d96208a7d3ab3f33969219fc2be2e9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":116,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p30-117', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 30, 'Indicators should provide clear descriptions of observable events that recipients can use to d etect threats while minimizing false positives/negatives. • Actionable. Indicators should provide enough information and context to allow recipients to develop a suitable response. In practice, an indicator may exhibit some, but not all, of these characteristics. For example, a lone indicator may be ambiguous, but when aggregated and analyzed with threat information from other 12 The extraction and handling of content like malware samples should be limited to organizations and individuals who have the knowledge, ability, and infrastructure needed to safely analyze malware. Special handling precautions should be stated and followed to prevent inadvertent introduction of malicious code onto production networks.', 'vec_doc-03-nist-sp-800-150-p30-117', 0, 204, 'v2.1.0', '9b966ec142f5cf13aff0c58659355ad0f9d9acd9b5dd4c6818bc7977f9105431', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":117,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p31-118', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 31, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 23 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 sources the indicator is enriched and demonstrates additional value. Also threat information from multiple sources may vary in precision and accuracy and it is important for users to be able to evaluate the information and assign tags that describe the quality or confidence level of the information. The tags are especially important when an organization needs to resolve discrepancies between threat information sources. As organizations enrich indicators, any new insights should be shared so that the entire community may benefit.', 'vec_doc-03-nist-sp-800-150-p31-118', 0, 172, 'v2.1.0', 'a5d343815697d93ab1245ecde6a386e67d9d3e7195ce6f4527f704bd351a14b9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":118,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p31-119', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 31, 'Organizations may, for example, use externally and internally-generated indicators to: • Add or modify rules or signatures used by firewalls, intrusion detection systems, data loss prevention systems, and/or other security controls to block or alert on activity matching the indicators (for example, connections involving IP addresses on a blacklist); • Configure security information and event management solutions or other log management-related systems to help with analysis of security log data; • Scan security logs, systems, or other sources of information, using indicators as search keys, to identify systems that may have already been compromised; • Find matching records when investigating an incident or potential incident to learn more about a threat, and to help hasten incident response and recovery actions; • Provide additional information to security operations center analysts; • Educate staff on threat characteristics; and • Identify threat trends that may suggest changes to security controls are needed.', 'vec_doc-03-nist-sp-800-150-p31-119', 0, 257, 'v2.1.0', '049269b7444dfa821753f5b9fee7b15754d1ad73dbd4e8f3bc4372ad736b04c2', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":119,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p31-120', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 31, 'Typically, an organization’s willingness to use indicators from external sources is strongly affected by the level of trust the organization has in the source. Indicators received from a trusted source might be put to immediate use to detect and respond to a threat. In contrast, indicators originating from an untrusted source may require independent validation, additional research, or testing before use. Indicator use might also be affected by other factors, such as an organization’s tolerance for service disruptions. For some organizations, security is paramount and occasionally blocking benign activity is considered acceptable. For other organizations, service availability may be so important that possible malicious activity might only trigger monitoring. An organization should carefully consider the characteristics of indicators that it receives and should take a risk-based approach to determining how indicators can be most effectively used.', 'vec_doc-03-nist-sp-800-150-p31-120', 0, 240, 'v2.1.0', '3cf0cf671103c3cc540aafd4d4b77def58bf9a256927a34d2d171eaae853f463', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":120,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p31-121', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.3 Consume and Use Indicators', 31, 'An organization may find that a specific indicator is useful in some situations but not in others. Ultimately each organization must decide how to best use indicators.', 'vec_doc-03-nist-sp-800-150-p31-121', 0, 42, 'v2.1.0', '988c801435c90985ff0e0522ed4019946f39aedaa9dbccc354da7506b6cfc44c', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.3 Consume and Use Indicators","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":121,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.3 Consume and Use Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p31-122', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.4 Organize and Store Cyber Threat Information', 31, 'Organizations may collect indicators from a variety of sources, including open source repositories, commercial threat feeds, and external partners. Depending on how indicators are being used, there may be a need to organize them in a knowledgebase. Free-form methods such as wikis can be quite flexible and suitable for developing working notes and indicator metadata. Structured databases are also useful for storing, organizing, tracking, querying, and analyzing collections of indicators.', 'vec_doc-03-nist-sp-800-150-p31-122', 0, 123, 'v2.1.0', 'ca8ce93965f7e5f6b752882e3e8e6a93c88a22e1e37e7a828e34c9466b9bca99', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.4 Organize and Store Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":122,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.4 Organize and Store Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p32-123', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.4 Organize and Store Cyber Threat Information', 32, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 24 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Information commonly recorded in a knowledgebase includes the following, when known: • Source of an indicator; • Rules governing the use or sharing of an indicator; • Date or time an indicator was collected; • Length of time that an indicator is still considered valid; • Whether or not attacks associated with an indicator have targeted specific organizations or sectors; • Any Common Vulnerability Enumeration (CVE), Common Platform Enumeration (CPE), Common Weakness Enumeration (CWE), Common Configuration Enumeration (CCE) records associated with an indicator; • Groups or actors associated with an indicator; • Aliases of any associated actors; • TTPs commonly used by an actor; • Motives or intent of an associated actor; • Individuals or types of individuals targeted in associated attacks; and • Systems targeted in attacks.', 'vec_doc-03-nist-sp-800-150-p32-123', 0, 247, 'v2.1.0', 'c84e82bab1f50e39885dd8aebca1bb34066aa9425239cb46dc7b0d71599a69c0', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.4 Organize and Store Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":123,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.4 Organize and Store Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p32-124', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.4 Organize and Store Cyber Threat Information', 32, 'An indicator knowledgebase is an attractive target of attack; therefore effective security practices should be followed, including implementing access controls, performing regular backups, maintaining operating system and application software by installing current patches, verifying secure configurations, and following software development best practices for the production of any in-house software used for the knowledgebase.13 Organizations should establish policies and procedures that address the disposition of indicators (and threat information in general). Policies and procedures should define data retention requirements for short (online) and long (offline) term availability of indicator information. Information handling and retention requirements may change once threat information is entered into evidence.', 'vec_doc-03-nist-sp-800-150-p32-124', 0, 206, 'v2.1.0', '52400004b2cb21de16693799f0baeae316ac3e997df497ae796747743b281849', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.4 Organize and Store Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":124,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.4 Organize and Store Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p32-125', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.4 Organize and Store Cyber Threat Information', 32, 'Evidence acquired during any incident investigations, for instance, should be collected and preserved using best practices for data preservation following chain of custody requirements and other laws pertaining to the submission of evidence. A more detailed treatment of forensic techniques related to chain of custody and preserving information integrity is available in NIST Special Publication 800-86 [12] and Section 3.3.2 of NIST Special Publication 800-61 [1]. For indicators that are not needed as evidence, organizations should determine proper retention policies.14 Although retaining threat information has costs, detailed information may provide historical value as well as help new sharing community members and partners understand the persistence and evolution of different actors and attack types. Other considerations, such as financial, legal, contractual, or regulatory issues, may limit data retention to a fixed period of months or years.', 'vec_doc-03-nist-sp-800-150-p32-125', 0, 240, 'v2.1.0', 'ad1b6f4b691c0ea629cf13f73c92aa7f9eb26ab112d66262d618a5dcfa10564f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.4 Organize and Store Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":125,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.4 Organize and Store Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p32-126', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.4 Organize and Store Cyber Threat Information', 32, 'Once a retention schedule is identified, organizations should either archive or destroy the indicators per applicable policies.15 13 The NIST Software Assurance Metrics and Tool Evaluation (SAMATE) project seeks to develop standard evaluation measures and methods for software assurance. See http://samate.nist.gov/index.php/SAMATE_Publications.html. 14 Federal agencies are subject to the National Archives and Records Administration (NARA) General Records Schedule as well as agency-specific retention policies. 15 NIST SP 800-88 [14] provides guidance to assist organizations in making risk-based decisions regarding the sanitization and disposition of media and information.', 'vec_doc-03-nist-sp-800-150-p32-126', 0, 170, 'v2.1.0', 'e216463666f73eae041b1013205a0101d145f02b4fa34b43ca8d54caa966b51e', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.4 Organize and Store Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":126,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.4 Organize and Store Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p33-127', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.4 Organize and Store Cyber Threat Information', 33, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 25 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150', 'vec_doc-03-nist-sp-800-150-p33-127', 0, 39, 'v2.1.0', 'fc32dd7cf8360d3731b1a33515c09b87d6665c69a122cad5dbfaa2d683865be6', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.4 Organize and Store Cyber Threat Information","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":127,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.4 Organize and Store Cyber Threat Information"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p33-128', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 33, 'Many organizations only consume indicators. However, some organizations, often those with more advanced security capabilities, choose to produce and publish their own indicators. An organization may benefit substantially by producing threat information. For example, an organization may gain greater expertise, help other organizations more effectively respond to threats in their environments, and foster trust with other community members. These effects are important for building and sustaining the flow of threat information that ultimately benefits a producing organization. A producer of shared threat information must decide what, if any, metadata should accompany shared information, what data formats should be used, how sensitive data should be handled, and how information sharing rules should be updated over time. The following subsections address these issues.', 'vec_doc-03-nist-sp-800-150-p33-128', 0, 219, 'v2.1.0', 'b084c94813f1a6ea18a9d3fcafb4c6cfa9e80ac71a99bc184d74d6409635ff49', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":128,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p33-129', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 33, '4.5.1 Indicator Enrichment Indicators that are produced and published should include metadata that provides context for each indicator, describes how the indicator is to be used and interpreted and how the indicator relates to other indicators. Metadata may also include sensitivity designations and provenance information (e.g., what tool was used to acquire the data, how the data was processed, who collected the data). As indicators are created, aggregated, or enriched, their sensitivity and classification should be reevaluated. An aggregation, association, or enrichment process may enable re-identification (e.g., using data mining techniques) or elevate the sensitivity of the information, thus necessitating additional data handling restrictions. The indicator production process should provide a mechanism for publishing indicators, updating indicators and associated metadata, and retracting submissions that are incorrect or perhaps inadvertently shared.', 'vec_doc-03-nist-sp-800-150-p33-129', 0, 242, 'v2.1.0', '660111bb73ad1c83d2b08f49f6ef1cf3b608cb8f6062cf82fbe20b1deecff394', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":129,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p33-130', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 33, 'Any automated mechanisms should be hardened and tested to ensure that they do not become viable attack vectors for threat actors. Organizations that share indicators should provide a feedback mechanism that allows sharing partners to submit error reports, suggest improvements, or request additional information about the indicators. Such feedback plays an important role in the enrichment, maturation, and quality of the indicators shared within a community. Some information shared within a community may be marked as “currently under investigation” and may require that members avoid sharing beyond the collective; such markings may also prohibit members from performing active information collection (such as retrieving malware samples from a suspect website, or performing DNS lookups on suspect hostnames) that might tip off a potential actor or otherwise compromise investigative activities.', 'vec_doc-03-nist-sp-800-150-p33-130', 0, 225, 'v2.1.0', 'fa5bafff9cf7cf9dd42c782b8b594732a9e6d7a7e75b07c8baea9f4747cf2fb5', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":130,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p33-131', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 33, 'At some point, such information will probably have its distribution and investigation restrictions downgraded, so a mechanism to change the marking or to add a revised marking such as “downgraded to GREEN as of 12/20/2015” is useful. 4.5.2 Standard Data Formats The use of standard data formats for the exchange of indicators enhances interoperability and allows information to be exchanged with greater speed. Unstructured formats (e.g., text documents, email) are suitable for high-level threat reports and ad hoc exchanges of indicator information and other materials intended to be read by security personnel rather than machines. For time-critical exchanges of indicators, however, such as automatically configuring a firewall to block specified communications, the use of standard data formats is encouraged because such formats reduce the need for human assistance.', 'vec_doc-03-nist-sp-800-150-p33-131', 0, 218, 'v2.1.0', 'c59bf8ed9b7301ccf143afc605be8492d2ad0cb6c9cb8b6e5c9c7dd34ad8f526', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":131,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p33-132', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 33, 'Organizations are encouraged to participate in threat information sharing standards development activities by sharing use cases, identifying desired features, and providing feedback to standards development', 'vec_doc-03-nist-sp-800-150-p33-132', 0, 52, 'v2.1.0', '4101ef91e09bed8a5682695c1cf4af994b9c7e5a3d431a8d7a1c868d75d90e8f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":132,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p34-133', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 34, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 26 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 organizations.16 Organizations should seek out data formats and exchange protocols that can effectively support their key threat information sharing use cases, demonstrate a high degree of maturity, broad adoption, and enable interoperability between a wide range of products and/or organizations. 4.5.3 Protection of Sensitive Data The indicators that an organization publishes may be sensitive, so proper safeguards should be used to prevent unauthorized disclosure or modification. Indicator data can be protected using a variety of methods, including encrypted network communications, authentication and authorization mechanisms, and storage in a hardened repository. If a repository is used, an organization should have a written SLA for the repository that specifies expected availability, security posture requirements, and acceptable use policies. When producing indicators that may contain sensitive information, proper sharing rules (see section 3.4) should be followed, and information should be shared only with community members that are trusted to follow sharing rules and that have agreed to do so. 16 For example, cyber threat information sharing standards development activities have been conducted in both the Organization for the Advancement of Structured Information Standards (OASIS) and Internet Engineering Task Force (IETF) standards organizations.', 'vec_doc-03-nist-sp-800-150-p34-133', 0, 382, 'v2.1.0', 'ecc9b87306cda0a4c41a53bb24179fa0391d83b06ec9765ef9a45ce576d7b59d', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":133,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p35-134', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 35, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 27 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Appendix A—Cyber Threat Information Sharing Scenarios This appendix presents some scenarios that describe threat information sharing in real-world applications. These scenarios seek to show how sharing and coordination can increase the efficiency and effectiveness of an organization’s cybersecurity capabilities. These scenarios represent only a small number of the possible applications of information sharing and collaboration. Scenario 1:  Nation-State Attacks against a Specific Industry Sector A nation-state regularly targets companies in a certain industry sector over several months. The attacks come in the form of targeted emails that carry malicious attachments containing a software exploit that, upon opening, launches malware on a victim’s system.', 'vec_doc-03-nist-sp-800-150-p35-134', 0, 229, 'v2.1.0', 'ce196ba98d37722174885c7dfbc09e70033bb6fd663ea5fc48bc7d709cf0c2f9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":134,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p35-135', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 35, 'Systems that are successfully compromised by the malware are then reconfigured by the malware to contact command and control servers and other infrastructure operated by the actor to receive additional instructions, download other malware, and perform data exfiltration. Many companies within this industry sector are members of a formal threat information sharing organization in which a central forum is used to post information about observed threats. The posts describe details relevant to detecting and defending against the threat, such as the sender addresses of phishing emails, samples of malware collected from the attacks, analysis of exploit code used by actors, the IPs and URLs associated with the actor’s command and control servers, and other infrastructure involved with attacks. As soon as one company’s security team identifies a new attack, the information is shared with its peers within the forum.', 'vec_doc-03-nist-sp-800-150-p35-135', 0, 230, 'v2.1.0', 'a2f099290a4c8da13dc98ac7be1c93638f3006cc93897bec4a34d80e783abeca', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":135,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p35-136', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 35, 'One of the companies (A) that participates in the forum has advanced malware analysis capabilities and is able to further characterize the actor and its command and control infrastructure using a malware sample shared via the forum by another company (B). Company A then shares back the information gained through its analysis of the malware. Through B’s sharing of the malware sample, the community benefits from the malware analysis capabilities of company A, and is able to quickly and efficiently detect and protect against similar attacks. In this scenario, an attack faced by one company contributes to another’s defense. Scenario 2:  Campaign Analysis Cybersecurity analysts from companies in a business sector have been sharing indicators and malware samples in an online forum over the past few years.', 'vec_doc-03-nist-sp-800-150-p35-136', 0, 203, 'v2.1.0', '671ce20d7f02534e08612ad2c5c63394050ecf328968ed36311c7e209f1bde7c', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":136,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p35-137', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 35, 'Each company performs independent analysis of the attacks and observes consistent patterns over time, with groups of events often having some commonalities, such as the type of malware used, the DNS domains of command and control channels, and other technical indicators. These observations lead the analysts to suspect that the attacks are not fully random, but part of a larger coordinated set of actions. The forum members participate in technical exchange meetings to share data, insights, and analyses of the different attacks. Through data aggregation and joint analyses, the members can identify activities that are likely attributable to a common actor or to coordination among actors. This scenario demonstrates how data fusion and analysis may help reveal collective action and campaigns by a threat actor and identify the TTPs that are used by specific actors as part of a campaign.', 'vec_doc-03-nist-sp-800-150-p35-137', 0, 224, 'v2.1.0', '6245f0397acf507faaf838970d0b4752a2d71784f955d2b692146a33c3300e7f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":137,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p35-138', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 35, 'Scenario 3:  Distributed Denial of Service Attack against an Industry Sector A hacktivist group targets a select set of companies for a large-scale distributed denial of service (DDoS) attack. The group uses a distributed botnet that is loosely coordinated and controlled by members of the', 'vec_doc-03-nist-sp-800-150-p35-138', 0, 73, 'v2.1.0', '58075a43270c2880581c437d24e10f3b6383fc5b2eec3846e9ce3f129c78b0a9', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":138,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p36-139', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 36, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 28 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 group. By analyzing traffic generated by the botnet, one of the companies targeted in the attack is able to determine that the actors are using a variant of a popular DDoS tool. The targeted companies are members of an ISAC and use the ISAC’s discussion portal to establish a working group to coordinate incident response activities. The working group contacts the ISAC’s law enforcement liaison, who coordinates with federal and international authorities to aid in the investigation and to gain court orders to shut down the actor’s systems. The working group contacts various internet service providers (ISPs), and provides information to aid in identifying abnormal traffic to their network addresses.', 'vec_doc-03-nist-sp-800-150-p36-139', 0, 215, 'v2.1.0', '1c67095b1ad9925ff7ae233cfb49083d6b00d663602ae5a3a79d92a20b097fb2', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":139,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p36-140', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 36, 'The ISPs assist both the affected companies and law enforcement personnel by helping to identify the upstream and downstream traffic sources, implementing routing changes, and enforcing data rate limits on these sources. Using network traffic collected by the ISPs, law enforcement agencies can identify the command and control servers, seize these assets, and identify some members of the hacktivist group. After a technical exchange meeting among the targeted companies, several companies decide to enlist the services of content distribution providers to deploy DDoS-resistant web architectures. Scenario 4:  Financial Conference Phishing Attack A cyber crime group makes use of a publicly available conference attendee list to target specific individuals with a wave of phishing emails. The group is able to identify attendees who are members of the target organization’s corporate accounting team (i.e., individuals who may have the authority to authorize payments or funds transfers).', 'vec_doc-03-nist-sp-800-150-p36-140', 0, 248, 'v2.1.0', '33262fde70967473b7bf74c557b837bf0082de4c53241f93895efb28c91491e1', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":140,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p36-141', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 36, 'Using targeted malware, distributed through phishing attacks, the group tries to compromise machines and accounts to complete unauthorized electronic payments and funds transfers to overseas businesses. One company is able to identify the phishing attack against personnel within its corporate accounting team and learns, during their investigation, that all the recipients targeted during the attack had attended the same conference six months earlier. The company’s CSIRT contacts the conference organizers, as well as representatives from other organizations that attended the conference. The affected organizations arrange a conference call to share specific information (e.g., email header content, attachments, embedded URLs) regarding the attacks. Using the shared indicators, other conference attendees review their mail and network traffic logs to identify potentially compromised hosts.', 'vec_doc-03-nist-sp-800-150-p36-141', 0, 224, 'v2.1.0', '5c44ed48111882e8cdf358d9f97a3ff43e7cbcb8b2077e1dfffe81eca759c5c7', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":141,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p36-142', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 36, 'These companies agree to ongoing collaboration and information sharing about future attacks via an informal email list. Scenario 5:  Business Partner Compromise “Company A” and “Company B” are business partners that have established network connectivity between their organizations to enable the exchange of business information. A cyber crime organization compromises a server at Company B and uses that access as a stepping stone to launch attacks against internal servers at Company A. Operations personnel at Company A notice the unusual activity and notify their security team. The security team identifies the source of the activity as coming from a Company B system. As stipulated in their business partner connectivity agreement, Company A notifies Company B about the anomalous traffic and the companies initiate a joint response to the incident following established procedures.', 'vec_doc-03-nist-sp-800-150-p36-142', 0, 222, 'v2.1.0', '7f9ca8ec1b23ad4d481e2b412d67ec8ee637bffdb04ae86ff3355e0e3643d468', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":142,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p36-143', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 36, 'Company A’s incident response team describes the activity that it sees, allowing Company B’s team to isolate the compromised server and perform an investigation to identify the source of the breach and other possible compromises. Company B’s investigation reveals that the actors exploited a software flaw in a web-facing application and used it to gain unauthorized access to the server. The application development team at Company B makes a code change and deploys a patch that', 'vec_doc-03-nist-sp-800-150-p36-143', 0, 120, 'v2.1.0', '773388bc3b7826dfff2111f7821f3ed123546da27786b2e62f78a8958a749d27', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":143,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p37-144', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 37, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 29 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 fixes the vulnerability, and the security operations team deploys logging and intrusion detection signatures to identify any similar future attacks. Because the security teams of the two companies had agreements and processes in place for a joint response, had pre-established contacts and existing trust relationships, and had already understood each other’s networks and operations, the companies were able to quickly respond and recover from the incident. Scenario 6: US-CERT Provides Indicators, Receives Feedback The US-CERT receives information, from a variety of independent sources, that servers located in the U.S. are being used to carry out cyber attacks against other U.S. companies. A specific foreign actor is known to control the compromised servers.', 'vec_doc-03-nist-sp-800-150-p37-144', 0, 230, 'v2.1.0', '6aa2b310fe3d12fa747de75864cb0b73095a85349a22c60ad92effdace74304f', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":144,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p37-145', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 37, 'The US-CERT identifies the targeted companies and notes that most operate within the aviation industry. The US-CERT contacts the security teams of these companies and shares initial threat information, including URLs, malware, and vulnerabilities being exploited by the actor. Using the indicators, some of the affected companies are able to detect attacks against their infrastructures and to take the actions necessary to prevent the attacks from being successful. While investigating incidents, the affected companies are also able to identify new indicators or provide context regarding the attack to the US-CERT. The US-CERT is able to share these new indicators with other firms after anonymizing the sources, which leads to a more comprehensive response to the threat. Scenario 7: A Retailer Fails to Share A large retailer is subject to a cyber attack by a criminal organization.', 'vec_doc-03-nist-sp-800-150-p37-145', 0, 222, 'v2.1.0', 'f213e9df98eb24f98f59a3cba131e680e456727a7d54f4b42e976a694a392e05', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":145,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p37-146', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 37, 'Millions of credit card numbers and account information are stolen during a breach that goes undiscovered for several weeks. The retailer does not share threat information and relies on its own security and detection capabilities. The retailer’s internal capabilities prove inadequate in the face of a sophisticated, targeted threat that uses custom malware. The breach is discovered by credit card companies investigating a rash of credit card fraud. The credit card companies determine that the commonality in the credit card fraud was purchases made from this one retailer. The credit card companies notify both law enforcement and the retailer, and an investigation is initiated. The damages are extensive. The retailer notifies its customers of the theft of personal information, but does not release details of how the attack was carried out. Consequently, several other retailers are successfully attacked using the same methods in the weeks following the initial breach.', 'vec_doc-03-nist-sp-800-150-p37-146', 0, 245, 'v2.1.0', '492096f49348b245d9eaa6dee1aad58223fc5a4e108c2e18e5c0478a6394a52b', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":146,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p37-147', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 37, 'The financial losses realized by the retailers, customers, and credit card issuers and the reputation loss to the retailers could have been avoided, at least in part, had the retailers engaged in active sharing of threat information with one another. The attacker is emboldened by the successful attack and benefits from the delayed response and lack of a coordination. The attacker benefits financially from the fraudulent activity and can use these additional resources to expand the scope and sophistication of their operations.', 'vec_doc-03-nist-sp-800-150-p37-147', 0, 133, 'v2.1.0', 'ec011a9f7a3b89353a33765db781bd282159dcd5880d739efe0e1cf1a7da44b8', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":147,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p38-148', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 38, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 30 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Appendix B—Glossary Selected terms used in the publication are defined below. Actor See threat actor. Alert A brief, usually human-readable, technical notification regarding current vulnerabilities, exploits, and other security issues. Also known as an advisory, bulletin, or vulnerability note. Continuous Monitoring Maintaining ongoing awareness of information security, vulnerabilities, and threats to support organizational risk management decisions. [15] Controlled Unclassified Information Information that law, regulation, or government-wide policy requires to have safeguarding or disseminating controls, excluding information that is classified under Executive Order 13526, Classified National Security Information, December 29, 2009, or any predecessor or successor order, or the Atomic Energy Act of 1954, as amended.', 'vec_doc-03-nist-sp-800-150-p38-148', 0, 246, 'v2.1.0', 'e1d738f595f4e5df2ff46fc2904309a9fa49f36a27748ee43aeacf460ff131b7', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":148,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p38-149', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 38, '[16] Cyber Threat  See threat. Indicator A technical artifact or observable that suggests an attack is imminent or is currently underway, or that a compromise may have already occurred. Information Sharing and Analysis Organization An ISAO is any entity or collaboration created or employed by public- or private sector organizations, for purposes of gathering and analyzing critical cyber and related information in order to better understand security problems and interdependencies related to cyber systems, so as to ensure their availability, integrity, and reliability. [17] Metadata Information describing the characteristics of data including, for example, structural metadata describing data structures (e.g., data format, syntax, and semantics) and descriptive metadata describing data contents (e.g., information security labels). [8] Observable An event (benign or malicious) on a network or system.', 'vec_doc-03-nist-sp-800-150-p38-149', 0, 228, 'v2.1.0', '9479ebf50f26fea3b3a31eec5ce910c406ea3bb43370bfcb2d8b36161b310192', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":149,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p38-150', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 38, 'Phishing Tricking individuals into disclosing sensitive personal information through deceptive computer-based means. [19] Rootkit A set of tools used by an attacker after gaining root-level access to a host to conceal the attacker’s activities on the host and permit the attacker to maintain root-level access to the host through covert means. [18] Sensitive Information Information, the loss, misuse, or unauthorized access to or modification of, that could adversely affect the national interest or the conduct of federal programs, or the privacy to which individuals are entitled under 5 U.S.C. Section 552a (the Privacy Act), but that has not been specifically authorized under criteria established by an Executive Order or an Act of Congress to be kept classified in the interest of national defense or foreign policy. [18]', 'vec_doc-03-nist-sp-800-150-p38-150', 0, 207, 'v2.1.0', 'a36a28af91e958a51a04df08edb515415f43babd425748c214e1dc94abd52539', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":150,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p39-151', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 39, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 31 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Sensor An intrusion detection and prevention system component that monitors and analyzes network activity and may also perform prevention actions. [14] Tactics, Techniques, and Procedures (TTPs) The behavior of an actor. A tactic is the highest-level description of this behavior, while techniques give a more detailed description of behavior in the context of a tactic, and procedures an even lower- level, highly detailed description in the context of a technique. Threat Any circumstance or event with the potential to adversely impact organizational operations (including mission, functions, image, or reputation), organizational assets, individuals, other organizations, or the Nation through an information system via unauthorized access, destruction, disclosure, or modification of information, and/or denial of service.', 'vec_doc-03-nist-sp-800-150-p39-151', 0, 246, 'v2.1.0', 'bd08b694de13459f5e6d80f23341b7ac4899e6842e3e6dc704ce75532d31be9b', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":151,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p39-152', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 39, '[2] Threat Actor An individual or a group posing a threat. Threat Information Any information related to a threat that might help an organization protect itself against a threat or detect the activities of an actor. Major types of threat information include indicators, TTPs, security alerts, threat intelligence reports, and tool configurations. Threat Intelligence Threat information that has been aggregated, transformed, analyzed, interpreted, or enriched to provide the necessary context for decision- making processes. Threat Intelligence Report A prose document that describes TTPs, actors, types of systems and information being targeted, and other threat-related information. Threat Shifting The response of actors to perceived safeguards and/or countermeasures (i.e., security controls), in which actors change some characteristic of their intent/targeting in order to avoid and/or overcome those safeguards/countermeasures.', 'vec_doc-03-nist-sp-800-150-p39-152', 0, 234, 'v2.1.0', 'd90e96ad17e44b7a37731c6cec9736c840cb6c3ab9f8d17dda0455e3928399e6', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":152,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p39-153', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 39, '[2] Tool Configuration A recommendation for setting up and using tools that support the automated collection, exchange, processing, analysis, and use of threat information. Watering Hole Attack A security exploit where the attacker infects websites that are frequently visited by members of the group being attacked, with a goal of infecting a computer used by one of the targeted group when they visit the infected website.', 'vec_doc-03-nist-sp-800-150-p39-153', 0, 106, 'v2.1.0', '4fff47bc0a1971ba93588c43a7c1f19264fb4cedc8c5d227ca3dc3897af39fe7', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":153,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p40-154', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 40, 'NIST SP 800-150 GUIDE TO CYBER THREAT INFORMATION SHARING 32 This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 Appendix C—Acronyms Selected acronyms used in the publication are defined below.', 'vec_doc-03-nist-sp-800-150-p40-154', 0, 59, 'v2.1.0', 'f6fb1914757b64086df69d67a2c398d7426b8617beb4b566fab6643812f1f6c1', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":154,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-03-nist-sp-800-150-p40-155', 'doc-03-nist-sp-800-150', 'doc-03-nist-sp-800-150', '4.5 Produce and Publish Indicators', 40, 'ACL Access Control List ARP Address Resolution Protocol CCE Common Configuration Enumeration CIO Chief Information Officer CISO Chief Information Security Officer CPE Common Platform Enumeration CSIRT Computer Security Incident Response Team CUI Controlled Unclassified Information CVE Common Vulnerability Enumeration CVSS Common Vulnerability Scoring System CWE Common Weakness Enumeration DDoS Distributed Denial of Service DHCP Dynamic Host Configuration Protocol DIB Defense Industrial Base DNS Domain Name System FISMA Federal Information Security Modernization Act FTP File Transfer Protocol GLBA Gramm-Leach-Bliley Act HIPAA Health Information Portability and Accountability Act IP Internet Protocol IR Interagency Report or Internal Report ISAC Information Sharing and Analysis Center ISAO Information Sharing and Analysis Organization ISP Internet Service Provider IT Information Technology ITL Information Technology Laboratory MAC Media Access Control MOU Memorandum of Understanding NDA Non-Disclosure Agreement NIST National Institute of Standards and Technology NVD National Vulnerability Database OMB Office of Management and Budget PCAP Packet Capture PCI DSS Payment Card Industry Data Security Standard PII Personally Identifiable Information PSIRT Product Security Incident Response Team RSS Rich Site Summary or Really Simple Syndication SIEM Security Information and Event Management SLA Service Level Agreement SOX Sarbanes-Oxley Act SP Special Publication SQL Structured Query Language TCP Transmission Control Protocol TLP Traffic Light Protocol TTP Tactics, Techniques, and Procedures UDP User Datagram Protocol', 'vec_doc-03-nist-sp-800-150-p40-155', 0, 410, 'v2.1.0', '97db56a9f116424f59e1f4a1f73795f1f082e8b47f7ba4215db119021fbafc81', '{"document_id":"doc-03-nist-sp-800-150","document_title":"NIST SP 800-150","chapter":"UNKNOWN","section":"4.5 Produce and Publish Indicators","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"CTI_SHARING","authority_tier":0,"chunk_seq":155,"source_path":".zayron/knowledge/physical-15/03-nist-sp-800-150.pdf","section_path":"4.5 Produce and Publish Indicators"}');
