INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p4-3', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 4, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Reports on Computer Systems Technology The Information Technology Laboratory (ITL) at the National Institute of Standards and Technology (NIST) promotes the U.S. economy and public welfare by providing technical leadership for the nations measurement and standards infrastructure.  ITL develops tests, test methods, reference data, proof of concept implementations, and technical analysis to advance the development and productive use of information technology.  ITLs responsibilities include the development of technical, physical, administrative, and management standards and guidelines for the cost-effective security and privacy of sensitive unclassified information in Federal computer systems.  This Special Publication 800-series reports on ITLs research, guidance, and outreach efforts in computer security and its collaborative activities with industry, government, and academic organizations. Certain commercial entities, equipment, or materials may be identified in this document in order to describe an experimental procedure or concept adequately. Such identification is not intended to imply recommendation or endorsement by the National Institute of Standards and Technology, nor is it intended to imply that the entities, materials, or equipment are necessarily the best available for the purpose. National Institute of Standards and Technology Special Publication 800-86 Natl. Inst. Stand. Technol. Spec. Publ. 800-86, 121 pages (August 2006) ii', 'vec_doc-04-nist-sp-800-86-p4-3', 0, 383, 'v2.1.0', '66212e153ba80e2a68b34ffbc30e9470fac02bc39906c1f251a15494e3e0b9c8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":4,"domain":"FORENSICS","authority_tier":0,"chunk_seq":3,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p5-4', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 5, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Acknowledgments The authors, Karen Kent and Tim Grance of the National Institute of Standards and Technology, and Suzanne Chevalier and Hung Dang of Booz Allen Hamilton, wish to thank their colleagues who reviewed drafts of this document and contributed to its technical content.  The authors would particularly like to acknowledge Rick Ayers, Wayne Jansen, Peter Mell, and Murugiah Souppaya of NIST, and Adam Feldman, Mike Noblett, and Joseph Nusbaum of Booz Allen Hamilton, for their keen and insightful assistance throughout the development of the document.  The authors would also like to express their thanks to security experts Susan Ballou (Office of Law Enforcement Standards), Brian Carrier (Purdue University), Eoghan Casey (Stroz Friedberg, LLC), Duane Crider (Microsoft), Kurt Dillard (Microsoft), Dean Farrington (Wells Fargo Bank), Jessica Reust (Stroz Friedberg, LLC), Marc Rogers (Purdue University), and Miles Tracy (U.S. Federal Reserve System), as well as representatives from the Department of State, for their particularly valuable comments and suggestions. Trademarks All product names are registered trademarks or trademarks of their respective companies. iii', 'vec_doc-04-nist-sp-800-86-p5-4', 0, 312, 'v2.1.0', '21a9da6a8fdf647544cc1919427ce781955bbcf4ffda51ed8cf61f4328ae02e8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":5,"domain":"FORENSICS","authority_tier":0,"chunk_seq":4,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
