INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p9-21', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 9, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Executive Summary Forensic science is generally defined as the application of science to the law. Digital forensics, also known as computer and network forensics, has many definitions. Generally, it is considered the application of science to the identification, collection, examination, and analysis of data while preserving the integrity of the information and maintaining a strict chain of custody for the data. Data refers to distinct pieces of digital information that have been formatted in a specific way. Organizations have an ever-increasing amount of data from many sources. For example, data can be stored or transferred by standard computer systems, networking equipment, computing peripherals, personal digital assistants (PDA), consumer electronic devices, and various types of media, among other sources.', 'vec_doc-04-nist-sp-800-86-p9-21', 0, 221, 'v2.1.0', 'f1ef818c3e77f03c1f257383b6b9e2ac021071404a417334b54a284f73a9ce99', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"FORENSICS","authority_tier":0,"chunk_seq":21,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p9-22', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 9, 'Because of the variety of data sources, digital forensic techniques can be used for many purposes, such as investigating crimes and internal policy violations, reconstructing computer security incidents, troubleshooting operational problems, and recovering from accidental system damage. Practically every organization needs to have the capability to perform digital forensics (referred to as forensics throughout the rest of the guide). Without such a capability, an organization will have difficulty determining what events have occurred within its systems and networks, such as exposures of protected, sensitive data. This guide provides detailed information on establishing a forensic capability, including the development of policies and procedures. Its focus is primarily on using forensic techniques to assist with computer security incident response, but much of the material is also applicable to other situations.', 'vec_doc-04-nist-sp-800-86-p9-22', 0, 231, 'v2.1.0', '6b3a0caef755539506662d89bc7a08bebfb0339c3651a5f5f611dfee678d2c9e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"FORENSICS","authority_tier":0,"chunk_seq":22,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p9-23', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 9, 'Because different organizations are subject to different laws and regulations, this publication should not be used as a guide to executing a digital forensic investigation, construed as legal advice, or used as the basis for investigations of criminal activity.1  Instead, organizations should use this guide as a starting point for developing a forensic capability in conjunction with extensive guidance provided by legal advisors, law enforcement officials, and management. The process for performing digital forensics comprises the following basic phases: ! Collection: identifying, labeling, recording, and acquiring data from the possible sources of relevant data, while following procedures that preserve the integrity of the data. ! Examination: forensically processing collected data using a combination of automated and manual methods, and assessing and extracting data of particular interest, while preserving the integrity of the data. !', 'vec_doc-04-nist-sp-800-86-p9-23', 0, 237, 'v2.1.0', 'f1b8344553090d71e9739e8b8e334b7c5582b9d823bb211c64c89330594f4be1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"FORENSICS","authority_tier":0,"chunk_seq":23,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p9-24', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 9, 'Analysis: analyzing the results of the examination, using legally justifiable methods and techniques, to derive useful information that addresses the questions that were the impetus for performing the collection and examination. ! Reporting: reporting the results of the analysis, which may include describing the actions used, explaining how tools and procedures were selected, determining what other actions need to be performed (e.g., forensic examination of additional data sources, securing identified vulnerabilities, improving existing security controls), and providing recommendations for improvement to policies, procedures, tools, and other aspects of the forensic process. This guide provides general recommendations for performing the forensic process.', 'vec_doc-04-nist-sp-800-86-p9-24', 0, 191, 'v2.1.0', '9d45cff976a2f58798bf88d97b391717adb123cfa14082b5baafb2be05062c8b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"FORENSICS","authority_tier":0,"chunk_seq":24,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p9-25', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 9, 'It also provides detailed information about using the analysis process with four major categories of data sources: files, 1  For further information regarding computer and network forensic requirements for law enforcement, see Electronic Crime Scene Investigation: A Guide for First Responders and Forensic Examination of Digital Evidence: A Guide for Law Enforcement, which are both available at http://www.ncjrs.gov/ by searching on each documents title. ES-1', 'vec_doc-04-nist-sp-800-86-p9-25', 0, 116, 'v2.1.0', 'b276cf22a326e89f4f43091a581d480c9ac0fe0adf8bdc51d78cdfeeca6d7b1a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":9,"domain":"FORENSICS","authority_tier":0,"chunk_seq":25,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p10-26', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 10, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE operating systems, network traffic, and applications. The guide focuses on explaining the basic components and characteristics of data sources within each category, as well as techniques for the collection, examination, and analysis of data from each category. The guide also provides recommendations for how multiple data sources can be used together to gain a better understanding of an event. Implementing the following recommendations should facilitate efficient and effective digital forensic activities for Federal departments and agencies. Organizations should ensure that their policies contain clear statements addressing all major forensic considerations, such as contacting law enforcement, performing monitoring, and conducting regular reviews of forensic policies and procedures.', 'vec_doc-04-nist-sp-800-86-p10-26', 0, 214, 'v2.1.0', '7461eb66e8f173eb35afefb1cef9ad6df1f57dc12ae3c305fd75e67a0686e60d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"FORENSICS","authority_tier":0,"chunk_seq":26,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p10-27', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 10, 'At a high level, policies should allow authorized personnel to monitor systems and networks and perform investigations for legitimate reasons under appropriate circumstances. Organizations may also have a separate forensic policy for incident handlers and others with forensic roles; this policy would provide more detailed rules concerning appropriate behavior. Forensic policy should clearly define the roles and responsibilities of all people and external organizations performing or assisting with the organizations forensic activities. The policy should clearly indicate who should contact which internal teams and external organizations under different circumstances. Organizations should create and maintain procedures and guidelines for performing forensic tasks, based on the organizations policies and all applicable laws and regulations.', 'vec_doc-04-nist-sp-800-86-p10-27', 0, 213, 'v2.1.0', 'c2fa62f05cb468da0bb7c453251f540fa6306ceed684a8a44c497a3f450cedd4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"FORENSICS","authority_tier":0,"chunk_seq":27,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p10-28', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 10, 'Guidelines should focus on general methodologies for investigating incidents using forensic techniques, since it is not feasible to develop comprehensive procedures tailored to every possible situation. However, organizations should consider developing step-by-step procedures for performing routine tasks. The guidelines and procedures should facilitate consistent, effective, and accurate actions, which is particularly important for incidents that may lead to prosecution or internal disciplinary actions; handling evidence in a forensically sound manner puts decision makers in a position where they can confidently take the necessary actions. The guidelines and procedures should support the admissibility of evidence into legal proceedings, including information on gathering and handling evidence properly, preserving the integrity of tools and equipment, maintaining the chain of custody, and storing evidence appropriately.', 'vec_doc-04-nist-sp-800-86-p10-28', 0, 233, 'v2.1.0', 'a1d85cc250c6123d74f0c912ba0726ddf135208ed38f9e45eca1f72f8582b6cf', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"FORENSICS","authority_tier":0,"chunk_seq":28,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p10-29', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 10, 'Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the integrity of such records. The guidelines and procedures should be reviewed periodically, as well as when significant changes are made to the teams policies and procedures. Organizations should ensure that their policies and procedures support the reasonable and appropriate use of forensic tools. Organizations policies and procedures should clearly explain what forensic actions should and should not be performed under various circumstances, as well as describing the necessary safeguards for sensitive information that might be recorded by forensic tools, such as passwords, personal data (e.g., Social Security numbers), and the contents of e-mails. Legal advisors should carefully review all forensic policy and high-level procedures.', 'vec_doc-04-nist-sp-800-86-p10-29', 0, 233, 'v2.1.0', '3066c147ca87a58cb2dc62eb485823bd10e0a32b7ad6d82e88642534498acb18', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"FORENSICS","authority_tier":0,"chunk_seq":29,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p10-30', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 10, 'Organizations should ensure that their IT professionals are prepared to participate in forensic activities. ES-2', 'vec_doc-04-nist-sp-800-86-p10-30', 0, 28, 'v2.1.0', 'f40dbb52c7b0e000ddac7e432762ec38a6b3bd06f194798eea5c2aa4b605727b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":10,"domain":"FORENSICS","authority_tier":0,"chunk_seq":30,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p11-31', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 11, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE IT professionals throughout an organization, especially incident handlers and other first responders to incidents, should understand their roles and responsibilities for forensics, receive training and education on forensicrelated policies and procedures, and be prepared to cooperate with and assist others when the technologies that they are responsible for are part of an incident or other event.  IT professionals should also consult closely with legal counsel both in general preparation for forensics activities, such as determining which actions IT professionals should and should not perform, and also on an as-needed basis to discuss specific forensics situations.  In addition, management should be responsible for supporting forensic capabilities, reviewing and approving forensic policy, and approving certain forensic actions, such as taking mission-critical systems off-line. ES-3', 'vec_doc-04-nist-sp-800-86-p11-31', 0, 240, 'v2.1.0', 'a881defc2be1fb783b74cfd5158a8a108bc79715ae99063dc9e5294170015493', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":11,"domain":"FORENSICS","authority_tier":0,"chunk_seq":31,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p12-32', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 12, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE This page has been left blank intentionally. ES-4', 'vec_doc-04-nist-sp-800-86-p12-32', 0, 29, 'v2.1.0', '71b7cb1f76e28a0773967867a7b7826211eaf7db8c906597d1ca915bad1297d1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":12,"domain":"FORENSICS","authority_tier":0,"chunk_seq":32,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p13-33', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'UNKNOWN', 13, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE', 'vec_doc-04-nist-sp-800-86-p13-33', 0, 16, 'v2.1.0', '08e2223757011f1b4f24bf7d8e5eeb9536127c56ce9317842b158f7f21fb09d5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"UNKNOWN","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"FORENSICS","authority_tier":0,"chunk_seq":33,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"General Document Content"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p13-34', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1.1 A uthority', 13, 'The National Institute of Standards and Technology (NIST) developed this document in furtherance of its statutory responsibilities under the Federal Information Security Management Act (FISMA) of 2002, Public Law 107-347. NIST is responsible for developing standards and guidelines, including minimum requirements, for providing adequate information security for all agency operations and assets; but such standards and guidelines shall not apply to national security systems.  This guideline is consistent with the requirements of the Office of Management and Budget (OMB) Circular A-130, Section 8b(3), Securing Agency Information Systems, as analyzed in A-130, Appendix IV: Analysis of Key Sections.  Supplemental information is provided in A-130, Appendix III. This guideline has been prepared for use by Federal agencies.  It may be used by nongovernmental organizations on a voluntary basis and is not subject to copyright, though attribution is desired. Nothing in this document should be taken to contradict standards and guidelines made mandatory and binding on Federal agencies by the Secretary of Commerce under statutory authority, nor should these guidelines be interpreted as altering or superseding the existing authorities of the Secretary of Commerce, Director of the OMB, or any other Federal official. This guideline should not be held as binding to law enforcement personnel relative to the investigation of criminal activity.', 'vec_doc-04-nist-sp-800-86-p13-34', 0, 362, 'v2.1.0', '3c79d863ec8e68e8d049770f12bc4118dc20cb5532be5adc8d6bfcbefb2a4e1a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1.1 A uthority","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"FORENSICS","authority_tier":0,"chunk_seq":34,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1.1 A uthority"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p13-35', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1.2 Purpose and Scope', 13, 'This publication is intended to help organizations in investigating computer security incidents and troubleshooting some information technology (IT) operational problems by providing practical guidance on performing computer and network forensics.  The guide presents forensics from an IT view, not a law enforcement view.2  Specifically, the publication describes the processes for performing effective forensics activities and provides advice regarding different data sources, including files, operating systems (OS), network traffic, and applications. The publication is not to be used as an all-inclusive step-by-step guide for executing a digital forensic investigation or construed as legal advice.  Its purpose is to inform readers of various technologies and potential ways of using them in performing incident response or troubleshooting activities.  Readers are advised to apply the recommended practices only after consulting with management and legal counsel for compliance concerning laws and regulations (i.e., local, state, Federal, and international) that pertain to their situation.', 'vec_doc-04-nist-sp-800-86-p13-35', 0, 275, 'v2.1.0', '6629de66a455f93ebf1ade4a0d1ada79a664da61ab8ab0f44a34aafd27f49ac1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1.2 Purpose and Scope","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"FORENSICS","authority_tier":0,"chunk_seq":35,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1.2 Purpose and Scope"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p13-36', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1.3 A udience', 13, 'This publication has been created for incident response teams; forensic analysts; system, network, and security administrators; and computer security program managers who are responsible for performing forensics for investigative, incident response, or troubleshooting purposes.  The practices recommended 2  For further information regarding computer and network forensic requirements for law enforcement, see Electronic Crime Scene Investigation: A Guide for First Responders and Forensic Examination of Digital Evidence: A Guide for Law Enforcement, which are both available at http://www.ncjrs.gov/ by searching on each documents title. 1-1', 'vec_doc-04-nist-sp-800-86-p13-36', 0, 162, 'v2.1.0', 'dd1ad932f17d1bb0634c69782ef65b28860961f7088e3a60514dc5a708ea5ffc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1.3 A udience","subsection":"UNKNOWN","table_id":null,"page":13,"domain":"FORENSICS","authority_tier":0,"chunk_seq":36,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1.3 A udience"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p14-37', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1.3 A udience', 14, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE in this guide are designed to highlight key principles associated with the handling and examination of electronic evidence.  Because of the constantly changing nature of electronic devices and software, and forensic procedures and tools, readers are expected to refer to other resources, including those listed in this guide, for more current and detailed information than that presented in this guide.', 'vec_doc-04-nist-sp-800-86-p14-37', 0, 117, 'v2.1.0', '4823fbbdd955fc9c19b6e3332a640523ad816fade3fa557fdad5edfcb8fa69ae', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1.3 A udience","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"FORENSICS","authority_tier":0,"chunk_seq":37,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1.3 A udience"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p14-38', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1.4 Pu blication Structure', 14, 'The remainder of this publication is divided into seven major sections: ! Section 2 discusses the need for computer and network forensics and provides guidance on establishing and organizing a forensics capability for an organization. ! Section 3 explains the basic steps involved in performing computer and network forensics: data collection, examination, analysis, and reporting. ! Sections 4 through 7 provide details on collecting, examining, and analyzing data from various data sources, based on the framework described in Section 3.  The data source categories discussed in Sections 4 through 7 are data files, OSs, network traffic, and applications, respectively. ! Section 8 presents case studies that illustrate how analysis can correlate events among several data sources. The publication also contains several appendices with supporting material: ! Appendix A presents the major recommendations made in the publication. ! Appendix B presents scenarios in which forensics techniques might be useful and asks the reader a series of questions regarding each scenario. ! Appendices C and D contain a glossary and acronym list, respectively. ! Appendix E lists print resources, and Appendix F identifies online tools and resources, that may be useful for establishing a forensics capability or understanding forensics tools and techniques. ! Appendix G contains an index for the publication. 1-2', 'vec_doc-04-nist-sp-800-86-p14-38', 0, 351, 'v2.1.0', '3285e8632af257a1011516ebf08fad836e748cba894f70decd8ca70a55adc6a0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1.4 Pu blication Structure","subsection":"UNKNOWN","table_id":null,"page":14,"domain":"FORENSICS","authority_tier":0,"chunk_seq":38,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1.4 Pu blication Structure"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p15-39', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. Establishing and Organizing a Forensics Capability', 15, 'The term data refers to distinct pieces of digital information that have been formatted in a specific way. The expansion of computers3 for professional and personal use and the pervasiveness of networking have fueled the need for tools that can record and analyze an ever-increasing amount of data from many sources. For example, data can be stored or transferred by standard computer systems (e.g., desktops, laptops, servers), networking equipment (e.g., firewalls, routers), computing peripherals (i.e., printers), personal digital assistants (PDA), CDs, DVDs, removable hard drives, backup tapes, flash memory, thumb drives, and jump drives. Many consumer electronic devices (e.g., cell phones, video game consoles, digital audio players, digital video recorders) can also be used to store data. This increasing variety of data sources has helped spur the development and refinement of forensics tools and techniques.', 'vec_doc-04-nist-sp-800-86-p15-39', 0, 231, 'v2.1.0', '25bb4034c1cad7b609fbc2f8e77e41e3bccb26781e7602276dc228a151b0bcdf', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. Establishing and Organizing a Forensics Capability","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"FORENSICS","authority_tier":0,"chunk_seq":39,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. Establishing and Organizing a Forensics Capability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p15-40', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. Establishing and Organizing a Forensics Capability', 15, 'This has also been caused by the realization that such tools and techniques can be used for many purposes, such as investigating crimes, reconstructing computer security incidents, troubleshooting operational problems, and recovering from accidental system damage. This section discusses several aspects of organizing a forensics capability for an organization. It begins by showing the wide variety of potential uses for forensics, and then presents a high-level overview of the forensics process. The next part of the section discusses how forensics services are typically provided and provides guidance on building and maintaining the necessary skills to perform forensics tasks. The section also explains the need to include various teams from throughout the organization, such as legal advisors and physical security staff, in some forensic activities.', 'vec_doc-04-nist-sp-800-86-p15-40', 0, 215, 'v2.1.0', '227a5bc15c4ead5337e78b38b40c13b52085bed251757c8cb6186490d394ec49', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. Establishing and Organizing a Forensics Capability","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"FORENSICS","authority_tier":0,"chunk_seq":40,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. Establishing and Organizing a Forensics Capability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p15-41', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. Establishing and Organizing a Forensics Capability', 15, 'The section ends by discussing how policies, guidelines, and procedures should address forensics (e.g., defining roles and responsibilities, providing guidance on the proper usage of tools and techniques, incorporating forensics into the information system life cycle). The techniques and processes presented in this guide are based on principles of digital forensics. Forensic science is generally defined as the application of science to the law. Digital forensics, also known as computer and network forensics, has many definitions. Generally, it is considered the application of science to the identification, collection, examination, and analysis of data while preserving the integrity of the information and maintaining a strict chain of custody for the data.', 'vec_doc-04-nist-sp-800-86-p15-41', 0, 192, 'v2.1.0', '7e4fc91c0d538740260c59e10031085608ded30375ab0ebb2e11d43b38a482fa', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. Establishing and Organizing a Forensics Capability","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"FORENSICS","authority_tier":0,"chunk_seq":41,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. Establishing and Organizing a Forensics Capability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p15-42', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. Establishing and Organizing a Forensics Capability', 15, 'Because different organizations are subject to different laws and regulations, this publication should not be used as a guide for executing a digital forensic investigation, construed as legal advice, or used as the basis for investigations of criminal activity. Instead, organizations should use this guide as a starting point for developing a forensic capability in conjunction with extensive guidance provided by legal advisors, law enforcement officials, and management.', 'vec_doc-04-nist-sp-800-86-p15-42', 0, 119, 'v2.1.0', '98d31f0b2b146c7e7d69c2c04ee1b16e5f12b04be6933703b3326eda70bc0cce', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. Establishing and Organizing a Forensics Capability","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"FORENSICS","authority_tier":0,"chunk_seq":42,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. Establishing and Organizing a Forensics Capability"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p15-43', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.1 The Need for Forensics', 15, 'Over the last decade, the number of crimes that involve computers has grown, spurring an increase in companies and products that aim to assist law enforcement in using computer-based evidence to determine the who, what, where, when, and how for crimes.  As a result, computer and network forensics has evolved to assure proper presentation of computer crime evidentiary data into court.  Forensic tools and techniques are most often thought of in the context of criminal investigations and computer security incident handlingused to respond to an event by investigating suspect systems, gathering and preserving evidence, reconstructing events, and assessing the current state of an event.  However, forensic tools and techniques are also useful for many other types of tasks, such as the following: ! Operational Troubleshooting.  Many forensic tools and techniques can be applied to troubleshooting operational issues, such as finding the virtual and physical location of a host with 3  In this publication, the term computer is used to refer to all computing, storage, and peripheral devices. 2-1', 'vec_doc-04-nist-sp-800-86-p15-43', 0, 275, 'v2.1.0', 'b116b8f1f1fef007f21aef291189b025adb98e5a4b2ebd508d72b90a5468af51', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.1 The Need for Forensics","subsection":"UNKNOWN","table_id":null,"page":15,"domain":"FORENSICS","authority_tier":0,"chunk_seq":43,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.1 The Need for Forensics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p16-44', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.1 The Need for Forensics', 16, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE an incorrect network configuration, resolving a functional problem with an application, and recording and reviewing the current OS and application configuration settings for a host. ! Log Monitoring. Various tools and techniques can assist in log monitoring, such as analyzing log entries and correlating log entries across multiple systems. This can assist in incident handling, identifying policy violations, auditing, and other efforts. ! Data Recovery. There are dozens of tools that can recover lost data from systems, including data that has been accidentally or purposely deleted or otherwise modified. The amount of data that can be recovered varies on a case-by-case basis. ! Data Acquisition. Some organizations use forensics tools to acquire data from hosts that are being redeployed or retired.', 'vec_doc-04-nist-sp-800-86-p16-44', 0, 218, 'v2.1.0', '974c796abf6515bd3841ae4c52021c501429ca050350dd72536d8309a8dec81a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.1 The Need for Forensics","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"FORENSICS","authority_tier":0,"chunk_seq":44,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.1 The Need for Forensics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p16-45', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.1 The Need for Forensics', 16, 'For example, when a user leaves an organization, the data from the users workstation can be acquired and stored in case it is needed in the future. The workstations media can then be sanitized to remove all of the original users data. ! Due Diligence/Regulatory Compliance. Existing and emerging regulations require many organizations to protect sensitive information and maintain certain records for audit purposes. Also, when protected information is exposed to other parties, organizations may be required to notify other agencies or impacted individuals. Forensics can help organizations exercise due diligence and comply with such requirements. Regardless of the situation, the forensic process comprises the following basic phases:4 ! Collection. The first phase in the process is to identify, label, record, and acquire data from the possible sources of relevant data, while following guidelines and procedures that preserve the integrity of the data.', 'vec_doc-04-nist-sp-800-86-p16-45', 0, 241, 'v2.1.0', 'bcb3c08939735a238229fc771e43b95b29844baaf863375a1a2f0fdb45e51ca9', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.1 The Need for Forensics","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"FORENSICS","authority_tier":0,"chunk_seq":45,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.1 The Need for Forensics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p16-46', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.1 The Need for Forensics', 16, 'Collection is typically performed in a timely manner because of the likelihood of losing dynamic data such as current network connections, as well as losing data from battery-powered devices (e.g., cell phones, PDAs). ! Examination. Examinations involve forensically processing large amounts of collected data using a combination of automated and manual methods to assess and extract data of particular interest, while preserving the integrity of the data. ! Analysis. The next phase of the process is to analyze the results of the examination, using legally justifiable methods and techniques, to derive useful information that addresses the questions that were the impetus for performing the collection and examination. ! Reporting.', 'vec_doc-04-nist-sp-800-86-p16-46', 0, 184, 'v2.1.0', '4e7d9e7c99954c3335b837452b2c1e9ca50229c96649046668bd535c382c19c6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.1 The Need for Forensics","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"FORENSICS","authority_tier":0,"chunk_seq":46,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.1 The Need for Forensics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p16-47', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.1 The Need for Forensics', 16, 'The final phase is reporting the results of the analysis, which may include describing the actions used, explaining how tools and procedures were selected, determining what other actions need to be performed (e.g., forensic examination of additional data sources, securing identified vulnerabilities, improving existing security controls), and providing recommendations for improvement to policies, guidelines, procedures, tools, and other aspects of the forensic process. The formality of the reporting step varies greatly depending on the situation. A more in-depth discussion of the forensic process is presented in Section 3. Sections 4 through 7 provide additional information on collecting, examining, and analyzing different types of forensic data. 4  There are many models for the forensic process. Although the exact phases of the models vary somewhat, the models reflect the same basic principles and the same overall methodology.', 'vec_doc-04-nist-sp-800-86-p16-47', 0, 235, 'v2.1.0', 'ceb26dac03ff386530d6cf8ef6e800cb362a8ec6c4ea0705dcefa294e5f61f25', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.1 The Need for Forensics","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"FORENSICS","authority_tier":0,"chunk_seq":47,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.1 The Need for Forensics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p16-48', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.1 The Need for Forensics', 16, 'Models differ primarily in how granular each phase of the process is and in the terms used for specific phases. The model presented in this guide offers a simple way of looking at the phases. Organizations should choose the specific forensic model that is most appropriate for their needs. 2-2', 'vec_doc-04-nist-sp-800-86-p16-48', 0, 74, 'v2.1.0', '317bd2f085deb6c43aa15fce9c6ed55c17d833727266df3107232383eef24aa5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.1 The Need for Forensics","subsection":"UNKNOWN","table_id":null,"page":16,"domain":"FORENSICS","authority_tier":0,"chunk_seq":48,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.1 The Need for Forensics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p17-49', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 17, 'Practically every organization needs to have some capability to perform computer and network forensics. Without such a capability, an organization will have difficulty determining what events have occurred within its systems and networks, such as exposures of protected, sensitive data. Although the extent of this need varies, the primary users of forensic tools and techniques within an organization usually can be divided into the following three groups:5 ! Investigators. Investigators within an organization are most often from the Office of Inspector General (OIG), and they are responsible for investigating allegations of misconduct. For some organizations, the OIG immediately takes over the investigation of any event that is suspected to involve criminal activity. The OIG typically uses many forensic techniques and tools. Other investigators within an organization might include legal advisors and members of the human resources department.', 'vec_doc-04-nist-sp-800-86-p17-49', 0, 239, 'v2.1.0', '68ad3c5e8a2e03dd2f74a05708c7be2072f3594430f516df2b24dd12894fbc8c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"FORENSICS","authority_tier":0,"chunk_seq":49,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p17-50', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 17, 'Law enforcement officials and others outside the organization that might perform criminal investigations are not considered part of an organizations internal group of investigators. ! IT Professionals. This group includes technical support staff and system, network, and security administrators. They use a small number of forensic techniques and tools specific to their area of expertise during their routine work (e.g., monitoring, troubleshooting, data recovery). ! Incident Handlers. This group responds to a variety of computer security incidents, such as unauthorized data access, inappropriate system usage, malicious code infections, and denial of service attacks. Incident handlers typically use a wide variety of forensic techniques and tools during their investigations. Many organizations rely on a combination of their own staff and external parties to perform forensic tasks.', 'vec_doc-04-nist-sp-800-86-p17-50', 0, 223, 'v2.1.0', '3dd64930ce5c42f94cf80e211ad3ac930cb8c7316ec3514eb6cb60aa79c7c903', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"FORENSICS","authority_tier":0,"chunk_seq":50,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p17-51', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 17, 'For example, some organizations perform standard tasks themselves and use outside parties only when specialized assistance is needed. Even organizations that want to perform all forensic tasks themselves usually outsource the most demanding ones, such as sending physically damaged media to a data recovery firm for reconstruction, or having specially trained law enforcement personnel or consultants collect data from an unusual source (e.g., cell phone). Such tasks typically require the use of specialized software, equipment, facilities, and technical expertise that most organizations cannot justify the high expense of acquiring and maintaining. As described in Section 3.1.2, organizations should determine in advance which actions should be performed by law enforcement officials. Also, when expert testimony is needed for legal proceedings, organizations might seek external assistance.', 'vec_doc-04-nist-sp-800-86-p17-51', 0, 224, 'v2.1.0', '51380a6b9274a9e41491bba79ee0d1a3d683d73a7a1ac04b152cdbcde752c187', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"FORENSICS","authority_tier":0,"chunk_seq":51,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p17-52', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 17, 'When deciding which internal or external parties should handle each aspect of forensics, organizations should keep the following factors in mind: ! Cost. There are many potential costs. Software, hardware, and equipment used to collect and examine data may carry significant costs (e.g., purchase price, software updates and upgrades, maintenance), and may also require additional physical security measures to safeguard them from tampering. Other significant expenses involve staff training and labor costs, which are particularly significant for dedicated forensic specialists. In general, forensic actions that are needed rarely might be more cost-effectively performed by an external party, whereas actions that are needed frequently might be more cost-effectively performed internally. 5  An individual performing forensic activities needs to understand forensic principles and practices, and follow the correct procedures for each activity, regardless of which group he or she is a member. 2-3', 'vec_doc-04-nist-sp-800-86-p17-52', 0, 250, 'v2.1.0', '93c8e93fb3f17726fe0a1ce4edc98546b470608e923cd8ca14a8ee1eb617385c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":17,"domain":"FORENSICS","authority_tier":0,"chunk_seq":52,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p18-53', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 18, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Response Time. Personnel located on-site might be able to initiate computer forensic activity more quickly than could off-site personnel. For organizations with geographically dispersed physical locations, off-site outsourcers located near distant facilities might be able to respond more quickly than personnel located at the organizations headquarters. ! Data Sensitivity. Because of data sensitivity and privacy concerns, some organizations might be reluctant to allow external parties to image hard drives and perform other actions that provide access to data. For example, a system that contains traces of an incident might also contain health care information, financial records, or other sensitive data; an organization might prefer to keep that system under its own control to safeguard the privacy of the data.', 'vec_doc-04-nist-sp-800-86-p18-53', 0, 222, 'v2.1.0', '8356415335e034d42365a1f89c242a424edaf5323ecbeb4636ddf1ff6d944c92', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"FORENSICS","authority_tier":0,"chunk_seq":53,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p18-54', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 18, 'On the other hand, if there is a privacy concern within the teamfor example, if an incident is suspected to involve a member of the incident handling teamuse of an independent third party to perform forensic actions would be preferable. Incident handlers performing forensic tasks need to have a reasonably comprehensive knowledge of forensic principles, guidelines, procedures, tools, and techniques, as well as anti-forensic tools and techniques that could conceal or destroy data. It is also beneficial for incident handlers to have expertise in information security and specific technical subjects, such as the most commonly used OSs, filesystems, applications, and network protocols within the organization. Having this type of knowledge facilitates faster and more effective responses to incidents.', 'vec_doc-04-nist-sp-800-86-p18-54', 0, 202, 'v2.1.0', '16ad001d74d36ee6cbd68eb2e3064639df4683fd76fee3769d69731cd9830a34', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"FORENSICS","authority_tier":0,"chunk_seq":54,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p18-55', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 18, 'Incident handlers also need a general, broad understanding of systems and networks so that they can determine quickly which teams and individuals are well-suited to providing technical expertise for particular forensic efforts, such as examining and analyzing data for an uncommon application. Individuals performing forensics might need to perform other types of tasks as well. For example, if the results of an investigation are used in a court of law, incident handlers may be called upon to provide testimony and corroborate their findings. Incident handlers might provide training courses in forensics to technical support staff, system and network administrators, and other IT professionals. Possible training topics include an overview of forensics tools and techniques, advice on using a particular tool, and the signs of a new type of attack.', 'vec_doc-04-nist-sp-800-86-p18-55', 0, 213, 'v2.1.0', '9523032ed4fcea17d5a575fa39d0e43de3b44d0f3f110a7b5bc2b6b88e45624a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"FORENSICS","authority_tier":0,"chunk_seq":55,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p18-56', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 18, 'Incident handlers might also want to have interactive sessions with groups of IT professionals to hear their thoughts on forensics tools and identify potential shortcomings in existing forensics capabilities. On an incident handling team, more than one team member should be able to perform each typical forensic activity so that the absence of any single team member will not severely impact the teams abilities. Incident handlers can train each other in the use of forensic tools and other technical and procedural topics. Hands-on exercises and external IT and forensic training courses can also be helpful in building and maintaining skills. In addition, it might be beneficial to have team members see demonstrations of new tools and technologies or try out forensic and anti-forensic tools in a lab. This can be particularly useful in familiarizing incident handlers with the collection, examination, and analysis of data from devices such as cell phones and PDAs.', 'vec_doc-04-nist-sp-800-86-p18-56', 0, 243, 'v2.1.0', '70e91ba992ff471d592cc2f01841b11bd03a335bcde9acebaf56e35f8304a8e2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"FORENSICS","authority_tier":0,"chunk_seq":56,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p18-57', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.2 F orensic Staffing', 18, 'Incident handlers need to stay current with new forensic technologies, techniques, and procedures.', 'vec_doc-04-nist-sp-800-86-p18-57', 0, 25, 'v2.1.0', '9e34f5fc1745afdb7fe715156821c87587f6dab0e911c977bff0028bedd25681', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.2 F orensic Staffing","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"FORENSICS","authority_tier":0,"chunk_seq":57,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.2 F orensic Staffing"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p18-58', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.3 Interactions with Other Teams', 18, 'It is not feasible for any one person to be well-versed in every technology (including all software) used within an organization; therefore, individuals performing forensic actions should be able to reach out to other teams and individuals within their organization as needed for additional assistance.  For example, an incident involving a particular database server might be handled more efficiently if the database administrator were available to provide background information, answer technical questions, and provide database documentation and other reference material.  Organizations should ensure that IT professionals throughout the organization, especially incident handlers and other first responders to incidents, 2-4', 'vec_doc-04-nist-sp-800-86-p18-58', 0, 182, 'v2.1.0', '33caba96603d830d9756c701e960a4e8b051938d20d5dfca4e96c4fb1d7b705c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.3 Interactions with Other Teams","subsection":"UNKNOWN","table_id":null,"page":18,"domain":"FORENSICS","authority_tier":0,"chunk_seq":58,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.3 Interactions with Other Teams"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p19-59', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.3 Interactions with Other Teams', 19, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE understand their roles and responsibilities for forensics, receive ongoing training and education on forensicrelated policies, guidelines, and procedures, and are prepared to cooperate with and assist others when the technologies that they are responsible for are part of an incident or other event. In addition to IT professionals and incident handlers, others within an organization may also need to participate in forensic activities in a less technical capacity. Examples include management, legal advisors, human resources personnel, auditors, and physical security staff. Management is responsible for supporting forensic capabilities, reviewing and approving forensic policy, and approving certain forensic actions (e.g., taking a mission-critical system off-line for 6 hours to collect data from its hard drives).', 'vec_doc-04-nist-sp-800-86-p19-59', 0, 222, 'v2.1.0', 'da6ec5f630e91862f256a6904e46ca46b2b92c72180504b4a8afe5e23e35beb1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.3 Interactions with Other Teams","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"FORENSICS","authority_tier":0,"chunk_seq":59,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.3 Interactions with Other Teams"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p19-60', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.3 Interactions with Other Teams', 19, 'Legal advisors should carefully review all forensic policy and high-level guidelines and procedures, and they can provide additional guidance when needed to ensure that forensic actions are performed lawfully. The human resources department can provide assistance in dealing with employee relations and the handling of internal incidents. Auditors can help determine the economic impact of an incident, including the cost of forensic activity. Physical security staff can assist in gaining access to and physically securing evidence. Although these teams often do not play a prominent role in the forensic process, the services that these teams provide can be beneficial. To facilitate inter-team communications, each team should designate one or more points of contact. These individuals are responsible for knowing the expertise of each team member and directing inquiries for assistance to the appropriate person.', 'vec_doc-04-nist-sp-800-86-p19-60', 0, 229, 'v2.1.0', '0ee58a95b2ce9eb0b8e5855f50618f7d22311f4620a8c96fd1665918aec56b72', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.3 Interactions with Other Teams","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"FORENSICS","authority_tier":0,"chunk_seq":60,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.3 Interactions with Other Teams"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p19-61', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.3 Interactions with Other Teams', 19, 'Organizations should maintain a list of contacts that the appropriate teams can reference as needed. The list should include both standard (e.g., office phone) and emergency (e.g., cell phone) contact methods.', 'vec_doc-04-nist-sp-800-86-p19-61', 0, 53, 'v2.1.0', 'de2b11a2b3acc3bc3555f03a29970ccb447213388ee2b3ba8727c15b215e1975', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.3 Interactions with Other Teams","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"FORENSICS","authority_tier":0,"chunk_seq":61,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.3 Interactions with Other Teams"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p19-62', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 19, 'Organizations should ensure that their policies contain clear statements that address all major forensic considerations, such as contacting law enforcement, performing monitoring, and conducting regular reviews of forensic policies, guidelines, and procedures. At a high level, policies should allow authorized personnel to monitor systems and networks and perform investigations for legitimate reasons under appropriate circumstances. Organizations may also have a separate policy for incident handlers and others with forensic roles; this policy would provide more detailed rules for appropriate behavior. Such personnel should be familiar with and understand the policy. Policies may need to be updated frequently, particularly for organizations that span many jurisdictions, because of changes to laws and regulations, as well as new court rulings.', 'vec_doc-04-nist-sp-800-86-p19-62', 0, 213, 'v2.1.0', '8a3d3d720130ae5ce8572f27c1d51fdd69ba647d9a860aa4d8d79cee49846fff', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"FORENSICS","authority_tier":0,"chunk_seq":62,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p19-63', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 19, 'In addition, the organizations forensic policy should be consistent with the organizations other policies, including policies related to reasonable expectations of privacy. Sections 2.4.1 through 2.4.3 discuss policy-related topics in more detail. 2.4.1 Defining Roles and Responsibilities Forensic policy should clearly define the roles and responsibilities of all people performing or assisting with the organizations forensic activities. This should include actions performed during both incident handling and routine work activities (e.g., system administration, network troubleshooting). The policy should include all internal teams that may participate in forensic efforts, such as those listed in Section 2.3, and external organizations such as law enforcement agencies, outsourcers, and incident response organizations. The policy should clearly indicate who should contact which internal teams and external organizations under different circumstances.', 'vec_doc-04-nist-sp-800-86-p19-63', 0, 241, 'v2.1.0', '4a6b6c163207889c8d6392a921d057069431f49233316b4df8ff067369d39252', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"FORENSICS","authority_tier":0,"chunk_seq":63,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p19-64', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 19, 'The policy should also discuss jurisdictional conflictsa crime that involves multiple jurisdictions, which could be investigated by multiple law enforcement agenciesand explain how to resolve them. As mentioned in Section 2.2, some organizations have an Office of Inspector General (OIG) that is responsible for investigating allegations of misconduct; the OIG may also be well-suited to resolving jurisdictional conflicts. In some organizations, if a crime may have been committed, the OIG immediately takes over the investigation. 2-5', 'vec_doc-04-nist-sp-800-86-p19-64', 0, 135, 'v2.1.0', '28920d0ee4d30b65516de5aa81a184c28d4b3417869653252f7d50daddb7ec14', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":19,"domain":"FORENSICS","authority_tier":0,"chunk_seq":64,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p20-65', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 20, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 2.4.2 2.4.3 Providing Guidance for Forensic Tool Use Incident handlers; IT professionals, such as system and network administrators; and others within an organization use forensic tools and techniques for a variety of reasons. Although the technologies have many benefits, they can also be misused accidentally or intentionally to provide unauthorized access to information, or to alter or destroy information, including evidence of an incident. In addition, the use of certain forensic tools may not be warranted in some situations (for example, a minor incident probably does not merit hundreds of hours of data collection and examination efforts). To ensure that tools are used reasonably and appropriately, the organizations policies, guidelines, and procedures should clearly explain what forensic actions should and should not be performed under various circumstances.', 'vec_doc-04-nist-sp-800-86-p20-65', 0, 235, 'v2.1.0', 'e4849238d70024656844b9e34ab6c0ff6ee1de7eb99ffd5aefb034881866cb58', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"FORENSICS","authority_tier":0,"chunk_seq":65,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p20-66', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 20, 'For example, a network administrator should be able to monitor network communications on a regular basis to solve operational problems, but should not read users e-mail unless specifically authorized to do so. A help desk agent might be permitted to monitor network communications for a particular users workstation to troubleshoot an application problem but not be permitted to perform any other network monitoring. Individual users might be forbidden from performing any network monitoring under any circumstances. Policies, guidelines, and procedures should clearly define the specific actions that are permitted and forbidden for each applicable role under normal circumstances (e.g., typical duties) and special circumstances (e.g., incident handling). Policies, guidelines, and procedures should also address the use of anti-forensic tools and techniques. Described in Sections 4 through 7, anti-forensic software is designed to conceal or destroy data so that others cannot access it.', 'vec_doc-04-nist-sp-800-86-p20-66', 0, 249, 'v2.1.0', 'fdee973eb7c913a90526fd400c6a309048de68671e3ba46feaef8d335d74a701', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"FORENSICS","authority_tier":0,"chunk_seq":66,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p20-67', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 20, 'There are many positive uses for anti-forensic software, such as removing data from computers that are to be donated to charity and removing data cached by Web browsers to preserve a users privacy. However, like forensic tools, anti-forensic tools can also be used for malicious reasons. Therefore, organizations should specify who is permitted to use such tools and under what circumstances. Because forensic tools may record sensitive information, policies, guidelines, and procedures should also describe the necessary safeguards for the information. There should also be requirements for handling inadvertent exposures of sensitive information, such as an incident handler seeing passwords or patient medical information. Supporting Forensics in the Information System Life Cycle Many incidents can be handled more efficiently and effectively if forensic considerations have been incorporated into the information system life cycle. Examples of such considerations are as follows: !', 'vec_doc-04-nist-sp-800-86-p20-67', 0, 247, 'v2.1.0', 'df3653d4bee0f4b1c8e31d942ef57ba39412bb12f2d61287461f2769a22995a1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"FORENSICS","authority_tier":0,"chunk_seq":67,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p20-68', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 20, 'Performing regular backups of systems and maintaining previous backups for a specific period of time ! Enabling auditing on workstations, servers, and network devices ! Forwarding audit records to secure centralized log servers ! Configuring mission-critical applications to perform auditing, including recording all authentication attempts ! Maintaining a database of file hashes for the files of common OS and application deployments, and using file integrity checking software on particularly important assets ! Maintaining records (e.g., baselines) of network and system configurations 2-6', 'vec_doc-04-nist-sp-800-86-p20-68', 0, 149, 'v2.1.0', '9173ed87d5c57ca753f7c4f639b8f3b230ed7a6abe5ebcbd32c0584f181d1968', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":20,"domain":"FORENSICS","authority_tier":0,"chunk_seq":68,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p21-69', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.4 P olicies', 21, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Establishing data retention policies that support performing historical reviews of system and network activity, complying with requests or requirements to preserve data relating to ongoing litigation and investigations, and destroying data that is no longer needed. Most of these considerations are extensions of existing provisions in the organizations policies and procedures, so they are typically specified within the relevant individual documents instead of a centralized forensics policy.', 'vec_doc-04-nist-sp-800-86-p21-69', 0, 141, 'v2.1.0', '100c80cdd39c20571ac88a2cf04c84eca3703450861e06aea1970f8672442d30', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.4 P olicies","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"FORENSICS","authority_tier":0,"chunk_seq":69,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.4 P olicies"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p21-70', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.5 Guidelines and Procedures', 21, 'As mentioned in Section 2.4, an organization should create and maintain guidelines and procedures for performing forensic tasks, based on the organizations policies, incident response staffing models, and other teams identified as participants in forensic activities. Even if the activities are performed by external parties, the organizations internal staff will still interact with them and participate to some extent in the activities, such as notifying the external party of a need for assistance, granting physical or logical access to systems, and securing an incident scene until an investigator arrives. The internal staff should work closely with the external parties to ensure that the organizations policies, guidelines, and procedures are understood and followed.', 'vec_doc-04-nist-sp-800-86-p21-70', 0, 195, 'v2.1.0', '0cebc89f7b6bd92d28fac77aa64f43f6621db250d3b52e92860ec19666ffeab1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.5 Guidelines and Procedures","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"FORENSICS","authority_tier":0,"chunk_seq":70,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.5 Guidelines and Procedures"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p21-71', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.5 Guidelines and Procedures', 21, 'An organizations forensic guidelines should include general methodologies for investigating an incident using forensic techniques, since it is not feasible to develop comprehensive procedures tailored to every possible situation. However, organizations also should consider developing step-by-step procedures for performing routine tasks, such as imaging a hard disk, capturing and recording volatile information from systems, or securing physical evidence (e.g., removable media). The goal for the guidelines and procedures is to facilitate consistent, effective, and accurate forensic actions, which is particularly important for incidents that may lead to prosecution or internal disciplinary actions.', 'vec_doc-04-nist-sp-800-86-p21-71', 0, 177, 'v2.1.0', '322e69ca2099553acd216d172cb5bc2d1415107f946f4aee8dabfcf43ad06eeb', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.5 Guidelines and Procedures","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"FORENSICS","authority_tier":0,"chunk_seq":71,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.5 Guidelines and Procedures"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p21-72', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.5 Guidelines and Procedures', 21, 'Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the integrity of such records.6 Information is rapidly migrating to a form in which all the information assets exist in electronic form. In both the public and private sectors, it is increasingly important to demonstrate conclusively the authenticity, credibility, and reliability of electronic records, such as the performance of a specific action or decision, or the existence of a certain item of information. Business records have normally been treated as equivalent to originals. Increasingly, some in the legal and forensic communities are concerned with the ease with which electronic records can be created, altered, or otherwise manipulated. In addition, various compliance initiatives in the public and private sectors are making it increasingly important to demonstrate the integrity of electronic records.', 'vec_doc-04-nist-sp-800-86-p21-72', 0, 251, 'v2.1.0', '1e7016820b2d15cdc27b3c5bf9d3ad26b0ef579cc1223b1eb553f6cb8b6ffcdc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.5 Guidelines and Procedures","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"FORENSICS","authority_tier":0,"chunk_seq":72,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.5 Guidelines and Procedures"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p21-73', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.5 Guidelines and Procedures', 21, 'With the explicit caveat that such issues are matters for discussion with legal counsel and senior IT officials and well beyond the scope of this publication, the use of sound, documented, and reasonably explicable forensic techniques coupled with other methods (such as log retention and analysis) is an important resource for decision makers as well as for incident handlers. Forensic guidelines and procedures should be consistent with the organizations policies and all applicable laws. Organizations should include technical experts and legal advisors in the development of guidelines and procedures as a quality assurance measure. Management should also be involved in guideline and procedure development, particularly in ensuring that all major decision-making points are documented and that the proper course of action is defined so that decisions are made consistently.', 'vec_doc-04-nist-sp-800-86-p21-73', 0, 220, 'v2.1.0', '363c568dbac25b87b8b6759f020785606acbfbdc40fab3e621abccfd52632047', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.5 Guidelines and Procedures","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"FORENSICS","authority_tier":0,"chunk_seq":73,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.5 Guidelines and Procedures"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p21-74', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.5 Guidelines and Procedures', 21, '6  For more information on preserving the integrity of computer security logs, see NIST SP 800-92 (DRAFT), Guide to Computer Security Log Management, which is available at http://csrc.nist.gov/publications/nistpubs/. 2-7', 'vec_doc-04-nist-sp-800-86-p21-74', 0, 55, 'v2.1.0', '2c6cc433e89dc42283ec5b0e9c7c6b7ba35d7c6047ea2c16ccf01935b6eb025c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.5 Guidelines and Procedures","subsection":"UNKNOWN","table_id":null,"page":21,"domain":"FORENSICS","authority_tier":0,"chunk_seq":74,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.5 Guidelines and Procedures"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p22-75', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.5 Guidelines and Procedures', 22, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE The guidelines and procedures should support the admissibility of evidence into legal proceedings, including information on gathering and handling evidence properly, preserving the integrity of tools and equipment, maintaining the chain of custody, and storing evidence securely.7  Although it may not be feasible to record every event or action taken in response to an incident, having a record of the major events and actions taken helps ensure that nothing has been overlooked, and helps explain to others how the incident was handled.  This documentation can be useful for case management, report writing, and testifying.  Keeping a record of the dates and times that people worked on an incident, including the time needed to recover systems, can also help calculate the costs of damages.  Also, handling evidence in a forensically sound manner puts decision makers in a position where they can confidently take the necessary actions. It is also important to maintain the guidelines and procedures once they are created so that they remain accurate.  Management should determine how frequently the guidelines and procedures should be reviewed (generally, at least annually).  Reviews should also be conducted whenever the teams policies, guidelines, and procedures undergo significant changes.   When a guideline or procedure is updated, the previous version should be archived for possible future use in legal proceedings.  Guideline and procedure reviews should include the same teams that participate in their creation.  In addition to performing reviews, organizations might choose to conduct exercises that help to validate the accuracy of certain guidelines and procedures.', 'vec_doc-04-nist-sp-800-86-p22-75', 0, 438, 'v2.1.0', 'dd862f86724d3a8e56b2a129f666c91d601cce568e6a7c5e13f23a6f1519d84b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.5 Guidelines and Procedures","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"FORENSICS","authority_tier":0,"chunk_seq":75,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.5 Guidelines and Procedures"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p22-76', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 22, 'The key recommendations on establishing and organizing a forensic capability are as follows: ! Organizations should have a capability to perform computer and network forensics. Forensics is needed for various tasks within an organization, including investigating crimes and inappropriate behavior, reconstructing computer security incidents, troubleshooting operational problems, supporting due diligence for audit record maintenance, and recovering from accidental system damage. Without such a capability, an organization will have difficulty determining what events have occurred within its systems and networks, such as exposures of protected, sensitive data. Also, handling evidence in a forensically sound manner puts decision makers in a position where they can confidently take the necessary actions. ! Organizations should determine which parties should handle each aspect of forensics. Most organizations rely on a combination of their own staff and external parties to perform forensic tasks.', 'vec_doc-04-nist-sp-800-86-p22-76', 0, 251, 'v2.1.0', '93e752fe0f291167f778de647cd0c537d09b0c50e775f8bbfb53f52db95d59bd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"FORENSICS","authority_tier":0,"chunk_seq":76,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p22-77', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 22, 'Organizations should decide which parties should take care of which tasks based on skills and abilities, cost, response time, and data sensitivity. ! Incident handling teams should have robust forensic capabilities. More than one team member should be able to perform each typical forensic activity. Hands-on exercises and IT and forensic training courses can be helpful in building and maintaining skills, as can demonstrations of new tools and technologies. ! Many teams within an organization should participate in forensics. Individuals performing forensic actions should be able to reach out to other teams and individuals within an organization, as needed, for additional assistance. Examples of teams that may provide assistance in these efforts include IT professionals, management, legal advisors, human resources personnel, auditors, and physical security staff.', 'vec_doc-04-nist-sp-800-86-p22-77', 0, 218, 'v2.1.0', '2500b9ba50e6f90e4454b4c1844bff471f3d936091d9d1ecc30f46d282a0ad28', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"FORENSICS","authority_tier":0,"chunk_seq":77,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p22-78', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 22, 'Members of these teams should understand their roles and 7  This document does not describe the computer and network forensic requirements placed on law enforcement. For further information regarding computer and network forensic requirements for law enforcement, see Electronic Crime Scene Investigation: A Guide for First Responders and Forensic Examination of Digital Evidence: A Guide for Law Enforcement, which are both available at http://www.ncjrs.gov/app/topics/topic.aspx?topicid=158. 2-8', 'vec_doc-04-nist-sp-800-86-p22-78', 0, 125, 'v2.1.0', 'daa6b561bd24e9b9a83215a8b0c2bd028fa562244690c20ad2612d2b4eaab133', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":22,"domain":"FORENSICS","authority_tier":0,"chunk_seq":78,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p23-79', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 23, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE responsibilities in forensics, receive training and education on forensicrelated policies, guidelines, and procedures, and be prepared to cooperate with and assist others on forensic actions. ! Forensic considerations should be clearly addressed in policies. At a high level, policies should allow authorized personnel to monitor systems and networks and perform investigations for legitimate reasons under appropriate circumstances. Organizations may also have a separate forensic policy for incident handlers and others with forensic roles that provides more detailed rules for appropriate behavior. Everyone who may be called upon to assist with any forensic efforts should be familiar with and understand the forensic policy. Additional policy considerations are as follows:  Forensic policy should clearly define the roles and responsibilities of all people performing or assisting with the organizations forensic activities.', 'vec_doc-04-nist-sp-800-86-p23-79', 0, 250, 'v2.1.0', 'b2b56944f318ded5c9f721880748e9c7201803152158869459dcc3bf783e5164', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"FORENSICS","authority_tier":0,"chunk_seq":79,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p23-80', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 23, 'The policy should include all internal and external parties that may be involved and should clearly indicate who should contact which parties under different circumstances.  The organizations policies, guidelines, and procedures should clearly explain what forensic actions should and should not be performed under normal and special circumstances and should address the use of anti-forensic tools and techniques. Policies, guidelines, and procedures should also address the handling of inadvertent exposures of sensitive information.  Incorporating forensic considerations into the information system life cycle can lead to more efficient and effective handling of many incidents. Examples include performing auditing on hosts and establishing data retention policies that support performing historical reviews of system and network activity. ! Organizations should create and maintain guidelines and procedures for performing forensic tasks.', 'vec_doc-04-nist-sp-800-86-p23-80', 0, 237, 'v2.1.0', 'e6f6125ea6bdbbe3bd2a0dc906f032996358267c1b7a716ab0889bbd9947302b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"FORENSICS","authority_tier":0,"chunk_seq":80,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p23-81', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 23, 'The guidelines should include general methodologies for investigating an incident using forensic techniques, and step-by-step procedures should explain how to perform routine tasks. The guidelines and procedures should support the admissibility of evidence into legal proceedings. Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the reliability and integrity of such records. The guidelines and procedures should also be reviewed regularly and maintained so that they are accurate. 2-9', 'vec_doc-04-nist-sp-800-86-p23-81', 0, 156, 'v2.1.0', '43913058e4b5e0891a89ef58ce59d5c47f40751e1a48a0782b03a23241a65a12', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":23,"domain":"FORENSICS","authority_tier":0,"chunk_seq":81,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p24-82', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2.6 Re commendations', 24, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE This page has been left blank intentionally. 2-10', 'vec_doc-04-nist-sp-800-86-p24-82', 0, 29, 'v2.1.0', 'f5a5cc66bb073327756fbd528b664d574e774c6395c097e36a9bf00b870736b7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2.6 Re commendations","subsection":"UNKNOWN","table_id":null,"page":24,"domain":"FORENSICS","authority_tier":0,"chunk_seq":82,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2.6 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p25-83', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Performing the Forensic Process', 25, 'The most common goal of performing forensics is to gain a better understanding of an event of interest by finding and analyzing the facts related to that event. As described in Section 2.1, forensics may be needed in many different situations, such as evidence collection for legal proceedings and internal disciplinary actions, and handling of malware incidents and unusual operational problems. Regardless of the need, forensics should be performed using the four-phase process shown in Figure 3-1. The exact details of these steps may vary based on the specific need for forensics; the organizations policies, guidelines, and procedures should indicate any variations from the standard procedure. This section describes the basic phases of the forensic process: collection, examination, analysis, and reporting.8  During collection, data related to a specific event is identified, labeled, recorded, and collected, and its integrity is preserved.', 'vec_doc-04-nist-sp-800-86-p25-83', 0, 238, 'v2.1.0', 'd65a51ac68a726aeb1fa7eaa33181945df9a864c2a33b3fbf3d7e980453994d6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Performing the Forensic Process","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"FORENSICS","authority_tier":0,"chunk_seq":83,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Performing the Forensic Process"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p25-84', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Performing the Forensic Process', 25, 'In the second phase, examination, forensic tools and techniques appropriate to the types of data that were collected are executed to identify and extract the relevant information from the collected data while protecting its integrity. Examination may use a combination of automated tools and manual processes. The next phase, analysis, involves analyzing the results of the examination to derive useful information that addresses the questions that were the impetus for performing the collection and examination. The final phase involves reporting the results of the analysis, which may include describing the actions performed, determining what other actions need to be performed, and recommending improvements to policies, guidelines, procedures, tools, and other aspects of the forensic process. Figure 3-1.', 'vec_doc-04-nist-sp-800-86-p25-84', 0, 203, 'v2.1.0', 'd1450c1b34138ca5e15d7ea33a21f999fcbf6603eae1d337ba144d4106286707', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Performing the Forensic Process","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"FORENSICS","authority_tier":0,"chunk_seq":84,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Performing the Forensic Process"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p25-85', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Performing the Forensic Process', 25, 'Forensic Process As shown at the bottom of Figure 3-1, the forensic process transforms media into evidence, whether evidence is needed for law enforcement or for an organizations internal usage.9  Specifically, the first transformation occurs when collected data is examined, which extracts data from media and transforms it into a format that can be processed by forensic tools.10  Second, data is transformed into information 8  As explained in Section 2.1, the forensic process model presented in this document offers a simple way of looking at the phases of the forensic process. There are many other forensic process models that reflect the same basic principles and overall methodology. Forensic models differ primarily in how granular each phase of the process is and in the terms used for specific phases. Organizations should choose the specific forensic model that is most appropriate for their needs.', 'vec_doc-04-nist-sp-800-86-p25-85', 0, 228, 'v2.1.0', '4b63748f0ae5303f72b165c4b9890be315699da7d4d49c5bb0f90fe7333c8ca4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Performing the Forensic Process","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"FORENSICS","authority_tier":0,"chunk_seq":85,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Performing the Forensic Process"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p25-86', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Performing the Forensic Process', 25, '9  From a legal perspective, the term evidence technically refers only to those items that are admitted into a court case by a judge. However, the term evidence is widely used in a much broader sense, and this publication uses the less restrictive definition of evidence. 10  In this context, the word media refers to both systems and networks. 3-1', 'vec_doc-04-nist-sp-800-86-p25-86', 0, 87, 'v2.1.0', 'de0c743c60f6148ba0bb8dcd0c1ec79a6af3152b06dcad6159727d39378d700c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Performing the Forensic Process","subsection":"UNKNOWN","table_id":null,"page":25,"domain":"FORENSICS","authority_tier":0,"chunk_seq":86,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Performing the Forensic Process"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p26-87', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Performing the Forensic Process', 26, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE through analysis.  Finally, the information transformation into evidence is analogous to transferring knowledge into actionusing the information produced by the analysis in one or more ways during the reporting phase.  For example, it could be used as evidence to help prosecute a specific individual, actionable information to help stop or mitigate some activity, or knowledge in the generation of new leads for a case.', 'vec_doc-04-nist-sp-800-86-p26-87', 0, 122, 'v2.1.0', '106ec3a4d6db9627195431145378e06a784affccf16930a8dbc863519db798c0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Performing the Forensic Process","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"FORENSICS","authority_tier":0,"chunk_seq":87,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Performing the Forensic Process"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p26-88', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 26, 'The first step in the forensic process is to identify potential sources of data and acquire data from them. Section 3.1.1 describes the variety of data sources available and discusses actions that organizations can take to support the ongoing collection of data for forensic purposes. Section 3.1.2 describes the recommended steps for collecting data, including additional actions necessary to support legal or internal disciplinary proceedings. Section 3.1.3 discusses incident response considerations, emphasizing the need to weigh the value of collected data against the costs and impact to the organization of the collection process. 3.1.1 Identifying Possible Sources of Data The increasingly widespread use of digital technology for both professional and personal purposes has led to an abundance of data sources. The most obvious and common sources of data are desktop computers, servers, network storage devices, and laptops.', 'vec_doc-04-nist-sp-800-86-p26-88', 0, 234, 'v2.1.0', '2de7901e0d15e10b764be858bd0b8683201658973323416da8a42c823c9eb450', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"FORENSICS","authority_tier":0,"chunk_seq":88,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p26-89', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 26, 'These systems typically have internal drives that accept media, such as CDs and DVDs, and also have several types of ports (e.g., Universal Serial Bus [USB], Firewire, Personal Computer Memory Card International Association [PCMCIA]) to which external data storage media and devices can be attached. Examples of external storage forms that might be sources of data are thumb drives, memory and flash cards, optical discs, and magnetic disks. Standard computer systems also contain volatile data that is available temporarily (i.e., until the system is shut down or rebooted). In addition to computer-related devices, many types of portable digital devices (e.g., PDAs, cell phones, digital cameras, digital recorders, audio players) may also contain data. Analysts should be able to survey a physical area, such as an office, and recognize the possible sources of data.11 Analysts should also think of possible data sources located in other places.', 'vec_doc-04-nist-sp-800-86-p26-89', 0, 237, 'v2.1.0', '3a406c733e4027d0e3e6a7dd1c18aaf8fe5b1e9a57b1e34fb9fc38259ff03e34', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"FORENSICS","authority_tier":0,"chunk_seq":89,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p26-90', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 26, 'For example, as described in Sections 6 and 7, there are usually many sources of information within an organization regarding network activity and application usage. Information may also be recorded by other organizations, such as logs of network activity for an Internet service provider (ISP). Analysts should be mindful of the owner of each data source and the effect that this might have on collecting data. For example, getting copies of ISP records typically requires a court order. Analysts should also be aware of the organizations policies, as well as legal considerations, regarding externally owned property at the organizations facilities (for example, an employees personal laptop or a contractors laptop). The situation can become even more complicated if locations outside the organizations control are involved, such as an incident involving a computer at a telecommuters home office.', 'vec_doc-04-nist-sp-800-86-p26-90', 0, 227, 'v2.1.0', '70bb01de12b5760df83de078faccd955d51361a8f61235141f7850d800304eaa', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"FORENSICS","authority_tier":0,"chunk_seq":90,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p26-91', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 26, 'Sometimes it is simply not feasible to collect data from a primary data source; therefore, analysts should be aware of alternate data sources that might contain some or all of the same data, and should use those sources instead of the unattainable source. Organizations can take ongoing proactive measures to collect data that may be useful for forensic purposes. For example, as described in Section 5.1.1, most OSs can be configured to audit and record certain types of events, such as authentication attempts and security policy changes, as part of normal operations. Audit records can provide valuable information, including the time that an event occurred and 11  Because forensic actions can be performed by people in various roles within an organization, this document typically uses the word analyst as a generic term for individuals performing forensic actions. 3-2', 'vec_doc-04-nist-sp-800-86-p26-91', 0, 219, 'v2.1.0', '3bddbeedef1532dbd490cd0146e37c5054bc5e0f1b900c5ace5fd78d222d30d1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":26,"domain":"FORENSICS","authority_tier":0,"chunk_seq":91,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p27-92', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 27, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the origin of the event.12  Another helpful action is to implement centralized logging, which means that certain systems and applications forward copies of their logs to secure central log servers. Centralized logging prevents unauthorized users from tampering with logs and employing anti-forensic techniques to impede analysis.13  Performing regular backups of systems allows analysts to view the contents of the system as they were at a particular time. In addition, as described in Sections 6 and 7, security monitoring controls such as intrusion detection software, antivirus software, and spyware detection and removal utilities can generate logs that show when and how an attack or intrusion took place. Another proactive data collecting measure is the monitoring of user behavior, such as keystroke monitoring, which records the keyboard usage of a particular system.', 'vec_doc-04-nist-sp-800-86-p27-92', 0, 235, 'v2.1.0', '863e4c93dc7dd179587b34496aba205b2beea5a2bcf888fcbfa1ddcec37d49f4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"FORENSICS","authority_tier":0,"chunk_seq":92,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p27-93', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 27, 'Although this measure can provide a valuable record of activity, it can also be a violation of privacy unless users are advised through organizational policy and login banners that such monitoring may be performed. Most organizations do not employ techniques such as keystroke monitoring except when gathering additional information on a suspected incident. Authority for performing such monitoring should be discussed with legal advisors and documented clearly in the organizations policy. 3.1.2 Acquiring the Data After identifying potential data sources, the analyst needs to acquire the data from the sources. Data acquisition should be performed using a three-step process: developing a plan to acquire the data, acquiring the data, and verifying the integrity of the acquired data. Although the following items provide an overview of these three steps, the specific details behind steps 2 and 3 vary based on the type of data being acquired.', 'vec_doc-04-nist-sp-800-86-p27-93', 0, 237, 'v2.1.0', 'c43ccd49eb4b24578c12aebab353c3602b18cf881ca87e45b398c7244cda8810', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"FORENSICS","authority_tier":0,"chunk_seq":93,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p27-94', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.1 D ata Collection', 27, 'Sections 4.2, 5.2, 6.3, and 7.3 provide more detailed explanations of acquiring and verifying the integrity of data files, OS data, network traffic data, and application data, respectively.', 'vec_doc-04-nist-sp-800-86-p27-94', 0, 48, 'v2.1.0', '1eebe77303b12ffe811aceac3c18801be91e1b04819244d809218ae46b8ec5cd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.1 D ata Collection","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"FORENSICS","authority_tier":0,"chunk_seq":94,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.1 D ata Collection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p27-95', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases', 27, 'because there are multiple potential data sources. The analyst should create a plan that prioritizes the sources, establishing the order in which the data should be acquired. Important factors for prioritization include the following: ! Likely Value. Based on the analysts understanding of the situation and previous experience in similar situations, the analyst should be able to estimate the relative likely value of each potential data source. ! Volatility. Volatile data refers to data on a live system that is lost after a computer is powered down or due to the passage of time. Volatile data may also be lost as a result of other actions performed on the system. In many cases, acquiring volatile data should be given priority over non-volatile data. However, non-volatile data may also be somewhat dynamic in nature (e.g., log files that are overwritten as new events occur). ! Amount of Effort Required. The amount of effort required to acquire different data sources may vary widely.', 'vec_doc-04-nist-sp-800-86-p27-95', 0, 249, 'v2.1.0', '2ae6f168ad28b1ee8e24fe62bdb5a598aa9a12bb97b6fe76f66f75676aec26d0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"FORENSICS","authority_tier":0,"chunk_seq":95,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p27-96', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases', 27, 'The effort involves not only the time spent by analysts and others within the organization (including legal advisors) but also the cost of equipment and services (e.g., outside experts). For example, acquiring data from a network router would probably require much less effort than acquiring data from an ISP. 12  If auditing was not enabled on a system when an event occurred, incident handlers might enable auditing after the event is discovered in an attempt to record evidence of ongoing activity. Because this could alter evidence of the incident and alert an attacker to the presence of the incident handlers, the impact of enabling auditing should be considered, and incident handlers should document their actions. 13  For more information on centralized logging, see NIST SP 800-92 (DRAFT), Guide to Computer Security Log Management, which is available at http://csrc.nist.gov/publications/nistpubs/. 3-3', 'vec_doc-04-nist-sp-800-86-p27-96', 0, 229, 'v2.1.0', '32683595013438e749f11c2734e3481f80267c1b6648987218e322064147928c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases","subsection":"UNKNOWN","table_id":null,"page":27,"domain":"FORENSICS","authority_tier":0,"chunk_seq":96,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p28-97', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases', 28, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE By considering these three factors for each potential data source, analysts can make informed decisions regarding the prioritization of data source acquisition, as well as determining which data sources to acquire.  In some cases, there are so many possible data sources that it is not practical to acquire them all.  Organizations should carefully consider the complexities of prioritizing data source acquisition and develop written plans, guidelines, and procedures that can help analysts perform prioritization effectively. 2. Acquire the data.  If the data has not already been acquired by security tools, analysis tools, or other means, the general process for acquiring data involves using forensic tools to collect volatile data, duplicating non-volatile data sources to collect their data, and securing the original non-volatile data sources.  Data acquisition can be performed either locally or over a network. Although it is generally preferable to acquire data locally because there is greater control over the system and data, local data collection is not always feasible (e.g., system in locked room, system in another location).  When acquiring data over a network, decisions should be made regarding the type of data to be collected and the amount of effort to use.  For instance, it might be necessary to acquire data from several systems through different network connections, or it might be sufficient to copy a logical volume from just one system.', 'vec_doc-04-nist-sp-800-86-p28-97', 0, 383, 'v2.1.0', '94acb436a4c9dd789cc481396e7250caa5cb7ef83c62715c7d982523817323ea', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"FORENSICS","authority_tier":0,"chunk_seq":97,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1. Develop a plan to acquire the data.  Developing a plan is an important first step in most cases"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p28-98', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 28, 'verified. It is particularly important for an analyst to prove that the data has not been tampered with if it might be needed for legal reasons. Data integrity verification typically consists of using tools to compute the message digest of the original and copied data, then comparing the digests to make sure that they are the same. Before the analyst begins to collect any data, a decision should be made by the analyst or management (in accordance with the organizations policies and legal advisors) on the need to collect and preserve evidence in a way that supports its use in future legal or internal disciplinary proceedings. In such situations, a clearly defined chain of custody should be followed to avoid allegations of mishandling or tampering of evidence.', 'vec_doc-04-nist-sp-800-86-p28-98', 0, 193, 'v2.1.0', '81c3b9d01dcaa7fc2d6fa3e40bbfadc49f090ed3335117eab08b868ec74359b0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"FORENSICS","authority_tier":0,"chunk_seq":98,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p28-99', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 28, 'This involves keeping a log of every person who had physical custody of the evidence, documenting the actions that they performed on the evidence and at what time, storing the evidence in a secure location when it is not being used, making a copy of the evidence and performing examination and analysis using only the copied evidence, and verifying the integrity of the original and copied evidence. If it is unclear whether or not evidence needs to be preserved, by default it generally should be preserved. In addition, several other steps should be taken. Throughout the process, a detailed log should be kept of every step that was taken to collect the data, including information about each tool used in the process. The documentation allows other analysts to repeat the process later if needed. Additionally, evidence should be photographed to provide visual reminders of the computer setup and peripheral devices.', 'vec_doc-04-nist-sp-800-86-p28-99', 0, 230, 'v2.1.0', '6979afa00bbf1e4f09aa75d60a1a87c77a9181e0f38fefc664e668bdca37ad75', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"FORENSICS","authority_tier":0,"chunk_seq":99,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p28-100', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 28, 'In addition, before actually touching a system, the analyst should make a note or photograph of any pictures, documents, running programs, and other relevant information displayed on the monitor. If a screen saver is active, that should be documented as well since it may be password-protected. If possible, one person on the scene should be designated the evidence custodian, and given the sole responsibility to photograph, document, and label every item that is collected, and record every action that was taken along with who performed the action, where it was performed, and at what time. Since the evidence may not be needed for legal proceedings for an extended time, proper documentation enables an analyst to remember exactly what was done to collect data and can be used to refute claims of mishandling.', 'vec_doc-04-nist-sp-800-86-p28-100', 0, 204, 'v2.1.0', '07aead9cb152cd6395af1183d6c7407ab62e4a784c8a3bed469ce3aef965571a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"FORENSICS","authority_tier":0,"chunk_seq":100,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p28-101', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 28, 'To assist the analyst with evidence collection, the necessary resources, such as forensic workstations, backup devices, blank media, and evidence handling supplies (e.g., hard-bound notebooks, chain of custody forms, evidence storage bags and tags, evidence tape, digital cameras) should be prepared 3-4', 'vec_doc-04-nist-sp-800-86-p28-101', 0, 76, 'v2.1.0', '21be1d0fabb779b37a1c5cb4f38c67c4d654bfbf1235bc2ace95be9958d48c96', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":28,"domain":"FORENSICS","authority_tier":0,"chunk_seq":101,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p29-102', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 29, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE beforehand. In some cases, it may be necessary to ensure that the scene is physically secured to prevent unauthorized access and alteration of the evidence. This may be as simple as having a physical security staff member guard a room. There also may be situations where a law enforcement representative should handle the data collection for legal reasons. This includes, but is not limited to, obtaining ISP records and collecting data from external computer systems and unusual devices and media. Based on guidance from legal advisors, organizations should determine in advance what types of data are best collected by law enforcement officials. Analysts should take into account what will be done with the collected data and plan for the potential ramifications. In some cases, the data may be turned over to a law enforcement agency or another external party for examination and analysis.', 'vec_doc-04-nist-sp-800-86-p29-102', 0, 239, 'v2.1.0', 'b51f2f2d09a526daa4ff8a0b7ecaf0f834b4cf5f767d050bfdcbffdbe1ee70f2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"FORENSICS","authority_tier":0,"chunk_seq":102,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p29-103', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 29, 'This could result in the collected hardware being unavailable for an extended period of time. If the original media needs to be kept secured for legal proceedings, it could be unavailable for years. Another concern is that sensitive information unrelated to the investigation (e.g., medical records, financial information) might be inadvertently captured along with the desired data. 3.1.3 Incident Response Considerations When performing forensics during incident response, an important consideration is how and when the incident should be contained. Isolating the pertinent systems from external influences may be necessary to prevent further damage to the system and its data or to preserve evidence. In many cases, the analyst should work with the incident response team to make a containment decision (e.g., disconnecting network cables, unplugging power, increasing physical security measures, gracefully shutting down a host).', 'vec_doc-04-nist-sp-800-86-p29-103', 0, 234, 'v2.1.0', '69553e23c5c02790f2e1ee72bd80288aedb0a83e5778c50659c491bf49a0611d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"FORENSICS","authority_tier":0,"chunk_seq":103,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p29-104', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 29, 'This decision should be based on existing policies and procedures regarding incident containment, as well as the teams assessment of the risk posed by the incident, so that the chosen containment strategy or combination of strategies sufficiently mitigates risk while maintaining the integrity of potential evidence whenever possible. The organization should also consider in advance the impact that various containment strategies may have on the ability of the organization to operate effectively. For example, taking a critical system offline for several hours to acquire disk images and other data might adversely affect the ability of the organization to perform its necessary operations. Significant downtime could result in substantial monetary losses to the organization. Therefore, care should be taken to minimize disruptions to an organizations operations.', 'vec_doc-04-nist-sp-800-86-p29-104', 0, 217, 'v2.1.0', '9c0a5632fc74ddac0dbbbfe3d0897db1f316321831e1139f5d4671769e098800', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"FORENSICS","authority_tier":0,"chunk_seq":104,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p29-105', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 29, 'One step often taken to contain an incident is to secure the perimeter around a computer and limit access to authorized personnel during the collection process to ensure that the evidence is not altered. Also, a list of all users who have access to the computer should be documented, because these persons may be able to provide passwords or information on where specific data is located. If the computer is connected to a network, disconnecting network cables attached to the computer can prevent remote users from modifying the computers data. If the computer uses a wireless network connection, the external network adapter may be unplugged from the computer or the internal network adapter may be disabled to sever the network connection. If neither option is possible, then powering off the wireless network access point that the computer is using should achieve the same result; however, doing so may prevent users outside the scope of the investigation from performing their daily routines.', 'vec_doc-04-nist-sp-800-86-p29-105', 0, 250, 'v2.1.0', 'd94ee435456981161fe5cbb656ebabb29a2ed2838136012136c978f242fadd75', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"FORENSICS","authority_tier":0,"chunk_seq":105,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p29-106', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. Verify the integrity of the data.  After the data has been acquired, its integrity should be', 29, 'In addition, there could be more than one access point within range of the computer. Some wireless network adapters automatically attempt to connect to other access points when the primary access point is unavailable, so that containing the incident in this way could involve disconnecting several access points. 3-5', 'vec_doc-04-nist-sp-800-86-p29-106', 0, 79, 'v2.1.0', '4c85c3bf7b36d22e5311601c4f324002d6d4800edc806f1f5a16f57c79f5d681', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be","subsection":"UNKNOWN","table_id":null,"page":29,"domain":"FORENSICS","authority_tier":0,"chunk_seq":106,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. Verify the integrity of the data.  After the data has been acquired, its integrity should be"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p30-107', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.2 Exam ination', 30, 'After data has been collected, the next phase is to examine the data, which involves assessing and extracting the relevant pieces of information from the collected data.  This phase may also involve bypassing or mitigating OS or application features that obscure data and code, such as data compression, encryption, and access control mechanisms.  An acquired hard drive may contain hundreds of thousands of data files; identifying the data files that contain information of interest, including information concealed through file compression and access control, can be a daunting task.  In addition, data files of interest may contain extraneous information that should be filtered.  For example, yesterdays firewall log might hold millions of records, but only five of the records might be related to the event of interest. Fortunately, various tools and techniques can be used to reduce the amount of data that has to be sifted through.  Text and pattern searches can be used to identify pertinent data, such as finding documents that mention a particular subject or person, or identifying e-mail log entries for a particular e-mail address. Another helpful technique is to use a tool that can determine the type of contents of each data file, such as text, graphics, music, or a compressed file archive.  Knowledge of data file types can be used to identify files that merit further study, as well as to exclude files that are of no interest to the examination.  There are also databases containing information about known files, which can also be used to include or exclude files from further consideration.  Specific information about examination tools and techniques is presented in Sections 4.3, 5.3, 6.4, and 7.4.', 'vec_doc-04-nist-sp-800-86-p30-107', 0, 431, 'v2.1.0', 'a8b6dd28aff262a64d2166cfe4a0e64960f3a8533aa0f3541ec64374956408b2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.2 Exam ination","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"FORENSICS","authority_tier":0,"chunk_seq":107,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.2 Exam ination"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p30-108', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.3 A nalysis', 30, 'Once the relevant information has been extracted, the analyst should study and analyze the data to draw conclusions from it.14  The foundation of forensics is using a methodical approach to reach appropriate conclusions based on the available data or determine that no conclusion can yet be drawn.  The analysis should include identifying people, places, items, and events, and determining how these elements are related so that a conclusion can be reached.  Often, this effort will include correlating data among multiple sources.  For instance, a network intrusion detection system (IDS) log may link an event to a host, the host audit logs may link the event to a specific user account, and the host IDS log may indicate what actions that user performed.  Tools such as centralized logging and security event management software can facilitate this process by automatically gathering and correlating the data.  Comparing system characteristics to known baselines can identify various types of changes made to the system.', 'vec_doc-04-nist-sp-800-86-p30-108', 0, 256, 'v2.1.0', '50c2371b38e47e64f131f46a01b870184818270457a94299f8661397338e76c7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.3 A nalysis","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"FORENSICS","authority_tier":0,"chunk_seq":108,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.3 A nalysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p30-109', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 8 describes this analysis process in more detail.', 30, 'As described in Section 3.1.2, if evidence may be needed for legal or internal disciplinary actions, analysts should carefully document the findings and all steps taken.', 'vec_doc-04-nist-sp-800-86-p30-109', 0, 43, 'v2.1.0', 'd3adac55415582c9ca9aade14478651dbef2bb39056c6b1f34953fb0a37e06f1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 8 describes this analysis process in more detail.","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"FORENSICS","authority_tier":0,"chunk_seq":109,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 8 describes this analysis process in more detail."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p30-110', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.4 Re porting', 30, 'The final phase is reporting, which is the process of preparing and presenting the information resulting from the analysis phase.  Many factors affect reporting, including the following: ! Alternative Explanations.  When the information regarding an event is incomplete, it may not be possible to arrive at a definitive explanation of what happened.  When an event has two or more plausible explanations, each should be given due consideration in the reporting process. Analysts should use a methodical approach to attempt to prove or disprove each possible explanation that is proposed. 14  Some forensic process methodologies have a separate analysis phase after the examination phase.  For the sake of simplicity, this publication presents analysis as part of the examination phase.  Typically, an analyst examines data and performs analysis of that data, then conducts additional examination and analysis based on the results of the initial analysis. 3-6', 'vec_doc-04-nist-sp-800-86-p30-110', 0, 240, 'v2.1.0', '3b7661e73932323709f513078e584c9cbb0a9b4b1593ca6d605fae0cc26ca2a3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.4 Re porting","subsection":"UNKNOWN","table_id":null,"page":30,"domain":"FORENSICS","authority_tier":0,"chunk_seq":110,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.4 Re porting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p31-111', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.4 Re porting', 31, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Audience Consideration. Knowing the audience to which the data or information will be shown is important. An incident requiring law enforcement involvement requires highly detailed reports of all information gathered, and may also require copies of all evidentiary data obtained. A system administrator might want to see network traffic and related statistics in great detail. Senior management might simply want a high-level overview of what happened, such as a simplified visual representation of how the attack occurred, and what should be done to prevent similar incidents. ! Actionable Information. Reporting also includes identifying actionable information gained from data that may allow an analyst to collect new sources of information. For example, a list of contacts may be developed from the data that might lead to additional information about an incident or crime.', 'vec_doc-04-nist-sp-800-86-p31-111', 0, 236, 'v2.1.0', '9bd0e623066083d3c5cfd0e868b72cfbe335ca10be953504fd52813d85484f54', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.4 Re porting","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"FORENSICS","authority_tier":0,"chunk_seq":111,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.4 Re porting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p31-112', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.4 Re porting', 31, 'Also, information might be obtained that could prevent future events, such as a backdoor on a system that could be used for future attacks, a crime that is being planned, a worm scheduled to start spreading at a certain time, or a vulnerability that could be exploited. As part of the reporting process, analysts should identify any problems that may need to be remedied, such as policy shortcomings or procedural errors. Many forensic and incident response teams hold formal reviews after each major event. Such reviews tend to include serious consideration of possible improvements to guidelines and procedures, and typically at least some minor changes are approved and implemented after each review. For example, one common problem is that many organizations find it resource-intensive to maintain current lists of personnel to contact regarding each different type of incident that may occur.', 'vec_doc-04-nist-sp-800-86-p31-112', 0, 225, 'v2.1.0', '0c1733fa0f1b69f4cefd83d2a5bc2d2fc413734eda1f6f4f031336ee1e5564b6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.4 Re porting","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"FORENSICS","authority_tier":0,"chunk_seq":112,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.4 Re porting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p31-113', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.4 Re porting', 31, 'Other common issues are what to do with the gigabytes or terabytes of data collected during an investigation, and how security controls (e.g., auditing, logging, intrusion detection) can be altered to record additional data that would be helpful for future investigations. Formal reviews can help identify ways to improve these processes. Once changes to guidelines and procedures are implemented, all team members should be informed of the changes and frequently reminded of the proper procedures to follow. Teams typically have formal mechanisms for tracking changes and identifying the current versions of each process and procedure document. In addition, many teams have posters or other highly visible documents mounted on walls or doors that remind teams of the key steps to take, so that everyone is constantly reminded of how things are supposed to be done. In addition to addressing identified problems, analysts should take other steps to maintain and grow their skills.', 'vec_doc-04-nist-sp-800-86-p31-113', 0, 245, 'v2.1.0', '993d7e02ad7f51e5551e6ee1b570768d4839e14d9586c959f712190d0104cb0b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.4 Re porting","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"FORENSICS","authority_tier":0,"chunk_seq":113,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.4 Re porting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p31-114', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.4 Re porting', 31, 'As a matter of maintaining their certification or accreditation, some forensic examiners must routinely refresh themselves with the latest tools and techniques that address the latest technologies pertaining to computer storage media, data types and formats, and other relevant issues. Whether required or not, periodic refreshing of skills through coursework, on-the-job experience, and academic sources helps ensure that people performing forensic actions keep pace with rapidly changing technologies and job responsibilities. Some organizations require all members of their forensic teams to pass annual proficiency examinations. Periodic review of policies, guidelines, and procedures also helps ensure that the organization stays current with trends in technology and changes in law.', 'vec_doc-04-nist-sp-800-86-p31-114', 0, 197, 'v2.1.0', '44473fea7f90973a55fdd52ad04e25f21454758292bb3cb042f469d1af6cee1f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.4 Re porting","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"FORENSICS","authority_tier":0,"chunk_seq":114,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.4 Re porting"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p31-115', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.5 Re commendations', 31, 'The key recommendations presented in this section for the forensic process are as follows: ! Organizations should perform forensics using a consistent process.  This guide presents a four-phase forensic process, with collection, examination, analysis, and reporting phases.  The exact details of each phase may vary based on the need for forensics. ! Analysts should be aware of the range of possible data sources.  Analysts should be able to survey a physical area and recognize possible sources of data.  Analysts should also think of possible data sources located elsewhere within an organization and outside the organization. 3-7', 'vec_doc-04-nist-sp-800-86-p31-115', 0, 159, 'v2.1.0', '85ecfbce676e2ceeb078ce443701a45d3966256ca5015c9676dc40ee8b210995', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":31,"domain":"FORENSICS","authority_tier":0,"chunk_seq":115,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p32-116', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.5 Re commendations', 32, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Analysts should be prepared to use alternate data sources if it is not feasible to collect data from a primary source. ! Organizations should be proactive in collecting useful data. Configuring auditing on OSs, implementing centralized logging, performing regular system backups, and using security monitoring controls can all generate sources of data for future forensic efforts. ! Analysts should perform data collection using a standard process. The recommended steps in this process are identifying sources of data, developing a plan to acquire the data, acquiring the data, and verifying the integrity of the data. The plan should prioritize the data sources, establishing the order in which the data should be acquired based on the likely value of the data, the volatility of the data, and the amount of effort required.', 'vec_doc-04-nist-sp-800-86-p32-116', 0, 223, 'v2.1.0', '9042c6d579ffcbbe9ac7c120993661997f9bc47b11db99fcf9166ee75c16f9eb', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"FORENSICS","authority_tier":0,"chunk_seq":116,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p32-117', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.5 Re commendations', 32, 'Before data collection begins, a decision should be made by the analyst or management regarding the need to collect and preserve evidence in a manner that supports its use in future legal or internal disciplinary proceedings. In such situations, a clearly defined chain of custody should be followed to avoid allegations of mishandling or tampering of evidence. If it is unclear whether or not evidence needs to be preserved, by default it generally should be preserved. ! Analysts should use a methodical approach to studying the data. The foundation of forensics is using a methodical approach in analyzing the available data so that analysts can either draw appropriate conclusions based on the available data or determine that no conclusion can yet be drawn. If evidence might be needed for legal or internal disciplinary actions, analysts should carefully document the findings and all steps taken. ! Analysts should review their processes and practices.', 'vec_doc-04-nist-sp-800-86-p32-117', 0, 240, 'v2.1.0', 'a8e6081c7f7de9b5b608fa2ed1087e5a98545463b9b63bef63b93b679e4cf0d4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"FORENSICS","authority_tier":0,"chunk_seq":117,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p32-118', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3.5 Re commendations', 32, 'Reviews of current and recent forensic actions can help identify policy shortcomings, procedural errors, and other issues that might need to be remedied, as well as ensuring that the organization stays current with trends in technology and changes in law. 3-8', 'vec_doc-04-nist-sp-800-86-p32-118', 0, 65, 'v2.1.0', '63081ad0cbeda74fa3ac782ecbc58e2fc857d4ec998b1c8d35160b66beacc9ef', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":32,"domain":"FORENSICS","authority_tier":0,"chunk_seq":118,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p33-119', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4. Using Data from Data Files', 33, 'A data file (also called a file) is a collection of information logically grouped into a single entity and referenced by a unique name, such as a filename.  A file can be of many data types, including a document, an image, a video, or an application.  Successful forensic processing of computer media depends on the ability to collect, examine, and analyze the files that reside on the media. This section provides an overview of the most common media types and filesystemsmethods for naming, storing, organizing, and accessing files.  It then discusses how files should be collected and how the integrity of the files should be preserved.  The section also discusses various technical issues related to file recovery, such as recovering data from deleted files.  The last portion of the section describes the examination and analysis of files, providing guidance on tools and techniques that can assist analysts.15', 'vec_doc-04-nist-sp-800-86-p33-119', 0, 229, 'v2.1.0', '38579ef7b8d6995ccb77babfb73d4667b761da858359d6c18eaaeabd64f62296', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4. Using Data from Data Files","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"FORENSICS","authority_tier":0,"chunk_seq":119,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4. Using Data from Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p33-120', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 33, 'Before attempting to collect or examine files, analysts should have a reasonably comprehensive understanding of files and filesystems.  First, analysts should be aware of the variety of media that may contain files; Section 4.1.1 provides several examples of the media used in personal computers and other types of digital devices. Section 4.1.2 then explains how filesystems are used to organize files and provides an overview of several common filesystems.  Section 4.1.3 discusses how data from deleted files can still exist within filesystems. 4.1.1 File Storage Media The widespread use of computers and other digital devices has resulted in a significant increase in the number of different media types that are used to store files.  In addition to traditional media types such as hard drives and floppy disks, files are often stored on consumer devices such as PDAs and cell phones, as well as on newer media types, such as flash memory cards, which were made popular by digital cameras. Table 4-1 lists media types that are commonly used on computers and digital devices.  This list does not include every media type available; rather, it is intended to show the variety of media types that an analyst might come across. 15  For additional information regarding examination and analysis, see Examination of Digital Evidence: A Guide for Law Enforcement, which can be found at http://www.ncjrs.gov/pdffiles1/nij/199408.pdf. 4-1', 'vec_doc-04-nist-sp-800-86-p33-120', 0, 359, 'v2.1.0', 'b321b1134fb451019a5821872636b78b4c4f50916a293704f49ddadadb2c1de9', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":33,"domain":"FORENSICS","authority_tier":0,"chunk_seq":120,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p34-121', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 34, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Table 4-1.', 'vec_doc-04-nist-sp-800-86-p34-121', 0, 19, 'v2.1.0', 'dc4e9c9acf5a95048aa66a317ab0a5e6b3736a060abcd5659151a8678e35daf1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"FORENSICS","authority_tier":0,"chunk_seq":121,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p34-122', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 34, 'Commonly Used Media Types Media Type Reader Typical Capacity16 Comments Primarily Used in Personal Computers Floppy disk Floppy disk drive 1.44 megabytes (MB) 3.5-inch disks; decreasing in popularity CD-ROM CD-ROM drive 650 MB800 MB Includes write-once (CD-R) and rewritable (CD- RW) disks; most commonly used media DVD-ROM DVD-ROM drive 1.67 gigabytes (GB)15.9 GB Includes write-once (DVD±R) and rewritable (DVD±RW) single and dual layer disks Hard drive N/A 20 GB400 GB Higher capacity drives used in many file servers Zip disk Zip drive 100 MB750 MB Larger than a floppy disk Jaz disk Jaz drive 1 GB2 GB Similar to Zip disks; no longer manufactured Backup tape Compatible tape drive 80 MB320 GB Many resemble audio cassette tapes; fairly susceptible to corruption from environmental conditions Magneto optical (MO) disk Compatible MO drive 600 MB9.1 GB 5.25-inch disks; less susceptible to environmental conditions than backup tapes Advanced Technology Attachment (ATA) flash card PCMCIA slot 8 MB2 GB PCMCIA flash memory card; measures 85.6 x 54 x 5 mm Used by Many Types of Digital Devices Flash/Jump drive USB interface 16 MB2 GB Also known as thumb drives because of their size CompactFlash card PCMCIA adapter or memory card reader 16 MB6 GB Type I cards measure 43 x 36 x 3.3 mm; Type II cards measure 43 x 36 x 5 mm Microdrive PCMCIA adapter or memory card reader 340 MB4 GB Same interface and form factor as CompactFlash Type II cards MultiMediaCard (MMC) PCMCIA adapter or memory card reader 16 MB512 MB Measures 24 x 32 x 1.4 mm Secure Digital (SD) Card PCMCIA adapter or memory card reader 32 MB1 GB Compliant with Secure Digital Music Initiative (SDMI) requirements; provides built-in data encryption of file contents; similar in form factor to MMCs Memory Stick PCMCIA adapter or memory card reader 16 MB2 GB Includes Memory Stick (50 x 21.5 x 2.8 mm), Memory Stick Duo (31 x 20 x 1.6 mm), Memory Stick PRO, Memory Stick PRO Duo; some are compliant with SDMI requirements and provide built-in encryption of file contents SmartMedia Card PCMCIA adapter or memory card reader 8 MB128 MB Measures 37 x 45 x 0.76 mm xD-Picture Card PCMCIA adapter or xD-Picture card reader 16 MB512 MB Currently used only in Fujifilm and Olympus digital cameras; measures 20 x 25 x 1.7 mm 16  The maximum capacity of many media types increases over time because of advances in technology and reductions in cost.', 'vec_doc-04-nist-sp-800-86-p34-122', 0, 606, 'v2.1.0', '68d004c29df9428c2ee09c743180ecda6f1264c75345439fcf974c52a6192992', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":34,"domain":"FORENSICS","authority_tier":0,"chunk_seq":122,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p35-123', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 35, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 4.1.2 Filesystems Before media can be used to store files, the media must usually be partitioned and formatted into logical volumes. Partitioning is the act of logically dividing a media into portions that function as physically separate units. A logical volume is a partition or a collection of partitions acting as a single entity that has been formatted with a filesystem. Some media types, such as floppy disks, can contain at most one partition (and consequently, one logical volume). The format of the logical volumes is determined by the selected filesystem. A filesystem defines the way that files are named, stored, organized, and accessed on logical volumes. Many different filesystems exist, each providing unique features and data structures. However, all filesystems share some common traits. First, they use the concepts of directories and files to organize and store data.', 'vec_doc-04-nist-sp-800-86-p35-123', 0, 238, 'v2.1.0', 'e5b9aa2823f59cec5d317747cb807eae23cb6fa0f8793bd1bb8624ac3c5069b5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"FORENSICS","authority_tier":0,"chunk_seq":123,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p35-124', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 35, 'Directories are organizational structures that are used to group files together. In addition to files, directories may contain other directories called subdirectories. Second, filesystems use some data structure to point to the location of files on media. In addition, they store each data file written to media in one or more file allocation units. These are referred to as clusters by some filesystems (e.g., File Allocation Table [FAT], NT File System [NTFS]) and as blocks by other filesystems (e.g., UNIX and Linux). A file allocation unit is simply a group of sectors, which are the smallest units that can be accessed on media. Some commonly used filesystems are as follows: ! FAT12.17  FAT12 is used only on floppy disks and FAT volumes smaller than 16 MB. FAT12 uses a 12-bit file allocation table entry to address an entry in the filesystem. ! FAT16. MS-DOS, Windows 95/98/NT/2000/XP, Windows Server 2003, and some UNIX OSs support FAT16 natively.', 'vec_doc-04-nist-sp-800-86-p35-124', 0, 240, 'v2.1.0', '69a8a4a97d3b30a96fa6c804508af82b7c6dbfd9cf4dd1ef8d97d07de0a9658f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"FORENSICS","authority_tier":0,"chunk_seq":124,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p35-125', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 35, 'FAT16 is also commonly used for multimedia devices such as digital cameras and audio players. FAT16 uses a 16-bit file allocation table entry to address an entry in the filesystem. FAT16 volumes are limited to a maximum size of 2 GB in MS-DOS and Windows 95/98. Windows NT and newer OSs increase the maximum volume size for FAT16 to 4 GB. ! FAT32.18  Windows 95 Original Equipment Manufacturer (OEM) Service Release 2 (OSR2), Windows 98/2000/XP, and Windows Server 2003 support FAT32 natively, as do some multimedia devices. FAT32 uses a 32-bit file allocation table entry to address an entry in the filesystem. The maximum FAT32 volume size is 2 terabytes (TB). ! NTFS. Windows NT/2000/XP and Windows Server 2003 support NTFS natively. NTFS is a recoverable filesystem, which means that it can automatically restore the consistency of the filesystem when errors occur.', 'vec_doc-04-nist-sp-800-86-p35-125', 0, 218, 'v2.1.0', '86f1f3dfee065efaefdb08f96e8fa1216c5b202f25a40705df663d0fff34a80b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"FORENSICS","authority_tier":0,"chunk_seq":125,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p35-126', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 35, 'In addition, NTFS supports data compression and encryption, and allows user and group-level access permissions to be defined for data files and directories.19  The maximum NTFS volume size is 2 TB. ! High-Performance File System (HPFS). HPFS is supported natively by OS/2 and can be read by Windows NT 3.1, 3.5, and 3.51. HPFS builds on the directory organization of FAT by providing automatic sorting of directories. In addition, HPFS reduces the amount of lost disk space by utilizing smaller units of allocation. The maximum HPFS volume size is 64 GB. 17  More information on FAT12 and FAT16 is available at http://www.microsoft.com/technet/prodtechnol/winxppro/reskit/c13621675.mspx. 18  The FAT32 filesystem specification, which provides highly technical details on FAT32, is available for download from http://www.microsoft.com/whdc/system/platform/firmware/fatgen.mspx. 19  Additional NTFS features are described at http://www.microsoft.com/technet/prodtechnol/winxppro/reskit/c13621675.mspx. 4-3', 'vec_doc-04-nist-sp-800-86-p35-126', 0, 251, 'v2.1.0', 'f5228c464e58c07c09f35fba0ee0fb745ff8fae7e6a66d29a940cf4684c9a245', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":35,"domain":"FORENSICS","authority_tier":0,"chunk_seq":126,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p36-127', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 36, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Second Extended Filesystem (ext2fs).20  ext2fs is supported natively by Linux. It supports standard UNIX file types and filesystem checks to ensure filesystem consistency. The maximum ext2fs volume size is 4 TB. ! Third Extended Filesystem (ext3fs). ext3fs is supported natively by Linux. It is based on the ext2fs filesystem and provides journaling capabilities that allow consistency checks of the filesystem to be performed quickly on large amounts of data. The maximum ext3fs volume size is 4 TB. ! ReiserFS.21  ReiserFS is supported by Linux and is the default filesystem for several common versions of Linux. It offers journaling capabilities and is significantly faster than the ext2fs and ext3fs filesystems. The maximum volume size is 16 TB. ! Hierarchical File System (HFS).22  HFS is supported natively by Mac OS. HFS is mainly used in older versions of Mac OS but is still supported in newer versions.', 'vec_doc-04-nist-sp-800-86-p36-127', 0, 245, 'v2.1.0', 'b6d6b2411210cee0d716d45b6651293e4597ab2e2facfa70b737521722c1b65d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"FORENSICS","authority_tier":0,"chunk_seq":127,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p36-128', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 36, 'The maximum HFS volume size under Mac OS 6 and 7 is 2 GB. The maximum HFS volume size in Mac OS 7.5 is 4 GB. Mac OS 7.5.2 and newer Mac OSs increase the maximum HFS volume size to 2 TB. ! HFS Plus.23  HFS Plus is supported natively by Mac OS 8.1 and later and is a journaling filesystem under Mac OS X. It is the successor to HFS and provides numerous enhancements, such as long filename support and Unicode filename support for international filenames. The maximum HFS Plus volume size is 2 TB. ! UNIX File System (UFS).24  UFS is supported natively by several types of UNIX OSs, including Solaris, FreeBSD, OpenBSD, and Mac OS X. However, most OSs have added proprietary features, so the details of UFS differ among implementations. ! Compact Disk File System (CDFS). As the name indicates, the CDFS filesystem is used for CDs. ! International Organization for Standardization (ISO) 9660 and Joliet. The ISO 9660 filesystem is commonly used on CD-ROMs.', 'vec_doc-04-nist-sp-800-86-p36-128', 0, 239, 'v2.1.0', '0304020b2e6c0bb49b71f6ec654e5d283e69fb18cf14a60e96dad2af387f7739', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"FORENSICS","authority_tier":0,"chunk_seq":128,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p36-129', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 36, 'Another popular CD-ROM filesystem, Joliet, is a variant of ISO 9660. ISO 9660 supports filename lengths of up to 32 characters, whereas Joliet supports up to 64 characters. Joliet also supports Unicode characters within filenames. ! Universal Disk Format (UDF). UDF is the filesystem used for DVDs and is also used for some CDs. 4.1.3 Other Data on Media As described in Section 4.1.2, filesystems are designed to store files on media. However, filesystems may also hold data from deleted files or earlier versions of existing files. This data can provide important information. (Section 4.2 discusses techniques for collecting this type of data.)  The following items describe how this data can still exist on various media: ! Deleted Files. When a file is deleted, it is typically not erased from the media; instead, the information in the directorys data structure that points to the location of the file is marked as deleted.', 'vec_doc-04-nist-sp-800-86-p36-129', 0, 233, 'v2.1.0', '9639d11bd7fa40504070100425259021dcc6388d57aa2f48e223f5098daeff92', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"FORENSICS","authority_tier":0,"chunk_seq":129,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p36-130', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 36, 'This means that the file is still stored on the media but is no longer enumerated by the 20  More information on ext2fs is available at http://e2fsprogs.sourceforge.net/ext2.html. 21  More information on ReiserFS and its successor, Reiser4, is available at http://www.namesys.com/. 22  An overview of HFS is available at http://developer.apple.com/documentation/mac/Files/Files-17.html. 23  An overview of HFS Plus and technical details on its implementation are available at http://developer.apple.com/technotes/tn/tn1150.html. 24  An overview of UFS is available at http://en.wikipedia.org/wiki/Unix_File_System. 4-4', 'vec_doc-04-nist-sp-800-86-p36-130', 0, 155, 'v2.1.0', 'ba013250fcca956541b3fc0e1d3ef9b4c71154e00d5f1333a448bec222b667ec', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":36,"domain":"FORENSICS","authority_tier":0,"chunk_seq":130,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p37-131', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 37, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE OS. The operating system considers this to be free space and can overwrite any portion of or the entire deleted file at any time. ! Slack Space. As noted previously, filesystems use file allocation units to store files. Even if a file requires less space than the file allocation unit size, an entire file allocation unit is still reserved for the file. For example, if the file allocation unit size is 32 kilobytes (KB) and a file is only 7 KB, the entire 32 KB is still allocated to the file, but only 7 KB is used, resulting in 25 KB of unused space. This unused space is referred to as file slack space, and it may hold residual data such as portions of deleted files. ! Free Space. Free space is the area on media that is not allocated to any partition; it includes unallocated clusters or blocks. This often includes space on the media where files (and even entire volumes) may have resided at one point but have since been deleted.', 'vec_doc-04-nist-sp-800-86-p37-131', 0, 251, 'v2.1.0', '2e900e494111e1668839983065ece5b87333a5213dc0f22e15d6b4390f09f90b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"FORENSICS","authority_tier":0,"chunk_seq":131,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p37-132', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 37, 'The free space may still contain pieces of data. Another way in which data might be hidden is through Alternate Data Streams (ADS) within NTFS volumes. NTFS has long supported multiple data streams for files and directories. Each file in an NTFS volume consists of an unnamed stream that is used to store the file''s primary data, and optionally one or more named streams (i.e., file.txt:Stream1, file.txt:Stream2) that can be used to store auxiliary information, such as file properties and picture thumbnail data.25  For instance, if a user right-clicks on a file in Windows Explorer, views the files properties, and then modifies the information displayed in the summary tab, the OS stores the summary information for the file in a named stream. All data streams within a file share the files attributes (e.g., timestamps, security attributes).', 'vec_doc-04-nist-sp-800-86-p37-132', 0, 212, 'v2.1.0', '03b1197a3af6ed0554f81dcf52b93bd47c6de403a0cea926693cc516b1e9915c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"FORENSICS","authority_tier":0,"chunk_seq":132,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p37-133', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.1 F ile Basics', 37, 'Although named streams do affect the storage quota of a file, they are largely concealed from users because standard Windows file utilities, such as Explorer, only report the size of a file''s unnamed stream. As a result, a user cannot readily determine whether a file contains ADS using the standard Windows file utilities. This allows hidden data to be contained within any NTFS filesystem. Moving files with ADS to non-NTFS filesystems effectively strips ADS from the file, so the ADS can be lost if analysts are not aware of their presence. Software and processes are available to identify ADS.26', 'vec_doc-04-nist-sp-800-86-p37-133', 0, 150, 'v2.1.0', '8007916d7d97da6d3c8327023b6677112fba9a603681322f5f0eb550a772fd2c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.1 F ile Basics","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"FORENSICS","authority_tier":0,"chunk_seq":133,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.1 F ile Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p37-134', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 37, 'During data collection, the analyst should make multiple copies of the relevant files or filesystems typically a master copy and a working copy.27  The analyst can then use the working copy without affecting the original files or the master copy.  Section 4.2.1 describes the primary techniques and tools for copying files and residual file data from media.  Section 4.2.2 discusses the importance of maintaining the integrity of the files and provides guidance on hardware and software that can assist in preserving and verifying file integrity.  It is often important to collect not only the files, but also significant timestamps for the files, such as when the files were last modified or accessed.  Section 4.2.3 describes the timestamps and explains how they can be preserved.  Other technical issues related to file collection, such as finding hidden files and copying files from redundant array of inexpensive disks (RAID) implementations, are addressed in Section 4.2.4. 25  Directories do not have an unnamed stream but may contain named streams. 26 Additional information on ADS is available at http://www.microsoft.com/technet/prodtechnol/winxppro/reskit/c13621675.mspx, http://www.infosecwriters.com/texts.php?op=display&id=53, and within http://www.heysoft.de/Frames/f_faq_ads_en.htm. 27  The purpose of the master copy is to generate additional working copies if the first working copy can no longer be used because of alteration or other reasons. 4-5', 'vec_doc-04-nist-sp-800-86-p37-134', 0, 367, 'v2.1.0', '824258068b8f44a0389e928585779f807d2ce41058556581ab7119a410d73723', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":37,"domain":"FORENSICS","authority_tier":0,"chunk_seq":134,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p38-135', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 38, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 4.2.1 Copying Files from Media Files can be copied from media using two different techniques: ! Logical Backup. A logical backup copies the directories and files of a logical volume. It does not capture other data that may be present on the media, such as deleted files or residual data stored in slack space. ! Bit Stream Imaging. Also known as disk imaging, bit stream imaging generates a bit-for-bit copy of the original media, including free space and slack space. Bit stream images require more storage space and take longer to perform than logical backups. If evidence may be needed for prosecution or disciplinary actions, the analyst should get a bit stream image of the original media, label the original media, and store it securely as evidence.', 'vec_doc-04-nist-sp-800-86-p38-135', 0, 205, 'v2.1.0', '9853955cbc915595fe37ba20ae47de325d3262262e8ed77d91296b72ddddb0cc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"FORENSICS","authority_tier":0,"chunk_seq":135,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p38-136', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 38, 'All subsequent analysis should be performed using the copied media to ensure that the original media is not modified and that a copy of the original media can always be recreated if necessary. All steps that were taken to create the image copy should be documented. Doing so should allow any analyst to produce an exact duplicate of the original media using the same procedures. In addition, proper documentation can be used to demonstrate that evidence was not mishandled during the collection process. Besides the steps that were taken to record the image, the analyst should document supplementary information such as the hard drive model and serial number, media storage capacity, and information about the imaging software or hardware that was used (e.g., name, version number, licensing information). All of these actions support the maintenance of the chain of custody. When a bit stream image is executed, either a disk-to-disk or a disk-to-file copy can be performed.', 'vec_doc-04-nist-sp-800-86-p38-136', 0, 244, 'v2.1.0', '2460c5009cafafc0e9372a69f5a5afc8e5166f95aa8e18b22a299feb1a4c70ab', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"FORENSICS","authority_tier":0,"chunk_seq":136,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p38-137', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 38, 'A disk-to-disk copy, as its name suggests, copies the contents of the media directly to another media. A disk-to-file copy copies the contents of the media to a single logical data file. A disk-to-disk copy is useful since the copied media can be connected directly to a computer and its contents readily viewed. However, a disk-to-disk copy requires a second media similar to the original media.28  A disk-to-file copy allows the data file image to be moved and backed up easily. However, to view the logical contents of an image file, the analyst has to restore the image to media or open or read it from an application capable of displaying the logical contents of bit stream images. The details of this are OS and forensics tool- dependent. Section 4.3 discusses this process in more detail. Numerous hardware and software tools can perform bit stream imaging and logical backups.', 'vec_doc-04-nist-sp-800-86-p38-137', 0, 221, 'v2.1.0', '68ff1a2fac98874eb76737119e6741b2509296070e5fb6dd315c1cf7f64d8553', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"FORENSICS","authority_tier":0,"chunk_seq":137,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p38-138', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 38, 'Hardware tools are generally portable, provide bit-by-bit images, connect directly to the drive or computer to be imaged, and have built-in hash functions.29  Hardware tools can acquire data from drives that use common types of controllers, such as Integrated Drive Electronics (IDE) and Small Computer System Interface (SCSI). Software solutions generally consist of a startup diskette, CD, or installed programs that run on a workstation to which the media to be imaged is attached.30  Some software solutions create logical copies 28  The destination medium should be forensically clean before the copy occurs, so that any existing data on the medium is eliminated. The destination medium should have a larger storage capacity than the data to be copied. 29  Examples of hardware-based disk imaging tools are Image MASSters SOLO Forensics (http://www.ics-iq.com/) and Logicubes Solitaire (http://www.logicube.com/).', 'vec_doc-04-nist-sp-800-86-p38-138', 0, 230, 'v2.1.0', '12fdc7006c727d9cb11c2726733f6a9ed59d0283ec76b641b8dea395bd0b7642', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"FORENSICS","authority_tier":0,"chunk_seq":138,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p38-139', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 38, 'Additional products are referenced in Web sites listed in Appendix F, including The Ultimate Collection of Forensics Software (TUCOFS) (http://www.tucofs.com/tucofs/tucofs.asp?mode=filelist&catid=10&oskey=12). The applications referenced throughout this publication are by no means a complete list of applications to use for forensic purposes, nor does this publication imply any endorsement of certain products. 30  Examples of software-based disk imaging tools are Linux dd, SafeBack (http://www.forensics-intl.com/safeback.html), EnCase (http://www.encase.com/), Norton Ghost (http://www.symantec.com/home_homeoffice/products/overview.jsp?pcid=br&pvid=ghost10), and ILook (http://www.ilook-forensics.org/). Additional products are referenced in Web sites listed in Appendix F. 4-6', 'vec_doc-04-nist-sp-800-86-p38-139', 0, 196, 'v2.1.0', '51cda34905cc2be029c8181882410fb3a096a3db434ca2d13c19be5981eec132', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":38,"domain":"FORENSICS","authority_tier":0,"chunk_seq":139,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p39-140', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 39, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE of files or partitions and may ignore free or unallocated drive space, whereas others create a bit-by-bit image copy of the media. In addition to their primary function, some disk imaging tools can also perform forensic recordkeeping, such as automated audit trails and chain of custody. The use of such tools can support consistency in the examination process and the accuracy and reproducibility of results. An increasing number of disk imaging tools are becoming available. In response to this proliferation and the lack of a standard for testing them, NISTs Computer Forensics Tool Testing (CFTT) project has developed rigorous testing procedures for validating the tools results.', 'vec_doc-04-nist-sp-800-86-p39-140', 0, 188, 'v2.1.0', 'bcdb5d21c7ef79b6d5c057da016fe8ea28cd8631ae5a5631196a426eb084d542', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"FORENSICS","authority_tier":0,"chunk_seq":140,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p39-141', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 39, 'Currently, only a few disk imaging tools have undergone CFTT testing.31 Generally, tools that perform bit stream imaging should not be used to acquire bit-by-bit copies of an entire physical device from a live systema system currently in usebecause the files and memory on such a system are changing constantly and therefore cannot be validated.32  However, a bit-by-bit copy of the logical areas of a live system can be completed and validated. When logical backups are being performed, it is still preferable not to copy files from a live system; changes might be made to files during the backup, and files that are held open by a process might not be easy to copy.', 'vec_doc-04-nist-sp-800-86-p39-141', 0, 168, 'v2.1.0', '4bf4c1995416e27cebfb13cc4e472ac73973c3126ce3f82cf56d5bbb6028b61a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"FORENSICS","authority_tier":0,"chunk_seq":141,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p39-142', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 39, 'Accordingly, analysts should decide whether copying files from a live system is feasible based on which files need to be obtained, how accurate and complete the copying needs to be, and how important the live system is.33  For example, it is not necessary to take down a critical server used by hundreds of people just to collect files from a single users home directory. For logical backups of live systems, analysts can use standard system backup software. However, performing a backup could affect the performance of the system and consume significant amounts of network bandwidth, depending on whether the backup is performed locally or remotely.', 'vec_doc-04-nist-sp-800-86-p39-142', 0, 163, 'v2.1.0', '68bcc107229794b64cacba848431a5088a949005ae3cd1b0fac4c710b6cd896f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"FORENSICS","authority_tier":0,"chunk_seq":142,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p39-143', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 39, 'Organizations should have policy, guidelines, and procedures that indicate the circumstances under which bit stream images and logical backups (including those from live systems) may be performed for forensic purposes and which personnel may perform them.34  It is typically most effective to establish policy, guidelines, and procedures based on categories of systems (i.e., low, moderate, or high impact) and the nature of the event of interest; some organizations also choose to create separate policy statements, guidelines, and procedures for particularly important systems. The policy, guidelines, or procedures should identify the individuals or groups with authority to make decisions regarding backups and images; these people should be capable of weighing the risks and making sound decisions. The policy, guidelines, or procedures should also identify which individuals or groups have the authority to perform the backup or imaging for each type of system.', 'vec_doc-04-nist-sp-800-86-p39-143', 0, 242, 'v2.1.0', '8b7ae75183be0664339c889f443faf7369127195ec39f3d3ede948f2fac0d383', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"FORENSICS","authority_tier":0,"chunk_seq":143,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p39-144', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 39, 'Access to some systems might be restricted because of the sensitivity of the operations or data in the system. 4.2.2 Data File Integrity During backups and imaging, the integrity of the original media should be maintained. To ensure that the backup or imaging process does not alter data on the original media, analysts can use a write-blocker while backing up or imaging the media. A write-blocker is a hardware or software-based tool that prevents a computer from writing to computer storage media connected to it. Hardware write-blockers are physically connected to the computer and the storage media being processed to prevent any writes to 31  The test results can be found at http://www.cftt.nist.gov/disk_imaging.htm. 32  For example, services or processes running on the system might be writing to a systems hard drive, even if no person is currently using the computer. 33  Analysts should also consider the possible need to collect volatile data from the system.', 'vec_doc-04-nist-sp-800-86-p39-144', 0, 244, 'v2.1.0', 'dad880500103abd174e4a3033ada6467a01fb72a369210fa95ebda961b19c348', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"FORENSICS","authority_tier":0,"chunk_seq":144,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p39-145', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 39, 'If the system is live, its volatile data is likely to change more quickly and to be more challenging to preserve. 34  This recommendation is not intended to restrict users from performing backups of their own data and local workstations, but to prevent people from collecting backups of others systems and data without appropriate cause for doing so. 4-7', 'vec_doc-04-nist-sp-800-86-p39-145', 0, 89, 'v2.1.0', '69709f35621143bb3f187a2d52379b66bf14e182bde4cca37d18a6d8dbcf99b0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":39,"domain":"FORENSICS","authority_tier":0,"chunk_seq":145,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p40-146', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 40, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE that media.35  Software write-blockers are installed on the analysts forensic system and currently are available only for MS-DOS and Windows systems. (Some OSs [e.g., Mac OS X, Linux] may not require software write-blockers because they can be set to boot with secondary devices not mounted. However, attaching a hardware write-blocking device will ensure that integrity is maintained.)  MS-DOSbased software write-blockers work by trapping Interrupt 13 and extended Interrupt 13 disk writes. Windows- based software write-blockers use filters to sort interrupts sent to devices to prevent any writes to storage media.36 In general, when using a hardware write-blocker, the media or device used to read the media should be connected directly to the write-blocker, and the write-blocker should be connected to the computer or device used to perform the backup or imaging.', 'vec_doc-04-nist-sp-800-86-p40-146', 0, 234, 'v2.1.0', '7e3948dff3417e40a5fb933b7f6789bb5a7ae8fd411c55bcdcafaf565f7fa006', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"FORENSICS","authority_tier":0,"chunk_seq":146,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p40-147', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 40, 'When using a software write-blocker, the software should be loaded onto a computer before the media or device used to read the media is connected to the computer. Write-blockers may also allow write-blocking to be toggled on or off for a particular device. It is important when write-blocking is used, that it be toggled on for all connected devices.37  Write- blockers also should be tested routinely to ensure that they support newer devices. For example, a new device might make use of reserved or previously unused functions or placeholders to implement device- specific functions that might ultimately write to the device and alter its contents.', 'vec_doc-04-nist-sp-800-86-p40-147', 0, 163, 'v2.1.0', '2c72365f1b8d00bb1c80bb172be0dc15831d3086571771bba9cfb47dcb770480', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"FORENSICS","authority_tier":0,"chunk_seq":147,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p40-148', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 40, 'After a backup or imaging is performed, it is important to verify that the copied data is an exact duplicate of the original data.38  Computing the message digest of the copied data can be used to verify and ensure data integrity.39  A message digest is a hash that uniquely identifies data and has the property that changing a single bit in the data will cause a completely different message digest to be generated. There are many algorithms for computing the message digest of data, but the two most commonly used are MD5 and Secure Hash Algorithm 1 (SHA-1). These algorithms take as input data of arbitrary length and produce as output 128-bit message digests. Because SHA-1 is a Federal Information Processing Standards (FIPS)approved algorithm and MD5 is not, Federal agencies should use SHA-1 instead of MD5 for message digests.40 When a bit stream image is performed, the message digest of the original media should be computed and recorded before the image is performed.', 'vec_doc-04-nist-sp-800-86-p40-148', 0, 245, 'v2.1.0', '1bb658feac93b2e97e1721a38d139f984c6f0f5603d33cda0ad38ca0243da096', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"FORENSICS","authority_tier":0,"chunk_seq":148,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p40-149', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 40, 'After the imaging, the message digest of the copied media should be computed and compared with the original message digest to verify that data integrity has been preserved. The message digest of the original media should then be computed again to verify that the imaging process did not alter the original media, and all results should be documented. The process should be used for logical backups, except that message digests should be computed and compared for 35  Examples of hardware write-blockers are FastBloc (http://www.guidancesoftware.com/lawenforcement/ef_index.asp), NoWrite (http://www.mykeytech.com/nowrite.html), and SCSIBlock (http://www.digitalintelligence.com/products/scsiblock/). Additional tools are referenced in the Web sites listed in Appendix F. 36  An example of a software write-blocker is PDBlock (http://www.digitalintelligence.com/software/disoftware/pdblock/). Additional tools are referenced in the Web sites listed in Appendix F.', 'vec_doc-04-nist-sp-800-86-p40-149', 0, 241, 'v2.1.0', 'e37352657359ae314bba35b9c4c514fc7065ccff96c4141e4ab1bc1bf8006ff2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"FORENSICS","authority_tier":0,"chunk_seq":149,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p40-150', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 40, '37  These are only general guidelines for using write-blockers. Analysts should refer to the operating procedures for a specific write-blocker product for instructions on proper usage. 38  If a backup is performed on a live system, it is likely that some files will change between the time the backup was initiated and the time it is completed and verified. 39  Message digests should be used to ensure the integrity of all data that is acquired during forensic activity, including log files and logical backups. 40  Federal agencies must use FIPS-approved encryption algorithms contained in validated cryptographic modules. The Cryptographic Module Validation Program (CMVP) at NIST coordinates FIPS testing; the CMVP Web site is located at http://csrc.nist.gov/cryptval/. FIPS 180-2, Secure Hash Standard, is available at http://csrc.nist.gov/publications/fips/fips180-2/fips180-2withchangenotice.pdf.', 'vec_doc-04-nist-sp-800-86-p40-150', 0, 226, 'v2.1.0', '9a6910595f1b9ed47009512bbb162377684c239afd52f471296f4362a348a4ce', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"FORENSICS","authority_tier":0,"chunk_seq":150,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p40-151', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 40, 'NIST has announced that Federal agencies should plan to transition from SHA-1 to stronger forms of SHA (e.g., SHA-224, SHA-256) by 2010. For more information, see NIST comments from August 2004 posted at http://csrc.nist.gov/hash_standards_comments.pdf, as well as http://www.nsrl.nist.gov/collision.html. 4-8', 'vec_doc-04-nist-sp-800-86-p40-151', 0, 78, 'v2.1.0', '6e57438be3498c35dc9301ec9ad36e450c13627845bb7445f7720a14a85be3c6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":40,"domain":"FORENSICS","authority_tier":0,"chunk_seq":151,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p41-152', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 41, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE each data file. For both bit stream images and logical backups, the message digests created to ensure data integrity should be stored on read-only or write-once media or printed, and then secured in a proper location. 4.2.3 4.2.4 File Modification, Access, and Creation Times It is often important to know when a file was created, used, or manipulated, and most OSs keep track of certain timestamps related to files. The most commonly used timestamps are the modification, access, and creation (MAC) times, as follows: ! Modification Time. This is the last time a file was changed in any way, including when a file is written to and when it is changed by another program. ! Access Time. This is the last time any access was performed on a file (e.g., viewed, opened, printed). ! Creation Time.', 'vec_doc-04-nist-sp-800-86-p41-152', 0, 215, 'v2.1.0', '3776c310e88c1a3e7e5f531dcf89f5c417241021a7aa1faf7e0ab2042ca8d7df', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"FORENSICS","authority_tier":0,"chunk_seq":152,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p41-153', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 41, 'This is generally the time and date the file was created; however, when a file is copied to a system, the creation time will become the time the file was copied to the new system. The modification time will remain intact. Different types of filesystem may store different types of times. For example, Windows systems retain the last modified time, the last access time, and the creation time of files.41  UNIX systems retain the last modification, last inode42 change, and last access times; however, some UNIX systems (including versions of BSD and SunOS) do not update the last access time of executable files when they are run. Some UNIX systems record the time when the metadata for a file was most recently altered. Metadata is data about data; for filesystems, metadata is data that provides information about a files contents. If an analyst needs to establish an accurate timeline of events, then the file times should be preserved.', 'vec_doc-04-nist-sp-800-86-p41-153', 0, 235, 'v2.1.0', 'aa88fc031f5b5dd406297c751c9c6ee68adc7fb14825785963669d1b0f9a0176', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"FORENSICS","authority_tier":0,"chunk_seq":153,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p41-154', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 41, 'Accordingly, analysts should be aware that not all methods for collecting data files can preserve file times. Bit stream images can preserve file times because a bit-for-bit copy is generated; performing a logical backup using some tools may cause file creation times to be altered when the data file is copied. For this reason, whenever file times are essential, bit stream imaging should be used to collect data. Analysts should also be aware that file times may not always be accurate. Among the reasons for such inaccuracies are the following: ! The computers clock does not have the correct time. For example, the clock may not have been synchronized regularly with an authoritative time source. ! The time may not be recorded with the expected level of detail, such omitting the seconds or minutes. ! An attacker may have altered the recorded file times. Technical Issues Several technical issues may arise in collecting data files.', 'vec_doc-04-nist-sp-800-86-p41-154', 0, 235, 'v2.1.0', '518e25edb04590fc29f6d4bbf00c67b8e226760055a2ff5a257d25712a4c243e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"FORENSICS","authority_tier":0,"chunk_seq":154,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p41-155', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 41, 'As noted in Section 4.2.1, the primary issue is the collection of deleted files and remnants of files existing in free and slack space on media. Individuals can use a variety of techniques to hinder the collection of such data. For example, there are many utilities available that perform wipingthe overwriting of media (or portions of media, such as particular files) with random or constant values (e.g., all 0s). Such utilities vary in services and reliability, but most are 41  Windows systems using the NTFS filesystem also record the entry modified time. 42  An inode is a set of data regarding certain characteristics of a file, such as the privileges set for the file and the files owner. 4-9', 'vec_doc-04-nist-sp-800-86-p41-155', 0, 176, 'v2.1.0', 'bf4a4c6ee80683a71dfcdbddd305cfb42cd43373f3fc7f04939ba7eb564dd437', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":41,"domain":"FORENSICS","authority_tier":0,"chunk_seq":155,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p42-156', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 42, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE effective in preventing easy collection of files, especially if several wipes are performed. Individuals can also use physical means to prevent data collection, such as demagnetizing a hard drive (also known as degaussing) or physically damaging or destroying media. Both physical and software-based techniques can make it very difficult, or even impossible, to recover all of the data using software. Recovery attempts in these cases necessitate the use of highly specialized forensic experts with advanced facilities, hardware, and techniques, but the cost and effort involved in making use of such means are prohibitive for general use.43  In some cases, the data is simply not recoverable. Another common issue is the collection of hidden data.', 'vec_doc-04-nist-sp-800-86-p42-156', 0, 203, 'v2.1.0', '7d41641faba9f1ec70e3f2c9cad6c084fe4aada9d130c16fd874900824eb1235', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"FORENSICS","authority_tier":0,"chunk_seq":156,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p42-157', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 42, 'Many OSs permit users to tag certain files, directories, or even partitions as hidden, which means that by default they are not displayed in directory listings.44  Some applications and OSs hide configuration files to reduce the chance that users will accidentally modify or delete them. Also, on some OSs, directories that have been deleted may be marked as hidden. Hidden data may contain a wealth of information; for example, a hidden partition could contain a separate OS and many data files.45  Users may create hidden partitions by altering the partition table to disrupt disk management and prevent applications from seeing that the data area exists. Hidden data can also be found within ADSs on NTFS volumes, in the end-of-file slack space and free space on a medium, and in the Host Protected Area (HPA) on some hard drives, which is a region of a drive intended to be used by vendors only.', 'vec_doc-04-nist-sp-800-86-p42-157', 0, 225, 'v2.1.0', '3e2a6b31a6e966c27613afe7dc955c5f0243793f3e69d96fa1254d9f9d974e47', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"FORENSICS","authority_tier":0,"chunk_seq":157,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p42-158', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 42, 'Many collection tools can recognize some or all of these methods of hiding data and recover the associated data. Yet another issue that may arise is collection of data from RAID arrays that use striping (e.g., RAID-0, RAID-5).46  In this configuration, a striped volume consists of equal-sized partitions that reside on separate disk drives. When data is written to the volume, it is evenly distributed across the partitions to improve disk performance. This can cause problems because all partitions of a striped volume must be present for the examination of its contents, but in this case the partitions reside on separate physical disk drives. To examine a striped volume, each disk drive in the RAID array needs to be imaged and the RAID configuration has to be recreated on the examination system.47  The examination system needs to be booted using a forensic boot disk that can recognize and use the RAID array and that prevents writes to the array.', 'vec_doc-04-nist-sp-800-86-p42-158', 0, 239, 'v2.1.0', '03a55173550cbf93a1b0f44c093fdb6ddbb58b4c90893285eb6c832581efbd44', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"FORENSICS","authority_tier":0,"chunk_seq":158,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p42-159', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.2 C ollecting Files', 42, 'Some imaging tools can acquire striped volumes and preserve unused data areas of the volume, such as free space and slack space.48', 'vec_doc-04-nist-sp-800-86-p42-159', 0, 33, 'v2.1.0', '2a64272aed52c8a8cb864f923dc7f549e17c7eb6d47a28b4482413387ff34cbb', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.2 C ollecting Files","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"FORENSICS","authority_tier":0,"chunk_seq":159,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.2 C ollecting Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p42-160', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 42, 'After a logical backup or bit stream imaging has been performed, the backup or image may have to be restored to another media before the data can be examined.  This is dependent on the forensic tools that will be used to perform the analysis.  Some tools can analyze data directly from an image file, whereas others require that the backup or image be restored to a medium first.49  Regardless of whether an image file or a restored image is used in the examination, the data should be accessed only as read-only to ensure 43  Companies that specialize in such recovery efforts include Data Recovery Services, DriveSavers, and Ontrack Data Recovery. 44  On UNIX systems, files or folders beginning with a . are considered hidden and are not displayed when listing files unless the a flag is used. 45  An example of a freely available tool that can be used to locate hidden partitions is the FDISK utility built into DOS. Information about additional tools is available from the Web sites listed in Appendix F. 46  An overview of RAID is available at http://www.adaptec.com/worldwide/product/markeditorial.html?prodkey=quick_explanation_of_raid. 47  Because RAID-5 stores parity information on one disk, it is possible to examine a RAID-5 volume by imaging all of the disks but one. 48  For more information regarding RAIDs, visit http://www.anandtech.com/storage/showdoc.html?i=1491. 49  At one time, when tools had more limited capabilities, it was often recommended that data files be restored to a system using the same OS or a related one.  Current tools are more advanced and are designed to be used with many types of data files, regardless of the underlying OS, so it is no longer necessary in most cases to restore data files to a particular OS. 4-10', 'vec_doc-04-nist-sp-800-86-p42-160', 0, 441, 'v2.1.0', '48641957a82371d5e950a2c4277af49796b4e1e666fe61ea4a30b2a6c247e297', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":42,"domain":"FORENSICS","authority_tier":0,"chunk_seq":160,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p43-161', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 43, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE that the data being examined is not modified and that it will provide consistent results on successive runs. As noted in Section 4.2.2, write-blockers can be used during this process to prevent writes from occurring to the restored image. After restoring the backup (if needed), the analyst begins to examine the collected data and performs an assessment of the relevant files and data by locating all files, including deleted files, remnants of files in slack and free space, and hidden files. Next, the analyst may need to extract the data from some or all of the files, which may be complicated by such measures as encryption and password protection. This section describes the processes involved in examining files and data, as well as techniques that can expedite examination. 4.3.1 4.3.2 Locating the Files The first step in the examination is to locate the files.', 'vec_doc-04-nist-sp-800-86-p43-161', 0, 234, 'v2.1.0', '2f0f836f359f1e8085e035d7bd5b9222e6612ce93e41df21a0c974390a283f8c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"FORENSICS","authority_tier":0,"chunk_seq":161,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p43-162', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 43, 'A disk image can capture many gigabytes of slack space and free space, which could contain thousands of files and file fragments. Manually extracting data from unused space can be a time-consuming and difficult process, because it requires knowledge of the underlying filesystem format. Fortunately, several tools are available that can automate the process of extracting data from unused space and saving it to data files, as well as recovering deleted files and files within a recycling bin. Analysts can also display the contents of slack space with hex editors or special slack recovery tools. Extracting the Data The rest of the examination process involves extracting data from some or all of the files. To make sense of the contents of a file, an analyst needs to know what type of data the file contains. The intended purpose of file extensions is to denote the nature of the files contents; for example, a jpg extension indicates a graphic file, and an mp3 extension indicates a music file.', 'vec_doc-04-nist-sp-800-86-p43-162', 0, 250, 'v2.1.0', '7eb2c0ed267fea546ecef5ceeaf63d2065d2c1c1eb1d21f05e4e2e3fb2d93e53', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"FORENSICS","authority_tier":0,"chunk_seq":162,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p43-163', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 43, 'However, users can assign any file extension to any type of file, such as naming a text file mysong.mp3 or omitting a file extension. In addition, some file extensions might be hidden or unsupported on other OSs. Therefore, analysts should not assume that file extensions are accurate. Analysts can more accurately identify the type of data stored in many files by looking at their file headers. A file header contains identifying information about a file and possibly metadata that provides information about the files contents. As shown in Figure 4-1, the file header contains a file signature that identifies the type of data that particular file contains.50  The example in Figure 4-1 has a file header of FF D8, which indicates that this is a JPEG file. A file header could be located in a file separate from the actual file data.', 'vec_doc-04-nist-sp-800-86-p43-163', 0, 209, 'v2.1.0', '8c6e1eb41fba8469fad9c9db329a48fd11eaaed506400ba23cbdba920731060e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"FORENSICS","authority_tier":0,"chunk_seq":163,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p43-164', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 43, 'Another effective technique for identifying the type of data in a file is a simple histogram showing the distribution of ASCII values as a percentage of total characters in a file. For example, a spike in the space, a, and e lines generally indicates a text file, while consistency across the histogram indicates a compressed file. Other patterns are indicative of files that are encrypted or that were modified through steganography. 50  File headers can also indicate whether a file is encrypted. Attackers can alter file headers using a hex editor to conceal the actual file type, and then alter the file header back to use the file. In some cases, a file can be used even when its header is altered. 4-11', 'vec_doc-04-nist-sp-800-86-p43-164', 0, 179, 'v2.1.0', 'cb955d387a4341f5b995f945543b20550fdb107badf87656d25482e879a45a40', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":43,"domain":"FORENSICS","authority_tier":0,"chunk_seq":164,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p44-165', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 44, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Figure 4-1. File Header Information Encryption often presents challenges for analysts. Users might encrypt individual files, folders, volumes, or partitions so that others cannot access their contents without a decryption key or passphrase.51  The encryption might be performed by the OS or a third-party program. Although it is relatively easy to identify an encrypted file, it is usually not so easy to decrypt it. The analyst might be able to identify the encryption method by examining the file header, identifying encryption programs installed on the system, or finding encryption keys (which are often stored on other media). Once the encryption method is known, the analyst can better determine the feasibility of decrypting the file. In many cases, it is not possible to decrypt files because the encryption method is strong and the authentication (e.g., passphrase) used to perform decryption is unavailable.', 'vec_doc-04-nist-sp-800-86-p44-165', 0, 246, 'v2.1.0', '14bf9f67bd4f8536de4849dc518fb5cd4631750b2298eedf6e70465d46a4308a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"FORENSICS","authority_tier":0,"chunk_seq":165,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p44-166', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 44, 'Although an analyst can detect the presence of encrypted data rather easily, the use of steganography is more difficult to detect. Steganography, also known as steg, is the embedding of data within other data. Digital watermarks and the hiding of words and information within images are examples of steganography. Some techniques an analyst can use to locate stegged data include looking for multiple versions of the same image, identifying the presence of grayscale images, searching metadata and registries, using histograms, and using hash sets to search for known steganography software.', 'vec_doc-04-nist-sp-800-86-p44-166', 0, 148, 'v2.1.0', 'b41aab83f59ba311c91fbe7495511d869ddbb6dc7256959ffbd8ece74d5a5b0a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"FORENSICS","authority_tier":0,"chunk_seq":166,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p44-167', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 44, 'Once certain that stegged data exists, analysts might be able to extract the embedded data by determining what software created the data and then finding the stego key, or by using brute force and cryptographic attacks to determine a password.52  However, such efforts are often unsuccessful and can be extremely time- consuming, particularly if the analyst does not find the presence of known steganography software on the media being reviewed. In addition, some software programs can analyze files and estimate the probability that the files were altered with steganography. Analysts may also need to access non-stegged files that are protected by passwords. Passwords are often stored on the same system as the files they protect, but in an encoded or encrypted format.', 'vec_doc-04-nist-sp-800-86-p44-167', 0, 193, 'v2.1.0', 'b8708662d181bea51736f844f4df62d7bf163579fccc437c51a046eb720539fd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"FORENSICS","authority_tier":0,"chunk_seq":167,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p44-168', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 44, 'Various utilities are available that can crack passwords placed on individual files, as well as OS passwords.53 Most cracking utilities can attempt to guess passwords, as well as performing brute force attempts that try every possible password. The time needed for a brute force attack on an encoded or encrypted password can vary greatly, depending on the type of encryption used and the sophistication of the password itself. Another approach is to bypass a password. For example, an analyst could boot a system and disable its screensaver password, or bypass a Basic Input/Output System (BIOS) password by pulling the BIOS 51  Although volumes and partitions can be encrypted on some operating systems, this is not common due to corruption and other functional problems that may result in a complete loss of data if only a sector of data is corrupted. Encryption of individual files and folders is far more common, and is supported by many newer operating systems.', 'vec_doc-04-nist-sp-800-86-p44-168', 0, 242, 'v2.1.0', '0b133dbfbb1d692854bed5463773b84e61c913a6084021e6da0f60baba2f67bc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"FORENSICS","authority_tier":0,"chunk_seq":168,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p44-169', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 44, '52  Further discussion regarding steganography is outside the scope of this document. For more information, see the article An Overview of Steganography for the Computer Forensics Examiner by Gary Kessler, available at http://www.fbi.gov/hq/lab/fsc/backissu/july2004/research/2004_03_research01.htm. 53  An example of an open source password cracking utility is John the Ripper, which supports multiple OSs and file types. Additional password cracking utilities are listed on several Web sites listed in Appendix F, including Computer Forensics Tools (http://www.forensix.org/tools/) and The Ultimate Collection of Forensic Software (TUCOFS) (http://www.tucofs.com/tucofs.htm). 4-12', 'vec_doc-04-nist-sp-800-86-p44-169', 0, 171, 'v2.1.0', '3c2819303b2cda7ae5d92beff70bc8fa0c2a7e78ac9fe467340748a9c14c8279', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":44,"domain":"FORENSICS","authority_tier":0,"chunk_seq":169,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p45-170', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 45, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE jumper from the systems motherboard or using a manufacturers backdoor password.54  Of course, bypassing a password might mean rebooting the system, which might be undesirable. Another possibility is to attempt to capture the password through network or host-based controls (e.g., packet sniffer, keystroke logger), with proper management and legal approval. If a boot-up password has been set on a hard drive, it might be possible to guess it (i.e., a default password from a vendor) or to circumvent it with specialized hardware and software. 4.3.3 Using a Forensic Toolkit Analysts should have access to various tools that enable them to perform examinations and analysis of data, as well as some collection activities. Many forensic products allow the analyst to perform a wide range of processes to analyze files and applications, as well as collecting files, reading disk images, and extracting data from files.', 'vec_doc-04-nist-sp-800-86-p45-170', 0, 246, 'v2.1.0', '0a4e4ba332878ca42a15849374510e7a4d2fdad91d02850b05747f6ab96e9b80', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"FORENSICS","authority_tier":0,"chunk_seq":170,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p45-171', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 45, 'Most analysis products also offer the ability to generate reports and to log all errors that occurred during the analysis. Although these products are invaluable in performing analysis, it is critical to understand which processes should be run to answer particular questions about the data. An analyst may need to provide a quick response or just answer a simple question about the collected data. In these cases, a complete forensic evaluation may not be necessary or even feasible. The forensic toolkit should contain applications that can accomplish data examination and analysis in many ways and can be run quickly and efficiently from floppy disks, CDs, or a forensic workstation. The following processes are among those that an analyst should be able to perform with a variety of tools: ! Using File Viewers.', 'vec_doc-04-nist-sp-800-86-p45-171', 0, 204, 'v2.1.0', 'f20e8a6da7078803d1c116d608d745fb572666e0c770af5a76cb281e575af364', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"FORENSICS","authority_tier":0,"chunk_seq":171,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p45-172', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 45, 'Using viewers instead of the original source applications to display the contents of certain types of files is an important technique for scanning or previewing data, and is more efficient because the analyst does not need native applications for viewing each type of file. Various tools are available for viewing common types of files, and there are also specialized tools solely for viewing graphics. If available file viewers do not support a particular file format, the original source application should be used; if this is not available, then it may be necessary to research the files format and manually extract the data from the file.55 ! Uncompressing Files. Compressed files may contain files with useful information, as well as other compressed files. Therefore, it is important that the analyst locate and extract compressed files. Uncompressing files should be performed early in the forensic process to ensure that the contents of compressed files are included in searches and other actions.', 'vec_doc-04-nist-sp-800-86-p45-172', 0, 252, 'v2.1.0', 'c3dd4b74a2303cd2a2ab7218e60147b504365724ee56b8d29552ba66008282a8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"FORENSICS","authority_tier":0,"chunk_seq":172,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p45-173', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 45, 'However, analysts should keep in mind that compressed files might contain malicious content, such as compression bombs, which are files that have been repeatedly compressed, typically dozens or hundreds of times. Compression bombs can cause examination tools to fail or consume considerable resources; they might also contain malware and other malicious payloads. Although there is no definite way to detect compression bombs before uncompressing a file, there are ways to minimize their impact. For instance, the examination system should use up-to-date antivirus software and should be standalone to limit the effects to just that system. In addition, an image of the examination system should be created so that, if needed, the system can be restored. ! Graphically Displaying Directory Structures.', 'vec_doc-04-nist-sp-800-86-p45-173', 0, 201, 'v2.1.0', 'd2005b6eb1c5bf426b920c8e1649f47e2fb4e730e21c0edc72be48ea900651f4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"FORENSICS","authority_tier":0,"chunk_seq":173,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p45-174', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 45, 'This practice makes it easier and faster for analysts to gather general information about the contents of media, such as the type of software installed and the likely technical aptitude of the user(s) who created the data. Most products can display Windows, Linux, and UNIX directory structures, whereas other products are specific to Macintosh directory structures. 54  See the article How to Bypass BIOS Passwords (available at http://labmice.techtarget.com/articles/BIOS_hack.htm) for more information and examples of known BIOS backdoor passwords. 55  Web sites such as Wotsits Format (http://www.wotsit.org/) contain file format information for hundreds of file types. 4-13', 'vec_doc-04-nist-sp-800-86-p45-174', 0, 170, 'v2.1.0', 'e743c2ab803f6dc8845429c403d61959afba8fb58a94f79e6c2379ad9848520d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":45,"domain":"FORENSICS","authority_tier":0,"chunk_seq":174,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p46-175', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 46, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Identifying Known Files. The benefit of finding files of interest is obvious, but it is also often beneficial to eliminate unimportant files, such as known good OS and application files, from consideration. Analysts should use validated hash sets, such as those created by NISTs National Software Reference Library (NSRL) project56 or personally created hash sets57 that have been validated, as a basis for identifying known benign and malicious files. Hash sets typically use the SHA-1 and MD5 algorithms to establish message digest values for each known file. ! Performing String Searches and Pattern Matches. String searches aid in perusing large amounts of data to find key words or strings. Various searching tools are available that can use Boolean, fuzzy logic, synonyms and concepts, stemming, and other search methods.', 'vec_doc-04-nist-sp-800-86-p46-175', 0, 224, 'v2.1.0', '6f0acb0d0abc4e7a28caa43849559bd1cb3a1e4c6d34d2684de28f663a0e1c14', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"FORENSICS","authority_tier":0,"chunk_seq":175,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p46-176', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 46, 'Examples of common searches include searching for multiple words in a single file and searching for misspelled versions of certain words. Developing concise sets of search terms for common situations can help the analyst reduce the volume of information to review. Some considerations or possible difficulties in performing string searches are as follows:  Some proprietary file formats cannot be string searched without additional tools. In addition, compressed, encrypted, and password-protected files require additional pre-processing before a string search.  The use of multi-character data sets that include foreign or Unicode characters can cause problems with string searches; some searching tools attempt to overcome this by providing language translation functions.  Another possible issue is the inherent limitations of the search tool or algorithm.', 'vec_doc-04-nist-sp-800-86-p46-176', 0, 216, 'v2.1.0', '9508fa745b73e12ccb1b8e3ca63d1db13eb4317db4f19c84b925a853c88acd87', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"FORENSICS","authority_tier":0,"chunk_seq":176,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p46-177', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 46, 'For example, a match might not be found for a search string if part of the string resided in one cluster and the rest of the string resided in a nonadjacent cluster. Similarly, some search tools might report a false match if part of a search string resided in one cluster and the remainder of the string resided in another cluster that was not part of the same file that contained the first cluster. ! Accessing File Metadata. File metadata provides details about any given file. For example, collecting the metadata on a graphic file might provide the graphics creation date, copyright information, and description, and the creators identity.58  Metadata for graphics generated by a digital camera might include the make and model of the digital camera used to take the image, as well as F-stop, flash, and aperture settings. For word processing files, metadata could specify the author, the organization that licensed the software, when and by whom edits were last performed, and user-defined comments.', 'vec_doc-04-nist-sp-800-86-p46-177', 0, 252, 'v2.1.0', '6022ecf4f04eac02acc2cf513e7ca04325818a884bcf679ed5cc69ea68a2e275', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"FORENSICS","authority_tier":0,"chunk_seq":177,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p46-178', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.3 Examining Data Files', 46, 'Special utilities can extract metadata from files.', 'vec_doc-04-nist-sp-800-86-p46-178', 0, 13, 'v2.1.0', 'c02a5e5ab4f6d4ae8a8e6ca3f152af02abbc89a3d9376754a47bef670cc441f5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.3 Examining Data Files","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"FORENSICS","authority_tier":0,"chunk_seq":178,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.3 Examining Data Files"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p46-179', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.4 A nalysis', 46, 'After the examination has been completed, the next step is to perform analysis of the extracted data.  As mentioned in Section 4.3.3, there are many tools available that can be helpful in analysis of different types of data.  When using these tools or performing manual reviews of data, analysts should be aware of the value of using system times and file times.  Knowing when an incident occurred, a file was created or modified, or an e-mail was sent can be critical to forensic analysis.  For example, such information can be used to reconstruct a timeline of activities.  Although this may seem like a simple task, it is often 56  The NSRL home page is located at http://www.nsrl.nist.gov/. 57  Analysts may also create hashes of system files periodically; these hash sets are then available when an event occurs so that the analyst can quickly eliminate known benign files from examination.  Analysts should rely on standard hash sets such as those from the NSRL project whenever possible, and create custom hash sets primarily for organization-specific files. 58  Only certain types of graphics files include metadata; for example, JPEG-format graphics might have metadata, but bitmap- format graphics cannot. 4-14', 'vec_doc-04-nist-sp-800-86-p46-179', 0, 305, 'v2.1.0', 'b79035d9f396516ada76ae914f369793636414d7d60db31041d85c71faef263d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.4 A nalysis","subsection":"UNKNOWN","table_id":null,"page":46,"domain":"FORENSICS","authority_tier":0,"chunk_seq":179,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.4 A nalysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p47-180', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.4 A nalysis', 47, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE complicated by unintentional or intentional discrepancies in time settings among systems. Knowing the time, date, and time zone settings for a computer whose data will be analyzed can greatly assist an analyst; Section 5 describes this in more detail. It is usually beneficial to analysts if an organization maintains its systems with accurate timestamping. The Network Time Protocol (NTP) synchronizes the time on a computer with an atomic clock run by NIST or other organizations. Synchronization helps ensure that each system maintains a reasonably accurate measurement of time. If multiple tools are used to complete an examination and analysis, the analyst should understand how each tool extracts, modifies, and displays file modification, access, and creation (MAC) times. For instance, some tools modify the last access time of a file or directory if the filesystem has been mounted with write permissions by the OS.', 'vec_doc-04-nist-sp-800-86-p47-180', 0, 247, 'v2.1.0', '001b9a5640e8c49145b51ccbfaae3f89152175ffd87a89efaa5662c76527397b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.4 A nalysis","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"FORENSICS","authority_tier":0,"chunk_seq":180,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.4 A nalysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p47-181', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.4 A nalysis', 47, 'Write-blockers can be used to prevent these tools from modifying the MAC times; however, although write-blockers can prevent these times from being modified on the media, they cannot prevent the OS from caching the changes in memory (i.e., storing the changes in random access memory [RAM]). The OS might then report the cached MAC times rather than the actual times, thereby returning inaccurate results. The analyst should be aware that the last access time for data files and directories might change between queries, depending on the tool used to perform the query. Because of these issues, analysts should take care in choosing a MAC viewing method and record the details of that method. Analysts can use special tools that can generate forensic timelines based on event data. Such tools typically give analysts a graphical interface for viewing and analyzing sequences of events. A common feature of these tools is to permit analysts to group related events into meta-events.', 'vec_doc-04-nist-sp-800-86-p47-181', 0, 246, 'v2.1.0', '4d82e4fd5bb1c828d05b38920a3ca3e2a9d9a81c41dc02562f2b961eb4cedfe3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.4 A nalysis","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"FORENSICS","authority_tier":0,"chunk_seq":181,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.4 A nalysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p47-182', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.4 A nalysis', 47, 'This helps analysts to get a big picture view of events. In many cases, forensic analysis involves not only data from files, but also data from other sources, such as the OS state, network traffic, or applications. Section 8 provides examples of how data from files and data from other sources can be correlated through analysis.', 'vec_doc-04-nist-sp-800-86-p47-182', 0, 83, 'v2.1.0', '19ed575c97eb38f38c0f7f4732fcb93be96c0752891cdd0aed4c6bcd4f00c765', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.4 A nalysis","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"FORENSICS","authority_tier":0,"chunk_seq":182,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.4 A nalysis"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p47-183', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.5 Re commendations', 47, 'The key recommendations presented in this section for using data from data files are as follows. ! Analysts should examine copies of files, not the original files.  During the collection phase, the analyst should make multiple copies of the desired files or filesystems, typically a master copy and a working copy.  The analyst can then work with the working copy of the files without affecting the original files or the master copy.  A bit stream image should be performed if evidence may be needed for prosecution or disciplinary actions, or if preserving file times is important. ! Analysts should preserve and verify file integrity.  Using a write-blocker during backups and imaging prevents a computer from writing to its storage media.  The integrity of copied data should be verified by computing and comparing the message digests of files.  Backups and images should be accessed as read-only whenever possible; write-blockers can also be used to prevent writes to the backup or image file or restored backup or image. ! Analysts should rely on file headers, not file extensions, to identify file content types. Because users can assign any file extension to a file, analysts should not assume that file extensions are accurate.  Analysts can identify the type of data stored in many files by looking at their file headers.  Although people can alter file headers to conceal actual file types, this is much less common than altering file extensions. 4-15', 'vec_doc-04-nist-sp-800-86-p47-183', 0, 366, 'v2.1.0', '8e28b0083587d5d277fa379120ce384710572f62f9c2d09b83ad09e33306cc7f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":47,"domain":"FORENSICS","authority_tier":0,"chunk_seq":183,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p48-184', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4.5 Re commendations', 48, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Analysts should have a forensic toolkit for data examination and analysis.  The toolkit should contain various tools that provide the ability to perform quick reviews of data as well as in-depth analysis.  The toolkit should allow its applications to be run quickly and efficiently from removable media (e.g., floppy disk, CD) or a forensic workstation. 4-16', 'vec_doc-04-nist-sp-800-86-p48-184', 0, 106, 'v2.1.0', '2e608efabac9c4de2f8a0711eb8f58d7a973c6c8ffd630de64d319d081f380e0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":48,"domain":"FORENSICS","authority_tier":0,"chunk_seq":184,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p49-185', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5. Using Data from Operating Systems', 49, 'An operating system (OS) is a program that runs on a computer and provides a software platform on which other programs can run.  In addition, an OS is responsible for processing input commands from a user, sending output to a display, interacting with storage devices to store and retrieve data, and controlling peripheral devices such as printers and modems.  Some common OSs for workstations or servers include various versions of Windows, Linux, UNIX, and Mac OS.  Some network devices, such as routers, have their own proprietary OSs (e.g., Cisco Internetwork Operating System [IOS]).  PDAs often run specialized OSs, including PalmOS and Windows CE.59  Many embedded systems, such as cellular phones, digital cameras, and audio players, also use OSs.60  This section discusses the components of an OS that might be relevant to forensics and provides guidance on collecting, examining, and analyzing data from common workstation and server OSs.61', 'vec_doc-04-nist-sp-800-86-p49-185', 0, 238, 'v2.1.0', '422b1430847c62444718adb41c035c81ee3dd398484371fda0eeb3e2a322b9f2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5. Using Data from Operating Systems","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"FORENSICS","authority_tier":0,"chunk_seq":185,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5. Using Data from Operating Systems"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p49-186', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 49, 'OS data exists in both non-volatile and volatile states. Non-volatile data refers to data that persists even after a computer is powered down, such as a filesystem stored on a hard drive. Volatile data refers to data on a live system that is lost after a computer is powered down, such as the current network connections to and from the system. Many types of non-volatile and volatile data may be of interest from a forensics perspective. This section discusses both of these types of OS data. 5.1.1 Non-Volatile Data The primary source of non-volatile data within an OS is the filesystem.62  The filesystem is also usually the largest and richest source of data within the OS, containing most of the information recovered during a typical forensic event. The filesystem provides storage for the OS on one or more media.63  A filesystem typically contains many types of files, each of which may be of value to analysts in different situations.', 'vec_doc-04-nist-sp-800-86-p49-186', 0, 236, 'v2.1.0', '0cf3befd4aa1042df43b84c70441cbb7c30b2dfde9143662f2478110453793cb', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"FORENSICS","authority_tier":0,"chunk_seq":186,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p49-187', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 49, 'In addition, as noted in Section 4.1.2, important residual data can be recovered from unused filesystem space. Several types of data that are commonly found within OS filesystems are as follows: ! Configuration Files. The OS may use configuration files to store OS and application settings.64 For example, configuration files could list the services to be started automatically after system boot, and specify the location of log files and temporary files. Users might also have individual OS and application configuration files that contain user-specific information and preferences, such as hardware-related settings (e.g., screen resolution, printer settings) and file associations. Configuration files of particular interest are as follows: 59  For more information on PDA forensics, see NIST SP 800-72, Guidelines on PDA Forensics, available at http://csrc.nist.gov/publications/nistpubs/index.html.', 'vec_doc-04-nist-sp-800-86-p49-187', 0, 226, 'v2.1.0', '92e3d94fbbeaaefb88a59c30e10d61372ab98e2ea76fbd3ef0cf2c8cda12a295', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"FORENSICS","authority_tier":0,"chunk_seq":187,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p49-188', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 49, '60  A discussion of the types of information that can be found on these types of devices and the methods for collecting, examining, and analyzing the information is beyond the scope of this document. Because of the wide variety of devices and the knowledge and equipment needed in many cases to forensically process the data they contain, most organizations will find it best to secure such a device and transfer it to an appropriate party that is experienced in collecting, examining, and analyzing data from such devices (e.g., a law enforcement agency). 61  Guidance specific to data from proprietary and specialized operating systems is beyond the scope of this document; however, many of the concepts described in this section should also apply to them. 62  This may not be true for some devices, such as consumer electronics that do not use standard filesystems. 63  In some cases, the filesystem may be stored in dynamic memory.', 'vec_doc-04-nist-sp-800-86-p49-188', 0, 235, 'v2.1.0', 'b83f0e565077977edb25d923bff217454e404dad54633fab3bd9152a7178bce8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"FORENSICS","authority_tier":0,"chunk_seq":188,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p49-189', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 49, 'The term memory filesystems refers to filesystems that reside only in a systems memory. Such filesystems are considered volatile data. Filesystems, including an entire bootable OS implementation, may also reside on removable media such as flash drives. 64  On Windows systems, many configuration settings reside in a set of special files known as the registry. For more information on the registry, see Microsoft Knowledge Base article 256986, Description of the Microsoft Windows Registry, available at http://support.microsoft.com/?id=256986. 5-1', 'vec_doc-04-nist-sp-800-86-p49-189', 0, 138, 'v2.1.0', 'c5d2e50329619a5ed9f0e3d2d3d7add017169f69c71d5cadc4add78baedfdb8c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":49,"domain":"FORENSICS","authority_tier":0,"chunk_seq":189,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p50-190', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 50, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE  Users and Groups. The OS keeps a record of its user accounts and groups. Account information may include group membership, account name and description, account permissions, account status (e.g., active, disabled), and the path to the accounts home directory.  Password Files. The OS may store password hashes in data files. Various password- cracking utilities may be used to convert a password hash to its clear text equivalent for certain OSs.  Scheduled Jobs. The OS maintains a list of scheduled tasks that are to be performed automatically at a certain time (e.g., perform a virus scan every week). Information that can be gleaned from this include the task name, the program used to perform the task, command line switches and arguments, and the days and times when the task is to be performed. ! Logs. OS log files contain information about various OS events, and may also hold application- specific event information.', 'vec_doc-04-nist-sp-800-86-p50-190', 0, 249, 'v2.1.0', 'cee54af5293e33beef772b2dc1b9809c94af007b34daedfbd2c39143ad471d52', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"FORENSICS","authority_tier":0,"chunk_seq":190,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p50-191', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 50, 'Depending on the OS, logs may be stored in text files, proprietary- format binary files, or databases. Some OSs write log entries to two or more separate files. The types of information typically found in OS logs are as follows:  System Events. System events are operational actions performed by OS components, such as shutting down the system or starting a service. Typically, failed events and the most significant successful events are logged, but many OSs permit system administrators to specify which types of events will be logged. The details logged for each event also vary widely. Each event is usually timestamped; other supporting information could include event codes, status codes, and username.  Audit Records. Audit records contain security event information such as successful and failed authentication attempts and security policy changes. OSs typically permit system administrators to specify which types of events should be audited.', 'vec_doc-04-nist-sp-800-86-p50-191', 0, 239, 'v2.1.0', 'd39182274547b053592cea318f9926ec83466e7dfa65cb41081a7fbc0687a1b5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"FORENSICS","authority_tier":0,"chunk_seq":191,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p50-192', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.1 O S Basics', 50, 'Administrators also can configure some OSs to log successful, failed, or all attempts to perform certain actions.  Application Events. Application events are significant operational actions performed by applications, such as application startup and shutdown, application failures, and major application configuration changes. Section 7 contains more information on application event logging.  Command History. Some OSs have separate log files (typically for each user) that contain a history of the OS commands performed by each user.  Recently Accessed Files. An OS might log the most recent file accesses or other usage, creating a list of the most recently accessed files. ! Application Files. Applications can be composed of many types of files, including executables, scripts, documentation, configuration files, log files, history files, graphics, sounds, and icons.', 'vec_doc-04-nist-sp-800-86-p50-192', 0, 219, 'v2.1.0', 'f7a3dfbd1e0a9e754f8101deecb688a12fed665cb8c116c86d302a23855adf26', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.1 O S Basics","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"FORENSICS","authority_tier":0,"chunk_seq":192,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.1 O S Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p50-193', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 50, '! Data Files.  Data files store information for applications.  Examples of common data files are text files, word processing documents, spreadsheets, databases, audio files, and graphics files.  In addition, when data is printed, most OSs create one or more temporary print files that contain the print-ready version of the data.  Sections 4 and 7 discuss application data files in more depth. ! Swap Files.  Most OSs use swap files in conjunction with RAM to provide temporary storage for data often used by applications.  Swap files essentially extend the amount of memory available to 5-2', 'vec_doc-04-nist-sp-800-86-p50-193', 0, 148, 'v2.1.0', 'a271eb14482742fcde6beb09025280499a69e3051c4f35b75606b1ba031f41fd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":50,"domain":"FORENSICS","authority_tier":0,"chunk_seq":193,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p51-194', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 51, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE a program by allowing pages (or segments) of data to be swapped in and out of RAM. Swap files may contain a broad range of OS and application information, such as usernames, password hashes, and contact information. Section 5.1.2 discusses the contents of memory in more detail. ! Dump Files. Some OSs have the ability to store the contents of memory automatically during an error condition to assist in subsequent troubleshooting. The file that holds the stored memory contents is known as a dump file. ! Hibernation Files. A hibernation file is created to preserve the current state of a system (typically a laptop) by recording memory and open files before shutting off the system. When the system is next turned on, the state of the system is restored. ! Temporary Files. During the installation of an OS, application, or OS or application updates and upgrades, temporary files are often created.', 'vec_doc-04-nist-sp-800-86-p51-194', 0, 241, 'v2.1.0', 'f35c7ca63f61d47429b00d5c2e012a413cb4a7ddbc79013b70a03fbda97655f3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"FORENSICS","authority_tier":0,"chunk_seq":194,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p51-195', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 51, 'Although such files are typically deleted at the end of the installation process, this does not always occur. In addition, temporary files are created when many applications are run; again, such files are usually deleted when the application is terminated, but this does not always happen. Temporary files could contain copies of other files on the system, application data, or other information. Although filesystems are the primary source of non-volatile data, another source of interest is the BIOS. The BIOS contains many types of hardware-related information, such as the attached devices (e.g., CD- ROM drives, hard drives), the types of connections and interrupt request line (IRQ) assignments (e.g., serial, USB, network card), motherboard components (e.g., processor type and speed, cache size, memory information), system security settings, and hot keys. The BIOS also communicates with RAID drivers and displays the information provided by the drivers.', 'vec_doc-04-nist-sp-800-86-p51-195', 0, 241, 'v2.1.0', '7cb348d3d3f44379ae47f2b934011913d0dce566f62360614132401f84bfc21c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"FORENSICS","authority_tier":0,"chunk_seq":195,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p51-196', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 51, 'For example, the BIOS views a hardware RAID as a single drive and a software RAID as multiple drives. The BIOS typically permits the user to set passwords, which restrict access to the BIOS settings and may prevent the system from booting if the password is not supplied. The BIOS also holds the system date and time. 5.1.2 Volatile Data OSs execute within the RAM of a system. While the OS is functioning, the contents of RAM are constantly changing. At any given time, RAM might contain many types of data and information that could be of interest. For example, RAM often contains frequently and recently accessed data, such as data files, password hashes, and recent commands. In addition, like filesystems, RAM can contain residual data in slack and free space, as follows: ! Slack Space. Memory slack space is much less deterministic than file slack space. For example, an OS generally manages memory in units known as pages or blocks, and allocates them to requesting applications.', 'vec_doc-04-nist-sp-800-86-p51-196', 0, 247, 'v2.1.0', 'cb4c9c47c9117e34d8a6750fe10ed6721e9eacace0683e9b317593ee2d312fa7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"FORENSICS","authority_tier":0,"chunk_seq":196,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p51-197', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 51, 'Sometimes, although an application might not request an entire unit, it is given one anyway. Residual data could therefore reside in the unit of memory allocated to an application, although it might not be addressable by the application. For performance and efficiency, some OSs vary the size of the units they allocate, which tends to result in smaller memory slack spaces. ! Free Space. Memory pages are allocated and deallocated much like file clusters. When they are not allocated, memory pages are often collected into a common pool of available pagesa process often referred to as garbage collection. It is not uncommon for residual data to reside in these reusable memory pages, which are analogous to unallocated file clusters. Some other significant types of volatile data that might exist within an OS are as follows: 5-3', 'vec_doc-04-nist-sp-800-86-p51-197', 0, 208, 'v2.1.0', '7e5c89565caa7b69884fb98d080a34491c8ba80532eca25b18a660dd80649a26', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":51,"domain":"FORENSICS","authority_tier":0,"chunk_seq":197,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p52-198', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 52, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Network Configuration. Although many elements of networking, such as network interface card (NIC) drivers and configuration settings, are typically stored in the filesystem, networking is dynamic in nature. For example, many hosts are assigned Internet Protocol (IP) addresses dynamically by another host, meaning that their IP addresses are not part of the stored configuration. Many hosts also have multiple network interfaces defined, such as wired, wireless, virtual private network (VPN), and modem; the current network configuration indicates which interfaces are currently in use. Users also may be able to alter network interface configurations from the defaults, such as manually changing IP addresses. Accordingly, analysts should use the current network configuration, not the stored configuration, whenever possible. ! Network Connections. The OS facilitates connections between the system and other systems.', 'vec_doc-04-nist-sp-800-86-p52-198', 0, 247, 'v2.1.0', '8be355687d249f7d203a67ae8a8cb6f511efc37b145b8fcf49064d979f43a1fe', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"FORENSICS","authority_tier":0,"chunk_seq":198,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p52-199', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 52, 'Most OSs can provide a list of current incoming and outgoing network connections, and some OSs can list recent connections as well. For incoming connections, the OS typically indicates which resources are being used, such as file shares and printers. Most OSs can also provide a list of the ports and IP addresses at which the system is listening for connections. Section 6 provides an in-depth examination of the significance of network connections. ! Running Processes. Processes are the programs that are currently executing on a computer. Processes include services offered by the OS and applications run by administrators and users. Most OSs offer ways to view a list of the currently running processes. This list can be studied to determine the services that are active on the system, such as a Web server, and the programs that individual users are running (e.g., encryption utility, word processor, e-mail client).', 'vec_doc-04-nist-sp-800-86-p52-199', 0, 231, 'v2.1.0', 'd27d575eeb493bcc4f79f41da1b3e49770038e83267f399f3b3a708048d4b2ed', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"FORENSICS","authority_tier":0,"chunk_seq":199,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p52-200', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 52, 'Process lists may also indicate which command options were used, as described in Section 7. Identifying the running processes is also helpful for identifying programs that should be running but have been disabled or removed, such as antivirus software and firewalls. ! Open Files. OSs may maintain a list of open files, which typically includes the user or process that opened each file. ! Login Sessions. OSs typically maintain information about currently logged-in users (and the start time and duration of each session), previous successful and failed logons, privileged usage, and impersonation.65  However, login session information might be available only if the computer has been configured to audit logon attempts. Logon records can help to determine a users computer usage habits and confirm whether a user account was active when a given event occurred. ! Operating System Time. The OS maintains the current time and stores daylight savings time and time zone information.', 'vec_doc-04-nist-sp-800-86-p52-200', 0, 246, 'v2.1.0', '489df87f87c9fc85c521f01596d3d1998a0c6ac9703d5b920f8ec8b181ee73be', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"FORENSICS","authority_tier":0,"chunk_seq":200,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p52-201', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 7 provides an in-depth discussion of application files.', 52, 'This information can be useful when building a timeline of events or correlating events among different systems. Analysts should be aware that the time presented by the OS might differ from that presented by the BIOS because of OS-specific settings, such as time zone.', 'vec_doc-04-nist-sp-800-86-p52-201', 0, 67, 'v2.1.0', '51cc0bf3d2f6597d6b2b2c18ef1aa566d32993a283637aa199b7928b6d38bfc0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 7 provides an in-depth discussion of application files.","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"FORENSICS","authority_tier":0,"chunk_seq":201,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 7 provides an in-depth discussion of application files."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p52-202', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 52, 'As described in Section 5.1, OS data exists in both non-volatile and volatile states.  Non-volatile OS data such as filesystem data can be collected using the approaches discussed in Section 4 for performing logical backups and bit stream imaging.  Volatile OS data should be collected before the computer is powered down.  Sections 5.2.1 and 5.2.2 provide recommendations for collecting volatile and non-volatile OS data, respectively.  Section 5.2.3 discusses technical issues that can impede the collection of data. 65  Impersonation can allow a regular system user to have higher system privileges to accomplish certain tasks.  For example, a particular program might require administrator access to run.  Through impersonation, a regular user can be given those permissions to run the application and then be reverted back to the usual privileges. 5-4', 'vec_doc-04-nist-sp-800-86-p52-202', 0, 214, 'v2.1.0', '6cc028239bd626033c58928e925da3f8947c81d20f19bdf336e2e7becb2ce4e1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":52,"domain":"FORENSICS","authority_tier":0,"chunk_seq":202,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p53-203', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 53, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 5.2.1 Collecting Volatile OS Data Volatile OS data involving an event can be collected only from a live system that has not been rebooted or shut down since the event occurred. Every action performed on the system, whether initiated by a person or by the OS itself, will almost certainly alter the volatile OS data in some way. Therefore, analysts should decide as quickly as possible whether the volatile OS data should be preserved. Ideally, the criteria for making this decision should have been documented in advance so that the analyst can make the best decision immediately. The importance of this decision cannot be stressed enough, because powering off the system or even disconnecting it from a network can eliminate the opportunity to collect potentially important information.', 'vec_doc-04-nist-sp-800-86-p53-203', 0, 213, 'v2.1.0', 'e4c122a3be43bef72a1bffd4d709ea784ff63f4a3314e32c774e9251a8135929', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"FORENSICS","authority_tier":0,"chunk_seq":203,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p53-204', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 53, 'For example, if a user recently ran encryption tools to secure data, the computers RAM might contain password hashes, which could be used to determine the passwords. On the other hand, collecting volatile OS data from a running computer has inherent risks. For instance, the possibility always exists that files on the computer might change and other volatile OS data might be altered. In addition, a malicious party might have installed rootkits designed to return false information, delete files, or perform other malicious acts. In deciding whether to collect volatile data, the risks associated with such collection should be weighed against the potential for recovering important information. As noted in Section 3.2, if evidence may be needed, the analyst should fully document what is seen on the screen before touching the system.', 'vec_doc-04-nist-sp-800-86-p53-204', 0, 210, 'v2.1.0', 'd356986c7db7d9a1c0bd89b9b2d97cbb53996ffc2789afb2379fbf733e9f748d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"FORENSICS","authority_tier":0,"chunk_seq":204,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p53-205', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 53, 'If a live system is in sleep mode or has visible password protection, analysts should also decide whether to alter the state of the system by waking it from sleep mode or attempting to crack or bypass the password protection so that analysts can attempt to collect volatile data. If the effort needed to collect the volatile data is not merited, analysts might instead decide to perform a shutdown, as described in Section 5.2.2. Section 5.2.1.1 describes how forensic tools should be compiled in preparation for collecting volatile OS data. Next, Section 5.2.1.2 discusses several types of data and mentions categories of tools or specific OS tools that are effective in collecting each type of data. Finally, Section 5.2.1.3 explains the need to identify the types of volatile OS data that are most likely to be valuable in a particular situation and then to prioritize the collection of data based on importance and relative volatility.', 'vec_doc-04-nist-sp-800-86-p53-205', 0, 235, 'v2.1.0', '36b0c5f91507b7cd641944848091bb33f5f366e5c83896417c7806c415adc5a8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"FORENSICS","authority_tier":0,"chunk_seq":205,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p53-206', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 53, '5.2.1.1 Forensic Tool Preparation When collecting volatile OS data, all forensic tools that might be needed should be placed on a floppy disk, CD-ROM, or USB flash drive, from which the tools should be executed. Doing so enables analysts to collect OS data with the least amount of disturbance to the system. In addition, only forensic tools should be used, since a user might have replaced system commands with malicious programs, such as one to format a hard disk or return false information. However, use of forensic tools is no guarantee that the data retrieved will be accurate. If a system has been fully compromised, it is possible that rootkits and other malicious utilities have been installed that alter the systems functionality at the kernel level. This can cause false data to be returned to user-level tools. When creating a collection of forensic tools, statically linked binary files should be used.', 'vec_doc-04-nist-sp-800-86-p53-206', 0, 229, 'v2.1.0', 'd42a42dd012fcc7d63d2371fb91c06343295041444a04f95ba56e6299683dc81', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"FORENSICS","authority_tier":0,"chunk_seq":206,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p53-207', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 53, 'Such an executable file contains all of the functions and library functions that it references, so separate dynamic link libraries (DLL) and other supporting files are not needed. This eliminates the need to place the appropriate versions of DLLs on the tool media and increases the reliability of the tools. The analyst should know how each tool affects or alters the system before collecting the volatile data. The message digest of each tool should be computed and stored safely to verify file integrity. Licensing and version information also should be documented for each forensic tool. In addition, the exact commands that were used to run each forensic tool should be documented (i.e., command line arguments and switches). It may be helpful to place a script on the tool media that can be run to capture which commands were run, at what time, and with what output. 5-5', 'vec_doc-04-nist-sp-800-86-p53-207', 0, 219, 'v2.1.0', '5e4b33ff1ca3f1134351e4f791d1b73b15aaf804af7b76b175b10c0dee95ceb2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":53,"domain":"FORENSICS","authority_tier":0,"chunk_seq":207,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p54-208', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 54, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE The media containing the tools should protect them from changes. Floppy disks should be write- protected to ensure that no changes are made to the tools. CD-ROMs should be write-once CDs (i.e., CD- R), not rewritable CDs, since the contents of a rewritable CD could be altered by CD-burning utilities on the users computer. After the tools have been burned to a write-once CD, the disc should be finalized to ensure that no additional data can be written to it.66 Because the media containing the tools should be write-protected, the results produced by the tools cannot be placed onto the tool media. Analysts often direct tool output to a floppy disk, but the prevalence of floppy disk drives on computing devices is decreasing. As a result, alternative methods of collecting output have been developed.', 'vec_doc-04-nist-sp-800-86-p54-208', 0, 218, 'v2.1.0', 'f576341bf259858356bd4b91b368339cca9f9d672e6862091f8278043e20d5f3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"FORENSICS","authority_tier":0,"chunk_seq":208,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p54-209', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 54, 'Specially prepared CDs and USB flash drives containing a Windows or Linux-based environment can be used to gather output without changing the state of the system and typically direct the output to another USB flash drive, external hard drive, or other writable media, or to a remote system. 5.2.1.2 Types of Volatile OS Data The following list shows several types of volatile OS data and explains how forensic tools can be used in collecting each type of data:67 ! Contents of Memory. There are several utilities that can copy the contents of RAM to a data file and assist in subsequent analysis of the data. On most systems, it is not possible to avoid alteration of RAM when running a utility that attempts to make a copy of RAM. Instead, the goal is to perform the copying with as small a footprint as possible to minimize the disruption of RAM. ! Network Configuration.', 'vec_doc-04-nist-sp-800-86-p54-209', 0, 219, 'v2.1.0', '9621b9b6e4d5cfd9cb2405fd5a53709ff6317d648c095ed54cda8d7be2fe3d58', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"FORENSICS","authority_tier":0,"chunk_seq":209,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p54-210', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 54, 'Most OSs include a utility that displays the current network configuration, such as ifconfig on UNIX systems and ipconfig on Windows systems. Information that can be provided through network configuration utilities includes the hostname, the physical and logical network interfaces, and configuration information for each interface (e.g., IP address, Media Access Control [MAC] address, current status). ! Network Connections. OSs typically provide a method for displaying a list of the current network connections. Both Windows and UNIX-based systems usually include the netstat program, which lists network connections by source and destination IP addresses and ports, and also lists which ports are open on each interface.68  Third-party utilities are available that can display port assignments for each program. Most OSs also can display a list of remotely mounted filesystems, which provides more detailed information than a network connection list.', 'vec_doc-04-nist-sp-800-86-p54-210', 0, 239, 'v2.1.0', '7f9cea32c9e0427a1c1ae9f35aea87a13b3596cd3f0f2fd859723ac6e0e793e2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"FORENSICS","authority_tier":0,"chunk_seq":210,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p54-211', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 54, 'Section 6.2.7 provides additional information about gathering network connection information.69 66  Finalizing a CD is a typical feature of CD-burning utilities. Some CD-burning utilities also allow the current session to be closed. However, closing a session simply indicates to the CD-burning utility that no additional data will be written to the disc in the current session; it does not prevent additional data from being written to the disc in a different session (often referred to as a multisession disc). Therefore, analysts should finalize the disc, not close the session, when creating a toolkit CD. 67  Many resources are available that list the hundreds of tools available for analysts. Appendix F lists several Web sites that contain more information on computer forensic tools. For tools that are included with OSs, analysts should use copies of the tools that are on read-only media, not tools on the OS of a system of interest.', 'vec_doc-04-nist-sp-800-86-p54-211', 0, 236, 'v2.1.0', 'a0d22248e0030f7a2477aa6e36a2beff4fdb57c98e6054490ffaf46c4f66e568', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"FORENSICS","authority_tier":0,"chunk_seq":211,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p54-212', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 54, '68  Another way of identifying the open ports is by running port scanning software from another system. Port scanning software sends network traffic to various ports and analyzes the responses, as well as missing responses, to determine which ports are open. However, port scanning might produce inaccurate results due to security controls, such as host-based firewalls that block the scans; also, the scans could change the state of the system. Accordingly, port scans are best suited for informal data acquisition and for information collection when access to the OS is not available. 69  More information on fport is available at http://www.foundstone.com/index.htm?subnav=resources/navigation.htm&subcontent=/resources/proddesc/fport.htm. 5-6', 'vec_doc-04-nist-sp-800-86-p54-212', 0, 187, 'v2.1.0', '68b5fff04d52c0dca3a19ae7da742ef0b19a0b395102db76d02db5702963af87', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":54,"domain":"FORENSICS","authority_tier":0,"chunk_seq":212,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p55-213', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 55, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Running Processes. All UNIX-based systems offer the ps command for displaying currently running processes. Although Windows offers a graphical user interface (GUI)based process list utility, the Task Manager, it is usually preferable to have a text-based listing. Third-party utilities can be used to generate a text list of running processes for Windows systems. ! Open Files. All UNIX-based systems offer the lsof command for displaying a list of open files. Third-party utilities can be used to generate text lists of open files for Windows systems. ! Login Sessions. Some OSs have built-in commands for listing the currently logged on users, such as the w command for UNIX systems, which also lists the source address of each user and when the user logged onto the system. Third-party utilities are available that can list currently connected users on Windows systems. ! Operating System Time.', 'vec_doc-04-nist-sp-800-86-p55-213', 0, 241, 'v2.1.0', '6518260dec7d3c3b34801681f9e24090611bc8b238edac51684830843a1bf53a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"FORENSICS","authority_tier":0,"chunk_seq":213,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p55-214', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 55, 'There are several utilities available for retrieving the current system time, time zone information, and daylight savings time settings. On UNIX systems, the date command can be used to retrieve this information. On Windows systems, the date, time, and nlsinfo commands can be used collectively to retrieve this information. In addition to the tools in the preceding list, it is often useful to include some general-purpose tools in the forensic toolkit, such as the following: ! OS Command Prompt. This utility provides an OS command prompt through which the other tools in the toolkit can be executed, such as cmd on Windows systems. ! SHA-1 Checksum. A utility that can compute the SHA-1 message digest of data files is helpful in file verification. It may also be useful to include in the toolkit a list of SHA-1 message digests for system data files associated with the target OS to assist in file verification. Utilities are available for various OSs for this purpose.70 ! Directory List.', 'vec_doc-04-nist-sp-800-86-p55-214', 0, 249, 'v2.1.0', '82aaecd014ab4f1cd576b6a70a8f6d8dcbaa1e6e7303e511951a3efc74dfea22', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"FORENSICS","authority_tier":0,"chunk_seq":214,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p55-215', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 55, 'A utility for listing the contents of directories should be included for navigating a filesystem and seeing its contents. Practically all OSs include such a utility; for example, the ls command is used on UNIX systems, whereas on Windows systems, the dir command is used. ! String Search. A utility for performing a text string search can be useful in identifying data files of interest. UNIX systems offer the grep command for performing text string searches, and a third-party grep utility is also available on Windows systems.71 ! Text Editor. A simple text editor can be useful for viewing text files or composing notes. Numerous text editors are available, such as Notepad on Windows systems and vi on UNIX systems. 5.2.1.3 Prioritizing Data Collection The types of volatile data that should be collected with the toolkit depend on the specific need.', 'vec_doc-04-nist-sp-800-86-p55-215', 0, 214, 'v2.1.0', 'fb628ab51dc8e08cf7f531eedbd02ff3417f37da3d15cab90d202ddbeb35a58e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"FORENSICS","authority_tier":0,"chunk_seq":215,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p55-216', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 55, 'For instance, if a network intrusion is suspected, it might be useful to collect network configuration information, network connections, login sessions, and running processes to determine how someone gained access to a system. If an investigation concerns identity theft, then the contents of RAM, the list of running processes, the list of open files, network configuration information, and network connections might reveal social security and credit card numbers, programs used to obtain or encrypt data, password hashes, and methods that might have been used to obtain the information over a network. When in doubt, it is usually a good idea to collect as much volatile data as possible because all opportunities to collect 70  See http://lists.thedatalist.com/pages/Checksum_Tools.htm for more information on checksum utilities. 71  One Windows version of grep is available at http://unxutils.sourceforge.net/. 5-7', 'vec_doc-04-nist-sp-800-86-p55-216', 0, 230, 'v2.1.0', 'bea6e476c194fee113f8c6455ad41c223f7880816679412f854d66070524de58', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":55,"domain":"FORENSICS","authority_tier":0,"chunk_seq":216,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p56-217', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.2 Collecting OS Data', 56, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE such data will be lost once the computer is powered down.  Later, a determination can be made as to which collected volatile data should be examined.  An automated script on a toolkit CD can be used for consistency in collecting volatile data.  The script can include ways to transfer the collected information to local storage media, such as a thumb drive, and to networked drive locations. Because volatile data has a propensity to change over time, the order and timeliness with which volatile data is collected is important.  In most cases, analysts should first collect information on network connections and login sessions, because network connections may time out or be disconnected and the list of users connected to a system at any single time may vary.  Volatile data that is less likely to change, such as network configuration information, should be collected later.  The recommended order in which volatile data generally should be collected, from first to last, is as follows:', 'vec_doc-04-nist-sp-800-86-p56-217', 0, 264, 'v2.1.0', '565f8410cb9fd9677b281d2a391b361d9e78bcedb92c7071cf014327760a4ee8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.2 Collecting OS Data","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"FORENSICS","authority_tier":0,"chunk_seq":217,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.2 Collecting OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p56-218', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 56, '5.2.2 Collecting Non-Volatile OS Data After obtaining volatile OS data, analysts often should collect non-volatile OS data.  To do so, the analyst first should decide whether the system should be shut down.  Shutting down the system not only affects the ability to perform bit stream imaging and many logical backups, but can also change which OS data is preserved.  Most systems can be shut down through two methods: ! Perform a Graceful OS Shutdown.  Nearly every OS offers a shutdown option.72  This causes the OS to perform cleanup activities, such as closing open files, deleting temporary files, and possibly clearing the swap file, before shutting down the system.  A graceful shutdown can also trigger removal of malicious material; for example, memory-resident rootkits may disappear, and Trojan horses may remove evidence of their malicious activity.  The OS is typically shut down from the account of the administrator or the current user of the system (if the current user has sufficient privileges). ! Remove Power from the System.  Disconnecting the power cord from the back of the computer (and removing the batteries on a laptop or other portable device) can preserve swap files, temporary data files, and other information that might be altered or deleted during a graceful shutdown.73  Unfortunately, a sudden loss of power can cause some OSs to corrupt data, such as 72  For example, on Windows systems, analysts could use the Shut Down feature on the Start menu. 73  Disconnecting a power cord from the electrical wall outlet is not recommended because the computers power cord may be plugged into an uninterruptible power supply (UPS) unit. 5-8', 'vec_doc-04-nist-sp-800-86-p56-218', 0, 417, 'v2.1.0', '6cbb6524bd2fd5f595a7e321d53aebeb6c0a798e831ea6ed86e3cceebb3075db', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":56,"domain":"FORENSICS","authority_tier":0,"chunk_seq":218,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p57-219', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 57, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE open files. In addition, for some consumer devices, such as PDAs and cell phones, removing battery power can cause a loss of data.74 Some tools are able to perform collection actions on running systems without any problems, while other tools are best run on systems that have been shut down. In the latter case, analysts should be aware of the characteristics of each OS and choose a shutdown method based on the typical behavior of the OS and the types of data that need to be preserved.75  For example, DOS and Windows 95/98 systems generally do not corrupt data when power is removed suddenly, so removing power should preserve data. Other OSs might corrupt data, such as open files or files that were being accessed at the time, if there is a loss of power.', 'vec_doc-04-nist-sp-800-86-p57-219', 0, 207, 'v2.1.0', '862b17435e0b32f9a6d87d67c88eecb33c79163296f57185df9f0e3a862bf5fe', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"FORENSICS","authority_tier":0,"chunk_seq":219,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p57-220', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 57, 'In these cases, a graceful shutdown is generally best unless swap files or temporary data files are of particular interest or the system might contain rootkits, Trojan horses, or other malicious programs that might be triggered by a graceful shutdown. After performing a shutdown (if needed), the analyst should acquire filesystem data from the systems storage media using the methods discussed in Section 4. After the computer has been powered off, all components, storage devices, media, and peripheral devices connected to the computer should be inventoried and labeled if they are needed as evidence. Whenever possible, the inventory should include the model number, serial number, and description of the item. In addition, information about how each item is connected to the outside or inside of the computer (e.g., cable connections, jumper settings) should be documented and photographed. This will help the analyst to recreate the users computer setup.', 'vec_doc-04-nist-sp-800-86-p57-220', 0, 241, 'v2.1.0', 'bb41ef404a478d5126cc6cabec0aabd51c2a21dbb054edc844c8f24f0d50ccb2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"FORENSICS","authority_tier":0,"chunk_seq":220,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p57-221', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 57, 'Assuming that the evidence can be legally seized, each item should be handled using antistatic bracelets, guarded against electrostatic discharges that can damage the item, sealed properly (i.e., a box that is taped shut), and packed securely for transport. Handlers should wear antistatic bracelets when handling sensitive media and protect media with antistatic bags and other special packing materials. Once the filesystem data has been collected, tools can be used to acquire specific types of data from the filesystem. Acquiring regular files, such as data, application, and configuration files, is relatively straightforward and is described in more detail in Section 4. The following list describes several other types of non-volatile OS data and explains how tools can be useful in acquiring each type from the filesystem:76 ! Users and Groups. Operating systems maintain a list of users and groups that have access to the system.', 'vec_doc-04-nist-sp-800-86-p57-221', 0, 235, 'v2.1.0', '96b35b30b150509b36b42ff6b113e8942acfac6b5abd45fde099a800de3c04f6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"FORENSICS","authority_tier":0,"chunk_seq":221,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p57-222', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 57, 'On UNIX systems, users and groups are listed in /etc/passwd and /etc/groups, respectively. In addition, the groups and users commands can be used to identify users who have logged onto the system and the groups to which they belong. On Windows systems, the net user and net group commands can be used to enumerate the users and groups on a system. ! Passwords. Most OSs maintain password hashes for users passwords on disk. On Windows systems, third-party utilities can be used to dump password hashes from the Security Account Manager (SAM) database. On UNIX systems, password hashes are usually in the /etc/passwd or /etc/shadow file. As described in Section 4.3.2, password cracking programs can be used to extract passwords from their hashes. 74  Power for such devices often must be maintained on an ongoing basis.', 'vec_doc-04-nist-sp-800-86-p57-222', 0, 205, 'v2.1.0', '33a5ba12b7ec9205f9327ee37afde21b527c5f36a99f1277ea0334d323a6886c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"FORENSICS","authority_tier":0,"chunk_seq":222,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p57-223', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 57, 'If a device does not have regular power, typically its memory will be sustained by battery power only for the short term (weeks at most, minutes at worst), even if the device is powered off. For long-term storage of consumer devices that contain important data, power should be maintained to preserve the devices memory. 75  In most cases, analysts can determine which type of OS is in use by looking at the screen. For example, Windows systems use taskbars and other graphic elements that do not appear on other OSs. 76  Some of the tools described in this section can also be used to collect data from a live system. 5-9', 'vec_doc-04-nist-sp-800-86-p57-223', 0, 156, 'v2.1.0', 'f4a659c8ddcd6c4d515ffd04017cbec8685a306ecf945d8a722f8214ad148aad', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":57,"domain":"FORENSICS","authority_tier":0,"chunk_seq":223,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p58-224', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 58, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Network Shares. A system may enable local resources to be shared across a network. On Windows systems, the SrvCheck utility can be used to list network shares.77  Third-party utilities can provide similar information for other OSs. ! Logs. Logs that are not stored in text files might necessitate use of log extraction utilities. For example, specialized utilities can retrieve information about recent successful and failed logon attempts on Windows systems, which are stored in binary format logs. Most log entries on Unix systems are stored in text files by syslog or in the /var/log directory, so special utilities are not needed to acquire information from the logs.78  Searching for filenames ending in .log should identify most log files.', 'vec_doc-04-nist-sp-800-86-p58-224', 0, 203, 'v2.1.0', '36737395e1118d1e898759ddb0e613acfe798dadcec6c7cc1dbdc73ab1b275c3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"FORENSICS","authority_tier":0,"chunk_seq":224,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p58-225', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 58, 'Occasionally, analysts may need to collect data from the BIOS, such as system date and time or processor type and speed.79  Because the BIOS primarily contains information related to the systems hardware configuration, BIOS data collection is most likely to be needed when a system administrator is troubleshooting operational issues. Typically, analysts who need BIOS data first collect any needed volatile data and filesystems, then reboot the system and press the appropriate function key (generally specified in the initial screen during boot) to display the BIOS settings. If the BIOS password is set, the analyst might not be able to gain access to the BIOS settings easily and might have to attempt to guess default passwords or circumvent the password protection.', 'vec_doc-04-nist-sp-800-86-p58-225', 0, 193, 'v2.1.0', '030e26cc7140bbf4c5713f75982a1f68903fae936a7571f95f0515ba995566d4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"FORENSICS","authority_tier":0,"chunk_seq":225,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p58-226', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 58, 'A variety of methods can be used to bypass BIOS passwords, including finding the appropriate manufacturer backdoor password, using a password cracker, moving the appropriate jumper on the motherboard, or removing the Complementary Metal Oxide Semiconductor (CMOS) battery (if possible). Systems vary, so analysts should first research the particular characteristics of the system they are analyzing, as described in motherboard documentation, to avoid harming a system unnecessarily.80 5.2.3 Technical Issues with Collecting Data Technical issues might also impede collection of OS data. Section 4 describes several filesystem-related issues; this section focuses on additional collection issues and provides guidance on what, if anything, can be done to mitigate them. The intent of this section is not to provide an exhaustive discussion of all possible issues, but to provide some basic information on common ones. ! OS Access.', 'vec_doc-04-nist-sp-800-86-p58-226', 0, 233, 'v2.1.0', '68c45a8be0d139d409310fed6942c504a298c6ef723699ee178f62e09245a52c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"FORENSICS","authority_tier":0,"chunk_seq":226,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p58-227', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 58, 'Collecting volatile data can be difficult because the analyst might not be able to readily gain access to the OS. For instance, a user might run a password-protected screen saver or have the system locked. In these cases, the analyst will need to circumvent this protection or find another way to gain access to volatile OS data.81  If a password-protected screen saver is active, restarting the system might allow the analyst to bypass the screen saver, but would also cause all volatile OS data to be lost. If a host uses biometric-based authentication, such as a fingerprint reader, or another add-on authentication service, this could cause similar issues in accessing volatile OS data. There are third-party utilities for some OSs that claim to crack screen 77  SrvCheck is available from the Windows Server 2003 Resource Kit. 78  More information on the syslog protocol is available in RFC 3164, The BSD Syslog Protocol, available at http://www.ietf.org/rfc/rfc3164.txt.', 'vec_doc-04-nist-sp-800-86-p58-227', 0, 244, 'v2.1.0', '40870a25972bed00b7db99ad969bf649da9f7c02d5e186255956551ca5a81ac8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"FORENSICS","authority_tier":0,"chunk_seq":227,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p58-228', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 58, '79  Hard drive information presented in the BIOS might be inaccurate for larger hard drives. Many drives now use Logical Block Addressing, which causes the BIOS to display incorrect drive geometry information. Analysts should be able to acquire the correct information by examining the physical label on the hard drive itself. 80  More information about bypassing BIOS passwords is available at http://www.freelabs.com/~whitis/security/backdoor.html and http://labmice.techtarget.com/articles/BIOS_hack.htm. 81  Several Web sites indicate ways to circumvent specific screen savers, such as taking advantage of known OS vulnerabilities. However, the screen saver bypass methods are of little use if the OS is unknown or the user has eliminated the vulnerabilities.', 'vec_doc-04-nist-sp-800-86-p58-228', 0, 191, 'v2.1.0', 'c01d2db37ff79b2b4a9278dc9a1a65f21b69a8e38198a930ba0d4174c40b20aa', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"FORENSICS","authority_tier":0,"chunk_seq":228,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p58-229', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 58, 'General information regarding passwords is available from the Microsoft Knowledge Base article Information About Unlocking a Workstation (http://support.microsoft.com/kb/q281250/) and the article titled Password Information in Windows XP (http://www.kellys-korner-xp.com/win_xp_passwords.htm). 5-10', 'vec_doc-04-nist-sp-800-86-p58-229', 0, 76, 'v2.1.0', '88f488641d3588e6a2fa6cb3b3c0b767cf4b5e52fc4fb1d04c8bb064a8199a2b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":58,"domain":"FORENSICS","authority_tier":0,"chunk_seq":229,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p59-230', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Operating system time.', 59, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE saver passwords without rebooting the system.  These utilities generally rely on the CD drives autorun feature; the utility automatically runs in the background, then locates the encrypted password and attempts to decrypt it. ! Log Modification.  The user might try to reduce the usefulness of logs by disabling log features, modifying log settings so that there is little storage available for logs, or writing many spurious events to the logs.  One way of reducing the impact of logging changes is to configure systems to archive their log entries on a centralized server. ! Hard Drives with Flash Memory.  Occasionally, an analyst might come across a hard drive that also contains flash memory.  This flash memory could contain a password that is needed to access the drive, even when the drive has been removed from the computer.  Typically, the analyst must then find, guess, or crack the password to gain access to the drive. ! Key Remapping.  On some computers, individual keys or combinations of keystrokes can be remapped to perform a different function from their initial purpose.  For example, a person could map the Ctrl, Alt, and Del keys so that they wipe the computers hard drive instead of the expected action, rebooting the system.  An analyst who uses the keyboard of a computer of interest could enter keystrokes that cause unexpected actions to be performed.  The best way to avoid key remapping problems is by collecting data from the computer without using its keyboard.  For example, the analyst could attach a forensic workstation to a computer of interest using a crossover network cable and run scripts from the forensic workstation.', 'vec_doc-04-nist-sp-800-86-p59-230', 0, 432, 'v2.1.0', '2f63caeb75fb2e3283147cba070ade8acbdd257120e6241f3113bd7c00a9d37b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Operating system time.","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"FORENSICS","authority_tier":0,"chunk_seq":230,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Operating system time."}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p59-231', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.3 Examining and Analyzing OS Data', 59, 'Various tools and techniques can be used to support the examination process. Many of the tools and techniques discussed in Section 4.3 for examining collected data files can also be used with collected OS data. In addition, as described in Section 7, security applications, such as file integrity checkers and host IDSs, can be very helpful in identifying malicious activity against OSs. For instance, file integrity checkers can be used to compute the message digests of OS files and compare them against databases of known message digests to determine whether any files have been compromised. If intrusion detection software is installed on the computer, it might contain logs that indicate the actions performed against the OS. Another issue that analysts face is the examination of swap files and RAM dumps, which are large binary data files containing unstructured data.', 'vec_doc-04-nist-sp-800-86-p59-231', 0, 219, 'v2.1.0', '718f4b748f414f85126c960b7fd4359ef99faff3a47eb69d22386bd9fc77c699', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.3 Examining and Analyzing OS Data","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"FORENSICS","authority_tier":0,"chunk_seq":231,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.3 Examining and Analyzing OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p59-232', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.3 Examining and Analyzing OS Data', 59, 'Hex editors can be used to open these files and examine their contents; however, on large files, manually trying to locate intelligible data using a hex editor can be a time-consuming process. Filtering tools automate the process of examining swap and RAM dump files by identifying text patterns and numerical values that might represent phone numbers, names of people, e- mail addresses, Web addresses, and other types of critical information. Analysts often want to gather additional information about a particular program running on a system, such as the processs purpose and manufacturer. After obtaining a list of the processes currently running on a system, analysts can look up the process name to obtain such additional information. However, users might change the names of programs to conceal their functions, such as naming a Trojan program calculator.exe.', 'vec_doc-04-nist-sp-800-86-p59-232', 0, 217, 'v2.1.0', 'b5593a003606887a48b681962d00774a44697bba73615c4839563d3b5e6713b4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.3 Examining and Analyzing OS Data","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"FORENSICS","authority_tier":0,"chunk_seq":232,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.3 Examining and Analyzing OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p59-233', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.3 Examining and Analyzing OS Data', 59, 'Therefore, process name lookups should be performed only after verifying the identity of the processs files by computing and comparing their message digests. Similar lookups can be performed on library files, such as DLLs on Windows systems, to determine which libraries are loaded and what their typical purposes are. As described in Section 5.2, analysts may collect many different types of OS data, including multiple filesystems. Trying to sift through each type of data to find relevant information can be a time-intensive 5-11', 'vec_doc-04-nist-sp-800-86-p59-233', 0, 134, 'v2.1.0', '0aa2f438e7bda1c8ea49e90c98bb20be7c95714d99ddc200e6976c6c816ec999', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.3 Examining and Analyzing OS Data","subsection":"UNKNOWN","table_id":null,"page":59,"domain":"FORENSICS","authority_tier":0,"chunk_seq":233,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.3 Examining and Analyzing OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p60-234', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.3 Examining and Analyzing OS Data', 60, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE process.  Analysts generally find it useful to identify a few data sources to review initially, then find other likely sources of important information on the basis of that review.  In addition, in many cases, analysis can involve data from other types of sources, such as network traffic or applications.  Section 8 provides examples of how data from OSs and other sources can be correlated through analysis.', 'vec_doc-04-nist-sp-800-86-p60-234', 0, 119, 'v2.1.0', 'c8aba2c8363ec54d8f3f7c3c1bee04cfcd0cfedd1ba3bab63c5114a9dc127649', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.3 Examining and Analyzing OS Data","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"FORENSICS","authority_tier":0,"chunk_seq":234,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.3 Examining and Analyzing OS Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p60-235', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '5.4 Re commendations', 60, 'The key recommendations presented in this section for using data from OSs are as follows. ! Analysts should act appropriately to preserve volatile OS data.  The criteria for determining whether volatile OS data must be preserved should be documented in advance so that analysts can make informed decisions as quickly as possible.  To determine whether the effort required to collect volatile OS data is warranted, the risks associated with such collection should be weighed against the potential for recovering important information. ! Analysts should use a forensic toolkit for collecting volatile OS data.  Use of a forensic toolkit enables accurate OS data to be collected while minimizing the disturbance to the system and protecting the tools from changes.  The analyst should know how each tool is likely to affect or alter the system during collection of data. ! Analysts should choose the appropriate shutdown method for each system.  Each method of shutting down a particular OS can cause different types of data to be preserved or corrupted; analysts should be aware of the typical shutdown behavior of each OS. 5-12', 'vec_doc-04-nist-sp-800-86-p60-235', 0, 282, 'v2.1.0', 'a8fd85aba0347bafca1b6743039ae0772ab81426565a8b482a837fb94ebbf588', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"5.4 Re commendations","subsection":"UNKNOWN","table_id":null,"page":60,"domain":"FORENSICS","authority_tier":0,"chunk_seq":235,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"5.4 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p61-236', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6. Using Data From Network Traffic', 61, 'Analysts can use data from network traffic to reconstruct and analyze network-based attacks and inappropriate network usage, as well as to troubleshoot various types of operational problems.  The content of communications carried over networks, such as e-mail messages or audio, might also be collected in support of an investigation.  The term network traffic refers to computer network communications that are carried over wired or wireless networks between hosts.82  This section provides an introduction to network traffic, including descriptions of major sources of network traffic data (e.g., intrusion detection software, firewalls).  In addition, it discusses techniques for collecting data from these sources and points out the potential legal and technical issues in such data collection.  The remainder of the section focuses on the techniques and tools for examining and analyzing data from network traffic. The section begins with an overview of Transmission Control Protocol/Internet Protocol (TCP/IP)a basic knowledge of TCP/IP is necessary to understand the data, tools, and methodologies presented in this section.', 'vec_doc-04-nist-sp-800-86-p61-236', 0, 283, 'v2.1.0', '592d10609d5a08f69d4a8bb73d9c1498ee3cc2c1eca5e4971e130b84fc631199', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6. Using Data From Network Traffic","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"FORENSICS","authority_tier":0,"chunk_seq":236,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6. Using Data From Network Traffic"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p61-237', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 61, 'TCP/IP is widely used throughout the world to provide network communications. TCP/IP communications are composed of four layers that work together. When a user wants to transfer data across networks, the data is passed from the highest layer through intermediate layers to the lowest layer, with each layer adding additional information. The lowest layer sends the accumulated data through the physical network; the data is then passed up through the layers to its destination. Essentially, the data produced by a layer is encapsulated in a larger container by the layer below it. The four TCP/IP layers, from highest to lowest, are shown in Figure 6-1. Application Layer. This layer sends and receives data for particular applications, such as Domain Name System (DNS), Hypertext Transfer Protocol (HTTP), and Simple Mail Transfer Protocol (SMTP). Transport Layer. This layer provides connection-oriented or connectionless services for transporting application layer services between networks.', 'vec_doc-04-nist-sp-800-86-p61-237', 0, 249, 'v2.1.0', '7e715bf33f619f8b87ca51a60a5b4f70e8889515d338eac7e72cd61777dad7df', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"FORENSICS","authority_tier":0,"chunk_seq":237,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p61-238', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 61, 'The transport layer can optionally ensure the reliability of communications. Transmission Control Protocol (TCP) and User Datagram Protocol (UDP) are commonly used transport layer protocols. Internet Protocol Layer (also known as Network Layer). This layer routes packets across networks. IP is the fundamental network layer protocol for TCP/IP. Other commonly used protocols at the network layer are Internet Control Message Protocol (ICMP) and Internet Group Management Protocol (IGMP). Hardware Layer (also known as Data Link Layer). This layer handles communications on the physical network components. The best known data link layer protocol is Ethernet. Figure 6-1. TCP/IP Layers The four TCP/IP layers work together to transfer data between hosts. As shown in Figure 6-2, each layer encapsulates the previous layers.', 'vec_doc-04-nist-sp-800-86-p61-238', 0, 206, 'v2.1.0', '7ec698e4767d9516e213b882af2ea28afbee1243aca3c54cd37d1cef3cdb41cd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"FORENSICS","authority_tier":0,"chunk_seq":238,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p61-239', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 61, 'Sections 6.1.1 through 6.1.4 describe these layers in greater detail and 82  Because nearly all network traffic of interest to organizations uses the TCP/IP protocol suite, this section addresses only TCP/IP-based communications. However, most of the principles discussed in this section can be applied to other types of network traffic as well. 6-1', 'vec_doc-04-nist-sp-800-86-p61-239', 0, 88, 'v2.1.0', '3e3a00a7a7c155ed52bcd5287405a7f19b6b16262564f46f5e92a66e36f0e451', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":61,"domain":"FORENSICS","authority_tier":0,"chunk_seq":239,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p62-240', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 62, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE indicate the characteristics that are most pertinent to network forensics. Section 6.1.5 explains how the layers relate to each other. Figure 6-2. TCP/IP Encapsulation 6.1.1 6.1.2 Application Layer The application layer enables applications to transfer data between an application server and client. An example of an application layer protocol is Hypertext Transfer Protocol (HTTP), which transfers data between a Web server and a Web browser. Other common application layer protocols include Domain Name System (DNS), File Transfer Protocol (FTP), Simple Mail Transfer Protocol (SMTP), and Simple Network Management Protocol (SNMP). There are hundreds of unique application layer protocols in common use, and many more that are not so common.83  Regardless of the protocol in use, application data is generated and then passed to the transport layer for further processing.', 'vec_doc-04-nist-sp-800-86-p62-240', 0, 235, 'v2.1.0', '20445d8266f4744bfc2293099c7e6c0b22ecce4e1a31d800a92b283d855e362c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"FORENSICS","authority_tier":0,"chunk_seq":240,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p62-241', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 62, 'Section 7 focuses on application-related data collection, examination, and analysis. Transport Layer The transport layer is responsible for packaging data so that it can be transmitted between hosts. After the transport layer has encapsulated application data, the resulting logical units are referred to as packets. (A packet can also be created without application datafor example, when a connection is first negotiated.) Each packet contains a header, which is composed of various fields that specify characteristics of the transport protocol in use; optionally, packets may also contain a payload, which holds the application data. Most applications that communicate over networks rely on the transport layer to ensure reliable delivery of data. Generally, this is accomplished by using the TCP transport layer protocol, which establishes a connection between two hosts and then makes a best effort to ensure the reliable transfer of data over that connection.', 'vec_doc-04-nist-sp-800-86-p62-241', 0, 242, 'v2.1.0', 'd6c21485c3de2a619b7019b073d3f157ecc3adae840ab759f51fde5c7b6ae9c6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"FORENSICS","authority_tier":0,"chunk_seq":241,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p62-242', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 62, 'Each TCP packet includes a source port and a destination port. One of the ports is associated with a server application on one system; the other port is associated with a corresponding client application on the other system. Client systems typically select any available port number for application use, whereas server systems normally have a static port number dedicated to each application. Although many server ports are usually used by particular applications (e.g., FTP servers at port 21, HTTP servers 83  For this reason, a detailed discussion of individual application layer protocols is beyond the scope of this document. 6-2', 'vec_doc-04-nist-sp-800-86-p62-242', 0, 159, 'v2.1.0', 'bd218556063d38e385a4aa5c2eaf2a35447cc34d3d513a3cefa447deaea2f2b4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":62,"domain":"FORENSICS","authority_tier":0,"chunk_seq":242,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p63-243', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 63, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE at port 80), many server applications can be run from any port number, so it is unwise to assume that network traffic contains data from a certain application solely on the basis of server port number. When loss of some application data is not a concern (e.g., streaming audio, video), the User Datagram Protocol (UDP) is typically used. UDP involves less overhead and latency than TCP because UDP is connectionless; one host simply sends data to another host without any preliminary negotiations. UDP is also used for applications that are willing to take responsibility for ensuring reliable delivery of data, such as DNS, and applications that are intended for use only on local area networks, such as Dynamic Host Configuration Protocol (DHCP) and SNMP. As is the case with TCP, each UDP packet contains a source port and a destination port.', 'vec_doc-04-nist-sp-800-86-p63-243', 0, 228, 'v2.1.0', '5edce9a3479ae5b4a4162b6909dfb47624a9a9459016c71fc66b669309a3f30b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"FORENSICS","authority_tier":0,"chunk_seq":243,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p63-244', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 63, 'Although UDP and TCP ports are very similar, they are distinct from each other and are not interchangeable. Some applications (such as DNS) can use both TCP and UDP ports; although such applications typically use the same number for the TCP port and the UDP port, this is not required. 6.1.3 IP Layer The IP layer can also be called the network layer, because it is responsible for handling the addressing and routing of data that it receives from the transport layer. The IP header contains a field called IP Version, which indicates which version of IP is in use. Typically this is set to 4 for IPv4; but the use of IPv6 is increasing, so this field may be set to 6 instead.84  Other significant IP header fields are as follows: ! Source and Destination IP Addresses. These are the from and to addresses that are intended to indicate the endpoints of the communication.85  Examples of IP addresses are 10.3.1.70 (IPv4) and 1000:0:0:2F:8A:400:0427:9BD1 (IPv6). ! IP Protocol Number.', 'vec_doc-04-nist-sp-800-86-p63-244', 0, 247, 'v2.1.0', '2ee9fe6070de649bf7b7a547d94481ed92b22491792b6101d5225565edf44656', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"FORENSICS","authority_tier":0,"chunk_seq":244,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p63-245', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 63, 'This indicates which transport layer protocol the IP payload contains.86 Commonly used IP numbers include 1 (Internet Control Message Protocol [ICMP]), 6 (TCP), 17 (UDP), and 50 (Encapsulating Security Payload [ESP]). The IP layer is also responsible for providing error and status information involving the addressing and routing of data; it does this with ICMP. ICMP is a connectionless protocol that makes no attempt to guarantee that its error and status messages are delivered. Because it is designed to transfer limited information, not application data, ICMP does not have ports; instead, it has message types, which indicate the purpose of each ICMP message.87  Some message types also have message codes, which can be thought of as subtypes. For example, the ICMP message type Destination Unreachable has several possible message codes that indicate what is unreachable (e.g., network, host, protocol).', 'vec_doc-04-nist-sp-800-86-p63-245', 0, 228, 'v2.1.0', '17f50e357ba837e8b4b5d2f5ee4973b59acb953292cfcd2c10db4cc699b5cf78', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"FORENSICS","authority_tier":0,"chunk_seq":245,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p63-246', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 63, 'Most ICMP messages are not intended to elicit a response.88 IP addresses are often used through a layer of indirection. When people need to access a resource on a network, such as a Web server or e-mail server, they typically enter the servers name, such as www.nist.gov, rather than the servers IP address. The name, also known as a domain name, is mapped 84  There are other possible IP version numbers as well, although none are commonly used. The official list of valid IP Version field values is available at http://www.iana.org/assignments/version-numbers. This document assumes the use of IPv4, but the techniques described can easily be adapted for use with IPv6 (assuming that comparable tools are available that support IPv6). 85  IP addresses are often inaccurate or misleading for identifying the actual endpoints of communication. Section 6.3 discusses this topic in more detail.', 'vec_doc-04-nist-sp-800-86-p63-246', 0, 224, 'v2.1.0', '61d8f203cf3136081c77f936291ec48c06612ebc7331642e3a6bf35b28821cb3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"FORENSICS","authority_tier":0,"chunk_seq":246,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p63-247', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 63, '86  The official list of valid IP Protocol Number values is available at http://www.iana.org/assignments/protocol-numbers. 87  The current list of valid ICMP types is available at http://www.iana.org/assignments/icmp-parameters. 88  ICMP is designed to limit responses, particularly to error messages. If ICMP had not been designed in this way, message loops could occur. For example, if Host A received an ICMP error message from Host B and responded with an error message, and Host B responded to that error message with an error message, the two hosts could continue sending error messages regarding the error messages. 6-3', 'vec_doc-04-nist-sp-800-86-p63-247', 0, 157, 'v2.1.0', '884883afe571a504583a32884b56c0fffd144adeee8a0b68b139c8ad886970ca', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":63,"domain":"FORENSICS","authority_tier":0,"chunk_seq":247,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p64-248', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 64, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE to the IP address through the DNS application layer protocol. The primary reason for entering a domain name instead of an IP address is that the former is generally easier for people to remember. In addition, where a domain name is likely to remain the same, a hosts IP address can change over time; by referencing a host by domain name, which is then mapped to the hosts IP address, users can reach the host no matter what IP address the host is currently using. 6.1.4 6.1.5 Hardware Layer As the name implies, the hardware layer involves the physical components of the network, including cables, routers, switches, and NIC. The hardware layer also includes various hardware layer protocols; Ethernet is the most widely used of these protocols.', 'vec_doc-04-nist-sp-800-86-p64-248', 0, 203, 'v2.1.0', 'f534ee5a45fece62c97c92858401ccc7b36e6cf33dc6fe213a85480c94ab2b47', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"FORENSICS","authority_tier":0,"chunk_seq":248,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p64-249', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 64, 'Ethernet relies on the concept of a MAC address, which is a unique 6-byte value (such as 00-02-B4-DA-92-2C) that is permanently assigned to a particular NIC.89  Each frame contains two MAC addresses, which indicate the MAC address of the NIC that just routed the frame and the MAC address of the next NIC to which the frame is being sent. As a frame passes through networking equipment (such as routers and firewalls) on its way between the original source host and the final destination host, the MAC addresses are updated to refer to the local source and destination. Several separate hardware layer transmissions may be linked together within a single IP layer transmission. In addition to the MAC addresses, each frame also contains an EtherType value, which indicates the protocol that the frames payload contains (typically IP or Address Resolution Protocol [ARP]).90  When IP is used, each IP address maps to a particular MAC address.', 'vec_doc-04-nist-sp-800-86-p64-249', 0, 236, 'v2.1.0', 'dbff0666ea60ad5ec6f9509f633a37ba2899866938ce636c6953fc583a127389', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"FORENSICS","authority_tier":0,"chunk_seq":249,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p64-250', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 64, '(Because multiple IP addresses can map to a single MAC address, a MAC address does not necessarily uniquely identify an IP address.) Layers Significance in Network Forensics Each of the four layers of the TCP/IP protocol suite contains important information. The hardware layer provides information about physical components, while other layers describe logical aspects. For events within a network, an analyst can map an IP address (logical identifier at the IP layer) to the MAC address of a particular NIC (physical identifier at the physical layer), thereby identifying a host of interest. The combination of the IP protocol number (IP layer field) and port numbers (transport layer fields) can tell an analyst which application was most likely being used or targeted. This can be verified by examining the application layer data. Network forensic analysis relies on all of the layers.', 'vec_doc-04-nist-sp-800-86-p64-250', 0, 223, 'v2.1.0', '9bed7d0ef29bee713c947ce89dcec055296195276489a304b405fd6d37a57bea', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"FORENSICS","authority_tier":0,"chunk_seq":250,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p64-251', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 64, 'When analysts begin to examine data, they typically have limited informationmost likely an IP address of interest and perhaps protocol and port information. Nevertheless, this is enough information to support searching common data sources for more information. In most cases, the application layer contains the actual activity of interestmost attacks are against vulnerabilities in applications (including services), and nearly all misuse involves misuse of applications. Analysts need IP addresses so that they can identify the hosts that may have been involved in the activity. The hosts may also contain additional data that would be of use in analyzing the activity. Although some events of interest may not have relevant application-level data (e.g., a distributed denial of service attack designed to consume all network bandwidth), most do; network forensics provides important support to the analysis of application-layer activities.', 'vec_doc-04-nist-sp-800-86-p64-251', 0, 236, 'v2.1.0', '3c2adb565d5838577d45727f728e57118c32eb1316b4d13de20992a194293487', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"FORENSICS","authority_tier":0,"chunk_seq":251,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p64-252', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.1 T CP/IP Basics', 64, '89  The first 3 bytes of each MAC address indicate the vendor of the NIC; a list of mappings is available at http://standards.ieee.org/regauth/oui/oui.txt. However, various software utilities are publicly available that allow people to configure systems to spoof other MAC addresses. There have also been cases in which manufacturers accidentally created NICs with duplicate MAC addresses. 90  EtherType value 0x0800 is IP, while 0x0806 is ARP. See http://www.iana.org/assignments/ethernet-numbers for more information on EtherType values. 6-4', 'vec_doc-04-nist-sp-800-86-p64-252', 0, 136, 'v2.1.0', 'c9420e710a64a2791d9d3b3d2105eee787241756a364b2149d9e7217bc7e9e18', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.1 T CP/IP Basics","subsection":"UNKNOWN","table_id":null,"page":64,"domain":"FORENSICS","authority_tier":0,"chunk_seq":252,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.1 T CP/IP Basics"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p65-253', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 65, 'Organizations typically have several types of information sources concerning network traffic that might be useful for network forensics. These sources collectively capture important data from all four TCP/IP layers. The following subsections highlight the major categories of network traffic data sources firewalls and routers, packet sniffers and protocol analyzers, IDSs, remote access, security event management software, and network forensic analysis toolsas well as several other types of data sources. The subsections explain the purpose of each source described and the type of data that is typically collected and can potentially be collected. 6.2.1 6.2.2 Firewalls and Routers Network-based devices such as firewalls and routers, and host-based devices such as personal firewalls, examine network traffic and permit or deny it based on a set of rules.', 'vec_doc-04-nist-sp-800-86-p65-253', 0, 216, 'v2.1.0', '59ea53fd063ae1b65e96f0d5c6be9a27290beddfcf4669a1af14d9d04bbda005', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"FORENSICS","authority_tier":0,"chunk_seq":253,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p65-254', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 65, 'Firewalls and routers are usually configured to log basic information for most or all denied connection attempts and connectionless packets; some log every packet.91  Information logged typically includes the date and time the packet was processed, the source and destination IP addresses, the transport layer protocol (e.g., TCP, UDP, ICMP), and basic protocol information (e.g., TCP or UDP port numbers, ICMP type and code). The content of packets is usually not recorded. Network-based firewalls and routers that perform network address translation (NAT) may contain additional valuable data regarding network traffic. NAT is the process of mapping addresses on one network to addresses on another network; this is most often accomplished by mapping private addresses92 from an internal network to one or more public addresses on a network that is connected to the Internet.', 'vec_doc-04-nist-sp-800-86-p65-254', 0, 220, 'v2.1.0', '7d4ff1ed6f871f537304b747b390b02c879dd60a019a012ecf7832d76534ac04', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"FORENSICS","authority_tier":0,"chunk_seq":254,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p65-255', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 65, 'NAT differentiates multiple internal addresses that are mapped to a single external address by assigning a different source port number to the external address for each internal address. The NAT device typically records each NAT address and port mapping. Some firewalls also act as proxies. A proxy receives a request from a client, and then sends a request on the clients behalf to the desired destination. When a proxy is used, each successful connection attempt actually results in the creation of two separate connections: one between the client and the proxy server, and another between the proxy server and the true destination. Proxy servers may log basic information about each connection. Many proxies are application-specific, and some actually perform some analysis and validation of application protocols, such as HTTP.', 'vec_doc-04-nist-sp-800-86-p65-255', 0, 208, 'v2.1.0', 'b67aa574f6e977ca813c74bd26e45fabbcab176d26486139f9cc2affe1e21cf5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"FORENSICS","authority_tier":0,"chunk_seq":255,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p65-256', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 65, 'The proxy may reject client requests that appear to be invalid and log information regarding these requests.93 In addition to providing NAT and proxying services, firewalls and routers may perform such other functions as intrusion detection and VPN. The intrusion detection and VPN functions are discussed in more detail in Sections 6.2.3 and 6.2.4, respectively. Packet Sniffers and Protocol Analyzers Packet sniffers are designed to monitor network traffic on wired or wireless networks and capture packets. Normally, a NIC accepts only the incoming packets that are specifically intended for it. But when a NIC 91  Although logging all packets records more information about recent network activity than does logging information for connections and connection attempts, space limitations might permit packets to be kept for a short time only. In addition, the overhead required to record all packets might cause the systems performance to degrade.', 'vec_doc-04-nist-sp-800-86-p65-256', 0, 238, 'v2.1.0', '508fb7d91d4e782f9566bd24044e0604a062b9c27c809fc7142f3df3315f5f8d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"FORENSICS","authority_tier":0,"chunk_seq":256,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p65-257', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 65, '92  The proper name for private addresses is RFC 1918 addresses. RFC 1918, Address Allocation for Private Internets, is available at http://www.ietf.org/rfc/rfc1918.txt. 93  Some organizations configure their networks and network security so that all network traffic passing through the network perimeter for common applications is proxied, preventing individual users from bypassing the proxies. In such an environment, the proxy server logs can be particularly valuable for network forensics. 6-5', 'vec_doc-04-nist-sp-800-86-p65-257', 0, 125, 'v2.1.0', 'f5f0cf8a371609330c4fc36b7f0cc7f1279e47e5b57ce8c4bfa8ef54885ba520', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":65,"domain":"FORENSICS","authority_tier":0,"chunk_seq":257,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p66-258', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 66, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE is placed in promiscuous mode, it accepts all incoming packets that it sees, regardless of their intended destinations. Packet sniffers generally work by placing the NIC in promiscuous mode; the user then configures the sniffer to capture all packets or only those with particular characteristics (e.g., certain TCP ports, certain source or destination IP addresses). Packet sniffers are commonly used to capture a particular type of traffic for troubleshooting or investigative purposes. For example, if IDS alerts indicate unusual network activity between two hosts, a packet sniffer could record all of the packets traveling between the hosts, potentially providing additional information for analysts.', 'vec_doc-04-nist-sp-800-86-p66-258', 0, 193, 'v2.1.0', '38b6095122882ed0e372639ce00ba565613591a9e5d1b3188248311d34ba722d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"FORENSICS","authority_tier":0,"chunk_seq":258,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p66-259', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 66, 'Most packet sniffers are also protocol analyzers, which means that they can reassemble streams from individual packets and decode communications that use any of hundreds or thousands of different protocols.94  Protocol analyzers usually can process not only live network traffic but also packets that have been recorded previously in capture files by packet sniffers. Protocol analyzers are extremely valuable in displaying raw packet data in an understandable format. Protocol analyzers are discussed in more depth in Section 6.4 and Section 7.', 'vec_doc-04-nist-sp-800-86-p66-259', 0, 137, 'v2.1.0', '1201ac422213c06283751029951211fd78c37e60a612552e4a4d2a54f2085d64', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"FORENSICS","authority_tier":0,"chunk_seq":259,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p66-260', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 66, '6.2.3 Intrusion Detection Systems Network IDSs perform packet sniffing and analyze network traffic to identify suspicious activity and record relevant information.95  Host IDSs monitor characteristics of a particular system and events occurring within the system, which can include network traffic.96  Unlike network IDS sensors, which can monitor all network traffic on a particular network segment, host IDS software is intended to monitor network traffic only for the host on which it is installed.97  For each suspicious event, IDS software typically records the same basic event characteristics that firewalls and routers record (e.g., date and time, source and destination IP addresses, protocol, basic protocol characteristics), as well as application- specific information (e.g., username, filename, command, status code). IDS software also records information that indicates the possible intent of the activity.', 'vec_doc-04-nist-sp-800-86-p66-260', 0, 230, 'v2.1.0', 'c84f20105d0a5a8e46c135fd0b13c8cef43c1a51442c2b7e1430ba30167e9535', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"FORENSICS","authority_tier":0,"chunk_seq":260,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p66-261', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 66, 'Examples include the type of attack (e.g., buffer overflow), the targeted vulnerability, the apparent success or failure of the attack, and pointers to more information about the attack.98 Some IDSs can be configured to capture packets related to suspicious activity. This can range from recording only the packet that triggered the IDS to label the activity suspicious, to recording the rest of the session. Some IDSs even have the ability to store all sessions for a short period of time so that if something suspicious is detected, the previous activity in the same session can be preserved. The packets 94  Examples of open source packet sniffer and protocol analyzer software for wired networks include Ethereal (http://www.ethereal.com/), TCPDump (http://www.tcpdump.org/), and WinDump (http://www.winpcap.org/windump/). Open source software is also available for wireless networks, including Ethereal and Kismet (http://www.kismetwireless.net/).', 'vec_doc-04-nist-sp-800-86-p66-261', 0, 238, 'v2.1.0', '488e7690e51da0f6f77eb9937bc3607cb5b30d9872c7adc670c8664addaecbe6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"FORENSICS","authority_tier":0,"chunk_seq":261,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p66-262', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 66, 'Additional packet sniffer and protocol analyzer software products are listed on various Web sites, including the Talisker Security Wizardry Portal (http://www.networkintrusion.co.uk/protanalyzers.htm), Softpedia (http://www.softpedia.com/get/Network-Tools/Protocol-Analyzers-Sniffers/), Packet Storm (http://packetstormsecurity.org/defense/sniff/), and other Web sites listed in Appendix F. 95  Some network IDSs allow administrators to identify misuse as well as attacks. For example, an administrator (with proper approval) could configure the IDS with character strings of interest, such as an acronym or phrase associated with a sensitive project. The IDS could then search network traffic for file transfers, e-mails, and other forms of communication that used one of those character strings. 96  Examples of open source network IDS products include Bro (http://www.bro-ids.org/) and Snort (http://www.snort.org/).', 'vec_doc-04-nist-sp-800-86-p66-262', 0, 230, 'v2.1.0', 'fbe5bc9c8475c673dd4242a60c8e49218e233dd94d46c9490889cd1ee8f27757', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"FORENSICS","authority_tier":0,"chunk_seq":262,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p66-263', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 66, 'For more information about network and host IDS products, see the Talisker Security Wizardry Portal (http://www.networkintrusion.co.uk/ids.htm), Honeypots.net (http://www.honeypots.net/ids/products/), the Common Vulnerabilities and Exposures Web site (http://www.cve.mitre.org/compatible/product.html), and other Web sites listed in Appendix F. 97  See NIST SP 800-31, Intrusion Detection Systems, for more information on network and host IDS. It is available at http://csrc.nist.gov/publications/nistpubs/index.html. 98  Many IDS vendors provide help files that contain detailed information about each type of activity. IDS vendors also typically provide pointers to external sources of information, such as CERT®/CC advisories, Common Vulnerabilities and Exposures (CVE) numbers, and software vendor vulnerability announcements. 6-6', 'vec_doc-04-nist-sp-800-86-p66-263', 0, 209, 'v2.1.0', '39eeaac38787781b489d1d42e21959473474eff25ebd222c9110e7091ade9d32', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":66,"domain":"FORENSICS","authority_tier":0,"chunk_seq":263,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p67-264', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 67, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE are captured primarily so that intrusion detection analysts can review them when validating IDS alerts and investigating suspicious activity. Some IDSs also have intrusion prevention capabilities, which means that they actively attempt to stop attacks in progress. Any use of intrusion prevention features should be indicated in the IDS logs. 6.2.4 6.2.5 Remote Access Remote access servers are devices such as VPN gateways and modem servers that facilitate connections between networks. This often involves external systems connecting to internal systems through the remote access server but could also include internal systems connecting to external or internal systems. Remote access servers typically record the origin of each connection and might also indicate which user account was authenticated for each session. If the remote access server assigns an IP address to the remote user, this is also likely to be logged.', 'vec_doc-04-nist-sp-800-86-p67-264', 0, 247, 'v2.1.0', '7fb9c3680bc81fc101e2ae4fef9dd5cc2ae94b478399e7ed89ad267eaf2f3296', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"FORENSICS","authority_tier":0,"chunk_seq":264,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p67-265', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 67, 'Some remote access servers also provide packet filtering functions, which typically perform logging similar to that provided by firewalls and routers, as described in Section 6.2.1. Remote access servers typically work at a network level, supporting the use of many different applications. Because the servers have no understanding of the applications functions, they usually do not record any application-specific data. In addition to remote access servers, organizations typically use multiple applications that are specifically designed to provide remote access to a particular hosts OS. Examples include secure shell (SSH), telnet, terminal servers,99 and remote control software. Such applications can typically be configured to log basic information for each connection, including source IP address and user account. Organizations also typically use many applications that are accessed remotely, such as client/server applications.', 'vec_doc-04-nist-sp-800-86-p67-265', 0, 235, 'v2.1.0', 'a79bec9cdf883febd1f1f00a66ffbccaab216b944f4313a6b42bf635ac9e6a10', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"FORENSICS","authority_tier":0,"chunk_seq":265,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p67-266', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 67, 'Some of these applications also log basic information for connections. Although most remote accessrelated logging occurs on the remote access server or the application server, in some cases the client also logs information related to the connection. Security Event Management Software Security event management (SEM)100 software is capable of importing security event information from various network trafficrelated security event data sources (e.g., IDS logs, firewall logs) and correlating events among the sources.101  It generally works by receiving copies of logs from various data sources over secure channels, normalizing the logs into a standard format, then identifying related events by matching IP addresses, timestamps, and other characteristics. SEM products usually do not generate original event data; instead, they generate meta-events based on imported event data.', 'vec_doc-04-nist-sp-800-86-p67-266', 0, 221, 'v2.1.0', 'ead13ac2b6d983ccbbbc3780cdb4b29d3da70de9bc976316b90fa184ba805f0e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"FORENSICS","authority_tier":0,"chunk_seq":266,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p67-267', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 67, 'Many SEM products not only can identify malicious activity, such as attacks and virus infections, but also can detect misuse and inappropriate usage of systems and networks. SEM software can be helpful in making many sources of network traffic information accessible through a single interface. Because SEM products can handle nearly any security event data source, such as OS logs, antivirus software alerts, and physical security device logs, SEM products may contain a wide variety of information regarding events. However, it is typical for only some data fields to be brought over. For example, if an IDS records packets, the packets may not be transferred to the SEM because of bandwidth and storage limitations.', 'vec_doc-04-nist-sp-800-86-p67-267', 0, 180, 'v2.1.0', '3861e88315e15f875ed4a565873a2077ea65f44aa8b69217302b7710e50fcb7a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"FORENSICS","authority_tier":0,"chunk_seq":267,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p67-268', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 67, 'In addition, because most data sources record information in different formats, SEM products typically normalize the dataconverting each data field to a standard format and labeling 99  In this context, terminal server refers to products such as Microsoft Windows Terminal Services and Citrix Metaframe that provide graphical remote access to operating systems and applications. 100  SEM software is listed on several Web sites listed in Appendix F, including the Common Vulnerabilities and Exposures (CVE) Web site (http://www.cve.mitre.org/compatible/product.html). 101  Another common term for security event management is security information management (SIM). 6-7', 'vec_doc-04-nist-sp-800-86-p67-268', 0, 168, 'v2.1.0', '5d89c3a1802f31acd3e2356b1f553712fca02145f8b3301479894560290dc1cc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":67,"domain":"FORENSICS","authority_tier":0,"chunk_seq":268,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p68-269', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 68, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the data consistently. Although this is beneficial for analysis (as described in Section 6.4), the normalization process occasionally introduces errors in the data or causes some data to be lost. Fortunately, SEM products typically do not alter the original data sources, so analysts should retain copies of the original logs and use them to verify the accuracy of the data if needed. 6.2.6 6.2.7 Network Forensic Analysis Tools Network forensic analysis tools (NFAT)102 typically provide the same functionality as packet sniffers, protocol analyzers, and SEM software in a single product. Whereas SEM software concentrates on correlating events among existing data sources (which typically include multiple network trafficrelated sources), NFAT software focuses primarily on collecting, examining, and analyzing network traffic.', 'vec_doc-04-nist-sp-800-86-p68-269', 0, 224, 'v2.1.0', '43b57bbcd6aa462dc041824f39d0e4ca0a3d90e76e7b92814e15e7ecb9b9faf7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"FORENSICS","authority_tier":0,"chunk_seq":269,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p68-270', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 68, 'NFAT software also offers additional features that further facilitate network forensics, such as the following: ! Reconstructing events by replaying network traffic within the tool, ranging from an individual session (e.g., instant messaging [IM] between two users) to all sessions during a particular time period. The speed of the replaying can typically be adjusted as needed. ! Visualizing the traffic flows and the relationships among hosts. Some tools can even tie IP addresses, domain names, or other data to physical locations and produce a geographic map of the activity. ! Building profiles of typical activity and identifying significant deviations. ! Searching application content for keywords (e.g., confidential, proprietary). Other Sources Most organizations have other sources of network traffic information that can be of use for forensics in some capacity, including the following: ! Dynamic Host Configuration Protocol Servers.', 'vec_doc-04-nist-sp-800-86-p68-270', 0, 238, 'v2.1.0', '8d2588208367131fa57adaf03a1266458f0c11fd33c33612b904e1af9e36c566', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"FORENSICS","authority_tier":0,"chunk_seq":270,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p68-271', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 68, 'The DHCP service assigns IP addresses to hosts on a network as needed. Some hosts might have static IP addresses, which means that they always receive the same IP address assignment; however, most hosts typically receive dynamic assignments. This means that the hosts are required to renew their IP address assignments regularly and that there is no guarantee that they will be assigned the same addresses. DHCP servers may contain assignment logs that include the MAC address, the IP address assigned to that MAC address, and the time the assignment occurred. ! Network Monitoring Software. Network monitoring software is designed to observe network traffic and gather statistics about it.103  For example, it may record high-level information about traffic flows for a particular network segment, such as the amount of bandwidth typically consumed by various protocols.', 'vec_doc-04-nist-sp-800-86-p68-271', 0, 218, 'v2.1.0', '1048033464b3e42b52b50352ecb1de5da19cd70f391ad94ff78e4da7df2a02e4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"FORENSICS","authority_tier":0,"chunk_seq":271,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p68-272', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 68, 'Network monitoring software may also collect more detailed information about network activity, such as the payload size and the source and destination IP addresses and ports for each packet. Some managed switches and other network devices offer basic network monitoring capabilities, such as collecting statistics concerning bandwidth usage. 102  Listings of NFAT software are available from Web sites listed in Appendix F, such as the Talisker Security Wizardry Portal (http://www.networkintrusion.co.uk/fornettools.htm). 103  Open source network monitoring software includes EtherApe (http://etherape.sourceforge.net/) and IPaudit (http://ipaudit.sourceforge.net/). Packet sniffers, protocol analyzers, and IDS software may also perform basic network monitoring functions. See the Web sites listed in Appendix F for additional product names. 6-8', 'vec_doc-04-nist-sp-800-86-p68-272', 0, 212, 'v2.1.0', '1be9405edccb013757018c9b7083338d13b4df1c2549b202ca7c63652a574f55', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":68,"domain":"FORENSICS","authority_tier":0,"chunk_seq":272,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p69-273', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.2 Network Traffic Data Sources', 69, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Internet Service Provider Records.  ISPs may collect network traffic-related data as part of their normal operations and when investigating unusual activity, such as extremely high volumes of traffic or an apparent attack.  Usual ISP records often might be kept only for days or hours.', 'vec_doc-04-nist-sp-800-86-p69-273', 0, 88, 'v2.1.0', '3039f651aed142e1f919f71bd4438538eae78386f19addc3b2fb82fe6d630d24', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.2 Network Traffic Data Sources","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"FORENSICS","authority_tier":0,"chunk_seq":273,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.2 Network Traffic Data Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p69-274', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', 'Section 6.3.1 discusses legal considerations involved in collecting network traffic data from ISPs', 69, 'and other third parties. ! Client/Server Applications.  Some client/server applications used over networks may record information regarding successful and failed usage attempts, which could include connection- related data such as the clients IP address and port.  The data fields recorded (if any) vary widely among applications. ! Hosts Network Configurations and Connections.  Sections 5.1.2 and 5.2.1 describe the types of network information that can be collected from individual hosts, including the TCP and UDP ports at which a host is listening.', 'vec_doc-04-nist-sp-800-86-p69-274', 0, 139, 'v2.1.0', '3aed82d266690f633ce4fe34836131ddb60ceb6fb5059107f333e9c39ba3c398', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"Section 6.3.1 discusses legal considerations involved in collecting network traffic data from ISPs","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"FORENSICS","authority_tier":0,"chunk_seq":274,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"Section 6.3.1 discusses legal considerations involved in collecting network traffic data from ISPs"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p69-275', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 69, 'As described in Section 6.2, organizations typically have network traffic data recorded in many places during normal operations. Organizations also use the same data recording mechanisms to collect additional data on an as-needed basis when investigating incidents or troubleshooting problems. For example, a network administrator or incident handler might deploy a packet sniffer to examine unusual packets sent by a host. Network traffic data is usually recorded to a log or stored in a packet capture file. In most cases, collecting the data is as simple as collecting the logs and packet capture files. Section 4 describes how to collect files in an appropriate manner for evidentiary purposes. If data is not stored in a file (e.g., traffic flow map displayed graphically, data displayed on the console screen only), screen captures or photographs of the screen might be needed.', 'vec_doc-04-nist-sp-800-86-p69-275', 0, 221, 'v2.1.0', '78ce4e7b26015b0dda1be64b596805e0e1dc594e20e5029298c1cdf211f77668', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"FORENSICS","authority_tier":0,"chunk_seq":275,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p69-276', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 69, 'Although collecting network traffic data is typically straightforward, there are several important legal and technical issues that can make data collection more complicated. 6.3.1 Legal Considerations Collecting network traffic can pose legal issues. Among these issues is the capture (intentional or incidental) of information with privacy or security implications, such as passwords or the contents of e- mails. This could expose the information to the staff members who are analyzing the collected data or administering the recording systems (e.g., IDS sensors). Organizations should have policies in place regarding the handling of inadvertent disclosures of sensitive information. Another problem with capturing data such as e-mails and text documents is that long-term storage of such information might violate an organizations data retention policy.', 'vec_doc-04-nist-sp-800-86-p69-276', 0, 215, 'v2.1.0', '7204b0ac10b75160c6a705c47cccfb6aaf566787480a24fe0629dbef69a91f35', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"FORENSICS","authority_tier":0,"chunk_seq":276,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p69-277', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 69, 'It is also important to have policies regarding the monitoring of networks and to have warning banners on systems that indicate that activity may be monitored. Although most network traffic data collection occurs as part of regular operations, it can also occur as part of troubleshooting or incident handling. In the latter case, it is important to follow consistent processes and to document all actions performed. For example, recording all packets sent and received by a particular user should be initiated only after the successful completion of a formal request and approval process. Organizations should have policies that clearly explain what types of monitoring can and cannot be performed without approval, and that describe or reference the procedures that detail the request and approval process. 6-9', 'vec_doc-04-nist-sp-800-86-p69-277', 0, 203, 'v2.1.0', 'ccaeb7518f9700f4aa22a6b27144665ca5fbbc87aec3be324fffcfb3b553fe03', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":69,"domain":"FORENSICS","authority_tier":0,"chunk_seq":277,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p70-278', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 70, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Another potential legal issue is the preservation of original logs. As described in Section 6.4, many organizations send copies of network traffic logs to centralized devices, as well as use tools that interpret and analyze network traffic. In cases where logs may be needed as evidence, organizations may wish to collect copies of the original log files, the centralized log files, and interpreted log data, in case there are any questions regarding the fidelity of the copying and interpretation processes. Section 6.4 contains more information on this. As privacy has become a greater concern to organizations, many have become less willing to share information with each other, including network forensic data. For example, most ISPs now require a court order before providing any information related to suspicious network activity that might have passed through their infrastructure.', 'vec_doc-04-nist-sp-800-86-p70-278', 0, 238, 'v2.1.0', 'ef7bd35d6a8e6d3439d5a4935223347af1cf7f450db79955e69c0c0b7070c691', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"FORENSICS","authority_tier":0,"chunk_seq":278,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p70-279', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 70, 'Although this preserves privacy and reduces the burden on and liability of the ISPs, it also slows down the investigative process. This is particularly challenging when an organization is attempting to trace an ongoing network-based attack to its source, especially if the traffic passes through several ISPs. 6.3.2 Technical Issues Several technical issues might impede the collection of data about network traffic. This section describes several of the major issues and provides guidance on what, if anything, can be done to mitigate each. ! Data Storage. When there is a large volume of network activity, particularly during adverse events such as attacks, logs may record many events in a short time. If insufficient storage is available, information about recent activity may be overwritten and lost.', 'vec_doc-04-nist-sp-800-86-p70-279', 0, 202, 'v2.1.0', 'c5e8915a423b6f586b50331ea21d945b11d760a0401f6cd3fb583d892e8bac5a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"FORENSICS","authority_tier":0,"chunk_seq":279,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p70-280', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 70, 'Organizations should estimate typical and peak log usage, determine how many hours or days worth of data should be retained, and ensure that systems and applications have sufficient storage available to meet those goals.104 ! Encrypted Traffic. When protocols such as IP Security (IPsec), SSH, and Secure Sockets Layer (SSL) are used to encrypt network traffic, devices monitoring network traffic along the encrypted path can see only the most basic characteristics of the traffic, such as source and destination IP addresses. If VPNs or other tunneling techniques are being used, the IP addresses might be for the tunnel itself and not the true source and destination of the activity. To collect data about the decrypted traffic, a data source must be positioned where it can see the decrypted activity. For example, placing an IDS sensor immediately behind a VPN gateway can be effective at identifying anomalous activity in the decrypted communications.', 'vec_doc-04-nist-sp-800-86-p70-280', 0, 240, 'v2.1.0', '87d408e803281815f838ab6f83111920f3f719c95810514779d8b860596cea21', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"FORENSICS","authority_tier":0,"chunk_seq":280,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p70-281', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 70, 'If communications are encrypted all the way to the internal host (e.g., an SSL-encrypted Web session), then devices monitoring network traffic cannot see the decrypted packets. Organizations should consider establishing policies that specify the appropriate use of traffic encryption technologies, so that security controls such as IDS sensors can monitor the contents of traffic that does not need to be or should not be encrypted. ! Services Running on Unexpected Ports. Applications such as IDSs and protocol analyzers often rely on port numbers to identify which service is in use for a given connection. Unfortunately, as described in Section 6.1.2, most services can be run on any port number.', 'vec_doc-04-nist-sp-800-86-p70-281', 0, 175, 'v2.1.0', '698533ff7f66f54616a54b3310cd9aedbe22edae5a133f2adef5e9e19b1e1ca7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"FORENSICS","authority_tier":0,"chunk_seq":281,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p70-282', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 70, 'Because traffic involving services running on unexpected port numbers may not be captured, monitored, or analyzed properly, use of unauthorized services (e.g., providing Web services on an 104  Organizations should also provide sufficient data storage to keep logs associated with computer security incidents for a substantially longer time than other logs, as needed. For example, General Records Schedule (GRS) 24, Information Technology Operations and Management Records, specifies that computer security incident handling, reporting and follow-up records should be destroyed 3 years after all necessary follow-up actions have been completed.  GRS 24 is available from the National Archives and Records Administration at http://www.archives.gov/records-mgmt/ardor/. 6-10', 'vec_doc-04-nist-sp-800-86-p70-282', 0, 195, 'v2.1.0', '827a9a7c392dd15f5e6eca224d6fd3d62baaf085eab5fbf88b49e03940af21c2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":70,"domain":"FORENSICS","authority_tier":0,"chunk_seq":282,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p71-283', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 71, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE atypical port) might not be detected. Another motivation for using unexpected port numbers is to slip traffic through perimeter devices that filter based on port numbers. There are several ways to attempt to identify unexpected port usage, including the following:  Configuring IDS sensors to alert on connections involving unknown server ports  Configuring application proxies or IDS sensors that perform protocol analysis to alert on connections that use an unexpected protocol (e.g., FTP traffic using the standard HTTP port)  Performing traffic flow monitoring and identifying new and unusual traffic flows  Configuring a protocol analyzer to analyze a particular stream as something else. ! Alternate Access Points. Attackers often enter networks from alternate access points to avoid detection by security controls that are monitoring major access points, such as the organizations Internet gateway.', 'vec_doc-04-nist-sp-800-86-p71-283', 0, 244, 'v2.1.0', '3878137044f6ded91304e409bab0abe6be66d0478043d9739011c67d3857ec77', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"FORENSICS","authority_tier":0,"chunk_seq":283,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p71-284', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 71, 'A classic example of an alternate access point is a modem in a users workstation. If an attacker can dial into the workstation and gain access, attacks can be launched from that workstation against other hosts. In such cases, little or no information regarding the network activity might be logged because the activity would not pass through firewalls, IDS- monitored network segments, and other common data collection points. Organizations typically address this potential problem by limiting alternate access points, such as modems and wireless access points, and ensuring that each is monitored and restricted through firewalls, IDS sensors, and other controls. ! Monitoring Failures. Inevitably, systems and applications will occasionally experience failures or outages for various reasons (e.g., system maintenance, software failures, attacks).', 'vec_doc-04-nist-sp-800-86-p71-284', 0, 213, 'v2.1.0', '5ddd6ec542bad0810e50dfe810bbebaeccac099d7860c11a90eef6b7f553cb61', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"FORENSICS","authority_tier":0,"chunk_seq":284,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p71-285', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.3 Collecting Network Traffic Data', 71, 'In the case of dedicated monitoring systems such as IDS sensors, use of redundant equipment (e.g., two sensors monitoring the same activity) can lessen the impact of monitoring failures.105  Another strategy is to perform multiple levels of monitoring, such as configuring network-based and host- based firewalls to log connections.', 'vec_doc-04-nist-sp-800-86-p71-285', 0, 83, 'v2.1.0', 'b3f007b34050cdfcb7174cc855f01fd8abe5ffd453adb0f14d329fadb60f2dc3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.3 Collecting Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"FORENSICS","authority_tier":0,"chunk_seq":285,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.3 Collecting Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p71-286', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 71, 'When an event of interest has been identified, analysts assess, extract, and analyze network traffic data with the goal of determining what has happened and how the organizations systems and networks have been affected. This process might be as simple as reviewing a few log entries on a single data source and determining that the event was a false alarm, or as complex as sequentially examining and analyzing dozens of sources (most of which might contain no relevant data), manually correlating data among several sources, then analyzing the collective data to determine the probable intent and significance of the event. However, even the relatively simple case of validating a few log entries can be surprisingly involved and time-consuming. Although current tools (e.g., SEM software, NFAT software) can be helpful in gathering and presenting network traffic data, such tools have rather limited analysis abilities and can be used effectively only by well-trained, experienced analysts.', 'vec_doc-04-nist-sp-800-86-p71-286', 0, 249, 'v2.1.0', 'd0c16ae712e5a9c05a8e706b891bb67ee3267f4da43528325418a5a142f48954', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"FORENSICS","authority_tier":0,"chunk_seq":286,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p71-287', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 71, 'In addition to understanding the tools, analysts should also have reasonably comprehensive knowledge of networking principles, common network and application protocols, network and application security products, and network-based threats and attack methods.106  It is also very important that analysts have knowledge of the organizations environment, such as the network architecture and the IP addresses used by critical assets (e.g., firewalls, publicly accessible 105  In most organizations, the cost of redundant monitoring makes it feasible only for the highest risk areas. 106  Helpful references for analysts include lists of commonly used protocols and their typical port numbers, and Request for Comment (RFC) documents that explain the standards for various network and application protocols. 6-11', 'vec_doc-04-nist-sp-800-86-p71-287', 0, 202, 'v2.1.0', '3ffb1103eef74ed4493ea5e0084c6174d6c5cbb6cf0efb8f63b9b6ff2ffc0bac', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":71,"domain":"FORENSICS","authority_tier":0,"chunk_seq":287,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p72-288', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 72, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE servers), as well as knowledge of the information supporting the applications and OSs used by the organization. If analysts understand the organizations normal computing baseline, such as typical patterns of usage on systems and networks across the enterprise, they should be able to perform their work easier and faster. Analysts should also have a firm understanding of each of the network traffic data sources, as well as access to supporting materials, such as intrusion detection signature documentation. Analysts should understand the characteristics and relative value of each data source so that they can locate the relevant data quickly.', 'vec_doc-04-nist-sp-800-86-p72-288', 0, 178, 'v2.1.0', '2e0760627f8555b5e3626b66ecdec33233832eb2b721ad276d57b429e246acbb', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"FORENSICS","authority_tier":0,"chunk_seq":288,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p72-289', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 72, 'Given the potential complexities of the analysis process and the extensive knowledge of networking and information security required for analyzing network traffic data effectively, a full description of techniques needed for analyzing data and drawing conclusions in complex situations is beyond the scope of this document. Instead, the section focuses on the basic steps of the examination and analysis processes and highlights some significant technical issues that analysts should consider. 6.4.1 6.4.2 Identify an Event of Interest The first step in the examination process is the identification of an event of interest. Typically, this identification is made through one of two methods: ! Someone within the organization (e.g., help desk agent, system administrator, security administrator) receives an indication, such as an automated alert or a user complaint, that there is a security or operational-related issue. The analyst is asked to research the corresponding activity. !', 'vec_doc-04-nist-sp-800-86-p72-289', 0, 247, 'v2.1.0', 'd255637afc27816c4fb90003f37dca9c9e2b4a8ad949ffb60acd8b01367835f8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"FORENSICS","authority_tier":0,"chunk_seq":289,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p72-290', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 72, 'During a review of security event data (e.g., IDS monitoring, network monitoring, firewall log review), which is part of the analysts regular duties, the analyst identifies an event of interest and determines that it should be researched further. When an event of interest has been identified, the analyst needs to know some basic information about the event as a basis for research. In most cases, the event will have been detected through a network traffic data source, such as an IDS sensor or a firewall, so the analyst can simply be pointed to that data source for more information. However, in some cases, such as a user complaint, it might not be apparent which data sources (if any) contain relevant information or which hosts or networks might be involved. Therefore, analysts might need to rely on more general informationfor example, reports that several systems on the fourth floor have been rebooting themselves.', 'vec_doc-04-nist-sp-800-86-p72-290', 0, 232, 'v2.1.0', '440415aa1a1fa25e0ae57498192a5e6ac2f93a210d4e50733d06c72ca2fa0447', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"FORENSICS","authority_tier":0,"chunk_seq":290,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p72-291', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 72, 'Although data examination is easier if the event information is specific (e.g., IP addresses of affected systems), even general information provides the analyst with a starting point for finding the relevant data sources. Examine Data Sources As described in Section 6.2, organizations may have many sources of network traffic-related data. A single event of interest could be noted by many of these data sources, but it may be inefficient or impractical to check each source individually. For initial event data examination, analysts typically rely on a few primary data sources, such as an IDS console that displays alerts from all IDS sensors, or SEM or NFAT software that consolidates many other data sources and organizes the data. Not only is this an efficient solution, but also in most cases the event of interest will be identified by an alert from one of these primary data sources. For each data source examined, analysts should consider its fidelity.', 'vec_doc-04-nist-sp-800-86-p72-291', 0, 241, 'v2.1.0', 'dd20bd1bfdf708ec4eaa86364f370c490946317b30c828cab20d4908396d74d5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"FORENSICS","authority_tier":0,"chunk_seq":291,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p72-292', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 72, 'In general, analysts should have more confidence in original data sources than in data sources that receive normalized (modified) data from other sources. In addition, analysts should validate data that is based on interpretation, such as IDS and SEM alerts. No tool for identifying malicious activity is completely accurate; they produce both false 6-12', 'vec_doc-04-nist-sp-800-86-p72-292', 0, 89, 'v2.1.0', '517d0d130017959e652bb0b07ea3048cfea0721062210dca4fc1d21773026bb3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":72,"domain":"FORENSICS","authority_tier":0,"chunk_seq":292,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p73-293', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 73, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE positives (incorrectly reporting benign activity as malicious) and false negatives (incorrectly classifying malicious activity as benign).107  Tools such as NFAT and IDS might also produce inaccurate alerts if they do not process all packets within a connection.108  Validation should be based on an analysis of additional data (e.g., raw packets, supporting information captured by other sources), a review of available information on alert validity (e.g., vendor comments on known false positives), and past experience with the tool in question. In many cases, an experienced analyst can quickly examine the supporting data and determine that an alert is a false positive and does not need further investigation. Analysts may also need to examine secondary network traffic data sources, such as host-based firewall logs and packet captures, and non-network traffic data sources, such as host OS audit logs and antivirus software logs.', 'vec_doc-04-nist-sp-800-86-p73-293', 0, 250, 'v2.1.0', '57937d06257856dbd0389e7cf34663fe25296bc90343eadf835ff42645cbe912', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"FORENSICS","authority_tier":0,"chunk_seq":293,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p73-294', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 73, 'The most common reasons for doing this are as follows: ! No Data on Primary Sources. In some cases, the typical primary network traffic data sources do not contain evidence of the activity. For example, an attack might have occurred between two hosts on an internal network segment that is not monitored or controlled by network security devices. In these cases, analysts should identify other likely data sources and examine them for evidence. ! Insufficient or Unvalidated Data on Primary Sources. Analysts might need to examine secondary data sources if primary data sources do not contain sufficient information or analysts need to validate the data. After reviewing one or more primary data sources, analysts should query the appropriate secondary data sources based on the pertinent data from the primary data sources.', 'vec_doc-04-nist-sp-800-86-p73-294', 0, 206, 'v2.1.0', '9eceb5cfbdf00b6aa1fefb17a883f9ad403a7db8a6d761f4005636e4b302a427', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"FORENSICS","authority_tier":0,"chunk_seq":294,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p73-295', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 73, 'For example, if IDS records indicate an attack against the system at IP address 10.20.30.40 with an apparent origin of IP address 10.3.0.1, querying other data sources using one or both IP addresses might uncover additional data regarding the activity. Analysts also use timestamps,109 protocols, port numbers, and other common data fields to narrow their search as necessary. ! Best Source of Data Elsewhere. Occasionally, the best sources of network traffic data are located on a particular host, such as host-based firewall and IDS logs on a system that was attacked. Although such data sources can be very helpful, their data may be altered or destroyed during a successful attack. If additional data is needed but cannot be located and the suspicious activity is still occurring, analysts might need to perform more data collection activities. For example, an analyst could perform packet captures at an appropriate point on the network to gather more information.', 'vec_doc-04-nist-sp-800-86-p73-295', 0, 243, 'v2.1.0', '244a2c9f6f59bff08c796f2581671ad916cb1f61d7cfe036d6de0b9042452ada', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"FORENSICS","authority_tier":0,"chunk_seq":295,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p73-296', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 73, 'Other ways to collect more information include configuring firewalls or routers to log more information on certain activity, setting an IDS signature to capture packets for the activity, and writing a custom IDS signature that alerts when a specific activity occurs. See Section 6.2 for additional guidance on tools that can collect data. Collecting additional data may be helpful if the activity is ongoing or intermittent; if the activity has ended, there is no opportunity to collect additional data. 107  From an analysts perspective, the concept of false negatives is important because it means that security devices sometimes fail to report attacks that they have observed. Analysts should not assume that an activity is benign if security devices have not reported it as malicious.', 'vec_doc-04-nist-sp-800-86-p73-296', 0, 198, 'v2.1.0', '13018d3203f63e16b48fa80fe0e9a04672ea495df7063c11db77fd5732a15f27', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"FORENSICS","authority_tier":0,"chunk_seq":296,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p73-297', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 73, '108  There are several possible causes for not processing all packets, including security device failure (e.g., outage, software bug), security device overload (e.g., unusually high volume of packets to process), and asynchronous routing. In asynchronous routing, the incoming packets and outgoing packets for a connection take different routes. If only one of these routes is monitored by a device such as an IDS sensor, the device can see only part of the connection. 109  As mentioned in Section 4.3.3, organizations should use time synchronization to keep systems clocks consistent. Correlating an event among multiple network traffic sources is easier and more effective if the clocks are in synch. If event data sources are on separate devices, timestamps can be helpful in confirming the path that the packets used. (When packets traverse a network, it takes them some amount of time to get from one device to the next.) 6-13', 'vec_doc-04-nist-sp-800-86-p73-297', 0, 234, 'v2.1.0', '66f692fb09cedfe70621dcc562d16fd3371438021a9a88f9452241e8ba0a0728', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":73,"domain":"FORENSICS","authority_tier":0,"chunk_seq":297,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p74-298', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 74, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 6.4.2.1 Data Source Value As described in Section 6.2, organizations typically have many different sources of network traffic data. Because the information collected by these sources varies, the sources may have different value to the analyst, both in general and for specific cases. The following items describe the typical value of the most common data sources in network forensics: ! IDS Software. IDS data is often the starting point for examining suspicious activity. Not only do IDSs typically attempt to identify malicious network traffic at all TCP/IP layers, but also they log many data fields (and sometimes raw packets) that can be useful in validating events and correlating them with other data sources. Nevertheless, as noted previously, IDS software does produce false positives, so IDS alerts should be validated.', 'vec_doc-04-nist-sp-800-86-p74-298', 0, 224, 'v2.1.0', 'a57551851c3041618ae0fc48816eb137b4d981aaf86b0d2db50404a5712e1441', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"FORENSICS","authority_tier":0,"chunk_seq":298,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p74-299', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 74, 'The extent to which this can be done depends on the amount of data recorded related to the alert and the information available to the analyst about the signature characteristics or anomaly detection method that triggered the alert. ! SEM Software. Ideally, SEM can be extremely useful for forensics because it can automatically correlate events among several data sources, then extract the relevant information and present it to the user. However, because SEM software functions by bringing in data from many other sources, the value of SEM depends on which data sources are fed into it, how reliable each data source is, and how well the software can normalize the data and correlate events. ! NFAT Software. NFAT software is designed specifically to aid in network traffic analysis, so it is valuable if it has monitored an event of interest. NFAT software usually offers features that support analysis, such as traffic reconstruction and visualization; Section 6.2.6 describes these in more depth. !', 'vec_doc-04-nist-sp-800-86-p74-299', 0, 251, 'v2.1.0', '431ffb02d24cac56e006bcd0d51dac46dac0b30169f371e0ca7ebd5be834d005', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"FORENSICS","authority_tier":0,"chunk_seq":299,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p74-300', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 74, 'Firewalls, Routers, Proxy Servers, and Remote Access Servers. By itself, data from these sources is usually of little value. Analyzing the data over time can indicate overall trends, such as an increase in blocked connection attempts. However, because these sources typically record little information about each event, the data provides little insight into the nature of the events. Also, many events might be logged each day, so the sheer volume of data can be overwhelming. The primary value of the data is to correlate events recorded by other sources. For example, if a host is compromised and a network IDS sensor detected the attack, querying the firewall logs for events involving the apparent attacking IP address might confirm where the attack entered the network and might indicate other hosts that the attacker attempted to compromise.', 'vec_doc-04-nist-sp-800-86-p74-300', 0, 212, 'v2.1.0', '6d422729305492f90146a2d327e80751f2993a829116d035ed714fe38c7a2feb', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"FORENSICS","authority_tier":0,"chunk_seq":300,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p74-301', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 74, 'In addition, address mapping (e.g., NAT) performed by these devices is important for network forensics because the apparent IP address of an attacker or a victim might actually have been used by hundreds or thousands of hosts. Fortunately, analysts usually can review the logs to determine which internal address was in use. ! DHCP Servers. DHCP servers typically can be configured to log each IP address assignment and the associated MAC address, along with a timestamp. This information can be helpful to analysts in identifying which host performed an activity using a particular IP address. However, analysts should be mindful of the possibility that attackers on an organizations internal networks falsified their MAC addresses or IP addresses, a practice known as spoofing. ! Packet Sniffers. Of all the network traffic data sources, packet sniffers can collect the most information on network activity.', 'vec_doc-04-nist-sp-800-86-p74-301', 0, 228, 'v2.1.0', '158a1c98ba65cfbf11ca844605c4363d5860cf5623ec7da391970f0f6f6260b8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"FORENSICS","authority_tier":0,"chunk_seq":301,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p74-302', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 74, 'However, sniffers might capture huge volumes of benign data as wellmillions or billions of packetsand typically provide no indication as to which packets might contain malicious activity. In most cases, packet sniffers are best used to provide more data on events that other devices or software has identified as possibly malicious. Some organizations record most or all packets for some period of time so that when an incident occurs, 6-14', 'vec_doc-04-nist-sp-800-86-p74-302', 0, 111, 'v2.1.0', '0f6fa5c064c48748090415d8352b5080361baeab6d8589516109b60d414c5fb9', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":74,"domain":"FORENSICS","authority_tier":0,"chunk_seq":302,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p75-303', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 75, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the raw network data is available for examination and analysis.110  Packet sniffer data is best reviewed with a protocol analyzer, which interprets the data for the analyst based on knowledge of protocol standards and common implementations. ! Network Monitoring. Network monitoring software is helpful in identifying significant deviations from normal traffic flows, such as those caused by DDoS attacks, during which, hundreds or thousands of systems launch simultaneous attacks against particular hosts or networks. Network monitoring software can document the impact of these attacks on network bandwidth and availability, as well as providing information about the apparent targets. Traffic flow data can also be helpful in investigating suspicious activity identified by other sources. For example, it might indicate whether a particular communications pattern has occurred in the preceding days or weeks. ! ISP Records.', 'vec_doc-04-nist-sp-800-86-p75-303', 0, 248, 'v2.1.0', 'ae56b382546482d0d28120db933611f43da486aaf9cd4055605c63fe91f5d159', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"FORENSICS","authority_tier":0,"chunk_seq":303,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p75-304', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 75, 'Information from an ISP is primarily of value in tracing an attack back to its source, particularly when the attack uses spoofed IP addresses. Section 6.4.4 discusses this subject in more depth. 6.4.2.2 Examination and Analysis Tools Because network forensics can be performed for many purposes with dozens of data source types, analysts may use several different tools on a regular basis, each well-suited to certain situations. Analysts should be aware of the possible approaches to examining and analyzing network traffic data and should select the best tools for each case, rather than applying the same tool to every situation. Analysts should also be mindful of the shortcomings of tools; for example, a particular protocol analyzer might not be able to translate a certain protocol or handle unexpected protocol data (e.g., illegal data field value). It can be helpful to have an alternate tool available that might not have the same deficiency. Tools are often helpful in filtering data.', 'vec_doc-04-nist-sp-800-86-p75-304', 0, 249, 'v2.1.0', '3c54ac577dcdb54d3a065809945eb1e71d03fee5ec06d8e38cc84659cd9a36e1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"FORENSICS","authority_tier":0,"chunk_seq":304,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p75-305', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 75, 'For example, an analyst might need to search data without any concrete information that could narrow the search. This is most likely to occur when the analyst is responsible for performing periodic or ongoing reviews of security event data logs and alerts. If the volume of log entries and alerts is low, reviewing the data is relatively easybut in some cases, there may be many thousands of events listed per day. When a manual data review is not possible or practical, analysts should use an automated solution that filters the events and presents the analysts with only the events that are most likely to be of interest. One effective review technique is to import the logs into a database and run queries against them, either eliminating types of activity highly likely to be benign and reviewing the rest, or focusing on the types of activity most likely to be malicious.', 'vec_doc-04-nist-sp-800-86-p75-305', 0, 220, 'v2.1.0', '00186783dce12f2910ae576e947121c57590de760db32ba426e5f0e2f19e28da', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"FORENSICS","authority_tier":0,"chunk_seq":305,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p75-306', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 75, 'For example, if the initial suspicion is that the server was compromised through HTTP activity, then log filtering might start by eliminating everything except HTTP activity from consideration. An analyst who is very familiar with a particular data source can generally perform a blind search on it relatively quickly, but, on unfamiliar data sources, blind searches can take an extremely long time, because there might be little or no basis for eliminating certain types of activity from consideration. Another analysis option is to use a visualization tool. These tools present security event data in a graphical format. This is most often used to represent network traffic flows visually, which can be very helpful in troubleshooting operational issues and identifying misuse. For example, attackers might use covert channelsusing protocols in unintended ways to secretly communicate information (e.g., setting certain values in network protocol headers or application payloads).', 'vec_doc-04-nist-sp-800-86-p75-306', 0, 246, 'v2.1.0', 'ab8afc35737fefc9745a6f5f20342c00a98eb24a034feabe9fb374546281f90e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"FORENSICS","authority_tier":0,"chunk_seq":306,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p75-307', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 75, 'The use of covert channels is generally hard to detect, but one useful method is identifying deviations in expected network traffic flows. 110  Many NFAT programs, as described in Section 6.2.6, provide this function, as well as additional capabilities. 6-15', 'vec_doc-04-nist-sp-800-86-p75-307', 0, 65, 'v2.1.0', 'a4e1449077154707cc6df578908bd58deb4979e17cd0291e26a5625a1e53c38c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":75,"domain":"FORENSICS","authority_tier":0,"chunk_seq":307,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p76-308', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 76, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Visualization tools are often included in NFAT software, as described in Section 6.2.6. Some visualization tools can perform traffic reconstructionby using timestamp and sequential data fields, the tools can determine the sequence of events and graphically display how the packets traversed the organizations networks. Some visualization tools can also be used to display other types of security event data. For example, an analyst could import intrusion detection records into a visualization tool, which would then display the data according to several different characteristics, such as source or destination IP address or port. An analyst could then suppress the display of known good activity so that only unknown events are shown. Although visualization tools can be very effective for analyzing certain types of data, analysts typically experience a steep learning curve with such tools.', 'vec_doc-04-nist-sp-800-86-p76-308', 0, 240, 'v2.1.0', '8eab7616d2c8337b49ecfc0d7559eb3fd8a304ba6ae49dd05337a75eaf6616f6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"FORENSICS","authority_tier":0,"chunk_seq":308,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p76-309', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 76, 'Importing data into the tool and displaying it is usually relatively straightforward, but learning how to use the tool efficiently to reduce large datasets to a few events of interest can take considerable effort. Traffic reconstruction can also be performed by protocol analyzers. Although these tools generally lack visualization capabilities, they can turn individual packets into data streams and provide sequential context for activities. 6.4.3 Draw Conclusions One of the most challenging aspects of network forensics is that the available data is typically not comprehensive. In many cases, if not most, some network traffic data has not been recorded and consequently has been lost. Generally, analysts should think of the analysis process as a methodical approach that develops conclusions based on the data that is available and assumptions regarding the missing data (which should be based on technical knowledge and expertise).', 'vec_doc-04-nist-sp-800-86-p76-309', 0, 235, 'v2.1.0', 'f69fccfc33bc8d510a82a05e0cc344c1997d7f982d783e1fd4452b9e026ddb0c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"FORENSICS","authority_tier":0,"chunk_seq":309,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p76-310', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 76, 'Although analysts should strive to locate and examine all available data regarding an event, this is not practical in some cases, particularly when there are many redundant data sources. The analyst should eventually locate, validate, and analyze enough data to be able to reconstruct the event, understand its significance, and determine its impact. In many cases, additional data is available from sources other than network trafficrelated sources (e.g., data files or host OSs). Section 8 provides examples of how analysis can correlate this other data with data from network traffic to get a more accurate and comprehensive view of what occurred. Generally, analysts should focus on identifying the most important characteristics of the activity and assessing the negative impact it has caused or may cause the organization.', 'vec_doc-04-nist-sp-800-86-p76-310', 0, 208, 'v2.1.0', 'f6f0d1bee2305bbc177574703407e9570522b7fdc6d9e1b5c1acf510bd8fc89c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"FORENSICS","authority_tier":0,"chunk_seq":310,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p76-311', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 76, 'Other actions, such as determining the identity of an external attacker, are typically time-intensive and difficult to accomplish, and do not aid the organization in correcting the operational issues or security weaknesses. Determining the intent of an attacker is also very difficult; for example, an unusual connection attempt could be caused by an attacker, malicious code, misconfigured software, or an incorrect keystroke, among other causes. Although understanding intent is important in some cases, the negative impact of the event should be the primary concern. Establishing the identity of the attacker might be important to the organization, particularly when criminal activity has occurred, but in other cases it should be weighed against other important goals to put it into perspective. The focus of the investigation should be determined at the onset by the appropriate parties, who should decide if learning the identity of the attacker is vital.', 'vec_doc-04-nist-sp-800-86-p76-311', 0, 241, 'v2.1.0', '841fc92fe76d05e7e7f656ba01683c597608231f2e6316d1da171a2803ffb4fd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"FORENSICS","authority_tier":0,"chunk_seq":311,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p76-312', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 76, 'It is particularly important to seek the advice of legal counsel when developing policies and procedures related to making such decisions, as well as when guidance is needed for a particular situation. Organizations should be interested not only in analyzing real events, but also in understanding the causes of false alarms. For example, analysts are often well-positioned to identify the root causes of IDS false positives. As merited, analysts should recommend changes to security event data sources that improve detection accuracy. 6-16', 'vec_doc-04-nist-sp-800-86-p76-312', 0, 135, 'v2.1.0', '55a7c50741507d6223dbfb21192f01f53638b01d025173811275fbc4738f5c6b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":76,"domain":"FORENSICS","authority_tier":0,"chunk_seq":312,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p77-313', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 77, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 6.4.4 Attacker Identification When analyzing most attacks, identifying the attacker is not an immediate, primary concern: ensuring that the attack is stopped and recovering systems and data are the main interests. If an attack is ongoing, such as an extended denial of service attack, organizations might want to identify the IP address used by the attacker so that the attack can be stopped. Unfortunately, this is often not as simple as it sounds. The following items explain potential issues involving the IP addresses apparently used to conduct an attack: ! Spoofed IP Addresses. Many attacks use spoofed IP addresses. Spoofing is far more difficult to perform successfully for attacks that require connections to be established, so it is most commonly used in cases where connections are not needed.111  When packets are spoofed, usually the attacker has no interest in seeing the response.', 'vec_doc-04-nist-sp-800-86-p77-313', 0, 240, 'v2.1.0', 'c4298acedd547e681d50460e678fb941878747fadc83e5f2d741d4b2b55c5046', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"FORENSICS","authority_tier":0,"chunk_seq":313,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p77-314', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 77, 'This is not always trueattackers could spoof an address from a subnet that they monitor, so that when the response goes to that system, they can sniff it from the network. Sometimes spoofing occurs by accident, such as an attacker misconfiguring a tool and accidentally using internal NAT addresses. Sometimes an attacker spoofs a particular address on purposefor example, the spoofed address might be the actual intended target of the attack, and the organization seeing the activity might simply be a middleman. ! Many Source IP Addresses. Some attacks appear to use hundreds or thousands of different source IP addresses. Sometimes this appearance reflects realityfor example, DDoS attacks typically rely on large numbers of compromised machines performing a coordinated attack. Sometimes this appearance is illusoryan attack might not require the use of real source IP addresses, so the attacker generates many different fake IP addresses to add confusion.', 'vec_doc-04-nist-sp-800-86-p77-314', 0, 241, 'v2.1.0', 'aef53c887f07333647a8f6ecca578c4778ef46ad324b0b0a8f895a7721d8dcba', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"FORENSICS","authority_tier":0,"chunk_seq":314,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p77-315', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 77, 'Sometimes attackers will use one real IP address and many fake ones; in that case, it might be possible to identify the real IP address by looking for other network activity occurring before or after the attack that uses any of the same IP addresses. Finding a match does not confirm that it was the attackers address; the attacker could have inadvertently or purposely spoofed a legitimate IP address that happened to be interacting with the organization. ! Validity of the IP Address. Because IP addresses are often assigned dynamically, the system currently at a particular IP address might not be the same system that was there when the attack occurred. In addition, many IP addresses do not belong to end-user systems, but instead to network infrastructure components that substitute their IP address for the actual source address, such as a firewall performing NAT.', 'vec_doc-04-nist-sp-800-86-p77-315', 0, 218, 'v2.1.0', '8f9381ffa4929f83152c2dbdcb41f0594cbbcdc98a32c8b6d8d5634ebcd4a8d6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"FORENSICS","authority_tier":0,"chunk_seq":315,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p77-316', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 77, 'Some attackers use anonymizers, which are intermediate servers that perform activity on a users behalf to preserve the users privacy. Several ways of validating the identity of a suspicious host are as follows: ! Contact the IP Address Owner. The Regional Internet Registries, such as the American Registry for Internet Numbers (ARIN),112 provide WHOIS query mechanisms on their Web sites for identifying the organization or person that ownsis responsible fora particular IP address. This information can be helpful in analyzing some attacks, such as seeing that three different IP addresses generating suspicious activity are all registered to the same owner. However, in most cases, analysts should not contact the owner directly; instead, they should provide information about the owner to the management and legal advisors of the analysts organization, who can initiate contact with the organization or give the analyst approval to do so if needed.', 'vec_doc-04-nist-sp-800-86-p77-316', 0, 240, 'v2.1.0', 'a4f4405fc8abb17965840674d4d8646e8cc6d1cbae79808dfea65ac70bb58b27', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"FORENSICS","authority_tier":0,"chunk_seq":316,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p77-317', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 77, 'This caution 111  Connectionless protocols such as ICMP and UDP are the most likely to be spoofed. 112  ARINs web site is at http://www.arin.net/. The other registries are the Asia Pacific Network Information Centre (APNIC), located at http://www.apnic.net/; Latin American and Caribbean IP Address Regional Registry (LACNIC), located at http://lacnic.net/; and Réseaux IP Européens Network Coordination Centre (RIPE NCC), located at http://www.ripe.net/. 6-17', 'vec_doc-04-nist-sp-800-86-p77-317', 0, 116, 'v2.1.0', 'f4cee0a396a7e4d2aceefad2b5108e9d280adadd7bba46c271d1a5f079e06b53', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":77,"domain":"FORENSICS","authority_tier":0,"chunk_seq":317,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p78-318', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 78, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE is primarily related to concerns about sharing information with external organizations; also, the owner of an IP address could be the person attacking the organization. ! Send Network Traffic to the IP Address. Organizations should not send network traffic to an apparent attacking IP address to validate its identity. Any response that is generated cannot conclusively confirm the identity of the attacking host. Moreover, if the IP address is for the attackers system, the attacker might see the traffic and react by destroying evidence or attacking the host sending the traffic. If the IP address is spoofed, sending unsolicited network traffic to the system could be interpreted as unauthorized use or an attack. Under no circumstances should individuals attempt to gain access to others systems without permission. ! Seek ISP Assistance.', 'vec_doc-04-nist-sp-800-86-p78-318', 0, 227, 'v2.1.0', '4ce21befc5f3c836a260c049eb9e1b926502177c376f23f4a21df6390630d4e7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"FORENSICS","authority_tier":0,"chunk_seq":318,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p78-319', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 78, 'As mentioned in Section 6.3.1, ISPs generally require a court order before providing any information to an organization about suspicious network activity. Accordingly, ISP assistance is generally an option during only the most serious network-based attacks. This assistance is particularly useful in relation to attacks that involve IP address spoofing. ISPs have the ability to trace ongoing attacks back to their source, whether the IP addresses are spoofed or not. ! Research the History of the IP Address. Analysts can look for previous suspicious activity associated with the same IP address or IP address block. The organizations own network traffic data archives and incident tracking databases might show previous activity. Possible external sources include Internet search engines and online incident databases that allow searches by IP address.113 ! Look for Clues in Application Content. Application data packets related to an attack might contain clues to the attackers identity.', 'vec_doc-04-nist-sp-800-86-p78-319', 0, 249, 'v2.1.0', '9ebe09bce585d72ceacd3b66ca5e6c5116d668cb001f1ece06efad50ba036dc1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"FORENSICS","authority_tier":0,"chunk_seq":319,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p78-320', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.4 Examining and Analyzing Network Traffic Data', 78, 'In addition to IP addresses, valuable information could include an e-mail address or an Internet relay chat (IRC) nickname. In most cases, organizations do not need to positively identify the IP address used for an attack.', 'vec_doc-04-nist-sp-800-86-p78-320', 0, 56, 'v2.1.0', '7e377804fe4f8009dfb5cade3ceeb84a4fb0b08099f8836819edfdd2b1fc3c47', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.4 Examining and Analyzing Network Traffic Data","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"FORENSICS","authority_tier":0,"chunk_seq":320,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.4 Examining and Analyzing Network Traffic Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p78-321', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.5 Re commendations', 78, 'Key recommendations presented in this section for using data from network traffic are as follows: ! Organizations should have policies regarding privacy and sensitive information.  The use of forensic tools and techniques might inadvertently disclose sensitive information to analysts and others involved in forensic activities.  Also, long-term storage of sensitive information inadvertently captured by forensic tools might violate data retention policies.  Policies should also address the monitoring of networks, as well as requiring warning banners on systems that indicate activity may be monitored. ! Organizations should provide adequate storage for network activityrelated logs. Organizations should estimate typical and peak log usage, determine how many hours or days worth of data should be retained based on the organizations policies, and ensure that systems and applications have sufficient storage available.  Logs related to computer security incidents might need to be kept for a substantially longer period of time than other logs. ! Organizations should configure data sources to improve the collection of information.  Over time, operational experience should be used to improve the organizations forensic analysis capabilities.  Organizations should periodically review and adjust the configuration settings of data sources to optimize capture of relevant information. 113  One publicly available incident database is DShield, located at http://www.dshield.org/. 6-18', 'vec_doc-04-nist-sp-800-86-p78-321', 0, 374, 'v2.1.0', 'bd78a788b02f7d9564ca1a1d415d2d14c4ce9c6b3b89de862067878a8cc22274', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":78,"domain":"FORENSICS","authority_tier":0,"chunk_seq":321,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p79-322', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.5 Re commendations', 79, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Analysts should have reasonably comprehensive technical knowledge.  Because current tools have rather limited analysis abilities, analysts should be well-trained, experienced, and knowledgeable in networking principles, common network and application protocols, network and application security products, and network-based threats and attack methods. ! Analysts should consider the fidelity and value of each data source.  Analysts should have more confidence in original data sources than in data sources that receive normalized data from other sources.  The analysts should validate any unusual or unexpected data that is based on interpretation of data, such as IDS and SEM alerts. ! Analysts should generally focus on the characteristics and impact of the event.  Determining the identity of an attacker and other similar actions are typically time-intensive and difficult to accomplish, and do not aid the organization in correcting operational issues or security weaknesses.  Establishing the identity and intent of an attacker may be important, especially if a criminal investigation will ensue, but should be weighed against other important goals, such as stopping an attack and recovering systems and data. 6-19', 'vec_doc-04-nist-sp-800-86-p79-322', 0, 322, 'v2.1.0', '029bfbf69a5661eda309091c72fc52140462d5126ba3a4063f85c6134b4f5890', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":79,"domain":"FORENSICS","authority_tier":0,"chunk_seq":322,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p80-323', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '6.5 Re commendations', 80, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE This page has been left blank intentionally. 6-20', 'vec_doc-04-nist-sp-800-86-p80-323', 0, 29, 'v2.1.0', '92430fa52a76af4ed0321121625e8ff24bc87b6e814ade72b7dcbeff7c85ce86', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"6.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":80,"domain":"FORENSICS","authority_tier":0,"chunk_seq":323,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"6.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p81-324', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. Using Data from Applications', 81, 'Applications such as e-mail, Web browsers, and word processors are what make computers valuable to users.  OSs, files, and networks are all needed to support applications: OSs to run the applications, networks to send application data between systems, and files to store application data, configuration settings, and logs.  From a forensic perspective, applications bring together files, OSs, and networks. This section describes application architecturesthe components that typically make up applications and provides insights into the types of applications that are most often the focus of forensics.  The section also provides guidance on collecting, examining, and analyzing application data.', 'vec_doc-04-nist-sp-800-86-p81-324', 0, 175, 'v2.1.0', '7aebf2350ee5c5a385c744824dd8681c45b3dd1bc8ffaa16babc6a62ee8bbd3f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. Using Data from Applications","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"FORENSICS","authority_tier":0,"chunk_seq":324,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. Using Data from Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p81-325', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 81, 'All applications contain code in the form of executable files (and related files, such as shared code libraries) or scripts. In addition to code, many applications have one or more of the following components: configuration settings, authentication, logs, data, and supporting files. Sections 7.1.1 through 7.1.5 describe these components in detail, and Section 7.1.6 discusses the major types of application architectures, which relate to the intended distribution of the major components. 7.1.1 Configuration Settings Most applications allow users or administrators to customize certain aspects of the applications behavior by altering configuration settings. From a forensics perspective, many settings are trivial (e.g., specifying background colors), but others might be very important, such as the host and directory where data files and logs are stored or the default username. Configuration settings may be temporaryset dynamically during a particular application sessionor permanent.', 'vec_doc-04-nist-sp-800-86-p81-325', 0, 249, 'v2.1.0', '3ffaffd6ae9b07c6c0559e90924a43087478b5e05da534bfe12b9219e4bc127b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"FORENSICS","authority_tier":0,"chunk_seq":325,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p81-326', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 81, 'Many applications have some settings that apply to all users, and also support some user-specific settings. Configuration settings may be stored in several ways, including the following: ! Configuration File. Applications may store settings in a text file or a file with a proprietary binary format.114  Some applications require the configuration file to be on the same host as the application, whereas other applications allow configuration files to be located on other hosts. For example, an application might be installed on a workstation, but the configuration file for a particular user could be stored on the users home directory on a file server. ! Runtime Options. Some applications permit certain configuration settings to be specified at runtime through the use of command-line options. For example, the UNIX e-mail client mutt has options for specifying the location of the mailbox to open and the location of the configuration file.', 'vec_doc-04-nist-sp-800-86-p81-326', 0, 237, 'v2.1.0', 'ff944832bff7628289b5e2c738c679bf5d394c7a9c58312acb8f71c98968a4a6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"FORENSICS","authority_tier":0,"chunk_seq":326,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p81-327', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 81, 'Identification of the options being used for an active session is OS- and application-specific; possible identification methods include reviewing the list of active OS processes, examining an OS history file, and reviewing an application log. Runtime options can also be specified in icons, startup files, batch files, and other ways. ! Added to Source Code. Some applications that make source code available (e.g., open source applications, scripts) actually place user or administrator-specified configuration settings directly into the source code. If the application is then compiled (e.g., converted from human-readable code to a binary, machine-readable format), the configuration settings may actually be contained within executable files, potentially making the settings far more difficult to access than if they were specified in configuration files or as runtime options. In some cases, the settings can be found by searching for text strings within the executable files.', 'vec_doc-04-nist-sp-800-86-p81-327', 0, 246, 'v2.1.0', '0cf2ae7d0562155e1bed55544be3b7fcabc84d71ddd3b1f16fe735cdae72723f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"FORENSICS","authority_tier":0,"chunk_seq":327,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p81-328', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 81, '114  For example, on Windows systems, many configuration settings are stored in the Windows registry, which is essentially a set of large configuration files. 7-1', 'vec_doc-04-nist-sp-800-86-p81-328', 0, 41, 'v2.1.0', '8b33523cd20a2256c8845217d5cb5cee962b9d637bbf0264f1f2781998a4bf9f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":81,"domain":"FORENSICS","authority_tier":0,"chunk_seq":328,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p82-329', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 82, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 7.1.2 7.1.3 Authentication Some applications verify the identity of each user attempting to run the application. Although this is usually done to prevent unauthorized access to the application, it may also be done when access is not a concern so that the application can be customized based on the users identity. Common authentication methods include the following: ! External Authentication. The application may use an external authentication service, such as a directory server. Although the application may contain some records related to authentication, the external authentication service is likely to contain more detailed authentication information. ! Proprietary Authentication. The application may have its own authentication mechanism, such as user accounts and passwords that are part of the application, not the OS. ! Pass-Through Authentication.', 'vec_doc-04-nist-sp-800-86-p82-329', 0, 231, 'v2.1.0', 'c045f456f7ea3b18396a0ffa42a3f4b561b65649c965ac8c753e12a61e027766', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"FORENSICS","authority_tier":0,"chunk_seq":329,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p82-330', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 82, 'Pass-through authentication refers to passing OS credentials (typically, username and password) unencrypted from the OS to the application. ! Host/User Environment. Within a controlled environment (e.g., managed workstations and servers within an organization), some applications may be able to rely on previous authentication performed by the OS. For example, if all hosts using an application are part of the same Windows domain and each user has already been authenticated by the domain, then the application can extract the OS-authenticated identity from each workstations environment. The application can then restrict access to the application by tracking which users are permitted to have access and comparing the OS-authenticated identity to the authorized user list. This technique is effective only if users cannot alter the user identity in the workstation environment. Authentication implementations vary widely among environments and applications.', 'vec_doc-04-nist-sp-800-86-p82-330', 0, 241, 'v2.1.0', '62849b89750dfd45f49830c37e189c2eb4c6ef125dff7e564254231322b5d4c8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"FORENSICS","authority_tier":0,"chunk_seq":330,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p82-331', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 82, 'The details of such implementations are beyond the scope of this document. However, analysts should be aware that there are many ways in which users can be authenticated and that, accordingly, the sources of user authentication records might vary greatly among applications and application implementations. Analysts should also know that some applications use access control (typically enforced by the OS) to restrict access to certain types of information or application functions. This knowledge can be helpful in determining what a particular application user could have done. In addition, some applications record information related to access control, such as failed attempts to perform sensitive actions or access restricted data. Logs Although some applications (primarily very simple ones) do not record any information to logs, most applications perform some type of logging.', 'vec_doc-04-nist-sp-800-86-p82-331', 0, 221, 'v2.1.0', '3283aaf9d5989ad3e48440f60923c43ae060273b0cbee848538e4752bb8c3259', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"FORENSICS","authority_tier":0,"chunk_seq":331,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p82-332', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 82, 'An application may record log entries to an OS-specific log (e.g., syslog on UNIX systems, event logs on Windows systems), a text file, a database, or a proprietary file format. Some applications record different types of events to different logs. Common types of log entries are as follows: ! Event. Event log entries typically list actions that were performed, the date and time each action occurred, and the result of each action. Examples of actions that might be recorded are establishing a connection to another system and issuing administrator-level commands. Event log entries might also include supporting information, such as what username was used to perform each action and what status code was returned (which provides more information about the result than a simple successful/failed status). 7-2', 'vec_doc-04-nist-sp-800-86-p82-332', 0, 203, 'v2.1.0', '503029c91cc807abe9bdf89fd960c08c4d726ceb526f45dd3cf2d6337a735b86', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":82,"domain":"FORENSICS","authority_tier":0,"chunk_seq":332,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p83-333', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 83, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Audit. Audit log entries, also known as security log entries, contain information pertaining to audited activities, such as successful and failed logon attempts, security policy changes, file access, and process execution.115  Applications may use audit capabilities built into the OS or may provide their own auditing capabilities. ! Error. Some applications create error logs, which record information regarding application errors, typically with timestamps. Error logs are helpful in troubleshooting both operational issues and attacks. Error messages can be helpful in determining when an event of interest occurred and in identifying some characteristics of the event. ! Installation. An application may create a separate installation log file that records information pertinent to the initial installation and subsequent updates of that application.', 'vec_doc-04-nist-sp-800-86-p83-333', 0, 231, 'v2.1.0', '65b95300570ff0965f82ffe6e1361969494ea1682bdfb503a895833eb14cf3ec', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"FORENSICS","authority_tier":0,"chunk_seq":333,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p83-334', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 83, 'Information recorded in an installation log varies widely but is likely to include the status of various phases of the installation. The log may also indicate the source of the installation files, the locations where the application components were placed, and options involving the applications configuration. ! Debugging. Some applications can be run in a debugging mode, which means that they log far more information than usual regarding the operation of the application. Debugging records are often very cryptic and may have meaning only to the softwares creator, who can decipher error codes and other facets of the records. If an application offers a debugging capability, typically it is enabled only if administrators or developers need to resolve a specific operational problem. 7.1.4 7.1.5 Data Nearly every application is specifically designed to handle data in one or more ways, such as creating, displaying, transmitting, receiving, modifying, deleting, protecting, and storing data.', 'vec_doc-04-nist-sp-800-86-p83-334', 0, 250, 'v2.1.0', 'f37d936916dfd1c8b68c0c35d21be4a05af1fb9fdeec8fe35958bbc8124d94ff', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"FORENSICS","authority_tier":0,"chunk_seq":334,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p83-335', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 83, 'For example, an e- mail client allows a user to create an e-mail message and to send it to someone, as well as to receive, view, and delete an e-mail message from someone else. Application data often resides temporarily in memory, and temporarily or permanently in files. The format of a file containing application data may be generic (e.g., text files, bitmap graphics) or proprietary. Data may also be stored in databases, which are highly structured collections of files and data specifications. Some applications create temporary files during a session, which may contain application data. If an application fails to shut down gracefully, it may leave temporary files on media. Most OSs have a directory designated for temporary files; however, some applications have their own temporary directory, and other applications place temporary files in the same directory where data is stored. Applications may also contain data file templates and sample data files (e.g., databases, documents).', 'vec_doc-04-nist-sp-800-86-p83-335', 0, 249, 'v2.1.0', '0baa97832f582148c98115a3970a4d9f28a83044ab278b1a5d8b8f62754c9214', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"FORENSICS","authority_tier":0,"chunk_seq":335,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p83-336', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 83, 'Supporting Files Applications often include one or more types of supporting files, such as documentation and graphics. Supporting files tend to be static, but that does not mean that they are not of value for forensics. Types of supporting files include the following: ! Documentation. This may include administrator and user manuals, help files, and licensing information. Documentation can be helpful to analysts in many ways, such as explaining what the application does, how the application works, and what components the application has. Documentation also typically contains contact information for the vendor of the application; the vendor might be able to answer questions and provide other assistance in understanding the application. 115  Some applications record logon attempts to a separate authentication log. Section 7.1.2 contains additional information about authentication. 7-3', 'vec_doc-04-nist-sp-800-86-p83-336', 0, 224, 'v2.1.0', 'b5b8795a477806827c190979b9d0e86cadabd21a46386ac2764a5832230a8244', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":83,"domain":"FORENSICS","authority_tier":0,"chunk_seq":336,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p84-337', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 84, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE ! Links. Also known as shortcuts, links are simply pointers to something else, such as an executable. Links are most frequently used on Windows systems; for example, the items listed on the Start menu are really links to programs. By examining the properties of a link, an analyst can determine what program the link runs, where the program is, and what options (if any) are set. ! Graphics. These files may include standalone graphics used by the application, as well as graphics for icons. Although application graphics are typically of little interest to an analyst, icon graphics may be of interest for identifying which executable was running. 7.1.6 Application Architecture Every application has an architecture, which refers to the logical separation of its components and the communication mechanisms used between components. Most applications are designed to follow one of three major application architecture categories, as follows: !', 'vec_doc-04-nist-sp-800-86-p84-337', 0, 252, 'v2.1.0', 'da6734b99fe99232764c5ae159f127b45f6f9fbff29d03d11eac2a1dd4f4a150', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"FORENSICS","authority_tier":0,"chunk_seq":337,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p84-338', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 84, 'Local. A local application is intended to be contained mainly within a single system. The code, configuration settings, logs, and supporting files are located on the users system. Local applications are unlikely to perform authentication. Application data may be contained on the users system or another system (e.g., file server) and usually cannot be modified simultaneously by multiple users. Examples of local applications are text editors, graphics editors, and office productivity suites (e.g., word processor, spreadsheet). ! Client/Server. A client/server application is designed to be split among multiple systems. A two-tiered client/server application stores its code, configuration settings, and supporting files on each users workstation, and its data on one or more central servers accessed by all users. Logs are most likely stored on the workstations only.', 'vec_doc-04-nist-sp-800-86-p84-338', 0, 219, 'v2.1.0', '31d1ba122009d290d0342c2097f84b6314a7f9ef79c84e513c1ba6f231853815', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"FORENSICS","authority_tier":0,"chunk_seq":338,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p84-339', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 84, 'A three-tiered client/server application separates the user interface from the rest of the application, and also separates the data from the other components. The classic three-tier model places the user interface code on the client workstation (along with some supporting files), the rest of the application code on an application server, and the data on a database server. Many Web-based applications use four-tier models: Web browser, Web server, application server, and database server. Each tier interacts only with the adjacent tiers, so in three and four-tier models, the client does not interact directly with the database server. Examples of typical client/server applications are medical records systems, e-commerce applications, and inventory systems. ! Peer-to-Peer. A peer-to-peer application is designed so that individual client hosts directly communicate and share data with each other.', 'vec_doc-04-nist-sp-800-86-p84-339', 0, 226, 'v2.1.0', '9578c54d0a36cf49da47a8c487c6f7b8d4f1ca6dd174afdf895c96573e8b5375', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"FORENSICS","authority_tier":0,"chunk_seq":339,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p84-340', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 84, 'Typically, the clients first communicate with a centralized server that provides information about other clients; this information is then used to establish direct connections that do not need to go through the centralized server. Examples of peer-to-peer applications are certain file sharing, chat, and IM programs. However, some programs of these types, while popularly referred to as peer-to-peer, are actually client/server, because the clients communicate with a centralized server, instead of communicating directly with each other. Most applications are quite flexible in terms of architecture. For example, many client/server applications can have multiple tiers installed on a single system. Especially during application demonstrations or testing, all tiers might be installed on one system. On the other hand, some local applications can be split among systems, with some components on local systems and some on remote systems.', 'vec_doc-04-nist-sp-800-86-p84-340', 0, 235, 'v2.1.0', '306be962fa46f1c995d52337b7c2cc906d0f4a0d77e46ecb14708089ab9319b9', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"FORENSICS","authority_tier":0,"chunk_seq":340,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p84-341', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 84, 'Applications often make it easy to specify where different components should be installed and where data and configuration files should be stored. For many applications, there can be a great deal of variety among deployments. 7-4', 'vec_doc-04-nist-sp-800-86-p84-341', 0, 58, 'v2.1.0', '129b9604db508e4b3eb380fce6d5154bcb3a4d4bc1d038e2b260abf27ab13b3e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":84,"domain":"FORENSICS","authority_tier":0,"chunk_seq":341,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p85-342', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.1 A pplication Components', 85, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Applications that are designed to split their code among multiple hosts typically use application protocols for communications between hosts.116  Ubiquitous types of applications, such as e-mail and Web, use well-known, standardized application protocols to facilitate interoperability among different components. For example, nearly every e-mail client program is compatible with nearly every e-mail server program because they are based on the same application protocol standards.  However, a program based on a standard might add proprietary features or violate the standard in some way, especially if the standard is not exhaustively detailed.  If interoperability with other applications is not a concern (or not desirable) and the same party is creating all application components, non-standard protocols are often used. As described throughout Section 7.1, applications may have many different components that operate together.  In addition, an application may be dependent on one or more other applications.  For example, many e-commerce application clients run within Web browsers.  Many applications also rely on OS services, such as printing and DNS lookups (to find the IP addresses of application servers and other devices).  Applications vary widely in complexity, from a simple utility program such as a calculator to a large e-commerce application that may involve many thousands of components and have millions of users.', 'vec_doc-04-nist-sp-800-86-p85-342', 0, 376, 'v2.1.0', '24fc7870b9cc56116687b5e981ae84e80a09428729a730ed7ebba7fd2233cb5d', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.1 A pplication Components","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"FORENSICS","authority_tier":0,"chunk_seq":342,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.1 A pplication Components"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p85-343', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 85, 'Applications exist for nearly every purpose imaginable. Although forensic techniques can be applied to any application, certain types of applications are more likely to be the focus of forensic analysis, including e-mail, Web usage, interactive messaging, file sharing, document usage, security applications, and data concealment tools. Nearly every computer has at least a few applications installed from these categories. The following sections describe each of these types of applications in more detail. 7.2.1 E-mail E-mail has become the predominant means for people to communicate electronically. Each e-mail message consists of a header and a body. The body of the e-mail contains the actual content of the message, such as a memorandum or a personal letter. The header of the e-mail includes various pieces of information regarding the e-mail.', 'vec_doc-04-nist-sp-800-86-p85-343', 0, 213, 'v2.1.0', 'c2ba97a78ee6ce75c5655e73dbbeee31494bdfc56bb101a9609431d464ba4ce5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"FORENSICS","authority_tier":0,"chunk_seq":343,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p85-344', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 85, 'By default, most e-mail client applications display only a few header fields for each message: the senders and recipients e-mail addresses, the date and time the message was sent, and the subject of the message. However, the header typically includes several other fields, including the following:117 ! Message ID ! Type of e-mail client used to create the message ! Importance of the message, as indicated by the sender (e.g., low, normal, high) ! Routing informationwhich e-mail servers the message passed through in transit and when each server received it ! Message content type, which indicates whether the e-mail content simply consists of a text body or also has file attachments, embedded graphics, etc. E-mail client applications are used to receive, store, read, compose, and send e-mails.', 'vec_doc-04-nist-sp-800-86-p85-344', 0, 201, 'v2.1.0', '881bf234b8ec6e502bd7db3c87241f5a7deb68f0dc450d085435af346548d050', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"FORENSICS","authority_tier":0,"chunk_seq":344,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p85-345', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 85, 'Most e-mail clients also provide an address book that can hold contact information, such as e-mail addresses, names, and 116  Applications that are designed to keep all code on a single host typically do not need to use any application protocols. 117  Most e-mail clients have a configuration setting that specifies whether full or partial e-mail headers should be displayed. 7-5', 'vec_doc-04-nist-sp-800-86-p85-345', 0, 95, 'v2.1.0', '98f904fe8c70feea96ee53e8765e0567926c6942fffab34e333c6d4d2e46d415', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":85,"domain":"FORENSICS","authority_tier":0,"chunk_seq":345,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p86-346', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 86, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE phone numbers. Encryption programs are sometimes used in conjunction with e-mail clients to encrypt an e-mails body and/or attachments. When a user sends an e-mail, it is transferred from the e-mail client to the server using SMTP. If the sender and recipient of the e-mail use different e-mail servers, the e-mail is then routed using SMTP through additional e-mail servers until it reaches the recipients server. Typically, the recipient uses an e- mail client on a separate system to retrieve the e-mail using Post Office Protocol 3 (POP3) or Internet Message Access Protocol (IMAP); in some cases, the e-mail client may be on the destination server (e.g., a multi-user UNIX system). The destination server often performs checks on the e-mails before making them available for retrieval, such as blocking messages with inappropriate content (e.g., spam, virus).', 'vec_doc-04-nist-sp-800-86-p86-346', 0, 233, 'v2.1.0', '27c0c5f1e64854ea7a4b800df5371fddd1af365ff323e14511c10fb80fbac9f9', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"FORENSICS","authority_tier":0,"chunk_seq":346,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p86-347', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 86, 'From end to end, information regarding a single e-mail message may be recorded in several placesthe senders system, each e-mail server that handles the message, and the recipients system, as well as antivirus, spam, and content filtering servers.118 7.2.2 Web Usage Through Web browsers, people access Web servers that contain nearly every type of data imaginable. Many applications also offer Web-based interfaces, which are also accessed through Web browsers. Because they can be used for so many purposes, Web browsers are one of the most commonly used applications. The basic standard for Web communications is HTTP; however, HTTP can contain many types of data in a variety of standard and proprietary formats. HTTP is essentially the mechanism for transferring data between the Web browsers and the Web servers.119 Typically, the richest sources of information regarding Web usage are the hosts running the Web browsers.', 'vec_doc-04-nist-sp-800-86-p86-347', 0, 233, 'v2.1.0', '32fb3804fe93c276e861c4f2f541042547c5c35ffbe575a8e1f76cebbf7504a3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"FORENSICS","authority_tier":0,"chunk_seq":347,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p86-348', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 86, 'Information that may be retrieved from Web browsers include a list of favorite Web sites, a history (with timestamps) of Web sites visited, cached Web data files, and cookies (including their creation and expiration dates). Another good source of Web usage information is Web servers, which typically keep logs of the requests they receive. Data that is often logged by Web servers for each request includes a timestamp; the IP address, Web browser version, and OS of the host making the request; the type of request (e.g., read data, write data); the resource requested; and the status code. The response to each request includes a three-digit status code that indicates the success or failure of the request. For successful requests, the status code explains what action was performed; for failures, the status code explains why the request failed. Several other types of devices and software, in addition to Web browsers and servers, might also log related information.', 'vec_doc-04-nist-sp-800-86-p86-348', 0, 243, 'v2.1.0', '682ff4ac4a215dbdb4631e17f9d12ed8e8bbe1e768e0173a1bace57297829f0a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"FORENSICS","authority_tier":0,"chunk_seq":348,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p86-349', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 86, 'For example, Web proxy servers and application proxying firewalls might perform detailed logging of HTTP activity, with a level of detail similar to that of Web server logs.120  Routers, non-proxying firewalls, and other network devices might log the basic aspects of HTTP network connections, such as source and destination IP addresses and ports. Organizations that use Web content monitoring and filtering services might find useful data in the services logs, particularly regarding denied Web requests. 118  For more information on e-mail services, see NIST SP 800-45, Guidelines on Electronic Mail Security, available for download from http://csrc.nist.gov/publications/nistpubs/index.html. 119  For a detailed description of the current HTTP standard, see RFC 2616, Hypertext Transfer ProtocolHTTP/1.1, available at http://www.ietf.org/rfc/rfc2616.txt.', 'vec_doc-04-nist-sp-800-86-p86-349', 0, 215, 'v2.1.0', 'ce7c92a87c65d1bea2bbf89fd184b439a252fe1648d5de32eba80e3700c7cc07', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"FORENSICS","authority_tier":0,"chunk_seq":349,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p86-350', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 86, 'Also, see NIST SP 800-44, Guidelines on Securing Public Web Servers, for additional information on Web services; it is available for download from http://csrc.nist.gov/publications/nistpubs/index.html. 120  Typically, proxies cannot log the details of SSL or TLS-protected HTTP requests, because the requests and the corresponding responses pass through the proxy encrypted, which conceals their contents. 7-6', 'vec_doc-04-nist-sp-800-86-p86-350', 0, 103, 'v2.1.0', '552dea1c289b038e7685d210f46c67aa37663fd3482417e7195987637485cda8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":86,"domain":"FORENSICS","authority_tier":0,"chunk_seq":350,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p87-351', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 87, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE 7.2.3 7.2.4 Interactive Communications Unlike e-mail messages, which typically take minutes to go from sender to recipient, interactive communications services provide real-time (or near-real-time) communications. Types of applications commonly used for interactive communications include the following: ! Group Chat. Group chat applications provide virtual meeting spaces where many users can share messages at once. Group chat applications typically use a client/server architecture. The most popular group chat protocol, Internet Relay Chat (IRC), is a standard protocol that uses relatively simple text-based communications.121  IRC also provides a mechanism for users to send and receive files. ! Instant Messaging Applications. IM applications are either peer-to-peer, allowing users to send text messages and files directly to each other, or client/server, passing messages and files through a centralized server.', 'vec_doc-04-nist-sp-800-86-p87-351', 0, 246, 'v2.1.0', '61deef9f063748644bb3acbc62eed5fcd8f8577a72dd9fb071cf52611533d8da', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"FORENSICS","authority_tier":0,"chunk_seq":351,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p87-352', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 87, 'IM application configuration settings may contain user information, lists of users that the user has communicated with, file transfer information, and archived messages or chat sessions. There are several major Internet-based IM services, each of which uses its own proprietary communications protocols. Several companies also offer enterprise IM products that are run within an organization. Such products are often integrated to some extent with the organizations e-mail services and can be used only by authenticated e-mail users. ! Audio and Video. As the capacity of networks continues to increase, conducting real-time video and audio communications across computer networks also becomes more common.', 'vec_doc-04-nist-sp-800-86-p87-352', 0, 177, 'v2.1.0', '928b1368f80a32553d0d5b7987e1e07f71cdcbcef4ab2a77c9b073463c65a524', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"FORENSICS","authority_tier":0,"chunk_seq":352,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p87-353', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 87, 'Technologies such as Voice over IP (VoIP) permit people to conduct telephone conversations over networks such as the Internet.122  Some audio implementations provide computer-based service from end to end, whereas others are only partially computer-based, with an intermediate server converting the communications between computer networks and standard phone networks. Many audio technologies are primarily peer-to-peer applications. Video technologies can be used to hold teleconferences or to have video phone communications between two individuals. Commonly used protocols for audio and video communications include H.323 and Session Initiation Protocol (SIP).123 File Sharing Users can share files through many different programs. As described previously in this section, e-mail, group chat programs, and IM software all offer the ability to send and receive particular files. However, these programs generally do not allow a recipient to browse through files and to choose the files to transfer.', 'vec_doc-04-nist-sp-800-86-p87-353', 0, 251, 'v2.1.0', '6ef282c7cf1fa19a1d99b48e09e5ac35b1b3b8f6470415432cbcf5d1f1827c07', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"FORENSICS","authority_tier":0,"chunk_seq":353,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p87-354', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 87, 'Full-fledged file sharing programs and protocols are needed for this level of functionality. File sharing programs can be grouped by architecture, as follows: ! Client/Server. Traditional file sharing services use client/server architectures, with a central file server containing a repository of files. Clients can use the server by initiating connections to it, authenticating to it (if required), reviewing the list of available files (if needed), then transferring files to or from the server. Some commonly used client/server file sharing services are FTP, Network File Sharing (NFS), Apple Filing Protocol (AFP), and Server Message Block (SMB).124 121  The original standard for IRC is documented in RFC 1459, Internet Relay Chat Protocol, available at http://www.ietf.org/rfc/rfc1459.txt. RFCs 2810 through 2813 contain additional information that supplements RFC 1459.', 'vec_doc-04-nist-sp-800-86-p87-354', 0, 219, 'v2.1.0', 'a38c78356162033538ef28e003eb361693afbfeb8c46cb5b29ac85dfd7350fff', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"FORENSICS","authority_tier":0,"chunk_seq":354,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p87-355', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 87, '122  For more information on VoIP, see NIST SP 800-58, Security Considerations for Voice Over IP Systems, available at http://csrc.nist.gov/publications/nistpubs/index.html. 123  The standard for SIP is available as RFC 3261, SIP: Session Initiation Protocol, located at http://www.ietf.org/rfc/rfc3261.txt. 124  More information on SMB is available from http://samba.anu.edu.au/cifs/docs/what-is-smb.html. 7-7', 'vec_doc-04-nist-sp-800-86-p87-355', 0, 103, 'v2.1.0', '7e7aa102841c0fbf1d2955170233925b11369e8bd30cf38ff460b80c16cc9c93', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":87,"domain":"FORENSICS","authority_tier":0,"chunk_seq":355,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p88-356', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 88, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE These are standardized protocols that do not protect the confidentiality of the data in transit, including any supplied authentication credentials, such as passwords. Secure alternatives, such as Secure FTP (SFTP) and Secure Copy (scp), encrypt their network communications. Most OSs have built-in file sharing clients (e.g., FTP, SMB), but users can also install various third-party programs that provide similar functionality. ! Peer-to-Peer. Most peer-to-peer file sharing services are primarily used to trade music, graphics, or software across the Internet. Unlike client/server file sharing, in which a single server holds the file repository, peer-to-peer file sharing is distributed, with files located on many different hosts.', 'vec_doc-04-nist-sp-800-86-p88-356', 0, 200, 'v2.1.0', '3f9521358c642b8d937d98c90d313f712cfcf5d282d04ca90d06d19e9970d0f6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"FORENSICS","authority_tier":0,"chunk_seq":356,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p88-357', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 88, 'Peer-to-peer file sharing services typically have a central server that gives clients information on where other clients are located, but the server does not participate in the transmission of files or file information. Peer-to-peer file sharing services typically require no user authentication. All file browsing and transfers occur directly between the clients (peers). Users typically can choose from several client programs when using a particular service. Although most services allow each user to control which files are shared on their system, services known as encrypted peer-to-peer work by storing others files on an encrypted portion of each users hard drive, and giving users no control over or knowledge of what is stored in that area of their own systems.', 'vec_doc-04-nist-sp-800-86-p88-357', 0, 193, 'v2.1.0', 'ebd98beb1b23b0059f79e2fe2702d72d0ce37fede4400273e939047f254cc1df', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"FORENSICS","authority_tier":0,"chunk_seq":357,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p88-358', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 88, 'Anonymous peer-to-peer services send requested files through multiple intermediate hosts instead of simply sending them from source to destination, with the goal of making it very difficult to identify the true source or destination of any given file. 7.2.5 7.2.6 7.2.7 Document Usage Many users spend much of their time working with documents, such as letters, reports, and charts. Documents may contain any type of data, so they are often of interest to analysts. The class of software used for creating, viewing, and editing such documents is known as office productivity applications. This includes word processor, spreadsheet, presentation, and personal database software.', 'vec_doc-04-nist-sp-800-86-p88-358', 0, 170, 'v2.1.0', 'd2e14bd1fb0c6a73fcf669d093dd4ecbdde63e72891fe015eaafcb0c1a8bc969', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"FORENSICS","authority_tier":0,"chunk_seq":358,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p88-359', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 88, 'Documents often have user or system information embedded in them, such as the name or username of the person who created or most recently edited the document, or the license number of the software or the MAC address of the system used to create the document.125 Security Applications Hosts often run one or more security applications that attempt to protect the host from misuse and abuse occurring through commonly used applications, such as e-mail clients and Web browsers. Some commonly used security applications are antivirus software, spyware detection and removal utilities, content filtering (e.g., anti-spam measures), and host-based intrusion detection software. The logs of security applications may contain detailed records of suspicious activity and may also indicate whether a security compromise occurred or was prevented.', 'vec_doc-04-nist-sp-800-86-p88-359', 0, 210, 'v2.1.0', '04f506bb3d697663a9de979206ae6f6abd5aa5370071d6882bc9f98f02e41de4', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"FORENSICS","authority_tier":0,"chunk_seq":359,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p88-360', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 88, 'If the security application is part of an enterprise deployment, such as centrally managed and controlled antivirus software, logs may be available both on individual hosts and on a centralized application log. Data Concealment Tools Some people use tools that conceal data from others. This might be done for benign purposes, such as protecting the confidentiality and integrity of data against access by unauthorized parties, or for malicious purposes, such as concealing evidence of improper activities. Examples of data concealment tools include file encryption utilities, steganographic tools, and system cleanup tools. System cleanup tools are 125  One example of an office productivity application that might capture user or system information within a document is Microsoft Office. More information on this topic is available from Microsoft Knowledge Base article 834427, located at http://support.microsoft.com/default.aspx?scid=kb;en-us;834427. 7-8', 'vec_doc-04-nist-sp-800-86-p88-360', 0, 240, 'v2.1.0', '855658c0f6a2f22cc4591662e451e4affd218e6e7b0f84af62b54a003a488b1b', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":88,"domain":"FORENSICS","authority_tier":0,"chunk_seq":360,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p89-361', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.2 Types of Applications', 89, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE special-purpose software that removes data pertaining to particular applications, such as Web browsers, as well as data in general locations, such as temporary directories.  The use of most data concealment tools is unlikely to be captured in logs.  Analysts should be aware of the capabilities of these tools so that they can identify such tools on a system and recognize the tools effects.', 'vec_doc-04-nist-sp-800-86-p89-361', 0, 114, 'v2.1.0', 'a6bcb68159a88065668eb31179933284ed2e9b808927f48388cda5701654b265', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.2 Types of Applications","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"FORENSICS","authority_tier":0,"chunk_seq":361,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.2 Types of Applications"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p89-362', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.3 C ollecting Application Data', 89, 'As described in Section 7.1, application-related data may be located within filesystems, volatile OS data, and network traffic. Sections 4.2, 5.2, and 6.3 contain specific information about collecting data from these respective sources. The types of application data that these sources may contain are as follows: ! Filesystems. Filesystems may contain many types of files related to applications, including executable files and scripts, configuration files, supporting files (e.g., documentation), logs, and data files. ! Volatile OS Data. Volatile OS data may contain information about network connections used by applications, the application processes running on a system and the command line arguments used for each process, and the files held open by applications, as well as other types of supporting information. ! Network Traffic. The most relevant network traffic data involves user connections to a remote application and communications between application components on different systems.', 'vec_doc-04-nist-sp-800-86-p89-362', 0, 250, 'v2.1.0', '4b4ef9de742262bdf3d5e72e43c3d332dc2e247d634f8dcf314ea9fba3aac119', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.3 C ollecting Application Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"FORENSICS","authority_tier":0,"chunk_seq":362,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.3 C ollecting Application Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p89-363', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.3 C ollecting Application Data', 89, 'Other network traffic records might also provide supporting information, such as network connections for remote printing from an application, and DNS lookups by the application client or other components to resolve application components domain names to IP addresses. Analysts often face a major challenge in determining which data should be collected. In many cases, the analyst must first decide which application is of interest. For example, it is common to have multiple Web browsers and e-mail clients installed on a single system. If analysts are asked to collect data regarding an individuals use of the organizations e-mail services, they need to be mindful of all the ways in which the individual could have accessed those services. The users computer could contain three different e-mail clients, plus two Web browsers that could be used to access a Web-based e-mail client provided by the organization.', 'vec_doc-04-nist-sp-800-86-p89-363', 0, 230, 'v2.1.0', 'ecff036b0d29752bb334db76ac34333d210c0ddd83d086969c46dbbd76ad8619', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.3 C ollecting Application Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"FORENSICS","authority_tier":0,"chunk_seq":363,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.3 C ollecting Application Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p89-364', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.3 C ollecting Application Data', 89, 'For the users computer, analysts could simply collect all data from the computer and then determine during the examination process which clients were actually used for e-mail. However, there are many potential data sources aside from the users computer, and these sources might vary based on the client that was used. For example, use of the Web-based client might have been recorded in Web server, firewall, IDS, and content monitoring software logs, as well as in Web browser history files, Web browser caches, cookies, and personal firewall logs. In some situations, collecting the necessary data might involve identifying all components of the application, deciding which were most likely to be of interest (based on the details of the situation and the need), finding the location of each component, and collecting data from those components. Section 8 contains examples that illustrate the complexity of identifying components and prioritizing data collection for applications.', 'vec_doc-04-nist-sp-800-86-p89-364', 0, 247, 'v2.1.0', 'ab021dfb87bdffbd5cee474d7528fc0cc90328bbc025f32ce36edb67e008e3e3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.3 C ollecting Application Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"FORENSICS","authority_tier":0,"chunk_seq":364,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.3 C ollecting Application Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p89-365', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.4 Examining and Analyzing Application Data', 89, 'Examining and analyzing application data largely consists of looking at specific portions of application datafilesystems, volatile OS data, and network trafficusing the tools and techniques described in Sections 4.3 and 4.4, 5.3, and 6.4, respectively.  Examination and analysis might be hindered if the application were custom, such as a program written by the user; the analyst is unlikely to have any knowledge of such an application.  Another possible issue in examination involves use of application- based security controls, such as data encryption and passwords.  Many applications use such security controls to thwart unauthorized access to sensitive data by authorized users. 7-9', 'vec_doc-04-nist-sp-800-86-p89-365', 0, 173, 'v2.1.0', 'c79f44ff4a8df7d66dad5d7ec5133d59407c037c227caff5ee072c89d0b60e47', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.4 Examining and Analyzing Application Data","subsection":"UNKNOWN","table_id":null,"page":89,"domain":"FORENSICS","authority_tier":0,"chunk_seq":365,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.4 Examining and Analyzing Application Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p90-366', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.4 Examining and Analyzing Application Data', 90, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE In some cases, analysts bring together pertinent application data from several varied application data sources; this is largely a manual process.  Detailed analysis of application-related events and event reconstruction usually require a skilled and knowledgeable analyst who understands the information presented by all the sources.  The analyst can review the results of the examination and analysis of individual application data sources and see how the information fits together.  Tools that may be helpful to analysts include security event management software (described in Section 6.2.5), which can correlate some application-related events among multiple data sources, and log analysis software (including some types of host-based intrusion detection software), which can be run against certain types of logs to identify suspicious activity.  Section 8 shows how data from multiple types of sources can be correlated through analysis to reach a more accurate and comprehensive view of what occurred.', 'vec_doc-04-nist-sp-800-86-p90-366', 0, 268, 'v2.1.0', '35210a1afc1d41eab8fbbf5101576903add7c45fdc5ebac637ad17d25a14af7f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.4 Examining and Analyzing Application Data","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"FORENSICS","authority_tier":0,"chunk_seq":366,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.4 Examining and Analyzing Application Data"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p90-367', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7.5 Re commendations', 90, 'The key recommendations presented in this section for using data from applications are as follows: ! Analysts should consider all possible application data sources.  Application events might be recorded by many different data sources.  In addition, applications might be used through multiple mechanisms, such as multiple client programs installed on a system and Web-based client interfaces.  In such situations, analysts should identify all application components, decide which are most likely to be of interest, find the location of each component of interest, and collect the data. ! Analysts should bring together application data from various sources.  The analyst should review the results of the examination and analysis of individual application data sources and determine how the information fits together, to perform a detailed analysis of application-related events and event reconstruction. 7-10', 'vec_doc-04-nist-sp-800-86-p90-367', 0, 227, 'v2.1.0', '3de2b2acd818503119e776dd4ccdd8c728d0dc07b6efb3bfe90cadef5241ac0e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7.5 Re commendations","subsection":"UNKNOWN","table_id":null,"page":90,"domain":"FORENSICS","authority_tier":0,"chunk_seq":367,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7.5 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p91-368', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8. Using Data from Multiple Sources', 91, 'Sections 4 through 6 describe the collection, examination, and analysis of data from three data source categories: data files, OSs, and network traffic.  The techniques and processes for collecting, examining, and analyzing the data in these categories are fundamentally different.  Section 7 describes the collection, examination, and analysis of application data, which brings together the three data source categories.  For example, many applications use data files, alter the configuration of OSs, and generate network traffic. Many situations, such as computer security incidents, can be handled most effectively by analyzing multiple types of data sources and correlating events across sources. This section of the guide presents two examples of the use of multiple data sources during digital forensics.  Each example describes a scenario, indicates a specific need for forensic analysis, and presents an explanation of how the forensic process might be performed.  The explanations also illustrate how complex the process can be.  The examples presented in this section are as follows: ! Determining which worm has infected a system and identifying the worms characteristics ! Reconstructing the sequence of cyber events involving a threatening e-mail.', 'vec_doc-04-nist-sp-800-86-p91-368', 0, 316, 'v2.1.0', 'a9dc431fe6b27df130035a998d2deda25b280b9d48fd9921ed872b7b0276e057', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8. Using Data from Multiple Sources","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"FORENSICS","authority_tier":0,"chunk_seq":368,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8. Using Data from Multiple Sources"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p91-369', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 91, 'An organizations help desk receives several calls in a short time from users complaining about a particular server providing slow responses. The help desk sends a trouble ticket to the monitoring group. That groups network IDSs have recently reported several unusual alerts involving the server, and the analyst who reviewed the alerts believes that they may be accurate. The data in the alerts indicates that some suspicious activity was directed at the server, and the server is now generating identical activity directed at other systems. The intrusion detection analysts initial hypothesis is that a worm may have attacked a vulnerable network service and infected the server, which is now attempting to infect other systems. The monitoring group contacts the incident handler on duty to investigate the possible incident on the server.', 'vec_doc-04-nist-sp-800-86-p91-369', 0, 211, 'v2.1.0', '0c926c06d58f95c7f8297ec2eeb8ba37e29fb86965765e35882b9a30118a4b63', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"FORENSICS","authority_tier":0,"chunk_seq":369,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p91-370', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 91, 'For the incident, this particular incident handlers role is to determine the type of worm that has infected the system and to identify the distinguishing characteristics of the worm. This information is critical to the incident response teams ability to effectively perform containment, eradication, and recovery activities and to prevent other systems within the organization from becoming infected. If the incident handlers investigation shows that the incident was probably caused by something other than a worm, the characteristics the handler identifies should be very helpful in determining what actually occurred. Information regarding this incident may be recorded in several different places. The incident handler should check the data sources that are most likely to have relevant information first, based on the handlers previous experience with the data sources and the initial information available regarding the incident.', 'vec_doc-04-nist-sp-800-86-p91-370', 0, 235, 'v2.1.0', '2ceff4231f9615f811f852ab9a12ed8bf528e3de55f3232240887fb6b35c9e62', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"FORENSICS","authority_tier":0,"chunk_seq":370,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p91-371', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 91, 'For example, because network IDS sensors saw the suspicious activity, other network-based data sources monitoring the same network segment might also contain relevant information. If the organization uses security event management or network forensic analysis tool software, which bring together data from many different sources, the incident handler may be able to gather all necessary information just by running a few queries from the SEM or NFAT console. If a centralized source of data is not available, the handler should check individual potential sources of attack characteristics, such as the following: ! Network IDS. Because the initial reports of the incident were generated by network IDS sensors, it is very likely that the network IDS data contains information on the basic characteristics of the 8-1', 'vec_doc-04-nist-sp-800-86-p91-371', 0, 204, 'v2.1.0', 'c6c107f953d295b881966da75306c0ec0bd961276f28832b843d1e9b333d1be7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":91,"domain":"FORENSICS","authority_tier":0,"chunk_seq":371,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p92-372', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 92, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE network activity. At a minimum, the data should indicate which server was attacked and on what port number, which indicates which network service was targeted. Identifying the service is very important to finding the exploited vulnerability and developing a mitigation strategy to prevent similar incidents from occurring on other systems. From an analysis standpoint, knowing the targeted service and port number is also important because the information can be used to identify other likely data sources and to query them for relevant information. Some network IDS deployments may record additional useful information, such as application data (e.g., Web requests and responses, e-mail headers and file attachment names). The application data may contain words, phrases, or other character sequences that are associated with a particular worm. ! Network-Based Firewall.', 'vec_doc-04-nist-sp-800-86-p92-372', 0, 234, 'v2.1.0', '2df6389aeada037159e6952fee95fec2c94728d0aab9779ad44276b79908086f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"FORENSICS","authority_tier":0,"chunk_seq":372,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p92-373', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 92, 'Firewalls are typically configured to log blocked connection attempts, including the intended destination IP address and port. Accordingly, firewalls might have records of worm activity that they blocked. Some worms attempt to exploit multiple services or service ports; firewall records might show that a worm has actually tried to establish connections to at least four different port numbers, but that the firewall blocked connections using three of the ports. This information could be useful in identifying the worm. If firewalls are configured to record permitted connections, their logs may show which hosts within the organization have received worm traffic or been infected and generated their own worm traffic. This is particularly useful for situations in which network IDS sensors do not monitor all traffic that reaches the firewall.', 'vec_doc-04-nist-sp-800-86-p92-373', 0, 212, 'v2.1.0', 'f8cf2a6d65fc6db159c3c0e0d8d741e63ec744abee037254d3c0969bd1b62a10', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"FORENSICS","authority_tier":0,"chunk_seq":373,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p92-374', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 92, 'Other perimeter devices that the worm traffic may have passed through, such as routers, VPN gateways, and remote access servers, may record information similar to that logged by network-based firewalls. ! Host IDS and Firewall. IDS and firewall products running on the infected system may contain more detailed information than network IDS and firewall products. For example, a host IDS can identify changes to files or configuration settings on the host that were performed by a worm. This information is helpful not only in planning containment, eradication, and recovery activities by determining how the worm has affected the host, but also in identifying which worm infected the system. However, because many worms disable host-based security controls and destroy log entries, data from host IDS and firewall software may be limited or missing. If the software was configured to forward copies of its logs to centralized log servers, then queries to those servers may provide some information. !', 'vec_doc-04-nist-sp-800-86-p92-374', 0, 250, 'v2.1.0', 'd7d1e2692ad6708d519f42b4f04e12e51d5f801e1db51f856bdf54f89ef9a9bc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"FORENSICS","authority_tier":0,"chunk_seq":374,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p92-375', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 92, 'Antivirus Software. Because the threat reached the server and successfully breached it, it is unlikely that network or host-based antivirus software contains any record of the threat. If antivirus software had detected the worm, it should have stopped it. However, it is possible that the antivirus software saw the worm but somehow failed to stop it, or that the antivirus software was updated since the infection with new signatures that can recognize the worm. The incident handler can also scan the server for worms using a current version of antivirus software from a forensic toolkit. ! Application Logs. If the worm used a common application protocol, such as HTTP or SMTP, information regarding it might be recorded in several places, such as application server logs, proxy servers, and application-specific security controls. Less common application protocols probably have information only in the application server logs.', 'vec_doc-04-nist-sp-800-86-p92-375', 0, 233, 'v2.1.0', '9f6ecbe90206e36bc8dde59c2a26863d598457c8d6e3098c5f3db80f34957057', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"FORENSICS","authority_tier":0,"chunk_seq":375,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p92-376', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 92, 'Application logs record extensive details on the application-specific characteristics of the activity, and are particularly helpful at identifying attack characteristics from less common applications. The goal in the initial information gathering effort is to identify enough characteristics for positive identification of the worm. This can be challenging, particularly for worms that have dozens of variants; these variants often have similar characteristics but have different effects on systems. Analysts can perform queries on antivirus vendors malware databases, searching for identified characteristics such as 8-2', 'vec_doc-04-nist-sp-800-86-p92-376', 0, 156, 'v2.1.0', '2effff52c8d17c65791d5575634e53d29713d1d1f3fa0f37b74394ce6eae35c6', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":92,"domain":"FORENSICS","authority_tier":0,"chunk_seq":376,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p93-377', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 93, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE product name, service name or port number, text strings within the malware, and files or settings modified on the target.126  Virtually any instance of malware, other than the latest threats (e.g., released in the past several hours), is likely to be included in major malware databases. Each database entry typically contains extensive information on how the worm spreads, how it affects systems (e.g., what changes it makes), and how it can be eradicated, including measures concerning prevention of infections on other systems. If a search of malware databases does not lead to identification of the worm, then the incident handler may need to perform additional research and analysis to discover the information usually provided by malware database entries.', 'vec_doc-04-nist-sp-800-86-p93-377', 0, 207, 'v2.1.0', '64171eb9d63c795ef783c9d540f8aba70d93599f4cac13ab9057cff302f1cac8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"FORENSICS","authority_tier":0,"chunk_seq":377,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p93-378', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 93, 'Although the organization can send a copy of the worm to the organizations antivirus vendor for analysis and identification, the organization should perform its own analysis in the meantime, since the time frame for the vendors response is unknown. To gather more information, the analyst can examine the infection through the following methods: ! Current State of the Host. The analyst can examine the host to look at several aspects of its current state. In this case, it is probably most effective to examine the network connections listing to identify unusual connections (e.g., large number, unexpected port number usage, unexpected hosts) and unexpected listening ports (e.g., backdoors created by the worm). Other steps that may be useful include identifying unknown processes in the running processes list and examining the hosts logs to reveal any unusual entries that may be related to the infection. ! Hosts Network Activity.', 'vec_doc-04-nist-sp-800-86-p93-378', 0, 235, 'v2.1.0', '7217b41b9bda2646d20d17c92d602c06b440e13d6e2488c26489de509f4b5635', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"FORENSICS","authority_tier":0,"chunk_seq":378,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p93-379', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 93, 'The analyst can collect worm traffic being generated by the infected server through a packet sniffer and protocol analyzer. This may provide enough additional information regarding the characteristics of the worm to enable the analyst to locate it in major malware databases. Worm incidents often necessitate as rapid a response as possible, because an infected system may be attacking other systems inside and outside the organization. In addition, worms often install backdoors and other tools on systems that permit attackers to gain remote access to infected systems, which can create additional damage. Accordingly, organizations may choose to disconnect infected systems from networks immediately, instead of performing data collection for the host first.', 'vec_doc-04-nist-sp-800-86-p93-379', 0, 191, 'v2.1.0', '42fc78aed85c607c7a1cf3d26a204fdbc5ecce9711a4cf53e7c72ea462df5083', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"FORENSICS","authority_tier":0,"chunk_seq":379,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p93-380', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.1 Suspected Network Service Worm Infection', 93, 'This step may make it considerably more difficult for analysts to identify a worm and to determine its effects on systemsfor example, if systems are disconnected from the network, network activity and certain aspects of the host state will not be available. In such cases, the analyst may need to perform a more detailed forensic analysis of the server, such as collecting its filesystems and examining them for signs of malicious activity (e.g., altered system executables) to determine exactly what happened to the server. The analyst can also examine non-volatile characteristics of the servers OS, such as looking for administrative-level user accounts and groups that may have been added by the worm. Ultimately, the analyst should gather enough information to identify the worms behavior in sufficient detail to enable the incident response team to act effectively to contain, eradicate, and recover from the incident.', 'vec_doc-04-nist-sp-800-86-p93-380', 0, 232, 'v2.1.0', 'e3694e0d370b0dfcca6bc887f59e17b9660001c845649397fdc4560204acfa0c', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.1 Suspected Network Service Worm Infection","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"FORENSICS","authority_tier":0,"chunk_seq":380,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.1 Suspected Network Service Worm Infection"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p93-381', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 93, 'An incident handler responds to a request for assistance with an internal investigation.  An employee has been accused of sending a threatening e-mail to another employee through the organizations e-mail system.  The incident handler has been asked to help investigators find all data sources that may contain 126  Malware databases are maintained by several vendors, including Computer Associates (http://www3.ca.com/securityadvisor/virusinfo/default.aspx), F-Secure (http://www.f-secure.com/virus-info/), Network Associates (http://vil.nai.com/vil/default.aspx), Sophos (http://www.sophos.com/virusinfo/analyses/), Symantec (http://securityresponse.symantec.com/avcenter/vinfodb.html), and Trend Micro (http://www.trendmicro.com/vinfo/virusencyclo/). 8-3', 'vec_doc-04-nist-sp-800-86-p93-381', 0, 190, 'v2.1.0', '34f185de9b33f9492c8717df4d1f9565287a064dd03f85d59367141aeed66383', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":93,"domain":"FORENSICS","authority_tier":0,"chunk_seq":381,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p94-382', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 94, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE records of the e-mail. This information will be helpful to investigators in determining who sent the e- mail. Because e-mail can be forged easily, it is important to use all available data sources to reconstruct the sequence of events for creating, sending, and receiving the e-mail. Also, the incident handler needs to perform all work using forensically sound tools, techniques, and procedures, and to document all actions performed. The threatening e-mail is key to the investigation, and its header contains the most important information to the incident handler. It should contain the domain name and the IP address of the host that sent the e- mail, the type of e-mail client used to send the e-mail, the e-mails message ID, and the date and time the e-mail was sent.', 'vec_doc-04-nist-sp-800-86-p94-382', 0, 210, 'v2.1.0', '6cfd1148f758cdc179662640d8aff20c121e43038bfc96fa365c35457ece2e15', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"FORENSICS","authority_tier":0,"chunk_seq":382,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p94-383', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 94, 'The e-mail header should also list each e-mail server (domain name and IP address) that the message passed through and the date and time each server processed the e-mail.127  Because the e-mail was supposedly sent using the organizations e-mail system, the e-mail header should only list systems within the organization. Assuming that this is the case, the incident handler can check each system on the list for correlating information. Because of the importance of the threatening e-mail, the incident handler should focus first on collecting a copy of the e-mail, including its header. Depending on the type of e-mail client used by the recipient and its configuration, the e-mail may have been downloaded to the recipients workstation, or it may remain on the e-mail server. It is also possible that the e-mail is still stored in both locations.', 'vec_doc-04-nist-sp-800-86-p94-383', 0, 213, 'v2.1.0', '6f821fe58ce8744939c9996aa7e03350ededd140868fa123eef8f3c6d195947e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"FORENSICS","authority_tier":0,"chunk_seq":383,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p94-384', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 94, 'The incident handler should collect copies of the e-mail from multiple sources, if possible, to confirm that the content of the e-mail has been unchanged in transit or by the recipient. After reviewing the header, the incident handler should next gather more information about the sending of the e-mail. The header should list the IP address and the e-mail client used by the sender; the incident handler should determine which host was using that IP address at the time the e-mail was sent. There are three possibilities for the IP address: ! Local E-mail Client. In this case, the incident handler should be able to use network records, such as DHCP logs, to identify the desktop, laptop, PDA, or other device used to send the e-mail. The incident handler can then create images of the identified device and examine an image copy to look for malware and for records related to the e-mail.', 'vec_doc-04-nist-sp-800-86-p94-384', 0, 223, 'v2.1.0', '67a1fec41749a47733a67cd47d8a02e4fdcdb1a84afc135b5042a9a02ddc368a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"FORENSICS","authority_tier":0,"chunk_seq":384,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p94-385', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 94, 'For example, the e-mail client might be configured to keep a copy of each e-mail that it sends, or the user might have saved drafts of the e-mail message. If the message cannot be found intact on the system, collecting data from the devices memory and filesystems, including deleted and temporary files, might lead to the identification of fragments of the e-mail. In addition, security controls on the device, such as spam filtering and antivirus software, might have scanned the outgoing e-mail and logged a record of it. It is also possible, but unlikely, that a copy of the e-mail is stored on an e-mail server. In addition to looking for records of the e-mail on the local host, the incident handler should analyze the authentication records on the host to determine which user account was in use when the e-mail was sent. ! Server-Based E-mail Client. If the organization offers a server-based client, such as a Web- based e-mail interface, then the IP address may correspond to that server.', 'vec_doc-04-nist-sp-800-86-p94-385', 0, 250, 'v2.1.0', '17c1bea357cf08583a58b9605910f5154c3656dae6f00b667ef902d4651a992e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"FORENSICS","authority_tier":0,"chunk_seq":385,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p94-386', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 94, 'Typically, the use of such a server requires users to authenticate themselves, so there may be authentication records that indicate when the alleged sender logged on to the server and what IP address the users system was using. The incident handler can then determine which system was assigned that IP address at the time, perform bit stream imaging for the identified system, and examine a copy of 127  Within the e-mail header, these records are stored in reverse order, so the most recent record occurs first and the least recent record occurs last. If an e-mail has been forged, the false records are the least recent, so they should appear last in the header. 8-4', 'vec_doc-04-nist-sp-800-86-p94-386', 0, 168, 'v2.1.0', '9b25737180f4839d3a023362d684e1252baecf22566a876faa844991ed4b8bbe', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":94,"domain":"FORENSICS","authority_tier":0,"chunk_seq":386,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p95-387', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 95, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE the image for the malware and the e-mail. For example, temporary files from the Web browser may contain a copy of the e-mails contents. ! Spoofed. If the IP address was fabricatedfor example, if it is not a valid address within the organizations networksthe incident handler should rely on other data sources to identify the host that actually sent the e-mail message. The organizations e-mail servers are another likely source of information. Each of the server IP addresses listed in the e-mail header should contain some record of the e-mail, including the message ID value, which should facilitate quick identification of pertinent records. As mentioned previously, the final e-mail server in the list may contain a copy of the e-mail. Backups of that server may contain a copy of the e-mail, but only if it was held there for delivery for several hours or more.', 'vec_doc-04-nist-sp-800-86-p95-387', 0, 234, 'v2.1.0', 'd295e801cba2881daa82a1bfba6285b4e5a5908ecf90b70642dd5a69dc49f38f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"FORENSICS","authority_tier":0,"chunk_seq":387,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p95-388', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 95, 'Other services associated with e-mail, such as antivirus software and spam filters, may also contain basic records of e-mail activity, but are unlikely to contain many details. Another possible source of information is authentication records. Although few e-mail servers require users to authenticate to send e-mail, they typically do require authentication to deliver e-mail to users. Because users often send and receive e-mail during a single session, authentication logs may contain records for receiving e-mail that can be helpful in determining who may have sent a particular e-mail. Another possible source of information is a record of the network traffic generated by sending or receiving the e-mail. Packet sniffers or network forensic analysis tools that were monitoring network activity might have captured the activity, including the actual IP addresses of the sending or receiving hosts, the contents and header of the e-mail, and any associated authentication activity.', 'vec_doc-04-nist-sp-800-86-p95-388', 0, 246, 'v2.1.0', 'd17042b1508cf9017f89fe604c3eabbe107ccaa20564264385b4556f2e395fd2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"FORENSICS","authority_tier":0,"chunk_seq":388,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p95-389', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 95, 'Ultimately, the incident handler should identify the hosts that were used to send and receive the e-mail, as well as all intermediate hosts that transferred the e-mail from sender to receiver. The incident handler should collect copies of the e-mail and supporting information from each relevant host and, using the timestamps in records, should re-create the sequence of events from a cyber perspective. For example, a possible sequence might be as follows: A user logged on to a particular desktop computer at 8:37 a.m. At 10:02 a.m., the threatening e-mail was sent from that computer using its built-in e-mail client. The e- mail passed through three of the organizations e-mail servers and was stored on Server 4 to await retrieval by the intended recipient. The recipient user logged onto a particular laptop computer at 11:20 a.m. and downloaded e-mail, including the threatening e-mail, at 11:23 a.m.', 'vec_doc-04-nist-sp-800-86-p95-389', 0, 228, 'v2.1.0', '0efd2141e3dbb8726d29d8e74e59272d10021b58f625afd599960ad44f33d414', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"FORENSICS","authority_tier":0,"chunk_seq":389,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p95-390', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.2 T hreatening E-mail', 95, 'The contents of the e-mail on the recipients computer, as well as user-provided header fields (e.g., From, To, Subject), were identical to a copy saved in the Sent folder on the first users desktop computer. This information can be used as a basis for further investigation; although it documents cyber activities, it does not tell the whole story. For example, it cannot determine which person actually sent the e-mail from the desktop computer, only which user account was in use at the time. The incident handler could analyze the desktop computer in question to verify its integrity, such as comparing its security settings and controls to the organizations baseline settings, checking its clock settings, and checking the system for signs of compromise and other breaches of security.', 'vec_doc-04-nist-sp-800-86-p95-390', 0, 198, 'v2.1.0', '36f4cf131c90d9e042fe0a859dc5998e9ba5054a5aa2329dbeb939b0023049bd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.2 T hreatening E-mail","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"FORENSICS","authority_tier":0,"chunk_seq":390,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.2 T hreatening E-mail"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p95-391', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 95, 'The key recommendations presented in this section for using data from multiple sources are as follows: ! Analysts can handle many situations most effectively by analyzing several individual data sources and then correlating events among them.  The techniques and processes for collecting, 8-5', 'vec_doc-04-nist-sp-800-86-p95-391', 0, 73, 'v2.1.0', '1069cedde6db97e7f8efee3ab5e2e87f65d39592f6a7953c58a93ece962f7944', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":95,"domain":"FORENSICS","authority_tier":0,"chunk_seq":391,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p96-392', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 96, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE examining, and analyzing different types of data sources are fundamentally different.  Many applications have data captured in data files, OSs, and network traffic. ! Organizations should be aware of the technical and logistical complexity of analysis.  A single event can generate records on many different data sources and produce more information than analysts can feasibly review.  Tools such as SEM can assist analysts by bringing information from many data sources together in a single place. 8-6', 'vec_doc-04-nist-sp-800-86-p96-392', 0, 142, 'v2.1.0', 'de2beaeac88d946720e500887a4d4f166052ebc73d0700bf8bfc60cefe79eb97', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":96,"domain":"FORENSICS","authority_tier":0,"chunk_seq":392,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p97-393', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 97, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Appendix ARecommendations Appendix A restates the major recommendations presented in Sections 2 through 8 of this publication. The first group of recommendations applies to organizing a forensics capability. The remaining recommendations have been grouped by the phases of the forensics process: collection, examination, analysis, and reporting. A.1 A.1.1 A.1.2 Organizing a Forensics Capability ! Organizations should have a capability to perform computer and network forensics. Forensics is needed for various tasks within an organization, including investigating crimes and inappropriate behavior, reconstructing computer security incidents, troubleshooting operational problems, supporting due diligence for audit record maintenance, and recovering from accidental system damage.', 'vec_doc-04-nist-sp-800-86-p97-393', 0, 212, 'v2.1.0', '864d21ef591cc8b82921fbedf3b61aa07ecb8331e68a5f0d70c753f3efff7413', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"FORENSICS","authority_tier":0,"chunk_seq":393,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p97-394', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 97, 'Without such a capability, an organization will have difficulty determining what events have occurred within its systems and networks, such as exposures of protected, sensitive data. Also, handling evidence in a forensically sound manner puts decision makers in a position where they can confidently take the necessary actions. Forensic Participants ! Organizations should determine which parties should handle each aspect of forensics. Most organizations rely on a combination of their own staff and external parties to perform forensic tasks. Organizations should decide which parties should take care of which tasks based on skills and abilities, cost, response time, and data sensitivity. ! Analysts should have reasonably comprehensive technical knowledge.', 'vec_doc-04-nist-sp-800-86-p97-394', 0, 191, 'v2.1.0', 'e0571576a5cdd415120c92bb98388d21cbc27c12b327bf666de8f06df657e8b9', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"FORENSICS","authority_tier":0,"chunk_seq":394,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p97-395', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 97, 'Because current tools have rather limited analysis abilities, analysts should be well-trained, experienced, and knowledgeable in networking principles, common network and application protocols, network and application security products, and network-based threats and attack methods. ! Incident handling teams should have robust forensic capabilities. More than one team member should be able to perform each typical forensic activity. Hands-on exercises and IT and forensic training courses can be helpful in building and maintaining skills, as can demonstrations of new tools and technologies. ! Many teams within an organization should participate in forensics. Individuals performing forensic actions should be able to reach out to other teams and individuals within an organization, as needed, for additional assistance. Examples of teams that may provide assistance in these efforts include IT professionals, management, legal advisors, human resources personnel, auditors, and physical security staff.', 'vec_doc-04-nist-sp-800-86-p97-395', 0, 252, 'v2.1.0', 'b936d993a8cddd13f5e490babf9d4a9a4f4b21a7f9e6a99d4590aa24b5cf363e', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"FORENSICS","authority_tier":0,"chunk_seq":395,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p97-396', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 97, 'Members of these teams should understand their roles and responsibilities in forensics, receive training and education on forensicrelated policies, guidelines, and procedures, and be prepared to cooperate with and assist others on forensic actions. Forensic Policies, Guidelines, and Procedures ! Forensic considerations should be clearly addressed in policies. At a high level, policies should allow authorized personnel to monitor systems and networks and perform investigations for legitimate reasons under appropriate circumstances. Organizations may also have a separate forensic policy for incident handlers and others with forensic roles that provides more detailed rules for appropriate behavior. Everyone who may be called upon to assist with any forensic A-1', 'vec_doc-04-nist-sp-800-86-p97-396', 0, 193, 'v2.1.0', '93100b18b12a2aa476c1669ed9282e4b3dda0889eac56972d5e3983e6d361292', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":97,"domain":"FORENSICS","authority_tier":0,"chunk_seq":396,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p98-397', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 98, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE efforts should be familiar with and understand the forensic policy. Additional policy considerations are as follows:  Forensic policy should clearly define the roles and responsibilities of all people performing or assisting with the organizations forensic activities. The policy should include all internal and external parties that may be involved and should clearly indicate who should contact which parties under different circumstances.  The organizations policies, guidelines, and procedures should clearly explain what forensic actions should and should not be performed under normal and special circumstances and should address the use of anti-forensic tools and techniques. Policies, guidelines, and procedures should also address the handling of inadvertent exposures of sensitive information.', 'vec_doc-04-nist-sp-800-86-p98-397', 0, 218, 'v2.1.0', '3f095fa5d6a4b9ba80322b3dbee6a8e108cdb14b1f65da72ded1fa763d4d28bd', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"FORENSICS","authority_tier":0,"chunk_seq":397,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p98-398', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 98, ' Incorporating forensic considerations into the information system life cycle can lead to more efficient and effective handling of many incidents.  The organizations policies should address inadvertent disclosures and long-term storage of sensitive information captured by forensic tools, and should ensure that this does not violate the organizations privacy or data retention policies.  The organizations policies should also address the monitoring of networks, as well as requiring warning banners on systems that indicate that activity might be monitored. The policies should take into account reasonable expectations of user privacy. ! Organizations should create and maintain guidelines and procedures for performing forensic tasks. The guidelines should include general methodologies for investigating an incident using forensic techniques, and step-by-step procedures should explain how to perform routine tasks.', 'vec_doc-04-nist-sp-800-86-p98-398', 0, 232, 'v2.1.0', 'cb580013f2033a95a9519aea2e2b307b8797ef6b89c04857758dc5006ffb97d8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"FORENSICS","authority_tier":0,"chunk_seq":398,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p98-399', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 98, 'The guidelines and procedures should support the admissibility of evidence into legal proceedings. Because electronic logs and other records can be altered or otherwise manipulated, organizations should be prepared, through their policies, guidelines, and procedures, to demonstrate the reliability and integrity of such records. The guidelines and procedures should also be reviewed regularly and maintained so that they are accurate. A.1.3 A.2 Technical Preparation ! Analysts should have a forensic toolkit for data collection, examination, and analysis. It should contain various tools that provide the ability to collect and examine volatile and non- volatile data and to perform quick reviews of data as well as in-depth analysis. The toolkit should allow its applications to be run quickly and efficiently from removable media (e.g., floppy disk, CD) or a forensic workstation. ! Organizations should provide adequate storage for network activityrelated logs.', 'vec_doc-04-nist-sp-800-86-p98-399', 0, 242, 'v2.1.0', '98d8a01c5113b6778e16b7f9a7ce924fefa19ea2832f270705e01c8b908f26fc', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"FORENSICS","authority_tier":0,"chunk_seq":399,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p98-400', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 98, 'Organizations should estimate typical and peak log usage, determine how many hours or days worth of data should be retained based on the organizations policies, and ensure that systems and applications have sufficient storage available. Logs related to computer security incidents might need to be kept for a substantially longer period of time than other logs. Performing the Forensics Process ! Organizations should perform forensics using a consistent process. This guide presents a four-phase forensics process, with collection, examination, analysis, and reporting phases. The exact details of the phases may vary based on the need for forensics. A-2', 'vec_doc-04-nist-sp-800-86-p98-400', 0, 165, 'v2.1.0', '218f3407c4e092a3a2c19a33a6104c635c3bd45c4e3259664436eb5f395ccb94', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":98,"domain":"FORENSICS","authority_tier":0,"chunk_seq":400,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p99-401', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 99, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE A.2.1 Data Collection ! Organizations should be proactive in collecting useful data. Configuring auditing on OSs, implementing centralized logging, performing regular system backups, and using security monitoring controls can all generate sources of data for future forensic efforts. ! Analysts should be aware of the range of possible data sources. Analysts should be able to survey a physical area and recognize possible sources of data. Analysts should also think of possible data sources located elsewhere within an organization and outside the organization. Analysts should be prepared to use alternate data sources if it is not feasible to collect data from a primary source. ! Analysts should consider all possible application data sources. Application events might be recorded by many different data sources.', 'vec_doc-04-nist-sp-800-86-p99-401', 0, 220, 'v2.1.0', '424714456cbbe88601f21dd419df9a32545bbc17e4745825a9e8bed6d6675bf7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"FORENSICS","authority_tier":0,"chunk_seq":401,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p99-402', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 99, 'In addition, applications might be used through multiple mechanisms, such as multiple client programs installed on a system and Web-based client interfaces. In such situations, analysts should identify all application components, decide which are most likely to be of interest, find the location of each component of interest, and acquire the data. ! Analysts should perform data collection using a standard process. The recommended steps are identifying sources of data, developing a plan to acquire the data, acquiring the data, and verifying the integrity of the data. The plan should prioritize the data sources, establishing the order in which the data should be acquired, based on the likely value of the data, the volatility of the data, and the amount of effort required. Before data collection begins, a decision should be made by the analyst or management regarding the need to collect and preserve evidence in a manner that supports its use in future legal or internal disciplinary proceedings.', 'vec_doc-04-nist-sp-800-86-p99-402', 0, 252, 'v2.1.0', '03756411a6d1333ec2791860f79c74082d420e4cb66beb75af9288ace1008b06', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"FORENSICS","authority_tier":0,"chunk_seq":402,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p99-403', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 99, 'In such situations, a clearly defined chain of custody should be followed to avoid allegations of mishandling or tampering of evidence. ! Analysts should act appropriately to preserve volatile OS data. The criteria for determining whether volatile OS data must be preserved should be documented in advance so that analysts can make informed decisions as quickly as possible. To determine whether the effort required to collect volatile OS data is warranted, the risks associated with such collection should be weighed against the potential for recovering important information. ! Analysts should use a forensic toolkit for collecting volatile OS data. Use of a forensic toolkit enables accurate OS data to be collected while minimizing disturbance to the system and protecting the tools from changes. The analyst should know how each tool is likely to affect or alter the system during collection of data. ! Analysts should choose the appropriate shutdown method for each system.', 'vec_doc-04-nist-sp-800-86-p99-403', 0, 245, 'v2.1.0', '022a6b63eeac51368f30eef7b4f4aa7823b853a9957d8900525780da9027b491', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"FORENSICS","authority_tier":0,"chunk_seq":403,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p99-404', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 99, 'Each way of shutting down a particular OS can cause different types of data to be preserved or corrupted; analysts should be aware of the typical shutdown behavior of each OS. ! Analysts should preserve and verify file integrity. Using a write-blocker during backups and imaging prevents a computer from writing to its storage media. The integrity of copied data should be verified by computing and comparing the message digests of files. Backups and images should be accessed as read-only whenever possible; write-blockers can also be used to prevent writes to the backup or image file or restored backup or image. A-3', 'vec_doc-04-nist-sp-800-86-p99-404', 0, 155, 'v2.1.0', '0fba44e61e5fb3f6637089210f6f93046f7ad0f01061b2e3e7f8756d95295243', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":99,"domain":"FORENSICS","authority_tier":0,"chunk_seq":404,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p100-405', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 100, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE A.2.2 A.2.3 Examination and Analysis ! Analysts should use a methodical approach to studying the data. The foundation of forensics is using a methodical approach in analyzing the available data so that analysts can either draw appropriate conclusions based on the available data, or determine that no conclusion can yet be drawn. If evidence might be needed for legal or internal disciplinary actions, analysts should carefully document the findings and the steps that were taken. ! Analysts should examine copies of files, not the original files. During the collection phase, the analyst should make multiple copies of the desired files or filesystems, typically a master copy and a working copy. The analyst can then work with the working copy of the files without affecting the original files or the master copy.', 'vec_doc-04-nist-sp-800-86-p100-405', 0, 220, 'v2.1.0', 'cf0424bed736897683873e50c1e83c7a5f632bac4dd3aeba526e6211470fba94', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"FORENSICS","authority_tier":0,"chunk_seq":405,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p100-406', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 100, 'A bit stream image should be performed if evidence may be needed for prosecution or disciplinary actions, or if preserving file times is important. ! Analysts should consider the fidelity and value of each data source. Analysts should have more confidence in original data sources than in data sources that receive normalized data from other sources. Analysts should validate any unusual or unexpected data that is based on interpreting data, such as IDS and SEM alerts. ! Analysts should rely on file headers, not file extensions, to identify file content types. Because users can assign any file extension to a file, analysts should not assume that file extensions are accurate. Analysts can identify the type of data stored in many files by examining their file headers. Although people can alter file headers to conceal actual file types, this is much less common than altering file extensions. ! Analysts should generally focus on the characteristics and impact of the event.', 'vec_doc-04-nist-sp-800-86-p100-406', 0, 245, 'v2.1.0', '44e4cebc4f7e8113a8418759d035d499b65450af292cdfce35359fc6b8cdde16', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"FORENSICS","authority_tier":0,"chunk_seq":406,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p100-407', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 100, 'Determining the identity of an attacker and other similar actions are typically time-intensive and difficult to accomplish, and do not aid the organization in correcting operational issues or security weaknesses. Establishing the identity and intent of an attacker may be important, especially if a criminal investigation will ensue, but it should be weighed against other important goals. ! Organizations should be aware of the technical and logistical complexity of analysis. A single event can generate records on many different data sources and produce more information than analysts can feasibly review. Tools such as SEM can assist analysts by bringing information from many data sources together in a single place. ! Analysts should bring together data from various sources.', 'vec_doc-04-nist-sp-800-86-p100-407', 0, 196, 'v2.1.0', '9efdd486c7997f12ba77722c936ec6bbf8bb366317e12daecf08e7f81949ad23', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"FORENSICS","authority_tier":0,"chunk_seq":407,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p100-408', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 100, 'The analyst should review the results of the examination and analysis of individual data sources, such as data files, OSs, and network traffic, and determine how the information fits together, to perform a detailed analysis of application-related events and event reconstruction. Reporting ! Analysts should review their processes and practices. Reviews of current and recent forensic actions can help identify policy shortcomings, procedural errors, and other issues that might need to be remedied, as well as ensuring that the organization stays current with trends in technology and changes in law. A-4', 'vec_doc-04-nist-sp-800-86-p100-408', 0, 152, 'v2.1.0', '04f968a1cca81844d00cb50e6f79efd45bb20bcbce6a4aeaf81bc5c3dbe92926', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":100,"domain":"FORENSICS","authority_tier":0,"chunk_seq":408,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p101-409', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8.3 Re commendations', 101, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Appendix BScenarios Tabletop exercises that focus on how forensic tools and techniques can be used in various scenarios provide an inexpensive and effective way of building and maintaining skills and identifying problems with guidelines, procedures, and policies.  The exercise participants review a brief scenario and are then asked several questions related to the scenario.  The participants discuss each question and formulate an answer based on what they would really do in the situation.  The response is then compared with the organizations policies, procedures, and guidelines to identify any discrepancies or deficiencies.  For example, the answer to one question might indicate that forensic actions would be delayed because a participant lacked a particular piece of software and a particular team within the organization did not provide off-hours support. Section B.1 contains a list of general questions that could be applied to almost any scenario.  Section B.2 contains several sample scenarios, some of which are followed by additional scenario-specific questions. Organizations are encouraged to adapt these questions and scenarios for use in their own exercises. B.1 B.2 Scenario Questions', 'vec_doc-04-nist-sp-800-86-p101-409', 0, 319, 'v2.1.0', '09bc2e64f991ad8c57abb72d0a40f493f6edab4190c2fc423f51cb8947b04eb7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8.3 Re commendations","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"FORENSICS","authority_tier":0,"chunk_seq":409,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8.3 Re commendations"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p101-410', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '4. Which forensic tools and techniques would most likely be used?  Which other tools and', 101, 'techniques might also be used?', 'vec_doc-04-nist-sp-800-86-p101-410', 0, 8, 'v2.1.0', '5ebbaf51b4aa6cc4a659043f6ca3da71e62e03c7d7cd7f39557222570c56194a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"4. Which forensic tools and techniques would most likely be used?  Which other tools and","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"FORENSICS","authority_tier":0,"chunk_seq":410,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"4. Which forensic tools and techniques would most likely be used?  Which other tools and"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p101-411', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '7. From a forensic standpoint, what would be done differently if the scenario had occurred on a', 101, 'different day or at a different time (regular hours versus off-hours)?', 'vec_doc-04-nist-sp-800-86-p101-411', 0, 18, 'v2.1.0', 'b5a660e523065c22ac5c889bd854629ae09b7d6abb25a9caaea8d191d8aa675f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"7. From a forensic standpoint, what would be done differently if the scenario had occurred on a","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"FORENSICS","authority_tier":0,"chunk_seq":411,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"7. From a forensic standpoint, what would be done differently if the scenario had occurred on a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p101-412', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8. From a forensic standpoint, what would be done differently if the scenario had occurred at a', 101, 'different physical location (onsite versus offsite)? Scenarios Scenario 1:  Possible DDoS Attack On a Saturday afternoon, external users start having problems accessing the organizations public Web sites.  Over the next hour, the problem worsens to the point where nearly every attempt to access any of the organizations public Web sites fails.  Meanwhile, a member of the organizations networking staff responds to automatically generated alerts from an Internet border router and determines that much of the organizations Internet bandwidth is being consumed by an unusually large volume of User Datagram Protocol (UDP) packets to and from both of the organizations public Domain Name System (DNS) servers. B-1', 'vec_doc-04-nist-sp-800-86-p101-412', 0, 180, 'v2.1.0', '4815a059aaa6736d7d8937497c9f13709ee49f8ed7210a2193da574644945825', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8. From a forensic standpoint, what would be done differently if the scenario had occurred at a","subsection":"UNKNOWN","table_id":null,"page":101,"domain":"FORENSICS","authority_tier":0,"chunk_seq":412,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8. From a forensic standpoint, what would be done differently if the scenario had occurred at a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p102-413', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '8. From a forensic standpoint, what would be done differently if the scenario had occurred at a', 102, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE The following are additional questions for this scenario:', 'vec_doc-04-nist-sp-800-86-p102-413', 0, 31, 'v2.1.0', '2ce7bc63b87f9ff938e624ee54e848e72c2272e88075018149849f0e377badc2', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"8. From a forensic standpoint, what would be done differently if the scenario had occurred at a","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"FORENSICS","authority_tier":0,"chunk_seq":413,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"8. From a forensic standpoint, what would be done differently if the scenario had occurred at a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p102-414', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1. How would the forensic activity change if the DDoS attack appeared to be coming from a', 102, 'network in a different state?  In a different country?', 'vec_doc-04-nist-sp-800-86-p102-414', 0, 14, 'v2.1.0', '9b7860cb568e65dae60df3127034241817461dfa52ed304ebc716461c8f5fb45', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1. How would the forensic activity change if the DDoS attack appeared to be coming from a","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"FORENSICS","authority_tier":0,"chunk_seq":414,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1. How would the forensic activity change if the DDoS attack appeared to be coming from a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p102-415', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. How would the forensic activity change if the DDoS attack appeared to be coming from a', 102, 'business partners network? Scenario 2:  Online Payment Problems Over the course of a week, the number of phone calls coming into the organizations help line for online bill presentment and payment increases by 400 percent.  Most callers complain of having to resubmit payment information multiple times, and many cannot complete their payment. The following are additional questions for this scenario: 1. The problems could have a non-technical cause, such as a lack of clear instructions for new users. How should the technical and non-technical aspects of the investigation be coordinated and balanced?', 'vec_doc-04-nist-sp-800-86-p102-415', 0, 152, 'v2.1.0', '38ad4eb72d53b4ecc5f3e14c596ce8b665823ac1aaba7dbfc52b6eaa270d71b1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. How would the forensic activity change if the DDoS attack appeared to be coming from a","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"FORENSICS","authority_tier":0,"chunk_seq":415,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. How would the forensic activity change if the DDoS attack appeared to be coming from a"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p102-416', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. How would forensic tools and techniques be used if application developers were confident that an', 102, 'operational problem was causing the issues? Scenario 3:  Unknown Wireless Access Point On a Monday morning, the organizations help desk receives calls from five users on the same floor of a building who state that they are having problems with their wireless access.  A network administrator who is asked to assist in resolving the problem brings a laptop with wireless capability to the users floor.  As he views his wireless networking configuration, he notices that there is a new wireless access point listed as available.  Based on the insecure configuration settings transmitted by the access point, the administrator does not believe that his team deployed it. The following are additional questions for this scenario:', 'vec_doc-04-nist-sp-800-86-p102-416', 0, 182, 'v2.1.0', 'e56d84742b25910a1937cb2c5e2c1c1dffd736ec39395e122a34eea2536e8db8', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. How would forensic tools and techniques be used if application developers were confident that an","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"FORENSICS","authority_tier":0,"chunk_seq":416,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. How would forensic tools and techniques be used if application developers were confident that an"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p102-417', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. How would the forensic activities change if it was determined that the access point was deployed', 102, 'for a legitimate business purpose, such as temporary work at the office by a contractor?', 'vec_doc-04-nist-sp-800-86-p102-417', 0, 22, 'v2.1.0', '084c76132b07c3f5813bde0ab0de7546d3e30062a1f3e0c5426f495f4a15aed1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. How would the forensic activities change if it was determined that the access point was deployed","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"FORENSICS","authority_tier":0,"chunk_seq":417,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. How would the forensic activities change if it was determined that the access point was deployed"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p102-418', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. How would the forensic activities change if it was determined that an unknown individual had', 102, 'been seen deploying the access point? Scenario 4:  Reinfected Host During the past 2 weeks, a user has needed to have the same virus removed from a laptop computer twice, and the user is now reporting similar symptoms again.  The technical support staff who handled the previous infections confirmed that the antivirus software on the computer was enabled and up to date and were unable to determine how the virus was reinfecting the computer. The following are additional questions for this scenario: B-2', 'vec_doc-04-nist-sp-800-86-p102-418', 0, 127, 'v2.1.0', 'acdf4fd9de72666f710119389ed867b9d65d9065ae637ffb584e079fcbd96c24', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. How would the forensic activities change if it was determined that an unknown individual had","subsection":"UNKNOWN","table_id":null,"page":102,"domain":"FORENSICS","authority_tier":0,"chunk_seq":418,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. How would the forensic activities change if it was determined that an unknown individual had"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p103-419', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. What legal considerations should the analysts be aware of if they want to examine a data source', 103, 'that the organization does not own? Scenario 5:  Mistaken Identity Within the past 24 hours, two employees in the organization have reported fraudulent purchases charged to their organization-issued credit cards.  The organization frequently buys items from the companies that sold the items in the questioned transactions.  A follow-on assessment shows that charges to the organizations credit cards across the organization have increased by 30 percent in the past 3 days. The following are additional questions for this scenario:', 'vec_doc-04-nist-sp-800-86-p103-419', 0, 133, 'v2.1.0', 'ea211b654b742a3b179431222ed2348ed4e3a5cbc9363ea1cb3a40084b97e397', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. What legal considerations should the analysts be aware of if they want to examine a data source","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"FORENSICS","authority_tier":0,"chunk_seq":419,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. What legal considerations should the analysts be aware of if they want to examine a data source"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p103-420', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1. How could forensic tools and techniques help analysts determine what has happened (e.g., that', 103, 'individual employees in the organization are victims of identity theft, that financial resources have been corrupted)?', 'vec_doc-04-nist-sp-800-86-p103-420', 0, 30, 'v2.1.0', '1b7834040abe12c000357663b6dc890ff6bea974038a7ff17955ecedbd68d915', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1. How could forensic tools and techniques help analysts determine what has happened (e.g., that","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"FORENSICS","authority_tier":0,"chunk_seq":420,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1. How could forensic tools and techniques help analysts determine what has happened (e.g., that"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p103-421', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What privacy concerns should be considered in investigating employees financial transactions?', 103, 'Scenario 6:  Unwanted Screen Saver The organizations help desk has just received several calls from users who complain that a screen saver depicting pastoral scenery is activating while they are working at their computers.  The screen saver requires each user to submit his or her password to unlock the screen saver and continue work.  At the same time, the organizations network intrusion detection systems report several unusual alerts involving a Web server.  The data in the alerts indicates that some suspicious activity was directed at the server, and the server is now generating similar activity directed at other systems.  The intrusion detection analysts initial hypothesis is that a worm may have attacked a vulnerable network service on the Web server. The following are additional questions for this scenario:', 'vec_doc-04-nist-sp-800-86-p103-421', 0, 207, 'v2.1.0', '9a6e20996d7a00e101614470879079287e7c07981850aaea13ef402e993f98d5', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What privacy concerns should be considered in investigating employees financial transactions?","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"FORENSICS","authority_tier":0,"chunk_seq":421,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What privacy concerns should be considered in investigating employees financial transactions?"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p103-422', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '3. How would the use of forensic tools and techniques change if the infected desktop systems were', 103, 'used to process sensitive information that the organization is required to safeguard? Scenario 7:  Phishing Attempts In the past 24 hours, several employees have called the help desk to question the validity of e-mails from the organizations official credit card provider.  The e-mails cite a possible security breach in the financial institutions records and ask recipients to follow a link to the institutions Web site and create a new password, after identifying themselves by providing their existing passwords and account information. The following are additional questions for this scenario:', 'vec_doc-04-nist-sp-800-86-p103-422', 0, 150, 'v2.1.0', '3b9ea86aa234af49ff3ccbbb6837aec6e6d84812698556bba0ce4b373188647f', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"3. How would the use of forensic tools and techniques change if the infected desktop systems were","subsection":"UNKNOWN","table_id":null,"page":103,"domain":"FORENSICS","authority_tier":0,"chunk_seq":422,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"3. How would the use of forensic tools and techniques change if the infected desktop systems were"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p104-423', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What other organization(s) should be contacted to mitigate potential cases of identity theft?', 104, 'Scenario 8:  Encrypted Files An employee leaves an organization unexpectedly, and the employees manager is granted access to the former employees desktop computer to retrieve important project information that should be stored on it. The manager finds some filenames that appear to be related to the project, but the manager cannot access the contents of the files.  A system administrator looks at the system and concludes that the former employee probably encrypted the files. The following are additional questions for this scenario:', 'vec_doc-04-nist-sp-800-86-p104-423', 0, 135, 'v2.1.0', '9161a6c97fba8bee81d5142b87358e784b12e2319636b7ada74ddb60a78bd8d1', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What other organization(s) should be contacted to mitigate potential cases of identity theft?","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"FORENSICS","authority_tier":0,"chunk_seq":423,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What other organization(s) should be contacted to mitigate potential cases of identity theft?"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p104-424', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '1. Who should determine how much effort should be put into attempting to recover the encrypted', 104, 'data?  How would this be determined?', 'vec_doc-04-nist-sp-800-86-p104-424', 0, 9, 'v2.1.0', '0e4d5a6baaa8efcde7a5aecf7b6aa829ab57d0a3b72a25aa56bbd5307e9eed7a', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"1. Who should determine how much effort should be put into attempting to recover the encrypted","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"FORENSICS","authority_tier":0,"chunk_seq":424,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"1. Who should determine how much effort should be put into attempting to recover the encrypted"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p104-425', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 104, 'the impact of similar future incidents? B-4', 'vec_doc-04-nist-sp-800-86-p104-425', 0, 11, 'v2.1.0', 'df2a7f02ad489192eedc9919fe9793154aa4d301dff8ca37e056cb74f3666bf0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":104,"domain":"FORENSICS","authority_tier":0,"chunk_seq":425,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p105-426', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 105, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Appendix CGlossary Selected terms used in the Guide to Integrating Forensic Techniques into Incident Response are defined below. Analysis:  The third phase of the computer and network forensic process, which involves using legally justifiable methods and techniques, to derive useful information that addresses the questions that were the impetus for performing the collection and examination. Anti-Forensic:  A technique for concealing or destroying data so that others cannot access it. Bit Stream Imaging:  A bit-for-bit copy of the original media, including free space and slack space. Also known as disk imaging. Cluster:  A group of contiguous sectors. Collection:  The first phase of the computer and network forensics process, which involves identifying, labeling, recording, and acquiring data from the possible sources of relevant data, while following guidelines and procedures that preserve the integrity of the data.', 'vec_doc-04-nist-sp-800-86-p105-426', 0, 249, 'v2.1.0', '7dac2c694dcc205abb472b7cc4ffdc503fd90e83ae2cbd9b3194b71582e7bd24', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"FORENSICS","authority_tier":0,"chunk_seq":426,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p105-427', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 105, 'Data:  Distinct pieces of digital information that have been formatted in a specific way. Digital Forensics:  The application of science to the identification, collection, examination, and analysis, of data while preserving the integrity of the information and maintaining a strict chain of custody for the data. Directory:  Organizational structures that are used to group files together. Disk Imaging:  Generating a bit-for-bit copy of the original media, including free space and slack space. Also known as a bit stream image. Disk-to-Disk Copy:  Copying the contents of media directly to another media. Disk-to-File Copy:  Copying the contents of media to a single logical data file. Examination:  The second phase of the computer and network forensics process, which involves forensically processing large amounts of collected data using a combination of automated and manual methods to assess and extract data of particular interest, while preserving the integrity of the data.', 'vec_doc-04-nist-sp-800-86-p105-427', 0, 246, 'v2.1.0', '688011af1b79d2653efecb9743b6a57277482edff0e53c333311885d83ed6079', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"FORENSICS","authority_tier":0,"chunk_seq":427,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p105-428', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 105, 'False Negative:  Incorrectly classifying malicious activity as benign. False Positive:  Incorrectly classifying benign activity as malicious. File:  A collection of information logically grouped into a single entity and referenced by a unique name, such as a filename. File Allocation Unit:  A group of contiguous sectors, also known as a cluster. File Header:  Data within a file that contains identifying information about the file and possibly metadata with information about the file contents. C-1', 'vec_doc-04-nist-sp-800-86-p105-428', 0, 126, 'v2.1.0', 'f230238f01e60262f9518a8fcfa51edc0a8afecdb953588f6cb2476b4c511ea3', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":105,"domain":"FORENSICS","authority_tier":0,"chunk_seq":428,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p106-429', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 106, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Filename:  A unique name used to reference a file. Filesystem:  A method for naming, storing, organizing, and accessing files on logical volumes. Forensic Science:  The application of science to the law. Forensically Clean:  Digital media that is completely wiped of all data, including nonessential and residual data, scanned for malware, and verified before use. Free Space:  An area on media or within memory that is not allocated. Logical Backup:  A copy of the directories and files of a logical volume. Logical Volume:  A partition or a collection of partitions acting as a single entity that has been formatted with a filesystem. Message Digest:  A hash that uniquely identifies data. Changing a single bit in the data stream used to generate the message digest will yield a completely different message digest. Metadata:  Data about data. For filesystems, metadata is data that provides information about a files contents.', 'vec_doc-04-nist-sp-800-86-p106-429', 0, 249, 'v2.1.0', 'b0a3df4443ad571afaaef5de77ba43b3353e7be7306381b5b1ef0dc8193f9a23', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":106,"domain":"FORENSICS","authority_tier":0,"chunk_seq":429,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p106-430', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 106, 'Network Address Translation:  The process of mapping addresses on one network to addresses on another network. Network Intrusion Detection System:  Software that performs packet sniffing and network traffic analysis to identify suspicious activity and record relevant information. Network Traffic:  Computer network communications that are carried over wired or wireless networks between hosts. Non-Volatile Data:  Data that persists even after a computer is powered down. Normalize:  The process by which differently formatted data is converted into a standardized format and labeled consistently. Operating System:  A program that runs on a computer and provides a software platform on which other programs can run. Packet:  The logical unit of network communications produced by the transport layer. Packet Sniffer:  Software that monitors network traffic on wired or wireless networks and captures packets.', 'vec_doc-04-nist-sp-800-86-p106-430', 0, 228, 'v2.1.0', '44abccc0497c5c51157dda23095627b7d554c25de20feab30d6d1f44091b29d0', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":106,"domain":"FORENSICS","authority_tier":0,"chunk_seq":430,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p106-431', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 106, 'Partition:  A logical portion of a media that functions as though it were physically separate from other logical portions of the media. Process:  An executing program. Protocol Analyzer:  Software that can reassemble streams from individual packets and decode communications that use various protocols. C-2', 'vec_doc-04-nist-sp-800-86-p106-431', 0, 77, 'v2.1.0', 'be756d33e498ca791beed904aeca8e394747b1a780a3ef5b70b6a1c8be651eb7', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":106,"domain":"FORENSICS","authority_tier":0,"chunk_seq":431,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
INSERT OR REPLACE INTO knowledge_chunks (id, document_id, source_id, section, page, text, embedding_id, authority_tier, token_count, version, content_hash, metadata) VALUES ('doc-04-nist-sp-800-86-p107-432', 'doc-04-nist-sp-800-86', 'doc-04-nist-sp-800-86', '2. What changes could be made to the organizations policies, guidelines, and procedures to reduce', 107, 'GUIDE TO INTEGRATING FORENSIC TECHNIQUES INTO INCIDENT RESPONSE Proxy:  Software that receives a request from a client, then sends a request on the clients behalf to the desired destination. Remote Access Server:  Devices, such as virtual private network gateways and modem servers, that facilitate connections between networks. Reporting:  The final phase of the computer and network forensic process, which involves reporting the results of the analysis; this may include describing the actions used, explaining how tools and procedures were selected, determining what other actions need to be performed (e.g., forensic examination of additional data sources, securing identified vulnerabilities, improving existing security controls), and providing recommendations for improvement to policies, guidelines, procedures, tools, and other aspects of the forensic process.  The formality of the reporting step varies greatly depending on the situation. Sector:  The smallest unit that can be accessed on media. Security Event Management Software:  Software that imports security event information from multiple data sources, normalizes the data, and correlates events among the data sources. Slack Space:  The unused space in a file allocation block or memory page that may hold residual data. Steganography:  Embedding data within other data to conceal it. Subdirectory:  A directory contained within another directory. Volatile Data:  Data on a live system that is lost after a computer is powered down. Wiping:  Overwriting media or portions of media with random or constant values to hinder the collection of data. Write-Blocker:  A tool that prevents all computer storage media connected to a computer from being written to or modified. C-3', 'vec_doc-04-nist-sp-800-86-p107-432', 0, 436, 'v2.1.0', '42938f0de6b093238ebde4f95ad9d856e0d5153dfa4e3552e44f9cdb3e728708', '{"document_id":"doc-04-nist-sp-800-86","document_title":"NIST SP 800-86","chapter":"UNKNOWN","section":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce","subsection":"UNKNOWN","table_id":null,"page":107,"domain":"FORENSICS","authority_tier":0,"chunk_seq":432,"source_path":".zayron/knowledge/physical-15/04-nist-sp-800-86.pdf","section_path":"2. What changes could be made to the organizations policies, guidelines, and procedures to reduce"}');
